//   Critical = Rose-red     #E05A63    (overdue / blocking / late)
//   Ready    = Sage green   #4FAE7A    (paid / confirmed / done)
//   Pending  = Steel-gray   #9AA8B3    (inactive / future / neutral)
// CTA gradient is the steel-BLUE brushed-metal #4E6877 → #3F5B6A — the
// New Task button's color. Every primary CTA (incl. marquee New Event)
// inherits this blue; the gray-leaning detour was reverted in Sprint 60.V.
// Dark-canvas darkness level — one switch for the whole app's dark theme. Tokenized from
// palette.carbonNeutral (no hardcoded hex). 'deep' < 'mid' < 'soft' < 'softer'.
const CARBON_LEVEL = 'mid';
const CARBON = carbonNeutral[CARBON_LEVEL];
// Studio Matte "lighting" — a soft overhead glow that lifts the flat carbon canvas into
// dimension. A subtle radial from one step lighter (carbonNeutral.soft) at the top edge,
// fading to the base by ~46%. Tokenized from the carbon ramp; no hardcoded hex.
// The header sits at the TOP of this gradient, so the lightest band must NOT be at 0%
// (that made the header read lighter than the body). Start at the base tone so the
// header matches the rest of the app, then lift gently through the mid-content for
// the Studio Matte "overhead lighting", and settle back to base.
const CARBON_GRAD = `linear-gradient(178deg, ${CARBON.bg} 0%, ${carbonNeutral.soft.bg} 38%, ${CARBON.bg} 82%)`;
const LIGHT_GRAD  = 'linear-gradient(178deg, #f4f6fa 0%, #ffffff 40%, #f4f6fa 84%)';
// Metallic card edge — renders the 1px border as a vertical gradient (light caught at the
// TOP, shadow at the bottom) via the padding-box/border-box trick, so the edge reads as a
// brushed-metal bevel WITHOUT thickening the line. Card fill stays C.surface. Spread into
// a card style in place of its `background`/`border`.
const metalEdge = (C) => ({
  border: '1px solid transparent',
  background: `linear-gradient(${C.surface},${C.surface}) padding-box, linear-gradient(178deg, rgba(255,255,255,0.22) 0%, ${C.border} 46%, rgba(0,0,0,0.30) 100%) border-box`,
});
// Glass-chip eyebrow (user) — a frosted pill for the small labels on the left of cards.
// Tokenized via the per-theme glass* tokens; spread into an eyebrow style.
const glassChip = (C) => ({
  display: 'inline-block', background: C.glassFill,
  backdropFilter: 'blur(10px)', WebkitBackdropFilter: 'blur(10px)',
  border: `1px solid ${C.glassBorder}`, borderRadius: 999, padding: '3px 10px', boxShadow: C.glassHi,
});

const DARK = {
  // Lighter carbon canvas (user, 2026-06-23): moved from the deepest Standard Carbon
  // up to the MID Carbon ramp — softer, less operating-room, still unmistakably dark.
  // TOKENIZED from palette.js (`mid` bundle) — no hardcoded hex. Steel accent + status +
  // light theme stay on their own ramps (accent matches "what we're coming from").
  bg:       CARBON.bg,        // de-blued carbon page (palette.carbonNeutral[CARBON_LEVEL])
  bgGrad:   CARBON_GRAD,      // soft overhead "lighting" gradient for dimension (page roots use this)
  surface:  CARBON.panel,     // de-blued carbon card
  surface2: CARBON.surface2,  // de-blued carbon elevated
  border:   CARBON.border,    // de-blued carbon hairline
  // Card/panel dimension: a faint light catching the TOP outer line (inset highlight) +
  // soft lift below — raises the flat matte cards without breaking Studio Matte calm.
  cardShadow: 'inset 0 1px 0 0 rgba(255,255,255,0.09), 0 2px 5px rgba(0,0,0,0.45), 0 18px 38px -12px rgba(0,0,0,0.74)',
  // Glass-chip tokens (frosted pill for card eyebrows) — defined once per theme.
  glassFill:   'rgba(255,255,255,0.11)',
  glassBorder: 'rgba(255,255,255,0.20)',
  glassHi:     'inset 0 1px 0 rgba(255,255,255,0.20), 0 1px 4px rgba(0,0,0,0.4)',
  // Steel Blue 500 — silvery identity; accent for routes / links / today
  accent:   STEEL.blue500,    // #6F8794
  // Sprint 60.V correction — restore steel-BLUE CTA gradient. Bound to the
  // palette token so a future hue shift moves through one source.
  accentDeep:    steelBlueGradientBottom, // #3F5B6A — primary CTA base
  accentTopGrad: steelBlueGradientTop,    // #4E6877 — gradient top stop
  accentPressed: '#444B4F',   // pressed (was #2C4452)
  accentText:    STEEL.mist300, // #A8B7BF — CTA / link text on dark surfaces
  accentIcon:    STEEL.blue400, // #8BA0AA — icon-default accent
  accent2:  STEEL.blue500,
  text:     textPrimary,
  muted:    textSecondary,
  // Status anchors — bound to palette tokens (sprint-profile pass).
  warn:     amber,        // Attention — honey amber
  danger:   dangerRed,    // Critical — fire red
  success:  successGreen, // Ready — sage green
  live:     '#44CB76', // Live — bright green (running on schedule)
  today:    STEEL.blue500, // Today — Steel Blue 500 (alias)
  pending:  '#9AA8B3', // Pending — steel-gray (inactive / future)
  steel:    STEEL,
  // ── Attention System — 3 contrast tiers (governing view-guiding doctrine) ──
  // Squint at any screen → exactly ONE object (Tier 1) should survive. Most of
  // every screen lives in Tier 2/3. Amplify with SIZE + space, not color.
  tier1:    textPrimary,                // HERO — the one answer per screen (full white, large)
  tier2:    textSecondary,              // EVIDENCE — steel #849eb8, whispers (~60%)
  tier3:    'rgba(132,158,184,0.42)',   // DORMANT — ghost, collapsed/dimmed (~35%)
  tier3Dim: 'rgba(132,158,184,0.28)',   // DORMANT-er — fully at-rest counts / on-track
  // The ONE action object per viewport gets a single 2px left-edge hairline.
  actionEdge: dangerRed,                // accent is a BUDGET, spent once on the most urgent object
};

const LIGHT = {
  bg:       '#f8f8fa',   // clean near-white — neutral, not tinted
  bgGrad:   LIGHT_GRAD,  // matching soft overhead lighting (subtle on light)
  cardShadow: '0 0 0 0.5px rgba(0,0,0,0.05), 0 1px 2px rgba(0,0,0,0.07), 0 6px 16px -6px rgba(0,0,0,0.08)',
  glassFill:   'rgba(255,255,255,0.6)',
  glassBorder: 'rgba(0,0,0,0.07)',
  glassHi:     '0 1px 2px rgba(0,0,0,0.04)',
  surface:  '#ffffff',   // pure white cards
  surface2: '#f1f1f5',   // neutral hover/secondary surface
  border:   '#e2e2ea',   // light neutral gray — NOT purple; lets accent pop
  accent:   steelBlue,   // Studio Steel #4E6877 — banned #1a6fba removed (palette.js source)
  accent2:  '#0891b2',   // cyan-600 — blue-leaning teal, clearly distinct from green and amber
  text:     '#111118',   // near-black
  muted:    '#71707e',   // neutral gray — clearly secondary, not competing with accent
  danger:   '#ef4444',   // red-500 — 4.6:1 on white, vivid alert-red (not maroon)
  success:  '#16a34a',   // green-600 — 3.3:1 on white, reads as green (not dark forest)
  warn:     '#ef962e',   // CLEAN high-chroma amber (H32 S86) — the hard-won "lit tungsten" status amber (less-yellow, never gold #f59e0b, never muddy/desaturated). Disciplined "approaching/due-soon" STATUS only — never accent, never wallpaper.
  // ── Light parity completion (2026-06-12): DARK defined ~14 keys LIGHT did not.
  // Any component reading C.tier1 / C.steel / C.accentDeep / C.live etc. in light
  // mode got `undefined` → broken/transparent styling (the "light theme still
  // looks wrong" debt). Every DARK key now has a light-appropriate value. ──
  accentDeep:    '#3F5B6A',  // CTA gradient base (steel, works on light)
  accentTopGrad: '#4E6877',  // CTA gradient top
  accentPressed: '#34414b',  // pressed CTA
  accentText:    '#ffffff',  // text on the steel CTA fill
  accentIcon:    steelBlue,  // icon-default accent
  live:          '#16a34a',  // live/running — green
  today:         steelBlue,  // today marker — steel
  pending:       '#9aa3ad',  // pending/future — light steel-gray
  steel:         STEEL,      // steel ramp (palette object, mode-agnostic)
  // Attention System tiers in light: near-black hero → gray evidence → ghosted.
  tier1:    '#111118',
  tier2:    '#71707e',
  tier3:    'rgba(17,17,24,0.42)',
  tier3Dim: 'rgba(17,17,24,0.26)',
  actionEdge: '#ef4444',     // accent budget — danger red on the one urgent object
};

// Module-level C = DARK so every existing component referencing C directly
// gets correct tokens. When full per-component theme support is needed,
// swap each component to const C = useT() instead.
const C = DARK;

// Style factory — call makeS(C) inside components that need live theming.
// Module-level s = makeS(C) keeps backward compat for all existing components.
const makeS = (C) => {
  const isLight = C.surface === '#ffffff';
  return {
    app: { minHeight: '100vh', background: C.bgGrad || C.bg, color: C.text, fontFamily: FF, fontSize: T.body, WebkitFontSmoothing: 'antialiased', MozOsxFontSmoothing: 'grayscale', textRendering: 'optimizeLegibility' },
    header: {
      padding: '28px 32px 0',
      borderBottom: `1px solid ${C.border}`,
      boxShadow: isLight ? '0 1px 0 #e2e2ea' : 'none',
    },
    tabs: { display: 'flex', gap: 2, overflowX: 'auto' },
    tab: (a) => ({
      padding: '10px 18px', cursor: 'pointer', fontSize: T.secondary,
      fontWeight: a ? 600 : 500,
      borderRadius: '8px 8px 0 0', border: 'none',
      background: a ? (isLight ? C.accent + '14' : C.surface) : 'transparent',
      color: a ? (isLight ? C.accent : C.text) : C.muted,
      borderTop: a ? `2px solid ${C.accent}` : '2px solid transparent',
      transition: 'all 0.15s', whiteSpace: 'nowrap',
    }),
    sideTab: (a) => ({
      display: 'block', width: '100%', padding: '10px 16px', cursor: 'pointer',
      fontSize: T.secondary, fontWeight: a ? 700 : 500, border: 'none', borderRadius: 8, textAlign: 'left',
      background: a ? (isLight ? C.accent + '18' : C.accent + '18') : 'transparent',
      color: a ? C.accent : C.muted,
      borderLeft: a ? `3px solid ${C.accent}` : '3px solid transparent',
      transition: 'all 0.15s', whiteSpace: 'nowrap',
    }),
    body: { padding: '28px 32px' },
    card: {
      // Design polish on EVERY card, every tab: the metallic gradient edge + the
      // dimensional shadow are baked into the shared card style so no surface is flat.
      ...(isLight
        ? { background: 'linear-gradient(175deg, #ffffff 0%, #f3f3f7 100%)', border: '1px solid rgba(0,0,0,0.09)' }
        : metalEdge(C)),
      borderRadius: 12,
      padding: '20px 24px',
      marginBottom: 16,
      boxShadow: C.cardShadow,
    },
    // Sprint 60.U.3 10+ — global section eyebrow. Steel-blue + 800 weight
    // + slightly wider letterspacing matches the modal NO GUESSWORK rail,
    // CommandCenter section eyebrows, and Vendor Cockpit collapsible
    // headers — so every "section start" in the app reads in one voice.
    // Board ruling 2026-06-24 — SECTION TITLE register. Was a tiny 12px UPPERCASE accent
    // CHIP (glassChip), i.e. an eyebrow masquerading as a title — it rendered SMALLER than
    // the 15/16 body it headed (inverted hierarchy). Now a real title: 17px, sentence-case,
    // primary, leads its content by SIZE not hue. `sectionTitle` is the canonical name;
    // `cardTitle` is kept as an alias so every existing call site upgrades at once.
    sectionTitle: { fontSize: T.section, fontWeight: FW.bold, color: C.text, letterSpacing: '-0.01em', lineHeight: 1.3, margin: '0 0 12px' },
    cardTitle:    { fontSize: T.section, fontWeight: FW.bold, color: C.text, letterSpacing: '-0.01em', lineHeight: 1.3, margin: '0 0 12px' },
    input: { background: C.bg, border: `1px solid ${C.border}`, borderRadius: 8, color: C.text, fontSize: T.secondary, padding: '7px 12px', outline: 'none', width: '100%', boxSizing: 'border-box', fontFamily: FF },
    btn: (v = 'default') => {
      // ONE canonical CTA size for the whole app (parity pass). minHeight +
      // inline-flex centering means every s.btn() matches in height whether or
      // not it carries an icon — no more 30/34/38 drift across tabs. Genuinely
      // compact contexts still override padding/minHeight locally.
      const baseBtn = { display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: 6, minHeight: 32, padding: '6px 14px', borderRadius: 8, border: 'none', cursor: 'pointer', fontSize: T.secondary, fontWeight: FW.semibold, lineHeight: 1.1, whiteSpace: 'nowrap', boxSizing: 'border-box', fontFamily: FF };
      if (v === 'primary') {
        // Sprint 60.U — promote the marquee new-event CTA's brushed-steel gradient
        // to the standard primary CTA so every primary action shares one premium
        // color. Light theme (no gradient tokens) falls back to flat accent.
        const top  = C.accentTopGrad || C.accent;
        const deep = C.accentDeep    || C.accent;
        return {
          ...baseBtn,
          background: `linear-gradient(180deg, ${top} 0%, ${deep} 100%)`,
          // White text (not the hero's mist) so the gradient reads as the most
          // legible/prominent element even on small 12px CTAs.
          color: '#fff',
          textShadow: isLight ? 'none' : '0 1px 0 rgba(0,0,0,0.30)',
          boxShadow: isLight
            ? 'none'
            : 'inset 0 1px 0 rgba(255,255,255,0.12), inset 0 -1px 0 rgba(0,0,0,0.28), 0 1px 2px rgba(0,0,0,0.30), 0 0 0 1px rgba(193,203,208,0.16)',
        };
      }
      return {
        ...baseBtn,
        background: v === 'danger'  ? (isLight ? C.danger  : C.danger  + '1e')   // light: solid red; dark: tinted
          : v === 'teal'    ? (isLight ? C.accent2 + '59' : C.accent2 + '1e')
          : v === 'success' ? (isLight ? C.success + '59' : C.success + '1e')
          : v === 'ghost'   ? 'transparent'
          : (isLight ? C.surface2 : C.border),
        color: v === 'danger' ? (isLight ? '#fff' : C.danger) : v === 'teal' ? C.accent2 : v === 'success' ? C.success : v === 'ghost' ? C.muted : C.text,
      };
    },
    pill: (color) => ({
      display: 'inline-block', padding: '2px 9px', borderRadius: 99,
      fontSize: T.caption, fontWeight: FW.bold, letterSpacing: '0.04em', lineHeight: '18px',
      // Cylindrical tube physics — both themes: solid color base, white specular at top, shadow at base
      background: isLight
        ? [`linear-gradient(180deg, rgba(255,255,255,0.42) 0%, rgba(255,255,255,0.10) 38%, rgba(0,0,0,0.00) 62%, rgba(0,0,0,0.10) 100%)`, color].join(', ')
        : color + '33',
      color: isLight ? '#fff' : color,
      border: isLight ? 'none' : `1px solid ${color}55`,
      boxShadow: isLight
        ? `inset 0 1.5px 0 rgba(255,255,255,0.50), inset 0 -1.5px 0 rgba(0,0,0,0.14), 0 1px 3px ${color}55, 0 3px 8px ${color}22`
        : `inset 0 1px 0 rgba(255,255,255,0.10), 0 0 6px ${color}22`,
    }),
    statNum: (color) => {
      const c = color || C.text;
      const shadow = isLight
        ? (color ? `0 1px 3px ${color}2a, 0 2px 6px ${color}14` : '0 1px 2px rgba(0,0,0,0.07)')
        : (color ? `0 0 18px ${color}55` : 'none');
      return { fontWeight: FW.heavy, letterSpacing: '-0.03em', lineHeight: 1.1, color: c, textShadow: shadow };
    },
    table: { width: '100%', borderCollapse: 'collapse' },
    th: { textAlign: 'left', fontSize: T.caption, fontWeight: FW.semibold, color: C.muted, textTransform: 'uppercase', letterSpacing: '0.08em', padding: '0 10px 10px 0', borderBottom: `1px solid ${C.border}` },
    td: { padding: '11px 10px 11px 0', borderBottom: `1px solid ${C.border}`, verticalAlign: 'middle' },
    // ── Orchestration vocabulary (Sprint 23) ────────────────────────────────
    editLabel: { fontSize: T.eyebrow, fontWeight: FW.heavy, textTransform: 'uppercase', letterSpacing: '0.18em', color: C.muted, lineHeight: 1 },
    glanceNum: (sz, color) => ({ fontWeight: FW.black, fontSize: sz || T.statXl, letterSpacing: '-0.05em', lineHeight: 0.9, color: color || C.text, fontFeatureSettings: '"tnum" 1' }),
    orchDivider: { height: 1, background: `linear-gradient(90deg, ${C.border} 0%, transparent 80%)`, flexShrink: 0 },
    tensionCue: (level) => ({
      display: 'flex', alignItems: 'flex-start', gap: 9,
      padding: '8px 12px', borderRadius: 7,
      borderLeft: `2px solid ${level === 'critical' ? C.danger : level === 'warn' ? C.muted : C.accent2}`,
      background: level === 'critical' ? C.danger + '09' : level === 'warn' ? C.muted + '07' : C.accent2 + '07',
    }),
    seqNode: (state) => ({
      display: 'flex', alignItems: 'flex-start', gap: 10, padding: '7px 0',
      opacity: state === 'past' ? 0.35 : state === 'future' ? 0.55 : 1,
    }),
    metricRail: {
      display: 'grid', gap: 0,
      borderLeft: `1px solid ${C.border}`,
    },
    metricCell: (accent) => ({
      padding: '0 20px',
      borderRight: `1px solid ${C.border}`,
      cursor: accent ? 'pointer' : 'default',
    }),
  };
};
// Note: module-level s removed — all components use const s = makeS(C) inside their body.

// ─── 3D sphere helper ─────────────────────────────────────────────────────────
// Returns inline style for a matte 3D circle. Pass color as full hex string.
// textSz: font-size in px for initials (omit for dot-only use).
const mkSphere = (color, size, textSz = null) => ({
  width: size, height: size, borderRadius: '50%', flexShrink: 0,
  // 3-layer gradient stack (all solid-base so no background bleed on dark):
  //   1. Crisp elliptical specular highlight at upper-left
  //   2. Subtle rim light at lower-right (ambient bounce)
  //   3. Linear darkening toward bottom-right (shadow side)
  background: [
    `radial-gradient(ellipse 50% 28% at 33% 27%, rgba(255,255,255,0.65) 0%, transparent 100%)`,
    `radial-gradient(ellipse 30% 18% at 68% 75%, rgba(255,255,255,0.12) 0%, transparent 100%)`,
    `linear-gradient(145deg, ${color} 0%, ${color}bb 100%)`,
  ].join(', '),
  boxShadow: `0 2px 4px rgba(0,0,0,0.28), 0 6px 16px ${color}55, 0 1px 0 rgba(255,255,255,0.08) inset`,
  display: 'flex', alignItems: 'center', justifyContent: 'center',
  ...(textSz ? { fontSize: textSz, fontWeight: FW.bold, color: '#fff' } : {}),
});

// Dot version — small bullet circles (no text, no flex needed)
const mkDot = (color, size) => ({
  width: size, height: size, borderRadius: '50%', flexShrink: 0, display: 'inline-block',
  background: [
    `radial-gradient(ellipse 52% 30% at 33% 27%, rgba(255,255,255,0.70) 0%, transparent 100%)`,
    `linear-gradient(145deg, ${color} 0%, ${color}bb 100%)`,
  ].join(', '),
  boxShadow: `0 1px 3px rgba(0,0,0,0.26), 0 2px 6px ${color}55`,
});

// ─── Identity chip — board verdict (2026-06-23): real dimension via a LIT, hue-colored
// rounded-square "chip" (the mkSphere material) carrying a flat mist-white knockout glyph.
// 2.5D, not faked-3D-on-lines. Hue-adaptive (one color), theme-independent (lit on its own
// surface, not the page). Below ~18px it sheds the gloss to a clean flat chip.
const mkChip = (color, size) => ({
  width: size, height: size, borderRadius: Math.round(size * 0.28), flexShrink: 0,
  display: 'flex', alignItems: 'center', justifyContent: 'center',
  background: [
    `radial-gradient(ellipse 54% 30% at 30% 24%, rgba(255,255,255,0.6) 0%, transparent 100%)`,
    `radial-gradient(ellipse 30% 18% at 80% 82%, rgba(255,255,255,0.14) 0%, transparent 100%)`,
    `linear-gradient(145deg, color-mix(in srgb, ${color} 80%, white) 0%, ${color} 48%, color-mix(in srgb, ${color} 82%, black) 100%)`,
  ].join(', '),
  boxShadow: `0 2px 5px rgba(0,0,0,0.3), 0 7px 18px -3px ${color}66, 0 1px 0 rgba(255,255,255,0.18) inset, 0 -1px 0 rgba(0,0,0,0.22) inset`,
});
function IdentityChip({ icon, color, size = 44, stroke = 2 }) {
  const small = size < 18;
  const style = small
    ? { width: size, height: size, borderRadius: Math.round(size * 0.26), flexShrink: 0, display: 'flex', alignItems: 'center', justifyContent: 'center',
        background: `linear-gradient(145deg, color-mix(in srgb, ${color} 80%, white), color-mix(in srgb, ${color} 82%, black))`,
        boxShadow: `0 2px 6px -2px ${color}66` }
    : mkChip(color, size);
  return (
    <span aria-hidden style={style}>
      <span style={{ color: 'rgba(255,255,255,0.96)', display: 'flex' }}><Icon name={icon} size={Math.round(size * 0.56)} stroke={stroke} /></span>
    </span>
  );
}

// ─── Error Boundary ───────────────────────────────────────────────────────────
class ErrorBoundary extends Component {
  constructor(props) { super(props); this.state = { error: null }; }
  static getDerivedStateFromError(err) { return { error: err }; }
  render() {
    if (this.state.error) {
      return (
        <div style={{ padding: 40, textAlign: 'center', fontFamily: FF, background: carbonBody, minHeight: '100vh', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center' }}>
          <div style={{ fontSize: T.body, fontWeight: FW.bold, color: '#e8e8f0', marginBottom: 8 }}>A component failed to render</div>
          <div style={{ fontSize: T.secondary, color: '#6b6b80', marginBottom: 6, maxWidth: 340 }}>Your data is safe — this is a display error, not a data loss event.</div>
          <div style={{ fontSize: T.caption, color: '#f87171', fontFamily: 'monospace', marginBottom: 24, maxWidth: 380, wordBreak: 'break-word' }}>{this.state.error.message}</div>
          <div style={{ display: 'flex', gap: 10 }}>
            <button onClick={() => this.setState({ error: null })}
              style={{ padding: '8px 18px', borderRadius: 8, border: '1px solid #2a2a32', background: 'transparent', color: '#e8e8f0', cursor: 'pointer', fontSize: T.secondary, fontFamily: 'inherit' }}>
              Try again
            </button>
            <button onClick={() => window.location.reload()}
              style={{ padding: '8px 18px', borderRadius: 8, border: 'none', background: '#4a90d9', color: '#fff', cursor: 'pointer', fontSize: T.secondary, fontFamily: 'inherit' }}>
              Reload page
            </button>
          </div>
        </div>
      );
    }
    return this.props.children;
  }
}

// ─── Theme + breakpoint context ───────────────────────────────────────────────
const ThemeCtx = createContext({ C: DARK, theme: 'dark', setTheme: () => {} });
const useT = () => useContext(ThemeCtx).C;
// syncState: 'idle' | 'saving' | 'saved' | 'offline' | 'sync_failed' | 'reconnecting' | 'pending'
const SaveCtx  = createContext({ savedAt: null, online: true, syncState: 'idle', pendingCount: 0 });

// ─── Toast notification ───────────────────────────────────────────────────────
// Usage inside any component: const showToast = useToast(); showToast('Done!');
const ToastCtx  = createContext({ showToast: () => {} });
const useToast  = () => useContext(ToastCtx).showToast;

// ─── Sprint Budget/Payments — Undo toast (financial state actions) ─────────
// Usage: const showUndoToast = useUndoToast();
// showUndoToast({
//   title: 'Balance recorded as paid',
//   detail: '$3,200 marked paid for Lena Kim Photography',
//   summary: ['Recorded in: Vendor record', 'Money moved: None', ...],
