// ─── Claude AI ────────────────────────────────────────────────────────────────
const AICtx = createContext(''); // stores the planner's Anthropic API key
const useAIKey = () => useContext(AICtx);

async function askClaude(apiKey, prompt, { maxTokens = 700, onChunk, signal, system, context } = {}) {
  // Sprint 61: try backend AI proxy first — keeps API key server-side.
  // Falls back to BYOK (direct browser call) when proxy returns 503 or
  // when apiKey is available but BASE_URL isn't.
  const BASE = process.env.REACT_APP_API_BASE_URL;
  if (BASE) {
    try {
      const proxyRes = await fetch(`${BASE}/api/ai/status`);
      if (proxyRes.ok) {
        const { configured } = await proxyRes.json();
        if (configured) {
          const r = await fetch(`${BASE}/api/ai/complete`, {
            method: 'POST', signal,
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ prompt, system, max_tokens: maxTokens, context }),
          });
          if (r.ok) {
            const data = await r.json();
            if (onChunk) onChunk(data.text || '');
            return data.text || '';
          }
        }
      }
    } catch { /* fall through to BYOK */ }
  }
  // BYOK fallback
  if (!apiKey) throw new Error('no-key');
  const streaming = !!onChunk;
  const res = await fetch('https://api.anthropic.com/v1/messages', {
    method: 'POST', signal,
    headers: {
      'x-api-key': apiKey,
      'anthropic-version': '2023-06-01',
      'anthropic-dangerous-direct-browser-access': 'true',
      'content-type': 'application/json',
    },
    body: JSON.stringify({
      model: 'claude-haiku-4-5',
      max_tokens: maxTokens,
      stream: streaming,
      messages: [{ role: 'user', content: prompt }],
    }),
  });
  if (!res.ok) { const t = await res.text().catch(() => ''); throw new Error(`${res.status}: ${t}`); }
  if (streaming) {
    const reader = res.body.getReader();
    const dec = new TextDecoder();
    let full = '';
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      for (const line of dec.decode(value).split('\n')) {
        if (!line.startsWith('data: ')) continue;
        try { const d = JSON.parse(line.slice(6)); if (d.type === 'content_block_delta' && d.delta?.text) { full += d.delta.text; onChunk(full); } } catch {}
      }
    }
    return full;
  }
  const data = await res.json();
  return data.content?.[0]?.text || '';
}

// ── Unified AI call (Sprint 61.C) ────────────────────────────────────────────
// ONE path for every AI feature in the app. Prefers the secure server-side
// OpenAI proxy (lib/aiProxy → callAiFeature, no key in the browser); falls back
// to a BYOK Anthropic key (askClaude) only if the proxy isn't configured; else
// returns ''. `feature` must be one of AI_FEATURES. Non-streaming on the proxy
// path — onChunk (if given) is called once with the full text so callers that
// were written for streaming still render.
async function askNGW(feature, prompt, { onChunk, context = null, aiKey, maxTokens = 700, system } = {}) {
  if (isAiProxyConfigured()) {
    const r = await callAiFeature(feature, prompt, context);
    const text = ((r && r.text) || '').trim();
    if (onChunk && text) onChunk(text);
    return text;
  }
  if (aiKey) return await askClaude(aiKey, prompt, { onChunk, maxTokens, system, context });
  return '';
}
// True when ANY AI input path is available (backend proxy OR a BYOK key) — use
// for button visibility / gates so AI works on the backend without a local key.
const aiInputOn = (aiKey) => isAiProxyConfigured() || !!aiKey;

// Small reusable AI button — shows spinner while loading
function AIBtn({ onClick, loading, label = 'AI', style: xtra }) {
  const C = useT();
  const T = useType();
  const aiKey = useAIKey();
  if (!aiInputOn(aiKey)) return null; // hidden only if NO AI path (no backend + no key)
  return (
    <button onClick={onClick} disabled={loading} style={{ background: 'none', border: `1px solid ${C.border}`, borderRadius: 6, cursor: loading ? 'wait' : 'pointer', fontSize: T.caption, fontWeight: FW.semibold, color: C.muted, padding: '3px 8px', display: 'inline-flex', alignItems: 'center', gap: 4, opacity: loading ? 0.6 : 1, flexShrink: 0, ...xtra }}>
      {loading ? <span style={{ display: 'inline-block', width: 10, height: 10, border: `2px solid ${C.muted}`, borderTopColor: 'transparent', borderRadius: '50%', animation: 'spin 0.7s linear infinite' }} /> : null} {loading ? 'Working…' : label}
    </button>
  );
}

