      '@keyframes ceFadeIn { from { opacity: 0; } to { opacity: 1; } }',
      '@keyframes ceAura { 0%, 100% { opacity: 0.45; transform: scale(1); } 50% { opacity: 0.9; transform: scale(1.06); } }',
