      '.ngw-invite button:focus-visible, .ngw-invite a:focus-visible, .ngw-invite input:focus-visible, .ngw-invite textarea:focus-visible, .ngw-invite [role="radio"]:focus-visible, .ngw-invite [role="checkbox"]:focus-visible { outline: 2px solid currentColor !important; outline-offset: 2px !important; }',
      // Skip-to-content link — visible only when focused
