function useBreakpoint() {
  const [w, setW] = useState(() => window.innerWidth);
  useEffect(() => {
    const h = () => setW(window.innerWidth);
    window.addEventListener('resize', h);
    return () => window.removeEventListener('resize', h);
  }, []);
  // mobile < 640 · tablet 640–1023 (portrait iPad included) · tablet-land 1024–1279 · desktop ≥ 1280
  return w < 640 ? 'mobile' : w < 1024 ? 'tablet' : w < 1280 ? 'tablet-land' : 'desktop';
}

// Widescreen flag (≥1536) — a refinement WITHIN the 'desktop' bucket, deliberately
// NOT a new `bp` enum value (that would break the ~10 `bp === 'desktop'` checks app-wide).
// Used only by triage surfaces (Portfolio board, Home command grid) to turn extra
// real-estate into the WORK laid out in columns, not a stretched single column.
// Threshold board-revised 1680→1536: 1680 stranded the 1440/1536 laptops planners
// actually triage on; the leaner column set (no count smear) fits 1536 cleanly.
function useWideScreen() {
  const [wide, setWide] = useState(() => typeof window !== 'undefined' && window.innerWidth >= 1536);
  useEffect(() => {
    const h = () => setWide(window.innerWidth >= 1536);
    window.addEventListener('resize', h);
    return () => window.removeEventListener('resize', h);
  }, []);
  return wide;
}

// ─── Width / measure system ───────────────────────────────────────────────────
// ONE source of truth for content width, chosen by content TYPE (not per-tab), so
// every screen lines up. Applied as `maxWidth: measureFor(tier, isWideScreen)`:
//   reading — prose / a single decision or document / any form (legibility cap)
//   content — dashboards & command surfaces (Home · Command · Decisions · Documents)
//   data    — dense tables & boards that should USE width (Budget · Guests · triage)
//   full    — multi-pane workspaces (Vendors); panes structure the width, inner prose
//             caps at `reading`.
// Each measure binds only when the screen exceeds it and goes fluid below — so MOBILE
// and TABLET are consistent by construction (the same measure governs every device;
// it simply doesn't bind until the viewport is wide enough), no per-breakpoint forks.
// Board ruling (2026-06-11): collapse the old 4-tier measure to TWO tiers so
// the app stops reading as five different widths. `standard` is the default for
// every tab; `wide` is the ONE concession for dense data tables (Budget / Guests
// / Event Day Schedule). The tiers sit only ~80–200px apart so they read as one
// app. The old names (content/data/reading) alias onto the two tiers for back-
// compat: content→standard, data→wide, reading→standard (a form's narrowness is
// a property of its fields, not its page).
const CONTENT_MEASURE = {
  standard: { base: 1200, wide: 1280 },
  wide:     { base: 1360, wide: 1480 },
  // legacy aliases
  content:  { base: 1200, wide: 1280 },
  data:     { base: 1360, wide: 1480 },
  reading:  { base: 1200, wide: 1280 },
};
const measureFor = (tier, wide) =>
  tier === 'full' ? 'none'
  : (CONTENT_MEASURE[tier] || CONTENT_MEASURE.standard)[wide ? 'wide' : 'base'];

// ─── Utilities ───────────────────────────────────────────────────────────────
const fmtD     = (n) => '$' + Number(n || 0).toLocaleString(undefined, { minimumFractionDigits: 0, maximumFractionDigits: 0 });
const uid      = () => Math.random().toString(36).slice(2, 8);
// rsvpToken — the PUBLIC invite secret (?rsvp=CODE). Unlike uid() (a short, guessable
// 6-char id), this must be LONG + unguessable: the link itself is the only gate on the
// public invite/RSVP endpoints (see backend/app/routers/rsvp.py). ~22 url-safe chars of
// crypto-random entropy when available; falls back to Math.random concatenation.
const rsvpToken = () => {
  const ALPHA = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
  const N = 22;
  try {
    const c = (typeof window !== 'undefined' && window.crypto) || null;
    if (c && c.getRandomValues) {
      const bytes = c.getRandomValues(new Uint8Array(N));
      let out = '';
      for (let i = 0; i < N; i++) out += ALPHA[bytes[i] % ALPHA.length];
      return out;
    }
  } catch (e) { /* fall through to Math.random */ }
  let out = '';
  while (out.length < N) out += Math.random().toString(36).slice(2);
  return out.replace(/[^A-Za-z0-9]/g, '').slice(0, N);
};
// rsvpInviteUrl — the ONE builder for a guest invite URL. Emits a link ONLY for a real,
// server-resolvable token (≥16 chars — rsvp.py MIN_CODE_LEN). A short seed/legacy code or
// the old `|| event.id` slug fallback resolves to 404 (guests hit "failed to post" — proven
// by the live RSVP smoke), so we return '' rather than a dead link. One source = no drift.
const rsvpInviteUrl = (event) => {
  const code = event && event.rsvpCode;
  if (typeof code !== 'string' || code.length < 16) return '';
  if (typeof window === 'undefined') return '';
  return `${window.location.origin}${window.location.pathname}?rsvp=${code}`;
};
// getToday + daysUntil now live in ./lib/dates (single source — see import above),
// so the weather window and every countdown agree on the day count.
// Sprint 51 Figma parity: canonical countdown text per CYlmJqDCXEaacCuz9wW3bd
// frames K Command Center (655:60 "104 days from now") and B Event Dashboard
// (548:34 "15 days to event"). Single source of truth — replaces 5 inline
// variants that had drifted into "15d away", "15 days away", "Today!",
// "Complete", and "✓ 15d ago". `short` returns the same vocabulary in tight
// chip form when the surface can't afford full words.
const countdownLabel = (days) => {
  if (days === null || days === undefined) return null;
  if (days === 0) return 'Today';
  if (days > 0)  return `${days} days from now`;
  return `${Math.abs(days)} days ago`;
};
const countdownShort = (days) => {
  if (days === null || days === undefined) return null;
  if (days === 0) return 'Today';
  if (days > 0)  return `${days}d`;
  return `${Math.abs(days)}d ago`;
};
// Countdown WARMS as the day nears (mobile-innovation audit): anticipation should
// grow more present as it approaches, not grey out. Brighter = nearer, all within
// the Studio Matte green/steel palette (no warm gold) — "warming" = rising presence.
const countdownTone = (days, C) => {
  if (days == null) return C.muted;
  if (days < 0)   return C.muted;                 // past — calm
  if (days === 0) return C.success || C.accent;   // today — peak presence (arrived)
  if (days <= 7)  return C.accent;                // this week — lit
  if (days <= 30) return C.accent2 || C.accent;   // weeks out — present
  if (days <= 90) return C.text;                  // a month-plus — quietly present
  return C.muted;                                  // far off — calm
};
const parseMin  = (t) => { if (!t) return null; const [h, m] = t.split(':').map(Number); return h * 60 + (m || 0); };
const fmtDur    = (m) => { if (!m || m <= 0) return ''; const h = Math.floor(m / 60); const r = m % 60; return h > 0 ? (r > 0 ? `${h}h ${r}m` : `${h}h`) : `${r}m`; };
const fmtTime12 = (t) => {
  if (!t) return '—';
  // startTime is stored inconsistently — 12-hour display strings ("3:00 PM") in some paths,
  // 24-hour clock ("15:00") in others. If it's ALREADY 12-hour, pass it through: parsing it as
  // 24h reads "3:00 PM" as h=3, drops the "PM", and re-labels it "3:00 AM" (the cookout-at-3am bug).
  if (/[ap]\.?m\.?/i.test(t)) return t.trim();
  const [h, m] = t.split(':').map(Number);
  if (Number.isNaN(h)) return t; // not a clock value — don't mangle it
  return `${h % 12 || 12}:${String(m || 0).padStart(2, '0')} ${h >= 12 ? 'PM' : 'AM'}`;
};
const fmtDate   = (d) => { if (!d) return '—'; const dt = new Date(d + 'T00:00:00'); return dt.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }); };
const fmtMon    = (ym) => { const [y, m] = ym.split('-'); return new Date(y, m - 1, 1).toLocaleDateString('en-US', { month: 'long', year: 'numeric' }); };
const today8601 = () => new Date().toISOString().slice(0, 10);

// Sprint Date Friction Phase B — universal one-tap native picker helper.
// Spread {...dateInputProps} onto any <input type="date"> to:
//   • show the native picker on first tap (no need to focus, then tap again)
//   • surface the numeric keyboard on mobile for direct typing
// No storage model change. No new UI. Native picker remains the only picker.
const dateInputProps = {
  type: 'date',
  inputMode: 'numeric',
  onFocus: (e) => { try { e.target.showPicker?.(); } catch {} },
  onClick: (e) => { try { e.target.showPicker?.(); } catch {} },
};

// Sprint Date Friction Phase C — chip-date helpers. Compute resolved ISO
// strings only. No relative-storage metadata is introduced; the chip's
// output is a plain string equivalent to what the picker would produce.
//
// addDaysISO(base, n): add n calendar days to an ISO date string (or to
// today when base is empty).
const addDaysISO = (baseIso, n) => {
  const base = baseIso ? new Date(baseIso + 'T00:00:00') : getToday();
  const out = new Date(base);
  out.setDate(out.getDate() + n);
  return out.toISOString().slice(0, 10);
};
// nextWeekendISO(): nearest upcoming Saturday from today. If today IS
// Saturday, returns today; if Sunday, returns next Saturday (6 days).
const nextWeekendISO = () => {
  const d = getToday();
  const day = d.getDay(); // 0 Sun ... 6 Sat
  const add = day === 6 ? 0 : (6 - day + 7) % 7;
  return addDaysISO(today8601(), add);
};
// weekendAfter(): the Saturday after the one returned by nextWeekendISO.
const followingWeekendISO = () => addDaysISO(nextWeekendISO(), 7);
// addMonthsISO(n): nearest-real-day add. Handles end-of-month rollover.
const addMonthsISO = (n) => {
  const d = getToday();
  const m = d.getMonth();
  const target = new Date(d);
  target.setMonth(m + n);
  // Guard end-of-month overflow (e.g., Mar 31 + 1 month → May 1 in JS)
  if (target.getMonth() !== ((m + n) % 12 + 12) % 12) target.setDate(0);
  return target.toISOString().slice(0, 10);
};
// nextFridayISO(): the next Friday strictly after today (a common party night).
const nextFridayISO = () => {
  const day = getToday().getDay(); // 0 Sun..6 Sat
  let add = (5 - day + 7) % 7;
  if (add === 0) add = 7;
  return addDaysISO(today8601(), add);
};
// seasonISO(monthIdx, day): a representative date in the next occurrence of a
// season, at least ~30 days out. Couples/committees think in seasons, not exact
// days — this only POSITIONS the grid; the host still commits the exact day.
const seasonISO = (monthIdx, day) => {
  const t = getToday();
  let cand = new Date(t.getFullYear(), monthIdx, day);
  if ((cand - t) / 86400000 < 30) cand = new Date(t.getFullYear() + 1, monthIdx, day);
  return `${cand.getFullYear()}-${String(monthIdx + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
};
// Board ruling (unanimous): tailor WHICH relative quick-picks appear to the
// event type's plausible planning horizon — never preselect a date, never label
// one "recommended." Labels stay literal time spans; the host commits every date.
const LONG_LEAD_TYPES = new Set(['Wedding', 'Vow Renewal', 'Quinceañera', 'Fundraiser / Gala']);
