  teal:       '#2FB6B0',
  cyan:       '#23D3EE',
  magenta:    '#FF4FC3',
  periwinkle: '#7C8CFF',
  brown:      '#C8703C', // Ethiopian buna
  violet:     '#7C6FA6', // mourning violet
