// Returns true if a subtask should be hidden given the event's current food choices.
// Subtasks carry an optional skipWhenChoice: { <decisionId>: [<value>, ...] } field.
// When the host's explicit pick for that decision matches any listed value, the step
// is irrelevant (e.g. "Put down the deposit" when they chose "Host cooks everything").
function subtaskSkipped(sub, foodChoices) {
  if (!sub.skipWhenChoice || !foodChoices) return false;
  return Object.entries(sub.skipWhenChoice).some(([id, values]) =>
    Array.isArray(values) && values.includes(foodChoices[id])
  );
}

function TaskModal({ task, eventDate, foodChoices, onClose, onChange, onDelete }) {
  const C          = useT();
  const s          = makeS(C);
  const showToast  = useToast();
  const aiKey      = useAIKey();
  // Sprint 52B — roster-backed task ownership (free text still supported).
  const roster     = useMemo(() => loadTeamRoster(), []);
  const ownerSelectValue = (task.ownerId && roster.some(m => m.id === task.ownerId)) ? task.ownerId : '';
  const pickOwner  = (id) => {
    if (!id) { onChange('ownerId', ''); return; }
    const m = roster.find(x => x.id === id);
    if (m) { onChange('ownerId', m.id); onChange('owner', m.name); }
  };
  const [confirmDel, setConfirmDel] = useState(false);
  const [taskNotesLoad, setTaskNotesLoad] = useState(false);
  useEffect(() => {
    const handler = e => { if (e.key === 'Escape') onClose(); };
    document.addEventListener('keydown', handler);
    // Sprint 60.U.3 cont. — body scroll lock parity. Edit-modal users
    // should not see the page behind scroll while typing inside the modal.
    const prevOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => {
      document.removeEventListener('keydown', handler);
      document.body.style.overflow = prevOverflow;
    };
  }, [onClose]);
  const genTaskNotes = async () => {
    if (!aiInputOn(aiKey)) return;
    setTaskNotesLoad(true);
    const prompt = `You are an event planning assistant. Write a brief, practical note (2-4 sentences) for this planning task. Include: who should own it, how to execute it, and any key questions to answer. Be specific and actionable.\n\nTask: "${task.task}"\nPhase: ${task.week}\nCurrent owner: ${task.owner || 'not set'}\nCurrent notes: ${task.notes || '(none)'}\n\nWrite the note:`;
    try { await askNGW('checklist_help', prompt, { maxTokens: 120, onChunk: t => onChange('notes', t), aiKey }); }
    catch(e) { /* silent */ }
    setTaskNotesLoad(false);
  };
  return (
    <>
      <div onClick={onClose} style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.55)', zIndex: 40 }} />
      <div onKeyDown={e => { if (e.key === 'Escape') onClose(); e.stopPropagation(); }} style={{ position: 'fixed', right: 0, top: 0, bottom: 0, width: 400, background: C.surface, borderLeft: `1px solid ${C.border}`, zIndex: 50, display: 'flex', flexDirection: 'column' }}>
        <div style={{ padding: '20px 24px 16px', borderBottom: `1px solid ${C.border}`, flexShrink: 0 }}>
          <div style={{ display: 'flex', alignItems: 'flex-start', gap: 10, marginBottom: 8 }}>
            <button onClick={() => onChange('done', !task.done)} style={{ flexShrink: 0, marginTop: 3, width: 24, height: 24, borderRadius: '50%', border: `2px solid ${task.done ? C.success : C.border}`, background: task.done ? C.success + '22' : 'none', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', color: C.success, fontSize: T.secondary }}>
              {task.done ? '✓' : ''}
            </button>
            {/* Title — a wrapping, auto-growing field so a long task is fully readable
                (was a single-line input that truncated). */}
            <textarea rows={1} value={task.task} placeholder="Task name"
              ref={el => { if (el) { el.style.height = 'auto'; el.style.height = el.scrollHeight + 'px'; } }}
              onChange={e => { onChange('task', e.target.value); e.target.style.height = 'auto'; e.target.style.height = e.target.scrollHeight + 'px'; }}
              style={{ ...s.input, fontSize: T.title, fontWeight: FW.bold, letterSpacing: '-0.02em', flex: 1, lineHeight: 1.35, resize: 'none', overflow: 'hidden', minHeight: 38, textDecoration: task.done ? 'line-through' : 'none', color: task.done ? C.muted : C.text }} />
            <button aria-label="Close" onClick={onClose} style={{ ...s.btn('ghost'), fontSize: T.title, padding: '4px 10px', flexShrink: 0 }}>✕</button>
          </div>
          {task.done && <div style={{ fontSize: T.caption, color: C.success, fontWeight: FW.semibold, paddingLeft: 34 }}>Completed ✓</div>}
          {/* Sprint 60.U.3 10+ — NO GUESSWORK rail. Replaces the bare truth
              line. Explains what Event Boss auto-tracks for this task. */}
          {(() => {
            const steelTopT = C.accentTopGrad || C.accent;
            return (
              <div style={{
                display: 'flex', gap: 10, alignItems: 'flex-start',
                padding: '8px 10px', marginTop: 8,
                background: `linear-gradient(180deg, ${steelTopT}14 0%, ${steelTopT}07 100%)`,
                border: `1px solid ${steelTopT}33`,
                borderLeft: `3px solid ${steelTopT}`,
                borderRadius: 8,
              }}>
                <span aria-hidden style={{
                  flexShrink: 0, width: 20, height: 20, borderRadius: '50%',
                  background: `${steelTopT}22`, color: steelTopT,
                  display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
                  fontSize: T.caption, fontWeight: FW.heavy, marginTop: 1,
                }}>✓</span>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ fontSize: T.eyebrow, fontWeight: FW.heavy, letterSpacing: '0.16em', color: steelTopT }}>NO GUESSWORK</div>
                  <div style={{ fontSize: T.caption, color: C.text, lineHeight: 1.45, marginTop: 1 }}>
                    Edits autosave to this event's planning timeline. Event Boss tracks owner, due date, and phase.
                  </div>
                </div>
              </div>
            );
          })()}
        </div>
        <div style={{ flex: 1, overflowY: 'auto', padding: '16px 24px' }}>
          <div style={{ marginBottom: 16 }}>
            <label style={{ fontSize: T.caption, color: C.muted, display: 'block', marginBottom: 3 }}>Planning Phase</label>
            <select style={s.input} value={task.week} onChange={e => onChange('week', e.target.value)}>
              {[...Object.keys(PHASE_OFFSET), 'Custom'].map(p => {
                const pd = eventDate ? phaseDate(p, eventDate) : null;
                return <option key={p} value={p}>{pd ? `${pd} — ${p}` : p}</option>;
              })}
            </select>
          </div>
          <div style={{ marginBottom: 16 }}>
            <label style={{ fontSize: T.caption, color: C.muted, display: 'block', marginBottom: 3 }}>Owner / Responsible</label>
            {roster.length > 0 && (
              <select data-testid="task-owner-member" style={{ ...s.input, marginBottom: 6 }} value={ownerSelectValue} onChange={e => pickOwner(e.target.value)}>
                <option value="">Type a name (free text)</option>
                {roster.map(m => <option key={m.id} value={m.id}>{m.name}{m.roleLabel ? ` · ${m.roleLabel}` : ''}</option>)}
              </select>
            )}
            <input style={s.input} value={task.owner || ''} placeholder="Planner, Couple, Vendor…" onChange={e => { onChange('owner', e.target.value); onChange('ownerId', ''); }} />
          </div>
          {/* Steps — checkable subtasks. Break the task into the actual to-dos; each
              checks off with live progress. Persists on task.subtasks. */}
          {(() => {
            const subs = Array.isArray(task.subtasks) ? task.subtasks : [];
            // Filter out subtasks that are irrelevant given the host's food choices.
            // Hidden steps don't count toward progress and don't appear in the editor.
            const visibleSubs = subs.filter(s => !subtaskSkipped(s, foodChoices));
            const doneN = visibleSubs.filter(x => x.done).length;
            const setSubs = (next) => onChange('subtasks', next);
            const patchSub = (id, patch) => setSubs(subs.map(x => x.id === id ? { ...x, ...patch } : x));
            return (
              <div style={{ marginBottom: 16 }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 6 }}>
                  <label style={{ fontSize: T.caption, color: C.muted }}>Steps</label>
                  {visibleSubs.length > 0 && <span style={{ fontSize: T.caption, fontWeight: FW.semibold, color: doneN === visibleSubs.length ? C.success : C.muted }}>{doneN} of {visibleSubs.length} done</span>}
                </div>
                <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
                  {visibleSubs.map(sub => (
                    <div key={sub.id} style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                      <button type="button" onClick={() => patchSub(sub.id, { done: !sub.done })} aria-label={sub.done ? 'Mark step not done' : 'Mark step done'}
                        style={{ flexShrink: 0, width: 20, height: 20, borderRadius: 5, border: `1.5px solid ${sub.done ? C.success : C.border}`, background: sub.done ? C.success + '22' : 'transparent', color: C.success, cursor: 'pointer', fontSize: T.secondary, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>{sub.done ? '✓' : ''}</button>
                      <input value={sub.text} placeholder="Step…" onChange={e => patchSub(sub.id, { text: e.target.value })}
                        style={{ ...s.input, flex: 1, textDecoration: sub.done ? 'line-through' : 'none', color: sub.done ? C.muted : C.text }} />
                      <button type="button" onClick={() => setSubs(subs.filter(x => x.id !== sub.id))} aria-label="Remove step" style={{ flexShrink: 0, background: 'transparent', border: 'none', color: C.muted, cursor: 'pointer', fontSize: T.body, lineHeight: 1 }}>×</button>
                    </div>
                  ))}
                </div>
                <button type="button" onClick={() => setSubs([...subs, { id: uid(), text: '', done: false }])}
                  style={{ marginTop: subs.length ? 8 : 0, background: 'transparent', border: `1px solid ${C.border}`, color: C.accent, fontWeight: FW.bold, fontSize: T.secondary, cursor: 'pointer', padding: '7px 12px', borderRadius: 8 }}>+ Add a step</button>
              </div>
            );
          })()}
          <div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 3 }}>
              <label style={{ fontSize: T.caption, color: C.muted }}>Notes</label>
              <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                <AIBtn onClick={genTaskNotes} loading={taskNotesLoad} label="Fill in details" />
                <VoiceButton onResult={t => onChange('notes', (task.notes ? task.notes + ' ' : '') + t)} />
              </div>
            </div>
            <textarea style={{ ...s.input, minHeight: 90, resize: 'vertical', fontFamily: 'inherit' }} value={task.notes || ''} placeholder="Details, links, follow-up actions…" onChange={e => onChange('notes', e.target.value)} />
          </div>
        </div>
        <div style={{ padding: '14px 24px', borderTop: `1px solid ${C.border}`, flexShrink: 0 }}>
          {confirmDel ? (
            <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
              <span style={{ fontSize: T.secondary, color: C.muted }}>Delete this task?</span>
              <button style={s.btn('danger')} onClick={() => { showToast('Task deleted'); onDelete(); onClose(); }}>Yes, delete</button>
              <button style={s.btn()} onClick={() => setConfirmDel(false)}>Cancel</button>
            </div>
          ) : (
            <button style={{ ...s.btn('danger'), width: '100%' }} onClick={() => setConfirmDel(true)}>Delete Task</button>
          )}
        </div>
      </div>
    </>
  );
}

// ─── Budget Modal ─────────────────────────────────────────────────────────────

function BudgetModal({ row, committed, categoryVendors, onClose, onChange, onDelete, onOpenVendor }) {
  const C          = useT();
  const s          = makeS(C);
  const stageCLR   = STAGE_CLR(C);
  const showToast  = useToast();
  const fileRef    = useRef(null);
  const cameraRef  = useRef(null);
  const isPaid     = !!row.paid;
  const [confirmDel, setConfirmDel] = useState(false);
  // Sprint 60.U.3 cont. — body scroll lock parity.
  useEffect(() => {
    const prev = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => { document.body.style.overflow = prev; };
  }, []);
  const [synced, setSynced] = useState(false);

  // ─── Sprint 59C: Vendor payment source-of-truth lock ─────────────────────
  // When a Budget row has at least one committed vendor, the vendor record
  // (not the Budget row) is canonical for payment status + method. The row's
  // own `paid` + `paymentMethod` controls are hidden — replaced by a
  // read-only mirror of the primary vendor's payment state plus an
  // "Open vendor" CTA that routes to the Vendor cockpit. `budgeted`, `actual`,
  // `notes`, and `receiptPhoto` remain editable on the row — those are
  // planning inputs, not vendor truth.
  const committedVendors = (categoryVendors || []).filter(vendorIsCommitted);
  const isVendorLinked   = committedVendors.length > 0;
  // Primary mirror vendor: the largest unpaid commitment, falling back to the
  // largest cost overall. Drives the header chip and the inline CTA copy.
  const primaryVendor    = isVendorLinked
    ? ([...committedVendors].sort((a, b) => vendorBalance(b) - vendorBalance(a) || (b.cost || 0) - (a.cost || 0))[0])
    : null;
  const soonestDays      = isVendorLinked ? soonestUnpaidDueDays(categoryVendors, row.category) : null;
  const allBalancesPaid  = isVendorLinked && committedVendors.every(v => v.balancePaid);
  const mirrorMethod     = (primaryVendor && (primaryVendor.balanceMethod || primaryVendor.depositMethod)) || null;
  const mirrorPaidLabel  = allBalancesPaid
    ? 'Paid in full'
    : primaryVendor && primaryVendor.depositPaid
      ? 'Deposit paid'
      : 'Unpaid';

  // Local state for numeric inputs so user can clear the field and retype
  const [localActual,   setLocalActual]   = useState(() => String(row.actual));
  const [localBudgeted, setLocalBudgeted] = useState(() => String(row.budgeted));

  // Keep local in sync if parent updates row (e.g. new modal opened).
  // Intentionally keyed to row.id only — we reset when switching rows, not on every value change.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => { setLocalActual(String(row.actual));   }, [row.id]);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => { setLocalBudgeted(String(row.budgeted)); }, [row.id]);

  const previewActual   = Number(localActual)   || 0;
  const previewBudgeted = Number(localBudgeted) || 0;
  const balDue = committed - previewActual;

  const handlePhoto = (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (ev) => onChange('receiptPhoto', ev.target.result);
    reader.readAsDataURL(file);
  };

  return (
    <>
      <div onClick={onClose} style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.55)', zIndex: 40 }} />
      <div onKeyDown={e => { if (e.key === 'Escape') onClose(); e.stopPropagation(); }} style={{ position: 'fixed', right: 0, top: 0, bottom: 0, width: 'min(380px, 100vw)', background: C.surface, borderLeft: `1px solid ${C.border}`, zIndex: 50, display: 'flex', flexDirection: 'column' }}>
        <div style={{ padding: '20px 24px 16px', borderBottom: `1px solid ${C.border}`, flexShrink: 0 }}>
          <div style={{ display: 'flex', alignItems: 'flex-start', gap: 8, marginBottom: 12 }}>
            <input style={{ ...s.input, fontSize: T.title, fontWeight: FW.bold, letterSpacing: '-0.02em', flex: 1, padding: '5px 8px' }} value={row.category} onChange={e => onChange('category', e.target.value)} />
            <button aria-label="Close" onClick={onClose} style={{ ...s.btn('ghost'), fontSize: T.title, padding: '4px 10px', flexShrink: 0 }}>✕</button>
          </div>
          <div style={{ display: 'flex', gap: 20, alignItems: 'center' }}>
            <div>
              <div style={{ fontSize: T.caption, color: C.muted, marginBottom: 2 }}>Balance Due</div>
              {/* Sprint 59C: payment status color discipline — amber only
                  when there's an actionable due date ≤30d; red for overdue;
                  green for paid; neutral when no due date exists yet. */}
              <div style={{ ...s.statNum(committed === 0 ? C.muted : paymentStatusColor(C, balDue <= 0, soonestDays)), fontSize: T.display }}>
                {committed === 0 ? '—' : balDue <= 0 ? 'Paid' : fmtD(balDue)}
              </div>
            </div>
            {committed > 0 && (
              <div>
                <div style={{ fontSize: T.caption, color: C.muted, marginBottom: 2 }}>Committed</div>
                <div style={{ ...s.statNum(committed > row.budgeted ? C.danger : C.accent2), fontSize: T.display }}>{fmtD(committed)}</div>
              </div>
            )}
            <div style={{ marginLeft: 'auto' }}>
              {isVendorLinked ? (
                /* Sprint 59C: vendor-linked rows mirror the vendor's payment
                   truth (paid state + method) and route edits to the Vendor
                   cockpit. Local row.paid + row.paymentMethod are suppressed
                   so the planner doesn't fight two sources of truth. */
                <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: 4 }}>
                  <span style={{ ...s.pill(paymentStatusColor(C, allBalancesPaid, soonestDays)), fontSize: T.caption }}>
                    {allBalancesPaid ? '✓ Paid' : mirrorPaidLabel}
                    {mirrorMethod ? ` · ${mirrorMethod}` : ''}
                  </span>
                  <span style={{ fontSize: T.caption, color: C.muted }}>Vendor-owned</span>
                </div>
              ) : (
                <button
                  onClick={() => { onChange('paid', !isPaid); if (!isPaid && !row.paymentMethod) onChange('paymentMethod', 'Credit Card'); }}
                  style={{ ...s.btn(isPaid ? 'success' : 'default'), fontSize: T.secondary, padding: '6px 14px', fontWeight: FW.bold }}
                >
                  {isPaid ? '✓ Paid' : '○ Unpaid'}
                </button>
              )}
            </div>
          </div>
          {/* Sprint 60.U.3 10+ — NO GUESSWORK rail. Same dual-mode message
              preserved (vendor-linked vs unlinked) but elevated to the
              premium steel-blue rail style. */}
          {(() => {
            const steelTopB = C.accentTopGrad || C.accent;
            return (
              <div style={{
                display: 'flex', gap: 10, alignItems: 'flex-start',
                padding: '8px 10px', marginTop: 12,
                background: `linear-gradient(180deg, ${steelTopB}14 0%, ${steelTopB}07 100%)`,
                border: `1px solid ${steelTopB}33`,
                borderLeft: `3px solid ${steelTopB}`,
                borderRadius: 8,
              }}>
                <span aria-hidden style={{
                  flexShrink: 0, width: 20, height: 20, borderRadius: '50%',
                  background: `${steelTopB}22`, color: steelTopB,
                  display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
                  fontSize: T.caption, fontWeight: FW.heavy, marginTop: 1,
                }}>✓</span>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ fontSize: T.eyebrow, fontWeight: FW.heavy, letterSpacing: '0.16em', color: steelTopB }}>NO GUESSWORK</div>
                  <div style={{ fontSize: T.caption, color: C.text, lineHeight: 1.45, marginTop: 1 }}>
                    {isVendorLinked
                      ? 'Edits autosave. Payment status is owned by the vendor record — Event Boss keeps them in sync.'
                      : 'Edits autosave to this budget line. Event Boss tracks budget vs. actual.'}
                  </div>
                </div>
              </div>
            );
          })()}
        </div>

        <div style={{ flex: 1, overflowY: 'auto', padding: '16px 24px' }}>
          <div style={{ display: 'flex', gap: 12, marginBottom: 16 }}>
            <div style={{ flex: 1 }}>
              <label style={{ fontSize: T.caption, color: C.muted, display: 'block', marginBottom: 3 }}>Budgeted</label>
              <input style={s.input} type="number" value={localBudgeted}
                onChange={e => setLocalBudgeted(e.target.value)}
                onBlur={e => { const v = Number(e.target.value) || 0; setLocalBudgeted(String(v)); onChange('budgeted', v); }}
              />
            </div>
            <div style={{ flex: 1 }}>
              <label style={{ fontSize: T.caption, color: C.muted, display: 'block', marginBottom: 3 }}>Spent</label>
              <input style={{ ...s.input, borderColor: previewActual > previewBudgeted && previewBudgeted > 0 ? C.danger + '88' : undefined }} type="number" value={localActual}
                onChange={e => setLocalActual(e.target.value)}
                onBlur={e => { const v = Number(e.target.value) || 0; setLocalActual(String(v)); onChange('actual', v); }}
              />
            </div>
          </div>
          {categoryVendors?.length === 1 && categoryVendors[0].cost > 0 && (
            <div style={{ display: 'flex', gap: 8, alignItems: 'center', marginTop: 4, marginBottom: 12 }}>
              <button
                onClick={() => {
                  const v = categoryVendors[0];
                  onChange('budgeted', v.cost);
                  setLocalBudgeted(String(v.cost));
                  onChange('actual', v.depositPaid ? (v.balancePaid ? v.cost : v.depositAmt) : 0);
                  setLocalActual(String(v.depositPaid ? (v.balancePaid ? v.cost : v.depositAmt) : 0));
                  onChange('notes', v.name);
                  setSynced(true);
                  setTimeout(() => setSynced(false), 2000);
                }}
                style={{ ...s.btn(synced ? 'success' : 'ghost'), fontSize: T.caption, padding: '3px 10px' }}
              >
                {synced ? '✓ Synced' : `⇄ Sync from ${categoryVendors[0].name}`}
              </button>
              <span style={{ fontSize: T.caption, color: C.muted }}>${categoryVendors[0].cost.toLocaleString()} total · ${categoryVendors[0].depositAmt.toLocaleString()} deposit</span>
            </div>
          )}

          {/* Payment method — manual rows only. For vendor-linked rows the
              payment method lives on the vendor record; show a read-only
              mirror with a route-to-vendor CTA instead of a fight-the-vendor
              dropdown. Sprint 59C. */}
          {isVendorLinked ? (
            <div style={{ marginBottom: 16, padding: '10px 12px', background: C.bg, border: `1px dashed ${C.border}`, borderRadius: 8 }}>
              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 10 }}>
                <div>
                  <div style={{ fontSize: T.caption, color: C.muted, marginBottom: 2 }}>Payment method</div>
                  <div style={{ fontSize: T.secondary, fontWeight: FW.semibold, color: C.text }}>
                    {mirrorMethod || <span style={{ color: C.muted, fontWeight: FW.regular }}>— not set on vendor —</span>}
                  </div>
                </div>
                {primaryVendor && onOpenVendor && (
                  <button onClick={() => onOpenVendor(primaryVendor.id, 'payment')} style={{ background: 'none', border: 'none', cursor: 'pointer', color: C.accent, fontWeight: FW.semibold, fontSize: T.caption, padding: '2px 4px', minHeight: 0 }}>
                    Open payment details →
                  </button>
                )}
              </div>
              <div style={{ fontSize: T.caption, color: C.muted, marginTop: 6, lineHeight: 1.4 }}>
                Payment details live on the vendor record. Edit on the vendor to keep one source of truth.
              </div>
            </div>
          ) : (
            <div style={{ marginBottom: 16 }}>
              <label style={{ fontSize: T.caption, color: C.muted, display: 'block', marginBottom: 3 }}>Payment Method</label>
              <select style={s.input} value={row.paymentMethod || ''} onChange={e => onChange('paymentMethod', e.target.value)}>
                <option value="">— not set —</option>
                {PAY_METHODS.map(m => <option key={m}>{m}</option>)}
              </select>
            </div>
          )}

          <div style={{ marginBottom: 16 }}>
            <label style={{ fontSize: T.caption, color: C.muted, display: 'block', marginBottom: 3 }}>Notes</label>
            <textarea style={{ ...s.input, minHeight: 80, resize: 'vertical', fontFamily: 'inherit' }} value={row.notes} placeholder="Vendor name, invoice #, details…" onChange={e => onChange('notes', e.target.value)} />
          </div>

          {/* Receipt photo */}
          <div style={{ marginBottom: 16 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 6 }}>
              <label style={{ fontSize: T.caption, color: C.muted }}>Receipt</label>
              {row.receiptPhoto && (
                <button style={{ ...s.btn('danger'), fontSize: T.caption, padding: '2px 8px' }} onClick={() => onChange('receiptPhoto', null)}>Remove</button>
              )}
            </div>
            {row.receiptPhoto ? (
              <img src={row.receiptPhoto} alt="Receipt" style={{ width: '100%', borderRadius: 8, border: `1px solid ${C.border}`, maxHeight: 300, objectFit: 'contain', background: C.bg }} />
            ) : (
              <div style={{ display: 'flex', gap: 6 }}>
                <button style={{ ...s.btn(), flex: 1, padding: '9px 6px', fontSize: T.secondary, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 5 }} onClick={() => cameraRef.current?.click()}>Camera</button>
                <button style={{ ...s.btn(), flex: 1, padding: '9px 6px', fontSize: T.secondary, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 5 }} onClick={() => fileRef.current?.click()}>Choose File</button>
              </div>
            )}
            <input ref={fileRef}   type="file" accept="image/*"                       style={{ display: 'none' }} onChange={handlePhoto} />
            <input ref={cameraRef} type="file" accept="image/*" capture="environment" style={{ display: 'none' }} onChange={handlePhoto} />
          </div>

          <ProgressBar pct={previewBudgeted > 0 ? (previewActual / previewBudgeted) * 100 : 0} color={previewActual > previewBudgeted && previewBudgeted > 0 ? C.danger : undefined} />
          <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: T.caption, color: C.muted, marginTop: 4 }}>
            <span style={{ color: previewActual > previewBudgeted && previewBudgeted > 0 ? C.danger : C.text, fontWeight: FW.semibold }}>{fmtD(previewActual)} spent</span>
            <span>{fmtD(previewBudgeted)} budgeted</span>
          </div>

          {/* Linked vendors in this budget category. Sprint 59C: each row
              gets an "Open vendor" CTA so payment edits route to the canonical
              owner. Balance-due color follows the payment status discipline
              (amber only when ≤30d, red overdue, neutral otherwise). */}
          {categoryVendors && categoryVendors.length > 0 && (
            <div style={{ marginTop: 20 }}>
              <div style={{ fontSize: T.caption, fontWeight: FW.bold, textTransform: 'uppercase', letterSpacing: '0.08em', color: C.muted, marginBottom: 10 }}>Vendors in this category</div>
              <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
                {categoryVendors.map(v => {
                  const bal      = vendorBalance(v);
                  const dueDays  = v.payDueDate ? daysUntil(v.payDueDate) : null;
                  const balColor = paymentStatusColor(C, false, dueDays);
                  return (
                    <div key={v.id} style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '8px 12px', borderRadius: 8, background: C.bg, border: `1px solid ${C.border}` }}>
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <div style={{ fontSize: T.secondary, fontWeight: FW.semibold, color: C.text }}>{v.name}</div>
                        <div style={{ fontSize: T.caption, color: C.muted }}>{v.status}</div>
                      </div>
                      <div style={{ textAlign: 'right', flexShrink: 0 }}>
                        <div style={{ fontSize: T.secondary, fontWeight: FW.bold }}>{fmtD(v.cost)}</div>
                        {bal > 0 && <div style={{ fontSize: T.caption, color: balColor }}>{fmtD(bal)} due{typeof dueDays === 'number' ? ` · ${dueDays < 0 ? `${-dueDays}d overdue` : `${dueDays}d`}` : ''}</div>}
                        {v.balancePaid && <div style={{ fontSize: T.caption, color: C.success }}>Paid ✓</div>}
                      </div>
                      <span style={s.pill(stageCLR[v.status] || C.muted)}>{v.status}</span>
                      {onOpenVendor && (
                        <button
                          onClick={() => onOpenVendor(v.id, 'payment')}
                          title={`Open ${v.name}'s payment details`}
                          aria-label={`Open ${v.name} payment details`}
                          style={{ background: 'none', border: 'none', cursor: 'pointer', color: C.accent, fontWeight: FW.semibold, fontSize: T.caption, padding: '2px 4px', minHeight: 0, flexShrink: 0 }}
                        >
                          Open payment details →
                        </button>
                      )}
                    </div>
                  );
                })}
              </div>
            </div>
          )}
        </div>

        <div style={{ padding: '14px 24px', borderTop: `1px solid ${C.border}`, flexShrink: 0 }}>
          {confirmDel ? (
            <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
              <span style={{ fontSize: T.secondary, color: C.muted }}>Delete this budget line?</span>
              <button style={s.btn('danger')} onClick={() => { showToast('Budget line deleted'); onDelete(); onClose(); }}>Yes, delete</button>
              <button style={s.btn()} onClick={() => setConfirmDel(false)}>Cancel</button>
            </div>
          ) : (
            <button style={{ ...s.btn('danger'), width: '100%' }} onClick={() => setConfirmDel(true)}>Delete Budget Line</button>
          )}
        </div>
      </div>
    </>
  );
}

