// Best "City, ST" string for an event, for weather geocoding: structured city/state
// first, then the picked metro, then free-text venue. Empty when truly unknown.
// Single source of truth for "where is this event" — every location-aware feature
// (weather, store distances, pricing) resolves through here so they never disagree.
// Checks every place a location can land: the structured address from the wizard /
// "Where's it happening?" (venueCity/State/Address), the city/state, the picked metro,
// a real venue string — then defaults to the host's remembered HOME city when it's an
// at-home event with nothing explicit. Returns '' only when truly nothing is known.
function eventGeoQuery(event, profile) {
  if (!event) return '';
  const st = String(event.state || event.venueState || '').trim().toUpperCase();
  const city = String(event.venueCity || event.city || '').trim();
  if (city && US_STATES.includes(st)) return `${city}, ${st}, US`;
  const addr = String(event.venueAddress || '').trim();
  if (addr) return addr;
  const g = event.market && METRO_GEO[event.market];
  if (g) return `${g.city}, ${g.state}, US`;
  // METRO_GEO covers fewer metros than the create-flow dropdown (METRO_MARKETS) — so a
  // host who picked e.g. Miami/SF/Boston set event.market but METRO_GEO missed it. Resolve
  // the picked market through the CANONICAL dropdown list so every choice yields a city.
  const mk = event.market && METRO_MARKETS.find((m) => m.id === event.market);
  if (mk && mk.label) return mk.label.split(/[/(]/)[0].trim(); // "San Francisco / Bay Area" → "San Francisco"
  if (city) return st ? `${city}, ${st}` : city;
  const v = String(event.venue || '').trim();
  if (v && !/^(host'?s home|our (place|home|backyard)|home)$/i.test(v)) return v;
  // Host-home default — an at-home event with no explicit place uses the HOST's own home
  // location from their profile (the user's home), then the remembered city. This is what
  // makes "default to the user's home" actually work for at-home gatherings.
  if (profile) {
    const pmk = profile.metroMarket || profile.market;
    const pg = pmk && METRO_GEO[pmk];
    if (pg) return `${pg.city}, ${pg.state}, US`;
    const pm = pmk && METRO_MARKETS.find((m) => m.id === pmk);
    if (pm && pm.label) return pm.label.split(/[/(]/)[0].trim();
    const pcity = String(profile.city || '').trim();
    if (pcity) { const pst = String(profile.state || '').trim().toUpperCase(); return pst ? `${pcity}, ${pst}` : pcity; }
    const paddr = String(profile.address || '').trim();
    if (paddr) return paddr;
  }
  try {
    const hc = (typeof localStorage !== 'undefined' && localStorage.getItem('ngw-host-city')) || '';
    const hs = (typeof localStorage !== 'undefined' && localStorage.getItem('ngw-host-state')) || '';
    if (hc.trim()) return hs.trim() ? `${hc.trim()}, ${hs.trim()}` : hc.trim();
  } catch (e) { /* storage blocked */ }
  return '';
}

// US state → IANA timezone. We stamp the guest's calendar entry with the EVENT's zone
// so an out-of-zone guest sees the right hour (a floating local time would shift to
// THEIR device zone — e.g. a 7 PM Nashville gala showing as 8 PM for a New York guest).
// Covers the common US zones; a handful of split-zone states use their majority zone
// (the city override below corrects the well-known exceptions). Returns null when the
// state is unknown so the caller can fall back to the browser zone, then floating.
const US_STATE_TZ = {
  // Eastern
  CT: 'America/New_York', DE: 'America/New_York', DC: 'America/New_York', FL: 'America/New_York',
  GA: 'America/New_York', ME: 'America/New_York', MD: 'America/New_York', MA: 'America/New_York',
  NH: 'America/New_York', NJ: 'America/New_York', NY: 'America/New_York', NC: 'America/New_York',
  OH: 'America/New_York', PA: 'America/New_York', RI: 'America/New_York', SC: 'America/New_York',
  VT: 'America/New_York', VA: 'America/New_York', WV: 'America/New_York', MI: 'America/New_York',
  IN: 'America/New_York',
  // Central
  AL: 'America/Chicago', AR: 'America/Chicago', IL: 'America/Chicago', IA: 'America/Chicago',
  KS: 'America/Chicago', KY: 'America/Chicago', LA: 'America/Chicago', MN: 'America/Chicago',
  MS: 'America/Chicago', MO: 'America/Chicago', NE: 'America/Chicago', ND: 'America/Chicago',
  OK: 'America/Chicago', SD: 'America/Chicago', TN: 'America/Chicago', TX: 'America/Chicago',
  WI: 'America/Chicago',
  // Mountain
  CO: 'America/Denver', MT: 'America/Denver', NM: 'America/Denver', UT: 'America/Denver',
  WY: 'America/Denver', ID: 'America/Denver',
  // Mountain (no DST)
  AZ: 'America/Phoenix',
  // Pacific
  CA: 'America/Los_Angeles', NV: 'America/Los_Angeles', OR: 'America/Los_Angeles', WA: 'America/Los_Angeles',
  // Outside CONUS
  AK: 'America/Anchorage', HI: 'Pacific/Honolulu',
};

// Well-known city overrides for split-zone states (the state's majority zone above is
// wrong for these). Keyed lowercase city → IANA zone.
const US_CITY_TZ = {
  'el paso': 'America/Denver',          // TX is Central, El Paso is Mountain
  'miami': 'America/New_York',          // FL (already Eastern, explicit for clarity)
  'pensacola': 'America/Chicago',       // FL panhandle is Central
};

// Resolve an event's IANA timezone from its location. Returns a zone string, or '' when
// we can't place it (caller falls back to the browser zone, then floating local time).
function eventTimeZone(event) {
  if (!event) return '';
  const city = String(event.venueCity || event.city || '').trim().toLowerCase();
  if (city && US_CITY_TZ[city]) return US_CITY_TZ[city];
  let st = String(event.state || event.venueState || '').trim().toUpperCase();
  if (!st) {
    // No explicit state — parse one out of the canonical geo string ("Nashville, TN, US").
    try {
      const m = String(eventGeoQuery(event) || '').match(/,\s*([A-Z]{2})\b/);
      if (m) st = m[1];
    } catch (e) { /* ignore */ }
  }
  if (st && US_STATE_TZ[st]) return US_STATE_TZ[st];
  return '';
}

// Compute the UTC instant for a wall-clock {h, m} on a given YYYY-MM-DD in an IANA zone,
// returned as a basic-format UTC stamp "YYYYMMDDTHHMMSSZ" for an .ics DTSTART. Using a
// real UTC instant (rather than TZID + a hand-rolled VTIMEZONE) is the robust path: every
// calendar client renders it at the correct local hour with no VTIMEZONE to get wrong.
// Returns '' if the zone is unknown/unsupported by Intl in this runtime.
function zonedWallTimeToUtcStamp(ymd, h, m, zone) {
  if (!zone) return '';
  const [Y, Mo, D] = String(ymd).split('-').map((n) => parseInt(n, 10));
  if (!Y || !Mo || !D) return '';
  try {
    // Find the UTC ms whose rendered wall time in `zone` equals the target wall time.
    // Start from the naive UTC guess, then correct by the zone's offset at that instant.
    const targetUtcGuess = Date.UTC(Y, Mo - 1, D, h, m, 0);
    const dtf = new Intl.DateTimeFormat('en-US', {
      timeZone: zone, hour12: false,
      year: 'numeric', month: '2-digit', day: '2-digit',
      hour: '2-digit', minute: '2-digit', second: '2-digit',
    });
    const partsToMs = (ms) => {
      const p = dtf.formatToParts(new Date(ms)).reduce((a, x) => { a[x.type] = x.value; return a; }, {});
      let hh = parseInt(p.hour, 10); if (hh === 24) hh = 0;  // some engines render midnight as 24
      return Date.UTC(parseInt(p.year, 10), parseInt(p.month, 10) - 1, parseInt(p.day, 10), hh, parseInt(p.minute, 10), parseInt(p.second, 10));
    };
    // offset = (what the guess renders as) − (what we wanted); subtract it to land on target.
    const offset = partsToMs(targetUtcGuess) - targetUtcGuess;
    const real = targetUtcGuess - offset;
    const d = new Date(real);
    const pad = (n) => String(n).padStart(2, '0');
    return `${d.getUTCFullYear()}${pad(d.getUTCMonth() + 1)}${pad(d.getUTCDate())}T${pad(d.getUTCHours())}${pad(d.getUTCMinutes())}${pad(d.getUTCSeconds())}Z`;
  } catch (e) {
    return '';
  }
}

