// ─── Sprint 48: AttentionQueue — item-level cross-event triage ───────────────
// Matches Figma page I (frame 630:3 "What needs attention"). Flattens
// decisions, approvals, requests, and vendor issues across every event into a
// single sorted list. Each row is independently actionable — clicking opens
// the event and routes to the right tab.
// PL-13: swipe-to-clear wrapper for the Needs-You queue. On mobile, drag a row
// right past the threshold to fire its primary action, left to snooze it for
// the session. Desktop is untouched. The inline action buttons still work on
// mobile too — swipe is progressive enhancement, never the only way.
function SwipeRow({ enabled, onSwipeRight, rightLabel, onSwipeLeft, children }) {
  const C = useT();
  const T = useType();
  const [dx, setDx] = useState(0);
  const [snap, setSnap] = useState(false);
  const startX = useRef(null);
  if (!enabled) return children;
  const THRESH = 72;
  const onDown = (e) => { startX.current = e.clientX; setSnap(false); try { e.currentTarget.setPointerCapture(e.pointerId); } catch {} };
  const onMove = (e) => {
    if (startX.current == null) return;
    let d = e.clientX - startX.current;
    if (d > 0 && !onSwipeRight) d = Math.min(d, 24); // no right action → resist
    setDx(Math.max(-150, Math.min(150, d)));
  };
  const onUp = () => {
    if (startX.current == null) return;
    const d = dx;
    startX.current = null;
    setSnap(true);
    if (d > THRESH && onSwipeRight) { setDx(0); onSwipeRight(); return; }
    if (d < -THRESH && onSwipeLeft) { onSwipeLeft(); return; }
    setDx(0);
  };
  return (
    <div style={{ position: 'relative', overflow: 'hidden' }}>
      <div aria-hidden style={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '0 14px', pointerEvents: 'none' }}>
        <span style={{ fontSize: T.caption, fontWeight: FW.heavy, color: C.success, opacity: dx > 16 ? 1 : 0, transition: 'opacity 0.1s' }}>✓ {rightLabel || 'Handle'}</span>
        <span style={{ fontSize: T.caption, fontWeight: FW.heavy, color: C.muted, opacity: dx < -16 ? 1 : 0, transition: 'opacity 0.1s' }}>Snooze ⤵</span>
      </div>
      <div
        onPointerDown={onDown} onPointerMove={onMove} onPointerUp={onUp} onPointerCancel={onUp}
        style={{ transform: `translateX(${dx}px)`, transition: snap ? 'transform 0.18s ease-out' : 'none', background: C.surface2 || C.surface, touchAction: 'pan-y' }}
      >
        {children}
      </div>
    </div>
  );
}

function AttentionQueue({ events, onSelectEvent, onMarkTaskDone, onMarkMsgHandled, onLogVendorContact, heroIsUrgent = false, heroEventName = null }) {
  const C  = useT();
  const bp = useContext(BpCtx);
  const isMobile = bp === 'mobile';
  const [filter, setFilter] = useState('all');
  const [snoozed, setSnoozed] = useState(() => new Set()); // PL-13 session snooze
  const allItems = useMemo(() => getCrossEventAttentionItems(events), [events]);
  // Sprint 59H: optimistic in-row state for items the planner has just
  // acted on. Lets the row show "Done ✓" / "Handled ✓" / "Logged ✓"
  // immediately even though the cross-event recomputation will drop the
  // row on the next render. Keyed by attention-item id.
  const [actedOn, setActedOn] = useState({});
  const flashActed = (id, label) => {
    setActedOn(prev => ({ ...prev, [id]: label }));
    // The recomputation on the next state tick removes the row entirely
    // (timeline.done / msg.handled / vendor.log update all drop the item
    // out of getCrossEventAttentionItems). The flash is just a confidence
    // signal in the brief window before that happens.
  };

  const filtered = (filter === 'all' ? allItems : allItems.filter(it => it.kind === filter)).filter(it => !snoozed.has(it.id));
  const visible = filtered.slice(0, 8); // cap to avoid scroll fatigue
  const counts = {
    all:         allItems.length,
    decision:    allItems.filter(i => i.kind === 'decision').length,
    approval:    allItems.filter(i => i.kind === 'approval').length,
    request:     allItems.filter(i => i.kind === 'request').length,
    vendor:      allItems.filter(i => i.kind === 'vendor').length,
    // Sprint 57f.1: compression-summary items show in the queue when an
    // event's lead time is rush/compressed/tight AND it still has urgent
    // tasks. One row per event — not per task. Filter chip only renders
    // when at least one such item exists (gated by the `count === 0`
    // suppression in the tab map below).
    compression: allItems.filter(i => i.kind === 'compression').length,
  };

  const filterTabs = [
    { id: 'all',         label: 'All' },
    { id: 'compression', label: 'Tight timeline' },
    { id: 'decision',    label: 'Decisions' },
    { id: 'approval',    label: 'Approvals' },
    { id: 'request',     label: 'Requests' },
    { id: 'vendor',      label: 'Vendor issues' },
  ];

  return (
    // Sprint 60.P polish: AttentionQueue joins the raise family.
    <div style={{
      marginBottom: 20,
      background: C.surface2 || C.surface, border: `1px solid ${C.border}`, borderRadius: 14,
      padding: '16px 18px 4px',
      boxShadow: [
        'inset 0 1px 0 rgba(255,255,255,0.05)',
        '0 1px 0 rgba(255,255,255,0.02)',
        '0 4px 10px rgba(0,0,0,0.30)',
        '0 14px 28px rgba(0,0,0,0.22)',
      ].join(', '),
    }}>
      {/* Header */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 14, flexWrap: 'wrap' }}>
        <span style={{
          fontSize: T.section, fontWeight: FW.bold, color: C.text, letterSpacing: '-0.01em',
        }}>What needs attention</span>
        {counts.all > 0 && (
          <span style={{ fontSize: T.secondary, fontWeight: FW.semibold, color: C.text }}>{counts.all}</span>
        )}
        <div style={{ flex: 1 }} />
        {/* Filter tabs */}
        <div style={{ display: 'flex', gap: 4, flexWrap: 'wrap' }}>
          {filterTabs.map(tab => {
            const active = filter === tab.id;
            const count = counts[tab.id];
            if (tab.id !== 'all' && count === 0) return null;
            return (
              <button key={tab.id} onClick={() => setFilter(tab.id)} style={{
                padding: '7px 12px', borderRadius: 99, fontSize: T.secondary,
                minHeight: 40,
                fontWeight: active ? 600 : 500, cursor: 'pointer',
                background: active ? C.accent + '22' : 'transparent',
                color: active ? C.accent : C.muted,
                border: `1px solid ${active ? C.accent : C.border}`,
                fontFamily: 'inherit', transition: 'background 0.12s, color 0.12s',
              }}>
                {tab.label}
                {count > 0 && tab.id !== 'all' && (
                  <span style={{ marginLeft: 5, opacity: 0.75, fontWeight: FW.medium }}>{count}</span>
                )}
              </button>
            );
          })}
        </div>
      </div>

      {/* PL-13 swipe hint (mobile only) */}
      {isMobile && visible.length > 0 && (
        <div style={{ fontSize: T.caption, color: C.muted, margin: '0 0 8px 2px' }}>
          Swipe a row right to handle it · left to snooze
        </div>
      )}

      {/* Item rows */}
      {visible.length === 0 ? (
        <div style={{
          padding: '24px 0', textAlign: 'center', fontSize: T.secondary, color: C.muted,
          borderTop: `1px solid ${C.border}`,
        }}>
          {counts.all === 0
            ? (heroIsUrgent
                ? (heroEventName
                    ? `${heroEventName} is in the hero above — nothing else flagged here.`
                    : 'Everything else is quiet — see the hero above.')
                : 'All quiet — nothing needs you right now.')
            : 'No items in this filter.'}
        </div>
      ) : (
        <div>
          {visible.map((it, i) => {
            // Sprint 59H: derive inline quick actions per row kind. Each
            // action is { label, kind: 'record' | 'route' | 'handoff',
            // onClick }. Mobile wraps; desktop sits inline at the right.
            // Always include a route fallback so the planner can still
            // open the canonical owner for context.
            const ev = events.find(e => e.id === it.eventId);
            // Vendor-stale items carry the vendor id on their clickTarget
            // (CommandCenter.jsx:594), so we don't need to parse the row id.
            const vendor = ev && it.kind === 'vendor-stale' && it.clickTarget?.vendorId
              ? (ev.vendors || []).find(v => v.id === it.clickTarget.vendorId)
              : null;
            const vendorEmail = vendor?.contact;
            const mailtoAskTime = vendorEmail
              ? `mailto:${vendorEmail}?subject=${encodeURIComponent(`Quick reconfirm — ${ev?.name || 'event'}`)}&body=${encodeURIComponent(`Hi ${vendor?.name || ''},\n\nJust checking in — we're still on for ${ev?.name || 'your event'} and wanted to confirm everything's good on your end. Anything you need from us?\n\nThanks.`)}`
              : null;
            const acted = actedOn[it.id];
            const quickActions = [];
            if (acted) {
              quickActions.push({ key: 'acted', label: acted, kind: 'done' });
            } else if (it.kind === 'decision' && onMarkTaskDone) {
              // Overdue planning task — Mark done writes to event.timeline.
              quickActions.push({
                key: 'done',
                label: 'Mark done',
                kind: 'record',
                onClick: () => { onMarkTaskDone(it.eventId, it.clickTarget?.decisionId); flashActed(it.id, '✓ Done'); },
              });
            } else if (it.kind === 'request' && onMarkMsgHandled && it.clickTarget?.commId) {
              // Inbound message — Mark handled writes to event.commClient. Only offered
              // when there's a real message id (board: don't flash "✓ Handled" on a no-op).
              quickActions.push({
                key: 'handled',
                label: 'Mark handled',
                kind: 'record',
                onClick: () => { onMarkMsgHandled(it.eventId, it.clickTarget.commId); flashActed(it.id, '✓ Handled'); },
              });
            } else if (it.kind === 'vendor-stale' && onLogVendorContact && vendor) {
              // 21+ days quiet — primary action is the email handoff
              // (mailto) when we have a contact email, secondary is the
              // record-only log entry. Both surfaced.
              if (mailtoAskTime) {
                quickActions.push({
                  key: 'email',
                  label: 'Open email draft',
                  kind: 'handoff',
                  href: mailtoAskTime,
                  onClick: () => { /* mailto handled by href; no state write */ },
                });
              }
              quickActions.push({
                key: 'log',
                label: 'Log contact',
                kind: 'record',
                onClick: () => { onLogVendorContact(it.eventId, vendor.id); flashActed(it.id, '✓ Logged'); },
              });
            }
            const routeLabel = it.kind === 'decision' ? 'Open decision →'
              : it.kind === 'request' ? 'Open Communication →'
              : it.kind === 'vendor-stale' ? 'Open contact details →'
              : it.kind === 'approval' ? 'Open Decision →'
              : it.kind === 'compression' ? 'Open compressed tasks →'
              : 'Open event →';
            // Sprint 60.B: vendor-stale lands inside the vendor's contact
            // section (which today routes through the edit modal — no inline
            // contact panel exists). The clickTarget below carries the
            // vendorSection so the EventPlanner route chain expands the
            // right place after the event opens.
            const onRowOpen = () => {
              const navWithSection = (it.kind === 'vendor-stale' && it.clickTarget)
                ? { ...it.clickTarget, vendorSection: 'contact' }
                : it.clickTarget;
              onSelectEvent(it.eventId, navWithSection);
            };
            // PL-13: swipe-right fires the item's primary record action (if any).
            const recordAction = quickActions.find(a => a.kind === 'record' && a.onClick);

            return (
              <SwipeRow key={it.id} enabled={isMobile}
                onSwipeRight={recordAction ? recordAction.onClick : null}
                rightLabel={recordAction ? recordAction.label : null}
                onSwipeLeft={() => setSnoozed(s => { const n = new Set(s); n.add(it.id); return n; })}>
              <div
                style={{
                  display: 'flex', alignItems: 'center', gap: 12, flexWrap: 'wrap',
                  padding: '11px 0',
                  borderTop: `1px solid ${C.border}`,
                  fontFamily: 'inherit',
                }}
              >
                {/* Status pill */}
                <span style={{
                  display: 'inline-flex', alignItems: 'center',
                  fontSize: T.caption, fontWeight: FW.bold, letterSpacing: '0.08em',
                  padding: '3px 8px', borderRadius: 4, marginLeft: 4,
                  background: it.statusColor, color: '#fff',
                  flexShrink: 0, whiteSpace: 'nowrap',
                }}>{it.statusLabel}</span>

                {/* Title + meta (clickable area — opens the event) */}
                <button
                  onClick={onRowOpen}
                  style={{
                    flex: 1, minWidth: 0,
                    background: 'none', border: 'none', cursor: 'pointer',
                    textAlign: 'left', padding: 0, fontFamily: 'inherit',
                  }}
                  title={routeLabel}
                >
                  <div style={{
                    fontSize: T.secondary, fontWeight: FW.medium, color: C.text,
                    overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
                  }}>{it.title}</div>
                  <div style={{
                    fontSize: T.caption, color: C.muted, marginTop: 3,
                    overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
                  }}>{it.meta}</div>
                </button>

                {/* Due / timing */}
                <span style={{
                  fontSize: T.secondary, fontWeight: FW.semibold, color: it.dueColor, flexShrink: 0,
                  whiteSpace: 'nowrap',
                }}>{it.dueLabel}</span>

                {/* Sprint 59H inline action chips. On narrow widths these
                    wrap below the row via the parent's flexWrap. Each chip
                    absorbs its own click so the row's open-event button
                    doesn't fire. */}
                {quickActions.length > 0 && (
                  <div style={{ display: 'flex', gap: 6, flexShrink: 0, flexWrap: 'wrap' }}>
                    {quickActions.map(a => a.kind === 'done' ? (
                      <span key={a.key} style={{
                        fontSize: T.secondary, fontWeight: FW.bold,
                        color: C.success, background: C.success + '14',
                        border: `1px solid ${C.success}44`,
                        padding: '6px 12px', borderRadius: 7,
                      }}>{a.label}</span>
                    ) : a.kind === 'handoff' ? (
                      <a key={a.key} href={a.href} target="_blank" rel="noopener noreferrer"
                        onClick={e => { e.stopPropagation(); a.onClick && a.onClick(); }}
                        title="Opens your email app with a draft. Nothing is sent until you send it."
                        style={{
                          fontSize: T.secondary, fontWeight: FW.semibold,
                          color: C.text, background: 'transparent',
                          border: `1px solid ${C.border}`,
                          padding: '6px 12px', borderRadius: 7,
                          textDecoration: 'none', cursor: 'pointer',
                        }}>{a.label}</a>
                    ) : (
                      <button key={a.key} onClick={e => { e.stopPropagation(); a.onClick && a.onClick(); }}
                        style={{
                          fontSize: T.secondary, fontWeight: FW.semibold,
                          color: C.accent, background: C.accent + '14',
                          border: `1px solid ${C.accent}66`,
                          padding: '6px 12px', borderRadius: 7,
                          cursor: 'pointer', fontFamily: 'inherit',
                        }}>{a.label}</button>
                    ))}
                  </div>
                )}

                {/* Route chevron */}
                <button onClick={onRowOpen} title={routeLabel} aria-label={routeLabel}
                  style={{ background: 'none', border: 'none', color: C.muted, fontSize: T.secondary, marginRight: 4, cursor: 'pointer', padding: '4px 6px', fontFamily: 'inherit' }}>›</button>
              </div>
              </SwipeRow>
            );
          })}
          {filtered.length > visible.length && (
            <div style={{ padding: '8px 0', fontSize: T.caption, color: C.muted, textAlign: 'center', borderTop: `1px solid ${C.border}` }}>
              {filtered.length - visible.length} more · scroll for full queue
            </div>
          )}
        </div>
      )}
    </div>
  );
}

// ─── Sprint 48: Upcoming Events panel matching Figma page I (frame 631:3) ─────
// Each row: month + day-of-month in a dedicated column, vertical separator,
// event name + meta line, days-out pill on the right. No generic event card.
// Sprint 48+: prev/next arrows paginate through events 4 at a time.
function HomeUpcomingPanel({ events, onSelectEvent }) {
  const C = useT();
  const T = useType();
  const evtCLR = EVT_CLR(C);
  const PAGE = 4;
  const [offset, setOffset] = useState(0);
  const allUpcoming = useMemo(() =>
    events
      .filter(e => !e.archived)
      .filter(e => e.date && daysUntil(e.date) >= 0)
      .sort((a, b) => (a.date || '').localeCompare(b.date || '')),
    [events]);
  const upcoming = allUpcoming.slice(offset, offset + PAGE);
  const canPrev = offset > 0;
  const canNext = offset + PAGE < allUpcoming.length;

  return (
    <div style={{
      background: C.surface2 || C.surface, border: `1px solid ${C.border}`, borderRadius: 14,
      padding: '16px 18px 6px',
      // Sprint 60.P refinement: Studio Matte raise so this panel sits in
      // the same elevation family as the hero + supporting cards above.
      boxShadow: [
        'inset 0 1px 0 rgba(255,255,255,0.05)',
        '0 1px 0 rgba(255,255,255,0.02)',
        '0 4px 10px rgba(0,0,0,0.30)',
        '0 14px 28px rgba(0,0,0,0.22)',
      ].join(', '),
    }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 12 }}>
        <span style={{ fontSize: T.secondary, fontWeight: FW.bold, color: C.text }}>Upcoming Events</span>
        {allUpcoming.length > 0 && (
          <span style={{ fontSize: T.secondary, fontWeight: FW.semibold, color: C.muted }}>{allUpcoming.length}</span>
        )}
        <div style={{ flex: 1 }} />
        {allUpcoming.length > PAGE && (
          <>
            <span style={{ fontSize: T.caption, color: C.muted, marginRight: 4 }}>
              {Math.min(offset + 1, allUpcoming.length)}–{Math.min(offset + PAGE, allUpcoming.length)} of {allUpcoming.length}
            </span>
            <button onClick={() => setOffset(o => Math.max(0, o - PAGE))} disabled={!canPrev} aria-label="Previous page"
              style={{
                background: 'transparent', border: `1px solid ${C.border}`, borderRadius: 6,
                width: 30, height: 28, display: 'flex', alignItems: 'center', justifyContent: 'center',
                color: canPrev ? C.text : C.border, cursor: canPrev ? 'pointer' : 'default',
              }}><Icon name="chevronLeft" size={13} /></button>
            <button onClick={() => setOffset(o => o + PAGE)} disabled={!canNext} aria-label="Next page"
              style={{
                background: 'transparent', border: `1px solid ${C.border}`, borderRadius: 6,
                width: 30, height: 28, display: 'flex', alignItems: 'center', justifyContent: 'center',
                color: canNext ? C.text : C.border, cursor: canNext ? 'pointer' : 'default',
              }}><Icon name="chevronRight" size={13} /></button>
          </>
        )}
      </div>
      {upcoming.length === 0 ? (
        <div style={{ padding: '20px 0', textAlign: 'center', fontSize: T.secondary, color: C.muted }}>
          No upcoming events.
        </div>
      ) : (
        <div>
          {upcoming.map((ev, i) => {
            const days = daysUntil(ev.date);
            const eventColor = evtCLR[ev.type] || C.accent2;
            // Board audit (2026-06-13, #6): ≤14d painted 14/15/17d-out events amber —
            // but an event two-plus weeks out is a resting horizon, not a near-term
            // clock, so amber there reads as wallpaper. Tightened to a genuine
            // "this week" window: ≤7 days = approaching (amber), else neutral steel.
            const daysColor = days <= 7 ? C.warn : C.muted;
            const d = new Date(ev.date + 'T00:00:00');
            const month = d.toLocaleDateString('en-US', { month: 'short' }).toUpperCase();
            const day = String(d.getDate());
            const conf  = (ev.guests || []).filter(g => g.rsvp === 'Yes').length;
            const vConf = (ev.vendors || []).filter(v => v.status === 'Confirmed').length;
            const vTot  = (ev.vendors || []).length;
            const eng   = engineNextAction(ev); // T1: the engine's binding next action
            return (
              <button key={ev.id} onClick={() => onSelectEvent(ev.id)} style={{
                width: '100%', display: 'flex', alignItems: 'center', gap: 14,
                padding: '11px 0', background: 'none',
                border: 'none', borderTop: i === 0 ? 'none' : `1px solid ${C.border}`,
                cursor: 'pointer', textAlign: 'left', fontFamily: 'inherit',
              }}
                onMouseEnter={e => { e.currentTarget.style.background = C.surface; }}
                onMouseLeave={e => { e.currentTarget.style.background = 'none'; }}
              >
                {/* Date column */}
                <div style={{
                  width: 42, display: 'flex', flexDirection: 'column',
                  alignItems: 'center', flexShrink: 0,
                }}>
                  <span style={{
                    fontSize: T.eyebrow, fontWeight: FW.bold, letterSpacing: '0.12em', color: eventColor,
                  }}>{month}</span>
                  <span style={{
                    fontSize: T.title, fontWeight: FW.bold, color: C.text, letterSpacing: '-0.02em',
                    lineHeight: 1.1, marginTop: 1,
                  }}>{day}</span>
                </div>

                {/* Separator */}
                <div style={{ width: 1, height: 30, background: C.border, flexShrink: 0 }} />

                {/* Name + meta */}
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 6, minWidth: 0 }}>
                    <div style={{
                      fontSize: T.secondary, fontWeight: FW.semibold, color: C.text,
                      overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
                    }}>{ev.name}</div>
                    {/* Board ruling (2026-06-12): per-card SAMPLE stamp so a demo
                        event can NEVER be mistaken for a real client — the masquerade
                        fix that doesn't depend on the event's name. Quiet steel, not
                        an alarm color; unmissable on the card itself, not 400px away
                        in a banner. */}
                    {isSeedEvent(ev) && (
                      <span style={{
                        flexShrink: 0, fontSize: T.eyebrow, fontWeight: FW.heavy, letterSpacing: '0.1em',
                        textTransform: 'uppercase', color: C.muted,
                        border: `1px solid ${C.border}`, background: C.surface,
                        borderRadius: 3, padding: '1px 5px', lineHeight: 1.3,
                      }}>Sample</span>
                    )}
                  </div>
                  {/* PL-5 honest density: the vendor count is the actionable bit —
                      protect it from truncation. Event type ellipsizes; the count stays whole. */}
                  {/* T1: lead the subline with the engine's binding next action +
                      readiness dot — not the vendor-count plumbing. */}
                  <div style={{ fontSize: T.caption, color: C.muted, marginTop: 2, display: 'flex', alignItems: 'center', gap: 5, minWidth: 0 }}>
                    <span style={{ flexShrink: 0, whiteSpace: 'nowrap' }}>{eventTypeLabel(ev) || ev.type}</span>
                    {eng && eng.binding ? (
                      <>
                        <span aria-hidden style={{ flexShrink: 0, width: 6, height: 6, borderRadius: '50%', background: ENGINE_FLAG_COLOR(C, eng.flag) }} />
                        <span style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', minWidth: 0, color: eng.dateAtRisk ? C.danger : C.text }}>{eng.binding.name}</span>
                      </>
                    ) : (vTot > 0 && <span style={{ flexShrink: 0, whiteSpace: 'nowrap' }}>· {conf} conf · {vConf}/{vTot} vendors</span>)}
                  </div>
                </div>

                {/* Days pill */}
                <span style={{
                  fontSize: T.caption, fontWeight: FW.bold, color: daysColor,
                  border: `1px solid ${daysColor}`, padding: '3px 7px',
                  borderRadius: 4, flexShrink: 0, whiteSpace: 'nowrap',
                }}>{days === 0 ? 'Today' : `${days}d`}</span>
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
}

// ─── Sprint 48: This Week panel matching Figma page I (frame 631:53) ──────────
// 7-day strip with current day highlighted + named items below for days that
// have payments, vendor deadlines, or scheduled visits. Replaces the calendar
// widget on the dashboard view.
function HomeThisWeekPanel({ events, calNotes = [], onOpenCalendar, onSelectEvent }) {
  const C = useT();
  const T = useType();
  // Sprint 48+: prev/next arrows step a week at a time. weekOffset=0 is the
  // current week; +1 is next week; -1 is last week.
  const [weekOffset, setWeekOffset] = useState(0);

  const week = useMemo(() => {
    const today = new Date(); today.setHours(0, 0, 0, 0);
    const sunday = new Date(today);
    sunday.setDate(today.getDate() - today.getDay() + (weekOffset * 7));
    const days = [];
    for (let i = 0; i < 7; i++) {
      const d = new Date(sunday);
      d.setDate(sunday.getDate() + i);
      days.push({
        date: d,
        iso: d.toISOString().slice(0, 10),
        label: d.toLocaleDateString('en-US', { weekday: 'short' }).toUpperCase().slice(0, 3),
        day: String(d.getDate()),
        isToday: d.getTime() === today.getTime(),
      });
    }
    return { sunday, saturday: days[6].date, days };
  }, [weekOffset]);

  // Build items: vendor deadlines, payments due, notes — all within the week
  const items = useMemo(() => {
    const out = [];
    const startISO = week.days[0].iso;
    const endISO   = week.days[6].iso;
    for (const ev of events) {
      // Vendor payments due this week
      for (const v of (ev.vendors || [])) {
        // Canonical balance (cost − paid), not the stale fee/deposit fields that
        // always read $0. Only nudge when money is actually owed (B6: no "$0" Pay).
        const balance = vendorBalance(v);
        if (v.payDueDate && !v.balancePaid && balance > 0 && v.payDueDate >= startISO && v.payDueDate <= endISO) {
          out.push({
            id: `pay-${ev.id}-${v.id}`,
            dayLabel: new Date(v.payDueDate + 'T00:00:00').toLocaleDateString('en-US', { weekday: 'short' }).toUpperCase().slice(0, 3),
            label: `Pay ${v.name || 'vendor'}`,
            sub: `${ev.name} · ${fmtD(balance)}`,
            color: C.muted,
            iso: v.payDueDate,
            eventId: ev.id,
            clickTarget: { tab: 'Vendors', vendorId: v.id },
          });
        }
      }
      // Tasks with explicit due dates in the week (rare in current model — best-effort)
      for (const t of (ev.timeline || [])) {
        if (!t.done && t.dueDate && t.dueDate >= startISO && t.dueDate <= endISO) {
          out.push({
            id: `task-${ev.id}-${t.id}`,
            dayLabel: new Date(t.dueDate + 'T00:00:00').toLocaleDateString('en-US', { weekday: 'short' }).toUpperCase().slice(0, 3),
            label: t.task,
            sub: `${ev.name} · ${t.owner || 'You'}`,
            color: C.accent2,
            iso: t.dueDate,
            eventId: ev.id,
            clickTarget: { tab: 'Planning Tasks', taskId: t.id },
          });
        }
      }
    }
    // User calendar notes for this week
    for (const note of (calNotes || [])) {
      if (!note.date) continue;
      if (note.date >= startISO && note.date <= endISO) {
        out.push({
          id: `note-${note.id}`,
          dayLabel: new Date(note.date + 'T00:00:00').toLocaleDateString('en-US', { weekday: 'short' }).toUpperCase().slice(0, 3),
          label: note.text || 'Note',
          sub: 'Personal note',
          color: C.muted,
          iso: note.date,
        });
      }
    }
    // PL-6: return the full week — the day-dots above need every item, and the
    // render shows a "+N more" affordance instead of silently dropping items 7+.
    return out.sort((a, b) => (a.iso || '').localeCompare(b.iso || ''));
  }, [events, calNotes, week.days, C.muted, C.accent2, C.muted]);

  const fmtRange = (a, b) =>
    `${a.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })} – ${b.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}`;

  return (
    <div style={{
      background: C.surface2 || C.surface, border: `1px solid ${C.border}`, borderRadius: 10,
      padding: '16px 18px',
    }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 12 }}>
        <span style={{ fontSize: T.secondary, fontWeight: FW.bold, color: C.text }}>
          {weekOffset === 0 ? 'This Week' : weekOffset === 1 ? 'Next Week' : weekOffset === -1 ? 'Last Week' : weekOffset > 0 ? `In ${weekOffset} weeks` : `${Math.abs(weekOffset)} weeks ago`}
        </span>
        <div style={{ flex: 1 }} />
        <span style={{ fontSize: T.caption, color: C.muted, marginRight: 4 }}>{fmtRange(week.sunday, week.saturday)}</span>
        <button onClick={() => setWeekOffset(w => w - 1)} aria-label="Previous week"
          style={{
            background: 'transparent', border: `1px solid ${C.border}`, borderRadius: 6,
            width: 30, height: 28, display: 'flex', alignItems: 'center', justifyContent: 'center',
            color: C.text, cursor: 'pointer',
          }}><Icon name="chevronLeft" size={13} /></button>
        {weekOffset !== 0 && (
          <button aria-label="Today" onClick={() => setWeekOffset(0)} title="Today"
            style={{
              background: 'transparent', border: `1px solid ${C.border}`, borderRadius: 6,
              padding: '0 7px', height: 24, color: C.text, cursor: 'pointer',
              fontSize: T.caption, fontWeight: FW.semibold, fontFamily: 'inherit',
            }}>Today</button>
        )}
        <button onClick={() => setWeekOffset(w => w + 1)} aria-label="Next week"
          style={{
            background: 'transparent', border: `1px solid ${C.border}`, borderRadius: 6,
            width: 30, height: 28, display: 'flex', alignItems: 'center', justifyContent: 'center',
            color: C.text, cursor: 'pointer',
          }}><Icon name="chevronRight" size={13} /></button>
        {onOpenCalendar && (
          <button onClick={onOpenCalendar}
            style={{
              background: 'transparent', border: 'none', cursor: 'pointer',
              fontSize: T.caption, fontWeight: FW.medium, color: C.accent, padding: '0 0 0 4px',
              fontFamily: 'inherit',
            }}>Full calendar →</button>
        )}
      </div>

      {/* 7-day strip */}
      <div style={{ display: 'flex', gap: 4, marginBottom: 14 }}>
        {week.days.map(d => {
          const hasEvent = items.some(it => it.iso === d.iso);
          return (
            <div key={d.iso} style={{
              flex: 1, padding: '6px 0', borderRadius: 6,
              display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 2,
              background: d.isToday ? C.border : 'transparent',
              border: `1px solid ${C.border}`,
            }}>
              <span style={{ fontSize: T.eyebrow, fontWeight: FW.semibold, letterSpacing: '0.08em', color: C.muted }}>{d.label}</span>
              <span style={{
                fontSize: T.body, fontWeight: FW.bold,
                color: d.isToday ? C.success : C.text, letterSpacing: '-0.02em',
              }}>{d.day}</span>
              {hasEvent && (
                <div style={{ width: 4, height: 4, borderRadius: '50%', background: C.muted }} />
              )}
            </div>
          );
        })}
      </div>

      {/* Named items for the week */}
      {items.length === 0 ? (
        <div style={{ padding: '8px 0 4px', fontSize: T.caption, color: C.muted, textAlign: 'center' }}>
          Nothing scheduled this week.
        </div>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
          {items.slice(0, 6).map(it => {
            // Sprint 60.Y click-through audit — payment/task rows deep-link to
            // their tab; personal notes open the calendar. Mirrors MasterCalendarView.
            const go = it.eventId && onSelectEvent ? () => onSelectEvent(it.eventId, it.clickTarget)
              : (!it.eventId && onOpenCalendar) ? onOpenCalendar : null;
            return (
            <button key={it.id} onClick={go || undefined} disabled={!go}
              style={{ display: 'flex', alignItems: 'center', gap: 10, background: 'none', border: 'none', padding: '2px 0', cursor: go ? 'pointer' : 'default', fontFamily: 'inherit', textAlign: 'left', width: '100%' }}
              title={go ? (it.eventId ? 'Open' : 'Open calendar') : undefined}>
              <span style={{
                fontSize: T.eyebrow, fontWeight: FW.bold, letterSpacing: '0.12em', color: it.color,
                width: 28, flexShrink: 0,
              }}>{it.dayLabel}</span>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: T.secondary, color: C.text, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{it.label}</div>
                <div style={{ fontSize: T.caption, color: C.muted, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{it.sub}</div>
              </div>
            </button>
            );
          })}
          {items.length > 6 && (
            <button onClick={onOpenCalendar || undefined} disabled={!onOpenCalendar}
              style={{ background: 'none', border: 'none', padding: '4px 0', cursor: onOpenCalendar ? 'pointer' : 'default', fontFamily: 'inherit', textAlign: 'left', fontSize: T.caption, fontWeight: FW.semibold, color: C.accent }}>
              +{items.length - 6} more this week →
            </button>
          )}
        </div>
      )}
    </div>
  );
}

// ─── Sprint 48: Quick Actions row matching the brief's "5 inline CTAs" ───────
// Add Decision / Add Approval / Add Request / Create Event / Create Client.
// The 3 per-event actions route to the highest-attention event's Command
// Center (falling back to the first event, then disabled). No multi-step
// picker — fast path for the common case.
function HomeQuickActions({ events, onSelectEvent, onNew, onNewClient }) {
  const C = useT();
  const T = useType();
  const bp = useContext(BpCtx);
  const isMobile = bp === 'mobile' || bp === 'tablet';

  // Find the event with the most outstanding attention items as the default
  // routing target for "+ Decision / + Approval / + Request".
  const targetEvent = useMemo(() => {
    if (events.length === 0) return null;
    const summary = getCrossEventAttention(events);
    return summary.byEvent[0]?.event || events.find(e => !e.archived) || events[0];
  }, [events]);

  const route = (tab) => {
    if (!targetEvent) return;
    onSelectEvent(targetEvent.id, { tab });
  };

  // Sprint 50 friction fix #3: relabel to navigation truth + correct targets.
  // The first three open the canonical Sprint 49 surfaces (Decisions /
  // Communication tabs) on the highest-attention event. "+" prefix was
  // misleading — these are navigation actions, not composers. The trailing
  // event name in the title shows which event you'd land on.
  const targetLabel = targetEvent ? targetEvent.name : '';
  const actions = [
    { id: 'decision', label: 'Decisions',    title: targetLabel ? `Open Decisions on ${targetLabel}`    : '', onClick: () => route('Decisions'),     disabled: !targetEvent, color: C.accent2 },
    { id: 'approval', label: 'Approvals',    title: targetLabel ? `Open Approvals on ${targetLabel}`    : '', onClick: () => route('Decisions'),     disabled: !targetEvent, color: C.muted },
    { id: 'request',  label: 'Communication', title: targetLabel ? `Open Communication on ${targetLabel}` : '', onClick: () => route('Communication'), disabled: !targetEvent, color: C.accent2 },
    { id: 'event',    label: '+ Event',      title: 'Create new event',                                       onClick: onNew,                         disabled: false,        color: C.accent },
    { id: 'client',   label: '+ Client',     title: 'Create new client',                                      onClick: onNewClient,                   disabled: false,        color: C.accent },
  ];

  return (
    <div style={{ marginBottom: 20 }}>
      <div style={{
        fontSize: T.eyebrow, fontWeight: FW.bold, letterSpacing: '0.18em',
        textTransform: 'uppercase', color: C.muted, marginBottom: 10,
      }}>Quick actions</div>
      <div style={{
        display: 'grid',
        gridTemplateColumns: isMobile ? 'repeat(2, 1fr)' : 'repeat(5, 1fr)',
        gap: 8,
      }}>
        {actions.map((a, ai) => (
          <button key={a.id} onClick={a.onClick} disabled={a.disabled} title={a.disabled ? 'Create an event first' : (a.title || '')} style={{
            padding: '12px 14px', borderRadius: 8,
            background: 'transparent',
            border: `1px solid ${a.disabled ? C.border : a.color + '55'}`,
            color: a.disabled ? C.muted : C.text,
            fontFamily: 'inherit', fontSize: T.secondary, fontWeight: FW.semibold,
            cursor: a.disabled ? 'not-allowed' : 'pointer',
            opacity: a.disabled ? 0.5 : 1,
            minHeight: 44,
            transition: 'background 0.12s, border-color 0.12s',
            textAlign: 'left',
            // PL-1: on mobile (2-col) an odd-count list orphans the last tile on
            // its own row — let it span full width so the grid reads as complete.
            ...(isMobile && actions.length % 2 === 1 && ai === actions.length - 1 ? { gridColumn: '1 / -1' } : {}),
          }}
            onMouseEnter={a.disabled ? undefined : (e => { e.currentTarget.style.background = a.color + '0e'; e.currentTarget.style.borderColor = a.color + '99'; })}
            onMouseLeave={a.disabled ? undefined : (e => { e.currentTarget.style.background = 'transparent'; e.currentTarget.style.borderColor = a.color + '55'; })}
          >
            {a.label}
          </button>
        ))}
      </div>
    </div>
  );
}

// ─── Sprint 48: time-aware greeting hero matching Figma page I ────────────────
// Sprint 50 friction fix #1: when there are items needing attention, the status
// line becomes a button that routes to the first item via onSelectEvent. The
// most prominent attention signal on the home screen must be actionable.
function HomeHero({ profile, events, clients, onSelectEvent }) {
  const C = useT();
  const T = useType();
  const summary = useMemo(() => getCrossEventAttention(events), [events]);
  // Sprint 60.P Addendum — derive the summary line from the SAME command
  // state the hero uses, so the header line can't contradict the hero
  // ("all quiet" while hero shows urgent was the prior failure mode).
  const command = useMemo(() => selectStudioCommand(events), [events]);
  const firstItem = useMemo(() => {
    const items = getCrossEventAttentionItems(events);
    return items[0] || null;
  }, [events]);
  const activeEvents = events.filter(e => !e.archived).length;
  const hour = new Date().getHours();
  const greet = hour < 12 ? 'Good morning' : hour < 17 ? 'Good afternoon' : 'Good evening';
  const name = profile?.name?.split(' ')[0] || profile?.businessName?.split(' ')[0] || null;

  // Locked truth-table summaries — every line provably agrees with the hero.
  const need = summary.totals.total;
  const upcoming60 = events.filter(e => !e.archived && e.date)
    .map(e => ({ ev: e, days: Math.round((new Date(e.date) - new Date()) / 86_400_000) }))
    .filter(x => x.days >= 0 && x.days <= 60).length;
  let status;
  let summaryColor = C.muted;
  // Board L1 audit (Home, honesty): in sample-only mode the greeting must NOT
  // claim urgency ("10 active events · needs attention") over data the planner
  // knows isn't theirs — it's the grandmother-test panic the demo causes.
  const hasOnlySample = events.some(e => SEED_EVENT_IDS.has(e.id)) && !events.some(e => !SEED_EVENT_IDS.has(e.id));
  if (hasOnlySample) {
    status = 'Exploring sample data — nothing here is yours yet';
    summaryColor = C.muted;
  } else if (command?.category === 'today-act') {
    status = 'Event day · needs attention right now';
    summaryColor = C.danger;
  } else if (command?.category === 'today') {
    status = 'Event day is active';
    summaryColor = C.muted;
  } else if (command?.level === 'critical') {
    status = `${activeEvents} active event${activeEvents === 1 ? '' : 's'} · needs attention`;
    summaryColor = C.danger;
  } else if (command?.level === 'attention') {
    status = `${activeEvents} active event${activeEvents === 1 ? '' : 's'} · needs follow-up`;
    summaryColor = C.muted;
  } else if (command?.category === 'multiple-upcoming') {
    status = `${upcoming60} events in the next 60 days`;
  } else if (command?.category === 'calendar' || command?.category === 'all-clear') {
    status = `${activeEvents} active event${activeEvents === 1 ? '' : 's'} · all quiet`;
    summaryColor = C.success;
  } else if (activeEvents === 0) {
    status = '0 active events';
  } else {
    // Fall-through: count-based fallback (legacy behavior) so we never
    // silently render an empty line.
    status = need === 0
      ? `${activeEvents} active event${activeEvents === 1 ? '' : 's'} · all quiet`
      : `${activeEvents} active event${activeEvents === 1 ? '' : 's'} · ${need} item${need === 1 ? '' : 's'} need your attention`;
  }
  const actionable = need > 0 && firstItem && typeof onSelectEvent === 'function' && command?.level !== 'neutral';

  // Sprint 60.U.3 10+ — Event Boss Pulse eyebrow. Anchors the page in
  // product personality at first glance. Steel-blue + steady ✓ glyph =
  // "Event Boss is watching your pipeline; you don't have to think about
  // everything at once."
  const steelTopH = C.accentTopGrad || C.accent;
  return (
    <div style={{ marginBottom: 18 }}>
      <div style={{
        display: 'inline-flex', alignItems: 'center', gap: 8,
        padding: '4px 10px 4px 8px', borderRadius: 99,
        background: `${steelTopH}14`,
        border: `1px solid ${steelTopH}33`,
        marginBottom: 10,
      }}>
        <span aria-hidden style={{
          width: 14, height: 14, borderRadius: '50%',
          background: `${steelTopH}33`, color: steelTopH,
          display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
          fontSize: T.eyebrow, fontWeight: FW.heavy,
        }}>✓</span>
        <span style={{
          fontSize: T.caption, fontWeight: FW.heavy, letterSpacing: '0.16em',
          textTransform: 'uppercase', color: steelTopH, lineHeight: 1,
        }}>Today at a glance</span>
      </div>
      {/* PL-12 "One Thing Now": the greeting is demoted to a compact context
          line so the decision (the command panel directly below) is the visual
          hero. The greeting no longer owns a 28px headline or a duplicate
          action link — the command panel carries the single next-best action. */}
      <div style={{
        fontSize: T.body, fontWeight: FW.semibold, color: C.text, marginTop: 8,
        letterSpacing: '-0.01em', lineHeight: 1.35, overflowWrap: 'anywhere',
      }}>
        {name ? `${greet}, ${name}` : greet}
        {activeEvents > 0 && status ? (
          <span style={{ color: summaryColor !== C.muted ? summaryColor : C.muted, fontWeight: FW.medium }}> · {status}</span>
        ) : null}
      </div>
    </div>
  );
}

// ─── Sprint 52: Studio "What needs you today" panel ──────────────────────────
// First-run orchestration. Editorial panel sitting above SetupBanner / KPI
// strip on the dashboard. One title, one consequence, one primary CTA. The
// command itself is derived deterministically by selectStudioCommand —
// nothing fake, nothing AI, nothing decorative.
// (Was "Today's Command" → "Top of Book" → "What needs you today" — the
// Sprint 55 tone audit found "Top of Book" read as trading-floor jargon for
// first-time planners; plain English wins on accessibility without losing
// any signal for pros.)
// PL-14 "Brief me" — one-tap morning standup across all events. Uses the Claude
// key when configured (real, streamed); falls back to a deterministic summary
// built from the same attention data otherwise — honestly labeled so it never
// fakes intelligence. Ambient summarizer, not a chatbot.
function DailyBriefing({ events, onSelectEvent }) {
  const C = useT();
  const T = useType();
  const aiKey = useAIKey();
  const [open, setOpen] = useState(false);
  const [text, setText] = useState('');
  const [loading, setLoading] = useState(false);
  const [usedAI, setUsedAI] = useState(false);

  const active = (events || []).filter(e => !e.archived);
  if (active.length === 0) return null;

  const buildData = () => {
    const items = getCrossEventAttentionItems(active);
    const byEvent = new Map();
    items.forEach(it => { if (!byEvent.has(it.eventId)) byEvent.set(it.eventId, []); byEvent.get(it.eventId).push(it); });
    const lines = active
      .map(ev => ({ ev, days: daysUntil(ev.date) }))
      .filter(x => x.days === null || x.days >= 0)
      .sort((a, b) => (a.days ?? 99999) - (b.days ?? 99999))
      .map(({ ev, days }) => {
        const its = byEvent.get(ev.id) || [];
        const when = days === null ? 'no date set' : days === 0 ? 'today' : `${days} days out`;
        const top = its.slice(0, 3).map(i => i.title).join('; ') || 'nothing flagged';
        return `- ${ev.name} (${when}): ${its.length} item(s) — ${top}`;
      });
    return { items, lines };
  };

  const deterministic = () => {
    const { items } = buildData();
    const dated = active.map(ev => ({ ev, days: daysUntil(ev.date) }))
      .filter(x => x.days !== null && x.days >= 0).sort((a, b) => a.days - b.days);
    const closest = dated[0];
    const total = items.length;
    const parts = [];
    parts.push(`You have ${active.length} active event${active.length === 1 ? '' : 's'}${closest ? `, the nearest is ${closest.ev.name} ${closest.days === 0 ? 'today' : `in ${closest.days} day${closest.days === 1 ? '' : 's'}`}` : ''}.`);
    if (total > 0) parts.push(`${total} item${total === 1 ? '' : 's'} need${total === 1 ? 's' : ''} your attention — start with “${items[0].title}” on ${items[0].eventName}.`);
    else parts.push(`Nothing is flagged across your events right now — you’re clear.`);
    return parts.join(' ');
  };

  const brief = async () => {
    setOpen(true);
    // The daily summary runs on the OpenAI key on the BACKEND (the secure
    // server-side aiProxy → GPT-4o, the same path as message drafts), so no
    // Anthropic key needs to live in the browser. Order of preference:
    //   1. OpenAI proxy (event_brief feature) — the canonical path.
    //   2. Anthropic frontend key, if one is configured (legacy fallback).
    //   3. Deterministic local summary (never blocks on AI being available).
    const proxyOn = isAiProxyConfigured();
    if (!proxyOn && !aiKey) { setText(deterministic()); setUsedAI(false); return; }
    setLoading(true); setText(''); setUsedAI(true);
    const { lines } = buildData();
    const today = new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' });
    const prompt = `You are Event Boss, a calm event-planning copilot. Write a SHORT 3-sentence morning standup for the planner: what needs attention across their events today. Specific, warm, plainspoken. No greeting, no fluff, no markdown, no bullet points.\n\nToday: ${today}\nEvents:\n${lines.join('\n') || '(no upcoming events)'}\n\nStandup:`;
    try {
      if (proxyOn) {
        const r = await callAiFeature('event_brief', prompt, { today });
        const out = (r && r.text || '').trim();
        if (out) setText(out); else { setText(deterministic()); setUsedAI(false); }
      } else {
        await askNGW('event_brief', prompt, { aiKey, maxTokens: 220, onChunk: t => setText(t) });
      }
    } catch (e) {
      // 401 from the proxy ("please sign in") or any error → honest local summary.
      setText(deterministic()); setUsedAI(false);
    }
    setLoading(false);
  };

  const steel = C.accentTopGrad || C.accent;
  if (!open) {
    return (
      <button onClick={brief} aria-label="Brief me — daily standup"
        style={{
          display: 'inline-flex', alignItems: 'center', gap: 7, marginBottom: 16,
          padding: '8px 14px', minHeight: 38, borderRadius: 10,
          background: `${steel}12`, border: `1px solid ${steel}40`,
          color: steel, fontFamily: 'inherit', fontSize: T.secondary, fontWeight: FW.bold,
          cursor: 'pointer', letterSpacing: '0.01em',
        }}>
        <Icon name="sparkle" size={13} /> Brief me
      </button>
    );
  }
  return (
    <div style={{
      marginBottom: 16, padding: '14px 16px', borderRadius: 12,
      background: C.surface, border: `1px solid ${steel}40`, borderLeft: `3px solid ${steel}`,
    }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 8 }}>
        <Icon name="sparkle" size={12} style={{ color: steel }} />
        <span style={{ fontSize: T.eyebrow, fontWeight: FW.heavy, letterSpacing: '0.14em', textTransform: 'uppercase', color: steel }}>
          {usedAI ? 'Your daily brief' : 'Your daily summary'}
        </span>
        <span style={{ flex: 1 }} />
        <button onClick={brief} disabled={loading} aria-label="Refresh briefing"
          style={{ background: 'none', border: 'none', cursor: loading ? 'default' : 'pointer', color: C.muted, fontSize: T.caption, fontFamily: 'inherit', padding: '2px 6px' }}>↻</button>
        <button onClick={() => setOpen(false)} aria-label="Close briefing"
          style={{ background: 'none', border: 'none', cursor: 'pointer', color: C.muted, fontSize: T.secondary, fontFamily: 'inherit', padding: '2px 6px' }}>✕</button>
      </div>
      <div style={{ fontSize: T.secondary, lineHeight: 1.55, color: C.text }}>
        {text || (loading ? <span style={{ color: C.muted, fontStyle: 'italic' }}>Reading your events…</span> : '')}
      </div>
      {!usedAI && !loading && (
        <div style={{ fontSize: T.caption, color: C.muted, marginTop: 8 }}>
          Rule-based summary. Add your Anthropic key in Settings for a written brief.
        </div>
      )}
    </div>
  );
}

// Sprint 60.K: Reusable EmptyStateCard. Every empty surface should answer:
// "What belongs here?", "Why does it matter?", and "What should I do next?".
// One primary CTA required (route, modal, or honest light-handoff). Secondary
// CTA optional. No fake send/pay/notify CTAs — every action must do exactly
// what it says (UX_07). Carbon surface, generous spacing, ≥44px CTA.
function EmptyStateCard({ tag, title, body, primaryCta, onPrimary, secondaryCta, onSecondary, example }) {
  const C = useT();
  const T = useType();
  return (
    <div style={{
      padding: '22px 22px 24px',
      background: C.surface,
      border: `1px solid ${C.border}`,
      borderRadius: 12,
      display: 'flex', flexDirection: 'column', gap: 12,
    }}>
      {tag && (
        <div style={{
          fontSize: T.secondary, fontWeight: FW.bold, letterSpacing: '0.14em',
          textTransform: 'uppercase', color: C.muted,
        }}>{tag}</div>
      )}
      <div style={{
        fontSize: T.title, fontWeight: FW.heavy, letterSpacing: '-0.02em',
        lineHeight: 1.22, color: C.text,
      }}>{title}</div>
      {body && (
        <div style={{
          fontSize: T.body, lineHeight: 1.52, color: C.muted,
        }}>{body}</div>
      )}
      {example && (
        <div style={{
          fontSize: T.secondary, lineHeight: 1.45, color: C.muted, opacity: 0.88,
          fontStyle: 'italic',
        }}>{example}</div>
      )}
      <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap', alignItems: 'center', marginTop: 4 }}>
        {/* Sprint 60.L Studio Matte CTA — 3D depth:
            top highlight, bottom inner shadow, two-stop drop shadow,
            hairline border, subtle text-shadow for tonal weight. */}
        <button onClick={onPrimary}
          onMouseEnter={e => { e.currentTarget.style.transform = 'translateY(-1px)'; e.currentTarget.style.filter = 'brightness(1.06)'; }}
          onMouseLeave={e => { e.currentTarget.style.transform = 'translateY(0)'; e.currentTarget.style.filter = 'brightness(1)'; }}
          onMouseDown={e => { e.currentTarget.style.transform = 'translateY(1px)'; e.currentTarget.style.boxShadow = 'inset 0 2px 4px rgba(0,0,0,0.30), 0 2px 6px rgba(0,0,0,0.40), 0 0 0 1px rgba(193,203,208,0.18)'; }}
          onMouseUp={e => { e.currentTarget.style.transform = 'translateY(-1px)'; e.currentTarget.style.boxShadow = 'inset 0 1px 0 rgba(255,255,255,0.14), inset 0 -1px 0 rgba(0,0,0,0.30), 0 1px 0 rgba(255,255,255,0.04), 0 6px 14px rgba(0,0,0,0.40), 0 18px 36px rgba(0,0,0,0.30), 0 0 0 1px rgba(193,203,208,0.18)'; }}
          style={{
            padding: '15px 24px', minHeight: 54, borderRadius: 16,
            border: 'none',
            background: `linear-gradient(180deg, ${C.accentTopGrad} 0%, ${C.accentDeep} 100%)`,
            color: C.accentText,
            fontSize: T.body, fontWeight: FW.bold, cursor: 'pointer',
            fontFamily: 'inherit',
            letterSpacing: '0.01em',
            textShadow: '0 1px 0 rgba(0,0,0,0.25)',
            boxShadow: 'inset 0 1px 0 rgba(255,255,255,0.14), inset 0 -1px 0 rgba(0,0,0,0.30), 0 1px 0 rgba(255,255,255,0.04), 0 6px 14px rgba(0,0,0,0.40), 0 18px 36px rgba(0,0,0,0.30), 0 0 0 1px rgba(193,203,208,0.18)',
            transition: 'transform 0.16s cubic-bezier(.2,.7,.2,1), box-shadow 0.16s, filter 0.16s',
          }}>{primaryCta}</button>
        {secondaryCta && (
          <button onClick={onSecondary} style={{
            padding: '12px 14px', minHeight: 44, borderRadius: 8,
            border: 'none', background: 'transparent', color: C.muted,
            fontSize: T.body, fontWeight: FW.medium, cursor: 'pointer',
            textDecoration: 'underline', textDecorationColor: C.border,
            textUnderlineOffset: 3, fontFamily: 'inherit',
          }}>{secondaryCta}</button>
        )}
      </div>
    </div>
  );
}

function StudioCommandPanel({ events, clients, onSelectEvent, onJumpToAttention, onJumpToEvents, onNew, onLoadSampleData, profile }) {
  const C = useT();
  const T = useType();
  const bp = useContext(BpCtx);
  const isWide = bp === 'desktop' || bp === 'tablet-land';
  const isMobile = bp === 'mobile';
  const rawCommand = useMemo(() => selectStudioCommand(events), [events]);
  // Sprint 60.O Addendum: when only sample data is loaded, override the
  // hero into "explore first" onboarding mode. Showing real urgency
  // ("2 blockers") on data the user knows isn't theirs is dishonest and
  // fails the grandmother test ("panic about fake events"). The override
  // names the data identity and offers a calm, instructive next step.
  const hasSampleData = useMemo(() =>
    (events || []).some(e => SEED_EVENT_IDS.has(e.id)),
    [events]);
  const hasOnlySample = useMemo(() =>
    hasSampleData && !(events || []).some(e => !SEED_EVENT_IDS.has(e.id)),
    [events, hasSampleData]);
  const command = useMemo(() => {
    if (!hasOnlySample || !rawCommand) return rawCommand;
    // Pick the first sample event so the primary CTA can route into it.
    const firstSample = (events || []).find(e => SEED_EVENT_IDS.has(e.id));
    return {
      level: 'neutral',
      category: 'sample',
      eventId: firstSample?.id,
      eventName: firstSample?.name,
      title: 'Explore the app first.',
      // Sprint 60.O Addendum: locked sample-mode body copy.
      consequence: 'Tap around to see how planning works before adding your own event.',
      primaryCta: firstSample ? 'Open sample event' : 'Plan your own event',
      primaryRoute: firstSample ? { eventId: firstSample.id, tab: 'Command' } : undefined,
      primaryAction: firstSample ? undefined : 'new-event',
      secondaryCta: 'Plan your own event',
      secondaryAction: 'new-event',
    };
  }, [rawCommand, hasOnlySample, events]);
  // Sprint 60.L F4: derive isTodayEvent up here so the hook is
  // unconditional (Rules of Hooks). Falls back to false when there's no
  // command or no eventId.
  const isTodayEvent = useMemo(() => {
    if (!command || !command.eventId) return false;
    const ev = (events || []).find(e => e.id === command.eventId);
    if (!ev || !ev.date) return false;
    return daysUntil(ev.date) === 0;
  }, [command, events]);
  if (!command) return null;

  // Visual treatment per level — Studio Matte calibrated
  const accent =
    command.level === 'critical'  ? C.danger :
    command.level === 'attention' ? C.muted   :
                                    C.accent2; // neutral / quiet steel
  // Sprint 60.L F4: LIVE badge fires whenever the resolved hero event
  // is happening TODAY, regardless of which tier selectStudioCommand
  // returned. Additive: a critical blocker still owns tier color/copy,
  // the LIVE chip just confirms "yes, this is also today." isTodayEvent
  // is hoisted above the early return for Rules of Hooks compliance.
  const isToday = command.category === 'today' || isTodayEvent;
  // Sprint 60.O Addendum + 60.P Addendum: single-voice state-aware
  // eyebrow system. Split critical (START HERE) from attention
  // (NEEDS FOLLOW-UP) per the 60.P locked copy. The today-active
  // (LIVE · ACT NOW) variant fires when the today event has urgent
  // day-of items; plain today (TODAY · LIVE) fires when it's clean.
  const label =
    command.category === 'empty'             ? 'WELCOME' :
    hasOnlySample                            ? 'SAMPLE · NOT A REAL EVENT' :
    command.category === 'today-act'         ? 'LIVE · ACT NOW' :
    command.category === 'today' || isToday  ? 'TODAY · LIVE' :
    command.level === 'critical'             ? 'START HERE' :
    command.level === 'attention'            ? 'NEEDS FOLLOW-UP' :
    command.category === 'multiple-upcoming' ? 'UPCOMING EVENTS' :
    command.category === 'calendar'          ? 'UPCOMING EVENT' :
    command.category === 'all-clear'         ? 'ALL CLEAR' :
                                               'ALL CLEAR';

  const handlePrimary = () => {
    if (command.primaryAction === 'new-event') { onNew && onNew(); return; }
    if (command.primaryAction === 'events')    { onJumpToEvents && onJumpToEvents(); return; }
    if (command.primaryRoute && command.primaryRoute.eventId) {
      const { eventId, ...nav } = command.primaryRoute;
      onSelectEvent(eventId, nav);
    }
  };
  const handleSecondary = () => {
    if (command.secondaryAction === 'attention') { onJumpToAttention && onJumpToAttention(); return; }
    if (command.secondaryAction === 'events')    { onJumpToEvents && onJumpToEvents(); return; }
    if (command.secondaryAction === 'sample')    { onLoadSampleData && onLoadSampleData(); return; }
    if (command.secondaryAction === 'new-event') { onNew && onNew(); return; }
    // Sprint 60.O Addendum: tiers with a concrete secondary route (today
    // → View full event details, multi-upcoming → Open today's event)
    // navigate via the route object directly.
    if (command.secondaryRoute && command.secondaryRoute.eventId) {
      const { eventId, ...nav } = command.secondaryRoute;
      onSelectEvent(eventId, nav);
    }
  };

  return (
    <div
      role="region"
      aria-label="Studio command"
      style={{
        position: 'relative',
        marginBottom: isWide ? 28 : 22,
        padding: isWide ? '24px 28px 24px 32px' : '20px 18px 20px 22px',
        background: C.surface,
        border: `1px solid ${C.border}`,
        borderRadius: 14,
        // Sprint 60.P refinement: subtle Studio Matte 3D raise — panel
        // lifts off the Mid Carbon page with a faint top-edge highlight,
        // a soft mid drop, and a deeper floor shadow. Lighter intensity
        // than the CTA stack so a large panel doesn't feel heavy.
        boxShadow: [
          'inset 0 1px 0 rgba(255,255,255,0.05)',
          '0 1px 0 rgba(255,255,255,0.02)',
          '0 4px 10px rgba(0,0,0,0.30)',
          '0 14px 28px rgba(0,0,0,0.22)',
        ].join(', '),
        overflow: 'hidden',
      }}
    >
      {/* Editorial accent strip on the left — single piece of light, doctrine-compliant */}
      <div style={{
        position: 'absolute', left: 0, top: 0, bottom: 0, width: 4,
        background: accent,
        opacity: command.level === 'neutral' ? 0.4 : 1,
      }} />

      {/* Label tag row — Sprint 60.K-v2: 11.5 → 12 to meet status-pill
          12px min. Sprint 60.L F4: when the event is happening TODAY,
          render a paired LIVE chip so the user instantly recognizes the
          operational moment. Amber chip; no animation, no chaos. */}
      <div style={{
        display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap',
        marginBottom: isMobile ? 12 : 12,
      }}>
        <div style={{
          fontSize: T.eyebrow,
          fontWeight: FW.bold, letterSpacing: isMobile ? '0.14em' : '0.18em',
          textTransform: 'uppercase', color: accent,
        }}>
          {label}
        </div>
        {isToday && (
          <span aria-label="Event is happening today" style={{
            display: 'inline-flex', alignItems: 'center', gap: 6,
            fontSize: T.secondary, fontWeight: FW.heavy, letterSpacing: '0.12em',
            textTransform: 'uppercase', color: '#fff',
            background: accent, padding: '3px 10px', borderRadius: 999,
            lineHeight: 1,
          }}>
            <span aria-hidden="true" style={{
              width: 7, height: 7, borderRadius: '50%',
              background: '#fff',
            }} />
            LIVE
          </span>
        )}
      </div>

      {/* Title — Sprint 60.K-v2: mobile hero h2 24 → 30 to hit the
          30–36px hero target. Line-height tightened to 1.15 to keep
          two-line headlines from breathing too wide. */}
      <h2 style={{
        margin: 0, marginBottom: isMobile ? 14 : 10,
        fontSize: isWide ? 30 : isMobile ? 30 : 26,
        fontWeight: FW.heavy, letterSpacing: '-0.028em',
        lineHeight: 1.15, color: C.text,
        fontFamily: 'inherit',
      }}>
        {command.title}
      </h2>

      {/* Consequence paragraph — Sprint 60.K-v2: subtitle 14.5 → 15.5
          to hit the 15–17px helper-copy target on phone brightness. */}
      <p style={{
        margin: 0, marginBottom: isMobile ? 22 : 18,
        fontSize: isWide ? 14 : isMobile ? 15.5 : 13.5,
        lineHeight: 1.55, color: C.muted,
        maxWidth: 720,
      }}>
        {command.consequence}
      </p>

      {/* Action well + row.
          Sprint 60.P refinement: a small recessed well anchors the CTAs.
          Inset shadow + slightly deeper Carbon background sets the well
          *into* the panel surface, so the steel-blue gradient reads as a
          physical button sitting in a tray rather than floating on top.
          Action row stays stacked on mobile (full-width), inline on
          desktop. */}
      <div style={{
        background: C.bg,
        borderRadius: isMobile ? 14 : 12,
        padding: isMobile ? '12px 12px' : '12px 14px',
        boxShadow: [
          'inset 0 2px 4px rgba(0,0,0,0.35)',
          'inset 0 1px 0 rgba(0,0,0,0.40)',
          'inset 0 -1px 0 rgba(255,255,255,0.03)',
        ].join(', '),
      }}>
      <div style={{
        display: 'flex',
        flexDirection: isMobile ? 'column' : 'row',
        alignItems: isMobile ? 'stretch' : 'center',
        gap: isMobile ? 10 : 12,
        flexWrap: isMobile ? 'nowrap' : 'wrap',
      }}>
        {/* Sprint 60.L Studio Matte Button Polish:
            • neutral (default) tier → silvery steel-blue gradient
              (brushed camera metal feel: #4E6877 → #3F5B6A,
              inner top highlight, 1px steel-mist border, soft shadow).
            • critical / attention tiers keep their semantic fill
              (red / amber) — those are operational signals, not the
              accent identity.
            • text uses steel mist (#A8B7BF) on the neutral CTA — quiet
              confidence vs. pure white. White text reserved for the
              semantic-color tiers. */}
        {(() => {
          // Sprint 60.M Phase 2a: primary CTA is steel-blue across ALL tiers.
          // The accent rail (left strip) + the tier label/chip carry the
          // semantic signal — critical doesn't need a red button fighting
          // the gradient hierarchy. One CTA voice; tier tells you what kind.
          const fillBg = `linear-gradient(180deg, ${C.accentTopGrad} 0%, ${C.accentDeep} 100%)`;
          const ctaText = C.accentText;
          const shadow3D = [
            'inset 0 1px 0 rgba(255,255,255,0.14)',
            'inset 0 -1px 0 rgba(0,0,0,0.30)',
            '0 1px 0 rgba(255,255,255,0.04)',
            '0 6px 14px rgba(0,0,0,0.40)',
            '0 18px 36px rgba(0,0,0,0.30)',
            '0 0 0 1px rgba(193,203,208,0.18)',
          ].join(', ');
          return (
            <button
              onClick={handlePrimary}
              style={{
                // Sprint 60.P fix: full-width on mobile so the gradient
                // commands the hero edge. Justify-content: center keeps
                // the label + arrow visually balanced on the wide button.
                width: isMobile ? '100%' : undefined,
                padding: isWide ? '13px 24px' : isMobile ? '15px 24px' : '13px 22px',
                minHeight: isMobile ? 54 : undefined,
                borderRadius: isMobile ? 14 : 12,
                border: 'none',
                cursor: 'pointer',
                background: fillBg,
                color: ctaText,
                fontSize: isWide ? 14 : isMobile ? 16 : 13.5,
                fontWeight: FW.bold,
                letterSpacing: '0.01em',
                fontFamily: 'inherit',
                display: isMobile ? 'flex' : 'inline-flex',
                alignItems: 'center',
                justifyContent: 'center',
                gap: 8,
                transition: 'transform 0.16s cubic-bezier(.2,.7,.2,1), box-shadow 0.16s, filter 0.16s',
                boxShadow: shadow3D,
                textShadow: '0 1px 0 rgba(0,0,0,0.25)',
              }}
              onMouseEnter={e => { e.currentTarget.style.transform = 'translateY(-1px)'; e.currentTarget.style.filter = 'brightness(1.06)'; }}
              onMouseLeave={e => { e.currentTarget.style.transform = 'translateY(0)'; e.currentTarget.style.filter = 'brightness(1)'; }}
              onMouseDown={e => { e.currentTarget.style.transform = 'translateY(1px)'; e.currentTarget.style.boxShadow = 'inset 0 2px 4px rgba(0,0,0,0.30), 0 2px 6px rgba(0,0,0,0.40), 0 0 0 1px rgba(193,203,208,0.18)'; }}
              onMouseUp={e => { e.currentTarget.style.transform = 'translateY(-1px)'; e.currentTarget.style.boxShadow = shadow3D; }}
            >
              {command.primaryCta}
              <span style={{ fontSize: T.secondary, opacity: 0.85 }}>→</span>
            </button>
          );
        })()}
        {command.secondaryCta && (
          <button
            onClick={handleSecondary}
            style={{
              // Sprint 60.P fix: full-width centered link on mobile so it
              // visually pairs with the primary stack. Underline kept on
              // desktop for inline-row context; dropped on mobile because
              // the stacked block alignment already reads as "tap me".
              width: isMobile ? '100%' : undefined,
              padding: isWide ? '10px 14px' : isMobile ? '12px 14px' : '10px 12px',
              minHeight: isMobile ? 46 : undefined,
              borderRadius: 8,
              border: 'none',
              background: 'transparent',
              color: C.muted,
              fontSize: isWide ? 12.5 : isMobile ? 14 : 12.5,
              fontWeight: FW.medium,
              cursor: 'pointer',
              fontFamily: 'inherit',
              textDecoration: isMobile ? 'none' : 'underline',
              textUnderlineOffset: 3,
              textDecorationColor: C.border,
              textAlign: 'center',
            }}
            onMouseEnter={e => { e.currentTarget.style.color = C.text; }}
            onMouseLeave={e => { e.currentTarget.style.color = C.muted; }}
          >
            {command.secondaryCta}
          </button>
        )}
      </div>
      </div>
    </div>
  );
}

// ─── Global Compose — full communications hub, accessible from every screen ─────
// Sprint 66+: Message · Approval request · Follow-up · Internal note ·
// 📞 Call · 💬 WhatsApp · 📧 Email client — all one click from anywhere.
function GlobalCompose({ events, profile, clients, onMessageSent, onOpenConnections, currentEventId = null, open: controlledOpen, onOpenChange }) {
  const C    = useT();
  const s    = makeS(C);
  const bp   = useContext(BpCtx);
  const isMob = bp === 'mobile';
  // Sprint 61 (board / Wroblewski + Norman): the floating compose FAB was
  // killed. It was phantom-global — a fixed disc that only ever mounted on L1
  // Studio Home yet advertised "from anywhere," contradicting the IA and lying
  // about its affordance. Compose is now reached from an explicit Studio nav
  // item (and, inside an event, from the Messages tab + Reply CTAs). The
  // component is therefore CONTROLLED: the parent owns `open`. (A self-managed
  // fallback remains so any future uncontrolled mount still works.)
  const [internalOpen, setInternalOpen] = useState(false);
  const open    = controlledOpen !== undefined ? controlledOpen : internalOpen;
  const setOpen = (v) => { if (onOpenChange) onOpenChange(v); else setInternalOpen(v); };
  const [selectedEventId, setSelectedEventId] = useState('');
  const [channel,         setChannel]         = useState('client');
  const [msgType,         setMsgType]         = useState('message');
  const [subject,         setSubject]         = useState('');
  const [body,            setBody]            = useState('');
  const [busy,            setBusy]            = useState(false);
  const [sent,            setSent]            = useState(false);
  const [showTpl,         setShowTpl]         = useState(false);
  const commLive     = isCommApiConfigured() && canAuthenticatePlanner();
  const emailEnabled = isEmailConfigured();

  const activeEvents = useMemo(() =>
    events.filter(e => !e.archived && e.date && daysUntil(e.date) > -30)
      .sort((a, b) => (a.date || '').localeCompare(b.date || '')),
    [events]);
  const selectedEvent = useMemo(() =>
    events.find(e => e.id === selectedEventId) || null,
    [events, selectedEventId]);
  // Sprint 51B P0 Fix 1 — context inheritance / no silent event switch.
  // When the panel OPENS:
  //  • If launched with a source context (currentEventId — e.g. from an
  //    event, decision, approval, request, promise or vendor), inherit THAT
  //    event automatically.
  //  • Otherwise (the generic Home FAB, no source) NEVER silently assume a
  //    particular event. Auto-select only when there is exactly one active
  //    event (unambiguous); when there are several, leave the picker empty
  //    so the planner chooses explicitly — the old behaviour of defaulting
  //    to the soonest active event was the documented trust violation.
  //  • An explicit dropdown change is the only other way the event switches.
  useEffect(() => {
    if (!open) return;
    if (currentEventId && events.some(e => e.id === currentEventId)) {
      if (currentEventId !== selectedEventId) { setSelectedEventId(currentEventId); setChannel('client'); }
    } else if (!currentEventId && !selectedEventId && activeEvents.length === 1) {
      setSelectedEventId(activeEvents[0].id);
    }
  }, [open, currentEventId]); // eslint-disable-line react-hooks/exhaustive-deps

  const vendors = selectedEvent ? (selectedEvent.vendors || []).filter(v => v.contact || v.phone) : [];

  // The client linked to the selected event (used for both the "To" dropdown
  // label and the recipient identity card).
  const eventClient = useMemo(() =>
    selectedEvent ? (clients.find(c => (c.eventIds || []).includes(selectedEvent.id)) || null) : null,
    [selectedEvent, clients]);

  // Sprint 51B P0 Fix 2 — recipient identity. Resolve the ACTUAL person/company
  // (name, role, email, company) rather than the abstract Client/Vendor/Team.
  const recipient = useMemo(() => {
    if (!selectedEvent) return null;
    if (channel === '__team') return { name: 'Team', role: 'Internal note', isInternal: true };
    if (channel === 'client') {
      return eventClient
        ? { name: eventClient.name, role: 'Client', email: eventClient.email, phone: eventClient.phone, whatsapp: eventClient.whatsapp, googleVoice: eventClient.googleVoice }
        : null;
    }
    const v = vendors.find(vd => vd.name === channel);
    if (!v) return null;
    const hasPerson = v.contactName && v.contactName !== v.name;
    return {
      name: hasPerson ? v.contactName : v.name,
      role: v.category || 'Vendor',
      company: hasPerson ? v.name : undefined,
      email: v.contact, phone: v.phone, whatsapp: v.whatsapp, googleVoice: v.googleVoice,
    };
  }, [selectedEvent, channel, eventClient, vendors]);

  const canEmail = commLive && emailEnabled && !!recipient?.email;
  const canWA    = !!(recipient?.whatsapp || recipient?.phone);
  const canCall  = !!recipient?.phone;

  // Sprint 61 (board / Kare): emoji removed — they fought Studio Matte. The
  // pills carry their meaning in the word alone, like every other chip system.
  const TYPES = [
    { id: 'message',  label: 'Message',       placeholder: 'Write your message…',            autoSubj: '' },
    { id: 'approval', label: 'Approval',      placeholder: 'Describe what needs approval…',  autoSubj: 'Approval needed' },
    { id: 'followup', label: 'Follow-up',     placeholder: 'Following up on…',               autoSubj: 'Following up' },
    { id: 'note',     label: 'Internal note', placeholder: 'Private note — not sent…',        autoSubj: '' },
  ];

  const TEMPLATES = [
    { label: 'Contract follow-up',   text: 'Hi [Name], following up on the contract for your event. Could you review and sign at your earliest convenience?' },
    { label: 'Payment reminder',     text: 'Hi [Name], friendly reminder that a payment is due for your event. Let me know if you need invoice details.' },
    { label: 'Confirm arrival time', text: 'Hi [Name], confirming your arrival time. Please confirm so we can coordinate venue access.' },
    { label: 'RSVP deadline',        text: 'Hi [Name], RSVP deadline is approaching. Could you send the final headcount this week? Catering needs it.' },
    { label: 'Day-of logistics',     text: 'Hi [Name], sharing day-of logistics. Please confirm you have everything you need from your end.' },
    { label: 'Request approval',     text: 'Hi [Name], requesting your approval before we proceed. Please review and confirm at your earliest convenience.' },
    { label: 'Thank you',            text: 'Hi [Name], thank you for everything. It was a pleasure working with you and we look forward to future events.' },
  ];

  const pickType = (id) => {
    setMsgType(id);
    const t = TYPES.find(x => x.id === id);
    setSubject(t?.autoSubj || '');
    setShowTpl(false);
  };

  const handleSend = async () => {
    if (!body.trim() || !selectedEvent) return;
    if (msgType === 'note') {
      onMessageSent(selectedEvent.id, {
        id: `gc-note-${Date.now()}`, channel: 'internal', direction: 'internal',
        sender: 'planner', senderName: profile?.name || 'Planner',
        body, text: body, message_type: 'note',
        createdAt: new Date().toISOString(), deliveryStatus: 'note',
      });
      setBody(''); setSent(true);
      setTimeout(() => { setSent(false); setOpen(false); }, 1500);
      return;
    }
    if (busy) return;
    setBusy(true);
    const now = new Date().toISOString();
    const msgCh = channel === 'client' || channel === '__team' ? 'client' : 'vendor';
    const isApproval = msgType === 'approval';
    const base = {
      id: `gc-${Date.now()}`, channel: msgCh, direction: 'outbound',
      sender: 'planner', senderName: profile?.name || 'Planner',
      body, text: body, subject,
      message_type: isApproval ? 'approval_request' : 'standard',
      approval_status: isApproval ? 'pending' : null,
      createdAt: now, vendor_name: msgCh === 'vendor' ? channel : undefined,
    };
    try {
      // Board (Trust): default from the local flag, but the BACKEND result wins
      // below — a non-throwing failure must read 'email-failed', not "sent".
      let deliveryStatus = canEmail ? 'email-accepted' : 'sent-via-app';
      if (commLive && selectedEvent.id) {
        const apiPayload = {
          message_type: base.message_type, author_role: 'planner',
          author_name: profile?.name || 'Planner', body, subject,
        };
        if (isApproval) {
          // approval_request requires approval_context (= the message body).
          // notify_email + recipient_email both sent so the backend can use
          // whichever field is checked first (legacy + current paths).
          apiPayload.approval_context = body;
          if (recipient?.email) {
            apiPayload.notify_email     = recipient.email;
            apiPayload.recipient_email  = recipient.email;
            apiPayload.recipient_name   = recipient.name || undefined;
          }
          // Sprint 58P.4c — per-message portal authorization. Stored in
          // metadata.portal_token; the public portal-respond endpoint requires
          // it. Without it the client portal can only fall back to localStorage.
          if (selectedEvent?.portalToken) {
            apiPayload.portal_token = selectedEvent.portalToken;
          }
        } else if (canEmail && recipient?.email) {
          apiPayload.deliver_email    = true;
          apiPayload.recipient_email  = recipient.email;
          apiPayload.recipient_name   = recipient.name || undefined;
        }
        const result = await commApi.createMessage(selectedEvent.id, 'CLIENT', apiPayload);
        const delivery = result?.metadata?.delivery;
        if (delivery?.status === 'failed') deliveryStatus = 'email-failed';
        else if (delivery?.status === 'accepted' || delivery?.status === 'sent') deliveryStatus = 'email-accepted';
      }
      onMessageSent(selectedEvent.id, { ...base, deliveryStatus });
    } catch {
      onMessageSent(selectedEvent.id, { ...base, deliveryStatus: 'local-only' });
    }
    setBody(''); setSubject(''); setSent(true); setBusy(false);
    setTimeout(() => { setSent(false); setOpen(false); }, 1800);
  };

  const openWA = () => {
    const num  = (recipient?.whatsapp || recipient?.phone || '').replace(/\D/g, '');
    const text = encodeURIComponent(body || 'Hi, regarding your event');
    window.open(`https://wa.me/${num}?text=${text}`, '_blank');
  };
  const openCall   = () => window.open(`tel:${recipient?.phone}`, '_self');
  const canGV      = !!(recipient?.googleVoice || recipient?.phone);
  const openGV     = () => {
    const num = (recipient?.googleVoice || recipient?.phone || '').replace(/\D/g, '');
    window.open(`https://voice.google.com/calls?a=nc,%2B${num}`, '_blank');
  };
  const openMailto = () => {
    const sub = encodeURIComponent(subject || 'Re: Your Event');
    const bod = encodeURIComponent(body || '');
    window.open(`mailto:${recipient?.email}?subject=${sub}&body=${bod}`, '_blank');
  };

  const qBtnBase = {
    flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 5,
    padding: '7px 10px', borderRadius: 8, cursor: 'pointer',
    fontSize: T.caption, fontWeight: FW.semibold, fontFamily: 'inherit',
  };

  return (
    <>
      {/* Sprint 61: floating FAB removed (board kill). Compose opens from the
          Studio nav "New message" item — `open` is controlled by the parent. */}

      {/* Panel */}
      {open && (
        <>
          <div onClick={() => setOpen(false)} style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.3)', zIndex: 198 }} />
          <div style={{
            position: 'fixed', bottom: isMob ? 0 : 24, right: isMob ? 0 : 20, zIndex: 199,
            width: isMob ? '100vw' : 440, maxWidth: '100vw',
            ...metalEdge(C),
            borderRadius: isMob ? '16px 16px 0 0' : 14,
            boxShadow: '0 8px 40px rgba(0,0,0,0.4)',
            display: 'flex', flexDirection: 'column',
            maxHeight: isMob ? '90vh' : '87vh', overflow: 'hidden',
          }}>

            {/* Header */}
            <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '13px 16px', borderBottom: `1px solid ${C.border}`, flexShrink: 0 }}>
              <span style={{ fontSize: T.body }}>✉</span>
              <span style={{ fontWeight: FW.bold, fontSize: T.body, flex: 1, color: C.text }}>Communications</span>
              <button onClick={() => setOpen(false)} style={{ background: 'none', border: 'none', cursor: 'pointer', color: C.muted, fontSize: T.title, lineHeight: 1, padding: '0 4px' }}>×</button>
            </div>

            <div style={{ overflowY: 'auto', flex: 1, display: 'flex', flexDirection: 'column' }}>

              {/* Event + To selectors */}
              <div style={{ padding: '12px 16px', display: 'flex', gap: 8, borderBottom: `1px solid ${C.border}`, flexShrink: 0 }}>
                <div style={{ flex: 1 }}>
                  <label style={{ fontSize: T.caption, color: C.muted, display: 'block', marginBottom: 3, textTransform: 'uppercase', letterSpacing: '0.08em', fontWeight: FW.bold }}>Event</label>
                  <select style={{ ...s.input, fontSize: T.secondary }} value={selectedEventId} onChange={e => { setSelectedEventId(e.target.value); setChannel('client'); }}>
                    {/* Sprint 51B P0 Fix 1 — explicit-choice placeholder so the
                        panel never silently assumes an event the planner did
                        not pick. */}
                    {!selectedEventId && <option value="">Choose event…</option>}
                    {activeEvents.map(ev => <option key={ev.id} value={ev.id}>{ev.name}</option>)}
                    {!activeEvents.length && <option value="">No active events</option>}
                  </select>
                </div>
                <div style={{ flex: 1 }}>
                  <label style={{ fontSize: T.caption, color: C.muted, display: 'block', marginBottom: 3, textTransform: 'uppercase', letterSpacing: '0.08em', fontWeight: FW.bold }}>To</label>
                  <select style={{ ...s.input, fontSize: T.secondary }} value={channel} onChange={e => setChannel(e.target.value)}>
                    <option value="client">{eventClient?.name || 'Client'}</option>
                    {vendors.map(v => <option key={v.id || v.name} value={v.name}>{v.category ? `${v.name} · ${v.category}` : v.name}</option>)}
                    <option value="__team">Team · Internal note</option>
                  </select>
                </div>
              </div>

              {/* Sprint 51B P0 Fix 1 — explicit-choice prompt (shown only when
                  the generic FAB opened without a source event and several
                  events exist). Trust: no message is composed against an
                  unchosen event. */}
              {!selectedEvent && (
                <div style={{ padding: '12px 16px', borderBottom: `1px solid ${C.border}`, flexShrink: 0, fontSize: T.secondary, color: C.muted }}>
                  Choose the event this message is about — nothing is assumed for you.
                </div>
              )}

              {/* Recipient card + quick-action buttons */}
              {recipient && (
                <div style={{ padding: '10px 16px', borderBottom: `1px solid ${C.border}`, flexShrink: 0 }}>
                  {/* Sprint 51B P0 Fix 2 — actual recipient identity:
                      Name · Role · Company (if any) · Email / Phone. */}
                  <div style={{ marginBottom: recipient.isInternal ? 0 : 8 }}>
                    <div style={{ display: 'flex', alignItems: 'baseline', gap: 8, flexWrap: 'wrap' }}>
                      <span style={{ fontWeight: FW.bold, color: C.text, fontSize: T.secondary }}>{recipient.name}</span>
                      {recipient.role && (
                        <span style={{ fontSize: T.caption, fontWeight: FW.semibold, textTransform: 'uppercase', letterSpacing: '0.06em', color: C.muted, border: `1px solid ${C.border}`, borderRadius: 10, padding: '1px 7px' }}>{recipient.role}</span>
                      )}
                    </div>
                    {recipient.company && (
                      <div style={{ fontSize: T.caption, color: C.muted, marginTop: 2 }}>{recipient.company}</div>
                    )}
                    <div style={{ fontSize: T.caption, color: C.muted, marginTop: 3, display: 'flex', flexWrap: 'wrap', gap: '2px 12px' }}>
                      {recipient.email && <a href={`mailto:${recipient.email}`} style={{ color: 'inherit', textDecoration: 'none' }} title={`Email ${recipient.email}`}>📧 {recipient.email}</a>}
                      {recipient.phone && <a href={`tel:${String(recipient.phone).replace(/\s/g, '')}`} style={{ color: 'inherit', textDecoration: 'none' }} title={`Call ${recipient.phone}`}>📞 {recipient.phone}</a>}
                      {!recipient.email && !recipient.phone && !recipient.isInternal && (
                        <span style={{ color: C.muted }}>⚠ No contact info on file</span>
                      )}
                    </div>
                  </div>
                  {!recipient.isInternal && (canCall || canWA || canGV || recipient.email) && (
                    <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap' }}>
                      {canCall && (
                        <button onClick={openCall} style={{ ...qBtnBase, border: `1px solid ${C.border}`, background: 'transparent', color: C.text }}>
                          📞 Call
                        </button>
                      )}
                      {canWA && (
                        <button onClick={openWA} style={{ ...qBtnBase, border: '1px solid #25D366', background: '#25D36614', color: '#25D366' }}>
                          💬 WhatsApp
                        </button>
                      )}
                      {canGV && (
                        <button onClick={openGV} style={{ ...qBtnBase, border: '1px solid #1A73E8', background: '#1A73E814', color: '#1A73E8' }}>
                          📞 Google Voice
                        </button>
                      )}
                      {recipient.email && (
                        <button onClick={openMailto} title="Opens your email app with a draft. Nothing is sent until you send the draft." style={{ ...qBtnBase, border: `1px solid ${C.border}`, background: 'transparent', color: C.text }}>
                          📧 Open in email app
                        </button>
                      )}
                    </div>
                  )}
                </div>
              )}

              {/* Message type pills */}
              <div style={{ padding: '10px 16px', display: 'flex', gap: 5, flexWrap: 'wrap', borderBottom: `1px solid ${C.border}`, flexShrink: 0 }}>
                {TYPES.map(t => (
                  <button key={t.id} onClick={() => pickType(t.id)} style={{
                    padding: '5px 11px', borderRadius: 20, fontSize: T.caption, fontWeight: FW.semibold,
                    border: `1px solid ${msgType === t.id ? C.accent : C.border}`,
                    background: msgType === t.id ? C.accent + '20' : 'transparent',
                    color: msgType === t.id ? C.accent : C.muted,
                    cursor: 'pointer', fontFamily: 'inherit',
                  }}>{t.label}</button>
                ))}
              </div>

              {/* Templates */}
              <div style={{ padding: '8px 16px', borderBottom: `1px solid ${C.border}`, flexShrink: 0 }}>
                <button onClick={() => setShowTpl(v => !v)} style={{ background: 'none', border: 'none', cursor: 'pointer', fontSize: T.caption, color: C.muted, fontFamily: 'inherit', padding: 0, display: 'flex', alignItems: 'center', gap: 4 }}>
                  {showTpl ? '▾' : '▸'} Quick templates
                </button>
                {showTpl && (
                  <div style={{ marginTop: 6, display: 'flex', flexDirection: 'column', gap: 3 }}>
                    {TEMPLATES.map(t => (
                      <button key={t.label} onClick={() => { setBody(t.text); setShowTpl(false); }}
                        style={{ textAlign: 'left', background: 'transparent', border: `1px solid ${C.border}`, borderRadius: 6, padding: '5px 10px', cursor: 'pointer', fontSize: T.caption, color: C.text, fontFamily: 'inherit' }}
                        onMouseEnter={e => e.currentTarget.style.background = C.accent + '14'}
                        onMouseLeave={e => e.currentTarget.style.background = 'transparent'}
                      >{t.label}</button>
                    ))}
                  </div>
                )}
              </div>

              {/* Subject line */}
              {(canEmail || msgType === 'approval' || msgType === 'followup') && msgType !== 'note' && (
                <div style={{ padding: '8px 16px 0', flexShrink: 0 }}>
                  <input
                    type="text" value={subject} onChange={e => setSubject(e.target.value)}
                    placeholder="Subject line…"
                    style={{ ...s.input, fontSize: T.secondary, width: '100%', boxSizing: 'border-box' }}
                  />
                </div>
              )}

              {/* Body + footer */}
              <div style={{ padding: '8px 16px 14px', display: 'flex', flexDirection: 'column', gap: 8, flex: 1 }}>
                <textarea
                  autoFocus value={body} onChange={e => setBody(e.target.value)}
                  placeholder={TYPES.find(t => t.id === msgType)?.placeholder || 'Write your message…'}
                  onKeyDown={e => { if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) { e.preventDefault(); handleSend(); } }}
                  style={{ ...s.input, minHeight: 90, maxHeight: 200, resize: 'vertical', fontFamily: 'inherit', lineHeight: 1.5, fontSize: T.secondary }}
                />
                {/* Delivery hint — Sprint 58P.4a: explicit "NOT notified" copy when email is
                    not configured so the planner is never misled into thinking the recipient
                    received anything externally. */}
                <div style={{ fontSize: T.caption, color: msgType === 'note' ? C.muted : canEmail ? C.success : C.muted, display: 'flex', alignItems: 'center', gap: 4, flexWrap: 'wrap' }}>
                  <span style={{ width: 5, height: 5, borderRadius: '50%', background: msgType === 'note' ? C.muted : canEmail ? C.success : C.muted, flexShrink: 0 }} />
                  <span>
                    {msgType === 'note'
                      ? 'Internal only — not sent to anyone'
                      : canEmail ? `Email + in-app to ${recipient?.email}`
                      : commLive ? `Email not configured — logged to thread only. ${recipient?.name || 'Recipient'} will NOT be notified.`
                      : `Saved locally. ${recipient?.name || 'Recipient'} will NOT be notified.`}
                  </span>
                  {/* Sprint 60: route-to-fix when email is the missing capability. */}
                  {msgType !== 'note' && !canEmail && commLive && onOpenConnections && (
                    <button
                      type="button"
                      onClick={onOpenConnections}
                      style={{ background: 'none', border: 'none', color: C.accent, fontSize: T.caption, fontWeight: FW.semibold, cursor: 'pointer', padding: 0, marginLeft: 4 }}
                    >
                      Open Connections →
                    </button>
                  )}
                </div>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <span style={{ fontSize: T.caption, color: C.muted }}>⌘↵ to send</span>
                  <button
                    onClick={handleSend}
                    disabled={!body.trim() || busy || !selectedEvent || sent}
                    style={{
                      ...s.btn(body.trim() && !busy && !sent ? 'primary' : 'secondary'),
                      fontSize: T.secondary, padding: '8px 20px', fontWeight: FW.bold,
                      opacity: !body.trim() || busy ? 0.5 : 1,
                    }}
                  >
                    {sent ? (msgType === 'note' ? '✓ Saved'
                              : canEmail ? '✓ Email sent'
                              : '✓ Logged to thread')
                      : busy ? (canEmail ? 'Sending…' : 'Logging…')
                      : msgType === 'note' ? 'Save note'
                      : msgType === 'approval' ? 'Request approval'
                      : canEmail ? 'Send email'
                      : commLive ? 'Log to thread'
                      : 'Log locally'}
                  </button>
                </div>
              </div>
            </div>
          </div>
        </>
      )}
    </>
  );
}

// ─── Sprint 60.A: Pipeline L1 surface ──────────────────────────────────────
// Reads (does not own) clients + events + intake submissions and renders
// them as the revenue workflow: New inquiry → Proposal → Contracted →
// Deposit pending → Booked / Active → Complete. Every card carries a
// truthful primary CTA + an explicit status reason. Zero fake CRM
// pretense, zero new write paths. Conversion of an intake submission
// reuses the Sprint 67 conversion logic via onCreateFromIntake. Sprint
// 60.A also records a first-pipeline-viewed timestamp for the first-run
// signals.
function PipelineView({ events, clients, profile, onSelectEvent, onSelectClient, onNew, onLoadSampleData, onCreateFromIntake, onProfile }) {
  const C  = useT();
  const s  = makeS(C);
  const bp = useContext(BpCtx);
  const isMobile = bp === 'mobile';
  // Record the first-pipeline-viewed timestamp the first time this surface
  // mounts. Idempotent: ignores all later mounts.
  useEffect(() => {
    recordFirstRunSignal('firstPipelineViewedAt');
  }, []);

  // ── Intake submissions (Sprint 67 store) ─────────────────────────────
  // useState + effect (not useMemo) so callers can trigger a re-read after
  // writing back to localStorage without a phantom dependency that confuses
  // the exhaustive-deps lint rule.
  const [intakeSubs, setIntakeSubs] = useState([]);
  const reloadIntakeSubs = () => {
    if (!profile?.intakeToken) { setIntakeSubs([]); return; }
    try {
      const raw = localStorage.getItem(`ngw-intake-submissions-${profile.intakeToken}`);
      setIntakeSubs(raw ? JSON.parse(raw) : []);
    } catch { setIntakeSubs([]); }
  };
  useEffect(() => { reloadIntakeSubs(); /* eslint-disable-next-line react-hooks/exhaustive-deps */ }, [profile?.intakeToken]);
  const newInquiries = intakeSubs.filter(s => s.status === 'new');

  // ── Client-stage derivation ──────────────────────────────────────────
  // Each client + linked event(s) becomes one or more pipeline cards.
  // We lane on client.status (CLIENT_STAGES). Lane assignment is:
  //   • Proposal    ← client.status in ['Inquiry', 'Proposal']
  //   • Contracted  ← client.status === 'Contracted' AND not yet deposit-paid
  //   • Deposit     ← client.status === 'Contracted' AND has unpaid milestone
  //   • Active      ← client.status === 'Active'
  //   • Complete    ← client.status === 'Complete'
  // A client with no events linked still shows up in Proposal so the
  // planner can act on the lead before scheduling.
  const cards = useMemo(() => {
    const out = [];
    for (const c of clients) {
      const linkedEvents = events.filter(e => (c.eventIds || []).includes(e.id));
      // Compute money state from the client's fee schedule.
      const fee        = c.plannerFee || 0;
      const collected  = (c.feeSchedule || []).reduce((sum, f) => sum + (f.paid ? f.amount : (f.paidAmount || 0)), 0);
      const outstanding = Math.max(0, fee - collected);
      const hasUnpaidMilestone = (c.feeSchedule || []).some(f => !f.paid && f.amount > 0);
      const hasMilestones = (c.feeSchedule || []).length > 0;
      const stage = c.status || 'Inquiry';

      // What event date do we surface? Soonest future, or last past.
      const nextEvent = [...linkedEvents].sort((a, b) => (a.date || '').localeCompare(b.date || ''))
        .find(e => e.date && daysUntil(e.date) >= 0) || linkedEvents[0] || null;

      // Lane assignment
      let lane;
      let reason;
      if (stage === 'Complete') {
        lane = 'complete';
        reason = 'Event complete';
      } else if (stage === 'Active') {
        lane = 'active';
        reason = nextEvent && nextEvent.date
          ? `Active · ${daysUntil(nextEvent.date) >= 0 ? `${daysUntil(nextEvent.date)}d to event` : 'past event date'}`
          : 'Active client';
      } else if (stage === 'Contracted') {
        if (hasUnpaidMilestone) {
          lane = 'deposit';
          reason = `Deposit pending · ${fmtD(outstanding)} outstanding`;
        } else {
          lane = 'contracted';
          reason = hasMilestones ? 'Milestones paid' : 'Contract signed — add payment milestones';
        }
      } else {
        // Inquiry / Proposal — pre-contract work
        lane = 'proposal';
        reason = stage === 'Proposal' ? 'Proposal in progress' : 'New lead — start a proposal';
      }
      out.push({
        id: `c-${c.id}`,
        client: c,
        event: nextEvent,
        lane,
        reason,
        stage,
        outstanding,
        fee,
        hasUnpaidMilestone,
        hasMilestones,
      });
    }
    return out;
  }, [clients, events]);

  const byLane = (lane) => cards.filter(c => c.lane === lane);

  // Mobile: a single lane selector chip row; desktop: 5 columns.
  // Board L1 audit (Pipeline mobile): defaulted to 'proposal' — a routinely-EMPTY
  // lane, so mobile landed on "Nothing in this lane right now." Default to the
  // ACTIVE lane (the planner's real work, where events live).
  const [mobileLane, setMobileLane] = useState('active');
  // Sprint 54B: ONE planner-facing vocabulary (clientStatusLabel / STATUS_DISPLAY).
  // The old dual canonical/`friendly` labels are retired — each lane has a single
  // `label`, used in the KPI, the section header, the mobile chip, and reporting.
  // `Contracted` displays as "Booked", `Active` as "Planning". The derived
  // deposit-pending split is NOT a stage: those cards fold into "Booked" and carry a
  // Deposit-due MONEY BADGE (see renderCard). Lane ASSIGNMENT is unchanged — cards
  // keep their internal card.lane ('contracted'/'deposit'); only the display groups
  // them. `hint` is the helper sentence; `cards` is the resolved card list per stage.
  const lanes = [
    { id: 'inquiry',  label: 'Inquiry',  hint: 'New request — decide if it becomes an event',    cards: newInquiries,                              isInquiry: true },
    { id: 'proposal', label: 'Proposal', hint: 'Planning the offer or details',                  cards: byLane('proposal') },
    { id: 'booked',   label: 'Booked',   hint: 'Contract signed — planning may still be needed', cards: [...byLane('contracted'), ...byLane('deposit')] },
    { id: 'active',   label: 'Planning', hint: 'Booked client whose event is being planned',     cards: byLane('active') },
    { id: 'complete', label: 'Complete', hint: 'Event is finished',                               cards: byLane('complete') },
  ].map(l => ({ ...l, count: l.cards.length }));
  const totalCards = newInquiries.length + cards.length;
  const isEmpty = totalCards === 0;

  // ── Sprint 67 conversion reused. Marks submission converted and creates
  // event + client via the existing onCreateFromIntake callback. No new
  // write path.
  const convertInquiry = (sub) => {
    const newClient = {
      id: uid(), name: sub.name, email: sub.email, phone: sub.phone,
      status: 'Inquiry', stage: 'Inquiry', eventIds: [], log: [],
      intakeNotes: sub.notes || '',
      feeSchedule: [], plannerFee: 0,
    };
    const newEvent = {
      id: uid(), rsvpCode: rsvpToken(),
      name: `${sub.name}'s ${sub.eventType || 'Event'}`,
      type: sub.eventType || 'Other',
      date: sub.eventDate || '',
      venue: sub.venue || '',
      guestCount: sub.guestCount ? Number(sub.guestCount) : 0,
      budget: [], vendors: [], guests: [], timeline: [], ros: [], commClient: [],
    };
    // Race fix: create the event first. Only mark the intake submission
    // converted if onCreateFromIntake didn't throw — otherwise the planner
    // could see "converted" with no matching event.
    try {
      onCreateFromIntake && onCreateFromIntake(newEvent, newClient);
    } catch (e) {
      // Surface visibly; do NOT touch the submission state.
      // eslint-disable-next-line no-console
      console.error('convertInquiry: onCreateFromIntake failed — submission left as-is', e);
      return;
    }
    try {
      const key = `ngw-intake-submissions-${profile.intakeToken}`;
      const updated = intakeSubs.map(x => x.id === sub.id ? { ...x, status: 'converted', convertedEventId: newEvent.id } : x);
      localStorage.setItem(key, JSON.stringify(updated));
      reloadIntakeSubs();
    } catch {}
  };

  // ── Inquiry card (intake submission) ─────────────────────────────────
  const renderInquiryCard = (sub) => (
    <div key={sub.id} style={{ display: 'flex', flexDirection: 'column', gap: 6, padding: '12px 14px', background: C.bg, border: `1px solid ${C.border}`, borderRadius: 8 }}>
      <div style={{ fontSize: T.secondary, fontWeight: FW.bold, color: C.text }}>{sub.name}</div>
      <div style={{ fontSize: T.caption, color: C.muted, lineHeight: 1.4 }}>
        {sub.eventType || 'Event'}{sub.eventDate ? ` · ${fmtDate(sub.eventDate)}` : ''}{sub.guestCount ? ` · ${sub.guestCount} guests` : ''}
      </div>
      {sub.notes && <div style={{ fontSize: T.caption, color: C.muted, fontStyle: 'italic', lineHeight: 1.4 }}>"{sub.notes}"</div>}
      <div style={{ display: 'flex', gap: 6, marginTop: 4, flexWrap: 'wrap' }}>
        <button onClick={() => convertInquiry(sub)} style={{ ...s.btn('primary'), fontSize: T.caption, padding: '5px 10px' }}>
          Convert to event
        </button>
      </div>
    </div>
  );

  // ── Client/event card. Primary CTA per lane is truthful: it always
  // routes; it never claims to send anything.
  const renderCard = (card) => {
    const ev = card.event;
    const eng = ev ? engineNextAction(ev) : null; // T1: engine triplet on the card
    const ctaLabel = card.lane === 'active' || card.lane === 'complete'
      ? (ev ? 'Open event →' : 'Open client →')
      : card.lane === 'deposit'
        ? 'Open Budget →'
        : card.lane === 'contracted'
          ? (ev ? 'Open event →' : 'Open client →')
          : 'Open client →';
    const ctaAction = () => {
      if (card.lane === 'active' || card.lane === 'complete' || card.lane === 'contracted') {
        if (ev) onSelectEvent(ev.id);
        else onSelectClient(card.client.id);
      } else if (card.lane === 'deposit') {
        if (ev) onSelectEvent(ev.id, { tab: 'Budget' });
        else onSelectClient(card.client.id);
      } else {
        onSelectClient(card.client.id);
      }
    };
    return (
      <div key={card.id} style={{ display: 'flex', flexDirection: 'column', gap: 6, padding: '12px 14px', background: C.bg, border: `1px solid ${C.border}`, borderRadius: 8 }}>
        <div style={{ fontSize: T.secondary, fontWeight: FW.bold, color: C.text }}>{card.client.name}</div>
        {ev && (
          <div style={{ fontSize: T.caption, color: C.muted, lineHeight: 1.4 }}>
            {ev.name}{ev.date ? ` · ${fmtDate(ev.date)}` : ''}
          </div>
        )}
        {/* Sprint 54B: Deposit Due is a derived MONEY BADGE, not a stage. Shows on
            any booked card with money still owed (the old standalone "Deposit" lane
            folded into Booked), so the money signal survives even when the engine
            binding replaces the reason line below. */}
        {card.hasUnpaidMilestone && card.outstanding > 0 && (
          <span style={{ alignSelf: 'flex-start', fontSize: T.eyebrow, fontWeight: FW.bold, letterSpacing: '0.04em', textTransform: 'uppercase', color: C.accent, background: C.accent + '14', border: `1px solid ${C.accent}44`, borderRadius: 5, padding: '2px 7px' }}>
            Deposit due · {fmtD(card.outstanding)}
          </span>
        )}
        {eng && eng.binding ? (
          <div style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: T.caption, minWidth: 0 }}>
            <span aria-hidden style={{ width: 7, height: 7, borderRadius: '50%', background: ENGINE_FLAG_COLOR(C, eng.flag), flexShrink: 0 }} />
            <span style={{ color: eng.dateAtRisk ? C.danger : C.text, fontWeight: FW.semibold, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', minWidth: 0 }}>{eng.binding.name}</span>
            <span style={{ flexShrink: 0, fontSize: T.eyebrow, fontWeight: FW.bold, letterSpacing: '0.06em', textTransform: 'uppercase', color: C.muted, border: `1px solid ${C.border}`, borderRadius: 4, padding: '1px 5px' }}>{ENGINE_OWNER_LABEL(eng.binding.owner)}</span>
          </div>
        ) : (
          <div style={{ fontSize: T.caption, color: C.muted, lineHeight: 1.4 }}>{card.reason}</div>
        )}
        <div style={{ display: 'flex', gap: 6, marginTop: 4, flexWrap: 'wrap' }}>
          <button onClick={ctaAction} style={{ ...s.btn('ghost'), fontSize: T.caption, padding: '5px 10px' }}>
            {ctaLabel}
          </button>
          {/* Board L1 audit fix: the secondary "Open event" button duplicated the
              primary on active/complete/contracted/deposit lanes (both said
              "Open event →"). Only show it when the primary opens the CLIENT — so
              the two buttons always have distinct destinations. */}
          {ev && !(card.lane === 'active' || card.lane === 'complete' || card.lane === 'contracted' || card.lane === 'deposit') && (
            <button onClick={() => onSelectEvent(ev.id)} style={{ ...s.btn('ghost'), fontSize: T.caption, padding: '5px 10px' }}>
              Open event →
            </button>
          )}
        </div>
      </div>
    );
  };

  // ── Empty state ──────────────────────────────────────────────────────
  if (isEmpty) {
    return (
      <div style={{ padding: '32px 0' }}>
        <div style={{ maxWidth: 560 }}>
          <div style={{ fontSize: T.title, fontWeight: FW.bold, color: C.text, marginBottom: 8 }}>No active pipeline items yet</div>
          <div style={{ fontSize: T.secondary, color: C.muted, lineHeight: 1.55, marginBottom: 18 }}>
            Pipeline shows leads, contracted events, deposits pending, and bookings —
            grouped by stage. Start with an event or copy your intake-form link to
            collect inquiries.
          </div>
          <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap' }}>
            {onNew && (
              <button onClick={onNew} style={{ ...s.btn('primary'), fontSize: T.secondary, padding: '7px 14px' }}>
                Plan your first event
              </button>
            )}
            {profile?.intakeToken && (
              <button
                onClick={() => {
                  const base = window.location.origin + window.location.pathname;
                  const url  = `${base}?intake=${profile.intakeToken}`;
                  copyToClipboard(url, 'Link copied');
                }}
                title="Copy your public intake form link"
                style={{ ...s.btn('ghost'), fontSize: T.secondary, padding: '7px 14px' }}
              >
                Copy intake link
              </button>
            )}
            {!profile?.intakeToken && onProfile && (
              <button onClick={onProfile} style={{ ...s.btn('ghost'), fontSize: T.secondary, padding: '7px 14px' }}>
                Set up intake form →
              </button>
            )}
            {onLoadSampleData && (
              <button onClick={onLoadSampleData} style={{ ...s.btn('ghost'), fontSize: T.secondary, padding: '7px 14px', color: C.muted }}>
                Try a sample event
              </button>
            )}
          </div>
        </div>
      </div>
    );
  }

  // ─── Sprint 60.C: Setup Progress card — real signals only ────────────
  // Derived from the existing ngw-firstrun-signals localStorage (Sprint
  // 60.A) plus live state for "first event" / "first client" so the card
  // never lies: a freshly-cleared workspace shows 0 steps even if the
  // signal timestamps were recorded historically. No fake percentages.
  const setupSignals = readFirstRunSignals();
  const hasRealEvent  = (events || []).some(e => !SEED_EVENT_IDS.has(e.id));
  const hasRealClient = (clients || []).some(c => !SEED_CLIENT_IDS.has(c.id));
  const hasSample     = (events || []).some(e => SEED_EVENT_IDS.has(e.id));
  const steps = [
    { key: 'open',     label: 'Got started',                done: Boolean(setupSignals.firstAppOpenAt) },
    { key: 'event',    label: 'Added your first event',     done: hasRealEvent  || Boolean(setupSignals.firstEventCreatedAt) },
    { key: 'client',   label: 'Added a client',             done: hasRealClient || Boolean(setupSignals.firstClientCreatedAt) },
    { key: 'pipeline', label: 'Checked out the Pipeline',   done: Boolean(setupSignals.firstPipelineViewedAt) },
    { key: 'sample',   label: 'Tried the sample event',     done: hasSample     || Boolean(setupSignals.firstSampleLoadedAt) },
  ];
  const doneCount = steps.filter(s => s.done).length;
  const nextStep = !steps[1].done ? { label: 'Add your first event', action: onNew }
    : !steps[2].done ? { label: 'Add a client', action: null /* opens client modal — handled by parent */ }
    : !steps[0].done ? { label: 'Open the app once more to record', action: null }
    : (hasSample && !hasRealEvent) ? { label: 'Create your real event', action: onNew }
    : null;
  // Board L1 audit fix #5: the Pipeline "Setup progress · 3 of 5" app-tour tracker
  // was a THIRD onboarding counter (after Home's studio + first-event cards) with
  // its own denominator, off-context on the revenue-focused Pipeline. Its two
  // render sites are removed below; this is retained (unused) to avoid churn.
  // eslint-disable-next-line no-unused-vars
  const setupProgressCard = doneCount < steps.length ? (
    <div style={{
      marginBottom: 16, padding: '14px 16px', borderRadius: 10,
      ...metalEdge(C),
      display: 'flex', flexDirection: 'column', gap: 10,
    }}>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 8, flexWrap: 'wrap' }}>
        <div style={{ fontSize: T.caption, fontWeight: FW.bold, letterSpacing: '0.1em', textTransform: 'uppercase', color: C.muted }}>
          Setup progress
        </div>
        <div style={{ fontSize: T.caption, color: C.muted }}>
          {doneCount} of {steps.length} done
        </div>
      </div>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
        {steps.map(s => (
          <span key={s.key} style={{
            fontSize: T.secondary, fontWeight: FW.semibold,
            padding: '6px 11px', borderRadius: 99,
            color: s.done ? C.success : C.muted,
            background: s.done ? C.success + '14' : 'transparent',
            border: `1px solid ${s.done ? C.success + '44' : C.border}`,
          }}>
            {s.done ? '✓ ' : '○ '}{s.label}
          </span>
        ))}
      </div>
      {nextStep && (
        <div style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: T.caption, color: C.muted, flexWrap: 'wrap' }}>
          <span>Next:</span>
          {nextStep.action ? (
            <button onClick={nextStep.action} style={{ ...s.btn('ghost'), fontSize: T.caption, padding: '3px 10px' }}>
              {nextStep.label} →
            </button>
          ) : (
            <span style={{ color: C.text, fontWeight: FW.semibold }}>{nextStep.label}</span>
          )}
        </div>
      )}
    </div>
  ) : null;

  // ── Mobile layout: lane chip row + selected lane content ─────────────
  if (isMobile) {
    const activeLaneObj = lanes.find(l => l.id === mobileLane) || lanes[0];
    const activeLane = activeLaneObj.id;
    const items = activeLaneObj.cards.map(activeLaneObj.isInquiry ? renderInquiryCard : renderCard);
    return (
      <div>
        <div style={{ display: 'flex', gap: 6, overflowX: 'auto', paddingBottom: 10, marginBottom: 12 }}>
          {lanes.map(ln => {
            const isActive = activeLane === ln.id;
            // Sprint 54B: single planner-facing stage label per chip (no dual label).
            return (
              <button key={ln.id} onClick={() => setMobileLane(ln.id)}
                title={ln.hint}
                aria-label={`${ln.label}: ${ln.hint || ''}`}
                style={{
                  display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
                  padding: '11px 16px', borderRadius: 12,
                  minHeight: 46,
                  background: isActive ? C.accent + '22' : 'transparent',
                  border: `1px solid ${isActive ? C.accent : C.border}`,
                  cursor: 'pointer', fontFamily: 'inherit', flexShrink: 0, whiteSpace: 'nowrap',
                  gap: 6,
                }}>
                <span style={{ fontSize: T.secondary, fontWeight: FW.bold, color: isActive ? C.accent : C.text }}>
                  {ln.label}
                </span>
                {ln.count > 0 && (
                  <span style={{ fontWeight: FW.bold, color: isActive ? C.accent : C.muted }}>{ln.count}</span>
                )}
              </button>
            );
          })}
        </div>
        {(() => {
          const activeLaneObj = lanes.find(l => l.id === activeLane);
          return activeLaneObj?.hint ? (
            <div style={{ fontSize: T.secondary, color: C.muted, marginBottom: 14, lineHeight: 1.5 }}>{activeLaneObj.hint}</div>
          ) : null;
        })()}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
          {items.length > 0 ? items : (
            <div style={{ fontSize: T.secondary, color: C.muted, fontStyle: 'italic', padding: '14px 0' }}>
              Nothing in this lane right now.
            </div>
          )}
        </div>
      </div>
    );
  }

  // ── Desktop / tablet-land: 6-column board, auto-wrap to multi-row ────
  const LaneColumn = ({ lane }) => {
    const items = lane.id === 'inquiry' ? newInquiries.map(renderInquiryCard) : byLane(lane.id).map(renderCard);
    return (
      <div style={{ display: 'flex', flexDirection: 'column', gap: 8, minHeight: 120 }}>
        <div style={{ padding: '0 4px 8px', borderBottom: `1px solid ${C.border}` }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
            <span style={{ fontSize: T.caption, fontWeight: FW.bold, letterSpacing: '0.1em', textTransform: 'uppercase', color: C.muted }}>{lane.label}</span>
            {lane.count > 0 && (
              <span style={{ fontSize: T.caption, fontWeight: FW.bold, color: C.muted, background: C.border + '88', borderRadius: 10, padding: '1px 8px' }}>{lane.count}</span>
            )}
          </div>
          {lane.hint && (
            <div style={{ fontSize: T.caption, color: C.muted, marginTop: 4, lineHeight: 1.4 }}>{lane.hint}</div>
          )}
        </div>
        {items.length > 0 ? items : (
          <div style={{ fontSize: T.secondary, color: C.muted, lineHeight: 1.5, padding: '12px 4px', fontStyle: 'italic' }}>
            {/* Sprint 60.L: per-lane plain-language empty copy. Pipeline
                lanes that are routinely empty (no leads / no payments
                waiting) deserve a real message, not a dash. */}
            {lane.id === 'inquiry'    ? 'No new leads yet. Inbound inquiries will land here for triage.'
            : lane.id === 'proposal'  ? 'No proposals out. When you send a planning offer, it shows here.'
            : lane.id === 'contracted'? 'No contracts signed yet. Booked events show here once you mark them confirmed.'
            : lane.id === 'deposit'   ? 'No payments waiting. Vendor deposits and balance-due tracking land here.'
            : lane.id === 'active'    ? 'No active events here right now. In-flight events appear once work begins.'
            : lane.id === 'complete'  ? 'No completed events yet. Wrapped events archive here for reference.'
            : '—'}
          </div>
        )}
      </div>
    );
  };
  // Board L1 audit (Pipeline, kanban/list duality): the old 6-column board led
  // with four routinely-EMPTY pre-booking columns (Inquiry/Proposal/Contracted/
  // Deposit) before the planner's real work (Active events). Restructured into a
  // compact funnel SUMMARY bar (every stage at a glance) + the stages that
  // actually have events, each as a card grid below. One clean structure.
  void LaneColumn; // retained for the mobile path / reference; not used on desktop
  return (
    <div>
      {/* Board 2026-06-12 ("what am I supposed to be looking at?"): the FUNNEL is
          the KPI — lead with it. The old 3-line explainer box buried it; the
          per-lane tooltips + a one-line footnote carry the nuance instead. */}
      {/* Funnel summary — all stages at a glance, counts only. THIS leads. */}
      <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginBottom: 8 }}>
        {lanes.map(ln => (
          <div key={ln.id} title={ln.hint} style={{
            flex: '1 1 120px', minWidth: 110, padding: '10px 12px', borderRadius: 10,
            ...metalEdge(C),
            borderLeft: `3px solid ${ln.count > 0 ? C.accent2 : C.border}`,
            opacity: ln.count > 0 ? 1 : 0.62,
          }}>
            <div style={{ fontSize: T.eyebrow, fontWeight: FW.heavy, letterSpacing: '0.1em', textTransform: 'uppercase', color: C.muted }}>{ln.label}</div>
            <div style={{ fontSize: T.title, fontWeight: FW.heavy, color: ln.count > 0 ? C.text : C.muted, lineHeight: 1.1, marginTop: 2, fontFeatureSettings: '"tnum" 1' }}>{ln.count}</div>
          </div>
        ))}
      </div>
      {/* One-line nuance (the old wall of text, distilled). Per-lane tooltips carry the rest. */}
      <div style={{ fontSize: T.caption, color: C.muted, lineHeight: 1.5, marginBottom: 20 }}>
        Where each deal stands — counts are by client/deal, so this differs from the all-events total.
      </div>
      {/* Stages that have events — each a labeled section with a card grid */}
      {lanes.filter(ln => ln.count > 0).map(ln => {
        const items = ln.cards.map(ln.isInquiry ? renderInquiryCard : renderCard);
        return (
          <div key={ln.id} style={{ marginBottom: 24 }}>
            <div style={{ display: 'flex', alignItems: 'baseline', gap: 8, marginBottom: 10 }}>
              <span style={{ fontSize: T.secondary, fontWeight: FW.heavy, letterSpacing: '0.08em', textTransform: 'uppercase', color: C.text }}>{ln.label}</span>
              <span style={{ fontSize: T.caption, color: C.muted }}>{ln.count}</span>
              {ln.hint && <span style={{ fontSize: T.caption, color: C.muted, fontStyle: 'italic' }}>· {ln.hint}</span>}
            </div>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(260px, 1fr))', gap: 12 }}>
              {items}
            </div>
          </div>
        );
      })}
      {lanes.every(ln => ln.count === 0) && (
        <div style={{ fontSize: T.secondary, color: C.muted, fontStyle: 'italic', padding: '24px 4px' }}>
          No events in the pipeline yet. New events appear here as you create them.
        </div>
      )}
    </div>
  );
}

// Sprint 52B — Getting Started guide for brand-new users: the full
// event/client workflow, step by step. Opened from the welcome hero.
// Each step: [title, desc, key]. `key` drives both the completion check and
// the click destination — clicking a step closes the guide and jumps the user
// to the exact screen/section that needs action (see handleGuideStep), and the
// number flips to a ✓ once that key is satisfied (see guideProgress).
const GETTING_STARTED_STEPS = [
  ['Set up your studio', 'Open Settings (your avatar, top-right) and add your studio name, your name, contact info, and your market. This personalizes client briefs and makes budget estimates accurate for your area.', 'studio'],
  ['Add your first client', 'Go to Clients → New Client and enter their name, email, and phone. A client can be linked to one or more events — now or later.', 'client'],
  ['Create an event', 'Tap New Event. Pick a type, set a date, and add a guest count. Event Boss builds the planning structure for you — timeline, budget categories, and vendor slots.', 'event'],
  ['Estimate the budget', 'On New Event step 3 (or later in the Budget tab), open “Estimate my budget” and choose Good / Better / Best for each category — mix and match — then apply it to seed your budget.', 'budget'],
  ['Add your vendors', 'Inside the event → Vendors. Track each vendor’s contract, payments, and readiness. Save the ones you trust to your Vendor Bank (in Settings) to reuse across events.', 'vendors'],
  ['Assign your crew', 'Event → Crew. Add teammates, give each a role and call time, and mark who has confirmed. Solo events can skip this.', 'crew'],
  ['Start at the event Overview', 'The event’s home screen shows your single next-best action, open decisions, approvals, incoming requests, and overall readiness. Start here each day.', 'command'],
  ['Communicate', 'Event → Messages. Draft messages to clients and vendors. Drafts are copy-first and you choose when to send — nothing goes out automatically.', 'comms'],
  ['Add documents', 'Event → Documents. Upload contracts and files; the status clearly shows what is signed, pending, or still missing.', 'docs'],
  ['Run event day', 'When the day arrives, switch to Day-of Mode for vendor arrivals, the event day schedule, your crew manifest, and live messages — all in one focused view.', 'dayof'],
];

function GettingStartedGuide({ onClose, progress = {}, onStep }) {
  const C = useT();
  const T = useType(); const s = makeS(C);
  const doneCount = GETTING_STARTED_STEPS.filter(([, , key]) => progress[key]).length;
  // Sprint 60.X — slide-in/out drawer. Mount fully off-screen, then animate in
  // on the next frame; on close, animate out first and unmount after the
  // transition so the exit is visible (conditional `{showGuide && …}` alone
  // would pop it out instantly).
  const [shown, setShown] = useState(false);
  useEffect(() => {
    const id = requestAnimationFrame(() => setShown(true));
    return () => cancelAnimationFrame(id);
  }, []);
  const requestClose = () => { setShown(false); setTimeout(() => onClose?.(), 290); };
  // Drag-to-dismiss — grab the handle and slide the drawer out on demand. A
  // tap (no real movement) also closes; a partial drag snaps back.
  const [dragX, setDragX] = useState(0);
  const [dragging, setDragging] = useState(false);
  const startXRef = useRef(0);
  const onDragStart = (e) => { startXRef.current = e.clientX; setDragging(true); try { e.currentTarget.setPointerCapture?.(e.pointerId); } catch (x) { /* ignore */ } };
  const onDragMove = (e) => { if (!dragging) return; setDragX(Math.max(0, e.clientX - startXRef.current)); };
  const onDragEnd = () => {
    if (!dragging) return;
    setDragging(false);
    if (dragX > 110 || dragX < 4) requestClose(); // full slide-out OR a tap
    else setDragX(0);                              // partial drag — snap back
  };
  return (
    <div onClick={(e) => { if (e.target === e.currentTarget) requestClose(); }}
      style={{ position: 'fixed', inset: 0, background: `rgba(7,8,9,${shown ? 0.78 : 0})`, zIndex: 1000, display: 'flex', alignItems: 'stretch', justifyContent: 'flex-end', transition: 'background 0.29s ease' }}>
      <div role="dialog" aria-label="Getting started" style={{ position: 'relative', width: '100%', maxWidth: 560, height: '100%', overflow: 'auto', background: C.surface, borderLeft: `3px solid ${C.accent}`, transform: !shown ? 'translateX(100%)' : `translateX(${dragX}px)`, transition: dragging ? 'none' : 'transform 0.29s cubic-bezier(0.22, 1, 0.36, 1)', boxShadow: '-24px 0 60px rgba(0,0,0,0.45)' }}>
        <div style={{ position: 'sticky', top: 0, zIndex: 2, background: C.surface, padding: '22px 24px 16px', borderBottom: `1px solid ${C.border}`, display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 12 }}>
          <div onPointerDown={onDragStart} onPointerMove={onDragMove} onPointerUp={onDragEnd} onPointerCancel={onDragEnd}
            role="button" aria-label="Slide guide out" title="Drag or tap to slide out"
            style={{ alignSelf: 'center', flexShrink: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', width: 18, height: 40, marginLeft: -6, cursor: 'grab', touchAction: 'none' }}>
            <div style={{ width: 4, height: 30, borderRadius: 2, background: C.accent, opacity: 0.85 }} />
          </div>
          <div style={{ minWidth: 0, flex: 1 }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 7 }}>
              <span style={{ width: 18, height: 2, background: C.accent, borderRadius: 1 }} />
              <span style={{ fontSize: T.caption, fontWeight: FW.heavy, letterSpacing: '0.16em', color: C.accent, textTransform: 'uppercase' }}>Getting started</span>
            </div>
            <div style={{ fontSize: T.title, fontWeight: FW.bold, color: C.text, letterSpacing: '-0.01em' }}>How to run an event, start to finish</div>
            <div style={{ fontSize: T.secondary, color: C.muted, marginTop: 5, lineHeight: 1.55 }}>Ten steps from a blank workspace to event day. Do them in order or jump around — nothing locks.</div>
          </div>
          <button onClick={requestClose} aria-label="Close" style={{ background: C.bg, border: `1px solid ${C.border}`, color: C.muted, width: 30, height: 30, borderRadius: 8, fontSize: T.body, cursor: 'pointer', lineHeight: 1, flexShrink: 0, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>✕</button>
        </div>
        <div style={{ background: C.bg }}>
          {GETTING_STARTED_STEPS.map(([title, desc, key], i) => {
            const done = !!progress[key];
            const clickable = !!onStep;
            const Tag = clickable ? 'button' : 'div';
            return (
                <Tag key={i} type={clickable ? 'button' : undefined}
                  onClick={clickable ? () => { onStep(key); requestClose(); } : undefined}
                  title={clickable ? `Go to: ${title}` : undefined}
                  style={{ display: 'flex', gap: 14, alignItems: 'flex-start', padding: '15px 24px',
                    border: 'none', borderTop: i > 0 ? `1px solid ${C.border}` : 'none',
                    width: '100%', textAlign: 'left', background: 'transparent', fontFamily: 'inherit',
                    cursor: clickable ? 'pointer' : 'default' }}>
                <div style={{ flexShrink: 0, width: 30, height: 30, borderRadius: 9,
                  background: done ? C.accent2 : C.surface,
                  border: `1px solid ${done ? C.accent2 : C.border}`,
                  color: done ? '#fff' : C.accent, fontSize: done ? 14 : 13, fontWeight: FW.heavy,
                  display: 'flex', alignItems: 'center', justifyContent: 'center' }}>{done ? '✓' : i + 1}</div>
                <div style={{ minWidth: 0, paddingTop: 1, flex: 1 }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                    <div style={{ fontSize: T.body, fontWeight: FW.bold, color: C.text }}>{title}</div>
                    {done && <span style={{ fontSize: T.eyebrow, fontWeight: FW.heavy, letterSpacing: '0.1em', textTransform: 'uppercase', color: C.accent2 }}>Done</span>}
                  </div>
                  <div style={{ fontSize: T.secondary, color: C.muted, lineHeight: 1.55, marginTop: 3 }}>{desc}</div>
                </div>
                {clickable && <span aria-hidden style={{ color: C.muted, fontSize: T.title, alignSelf: 'center', flexShrink: 0 }}>›</span>}
              </Tag>
            );
          })}
        </div>
        <div style={{ position: 'sticky', bottom: 0, background: C.surface, borderTop: `1px solid ${C.border}`, padding: '14px 24px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 12 }}>
          <span style={{ fontSize: T.caption, color: C.muted }}>{doneCount} of {GETTING_STARTED_STEPS.length} done · checks off automatically as you go</span>
          <button onClick={requestClose} style={{ ...s.btn('primary'), fontSize: T.secondary }}>Got it — let’s start</button>
        </div>
      </div>
    </div>
  );
}

// ── Sprint UX-2 — Host Home (the L1 front door for accountType:'host') ─────────
// Replaces the planner CRM for hosts: a host arrives at "my event", not "my
// business". Five sections — Event Summary · Next Step · Progress · What Matters
// Most · Event Day — built entirely from readers that already exist (no new engine).
// Planner/operator accounts never see this; they keep MainDashboard untouched.
// Sprint UX-7 — contextual meaning capture (replaces the intake meaning step). ONE
// card on Host Home, not a wizard: a host names the moment that has to go right, in
// place, when they want to. Powers "What matters most" + the must-have outcome check.
function HostMeaningPrompt({ ev, onPatchEvent, C, cardStyle, eyebrowStyle }) {
  const [open, setOpen] = useState(false);
  const [mh, setMh] = useState(ev.must_have_moment || '');
  const [why, setWhy] = useState(ev.meaning_why || '');
  const field = { width: '100%', boxSizing: 'border-box', background: C.bg, border: `1px solid ${C.border}`, borderRadius: 8, color: C.text, fontSize: T.secondary, padding: '9px 11px', outline: 'none', fontFamily: 'inherit', marginTop: 6 };
  const label = { fontSize: T.caption, fontWeight: FW.semibold, color: C.muted, marginTop: 12 };
  if (!open) {
    return (
      <button onClick={() => setOpen(true)} style={{ ...cardStyle, width: '100%', textAlign: 'left', cursor: 'pointer', border: `1px dashed ${C.border}`, background: 'transparent' }}>
        <div style={eyebrowStyle}>What matters most</div>
        <div style={{ fontSize: T.body, fontWeight: FW.semibold, color: C.text, lineHeight: 1.4 }}>Every event has one moment it’s really for.</div>
        <div style={{ fontSize: T.secondary, color: C.muted, marginTop: 4, lineHeight: 1.5 }}>Name yours and we’ll keep the whole plan pointed at it.</div>
        <span style={{ display: 'inline-block', marginTop: 10, fontSize: T.secondary, fontWeight: FW.bold, color: C.accent }}>Name the moment →</span>
      </button>
    );
  }
  return (
    <div style={cardStyle}>
      <div style={eyebrowStyle}>What matters most</div>
      <div style={label}>The one moment that has to go right</div>
      <textarea value={mh} onChange={e => setMh(e.target.value)} rows={2} placeholder="e.g. her whole family there for the diploma walk" style={{ ...field, resize: 'vertical', lineHeight: 1.4 }} />
      <div style={label}>Why this matters <span style={{ fontWeight: FW.regular }}>· optional</span></div>
      <input value={why} onChange={e => setWhy(e.target.value)} placeholder="the heart of the day" style={field} />
      <div style={{ display: 'flex', gap: 8, marginTop: 14 }}>
        <button onClick={() => { onPatchEvent(ev.id, { must_have_moment: mh.trim(), meaning_why: why.trim() }); setOpen(false); }}
          style={{ fontSize: T.secondary, fontWeight: FW.bold, padding: '9px 16px', borderRadius: 9, border: 'none', cursor: 'pointer', background: C.accent, color: '#fff' }}>Save</button>
        <button onClick={() => setOpen(false)} style={{ fontSize: T.secondary, fontWeight: FW.semibold, padding: '9px 14px', borderRadius: 9, border: `1px solid ${C.border}`, cursor: 'pointer', background: 'transparent', color: C.muted }}>Cancel</button>
      </div>
    </div>
  );
}

