function VendorScriptsPanel({ profile, event }) {
  const C   = useT();
  const s   = makeS(C);
  const aiKey = useAIKey();
  const [openIdx,  setOpenIdx]  = useState(null);
  const [copied,   setCopied]   = useState(null);
  const [mode,     setMode]     = useState('email'); // 'email' | 'phone'
  const showToast = useToast();
  const [personalizedIdx,  setPersonalizedIdx]  = useState(null);
  const [personalizedText, setPersonalizedText] = useState('');
  const [personalizing,    setPersonalizing]    = useState(false);

  const plannerName  = profile?.name         || '[Your Name]';
  const businessName = profile?.businessName || '[Business Name]';
  const plannerPhone = profile?.phone        || '[Phone]';
  const plannerEmail = profile?.email        || '[Email]';
  const plannerCity  = profile?.city         || '[City]';
  const eventType    = event?.type           || null;

  const fillScript = (raw) =>
    raw
      .replace(/\[Your Name\]/g,      plannerName)
      .replace(/\[Business Name\]/g,  businessName)
      .replace(/\[Phone\]/g,          plannerPhone)
      .replace(/\[Email\]/g,          plannerEmail)
      .replace(/\[City\]/g,           plannerCity)
      .replace(/\[Event type\]/g,     eventType || 'social');

  const copyText = (idx, text) => {
    const finish = () => {
      setCopied(idx);
      showToast('Script copied to clipboard');
      setTimeout(() => setCopied(c => c === idx ? null : c), 2000);
    };
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(finish).catch(() => {
        const ta = document.createElement('textarea');
        ta.value = text; ta.style.position = 'fixed'; ta.style.opacity = '0';
        document.body.appendChild(ta); ta.select();
        document.execCommand('copy'); document.body.removeChild(ta); finish();
      });
    } else {
      const ta = document.createElement('textarea');
      ta.value = text; ta.style.position = 'fixed'; ta.style.opacity = '0';
      document.body.appendChild(ta); ta.select();
      document.execCommand('copy'); document.body.removeChild(ta); finish();
    }
  };

  const personalize = async (script, filled) => {
    if (!aiInputOn(aiKey)) return;
    setPersonalizing(true); setPersonalizedText('');
    const prompt = `Personalize this vendor outreach ${mode} for the specific event. Fill in all placeholders with realistic specifics. Keep the same professional tone. Return only the personalized text, no explanation.\n\nTemplate:\n${filled}\n\nEvent details:\n- Type: ${eventType||'social event'}\n- Venue: ${event?.venue||'TBD'}\n- Date: ${event?.date||'TBD'}\n- Est. guests: ${event?.guestEstimate||event?.guests?.length||'TBD'}\n- Planner: ${plannerName}, ${businessName}\n\nPersonalized version:`;
    try { await askNGW('vendor_followup', prompt, { maxTokens: 400, onChunk: t => setPersonalizedText(t), aiKey }); }
    catch(e) { setPersonalizedText('⚠ Check API key in Profile.'); }
    setPersonalizing(false);
  };

  const [showAll, setShowAll] = useState(false);

  // When event type is known: only show scripts relevant to that event type,
  // sorted by priority rank. "Show all" toggle reveals the rest.
  const { relevant, others } = useMemo(() => {
    if (!eventType) return { relevant: VENDOR_SCRIPTS, others: [] };
    const rel = [];
    const oth = [];
    [...VENDOR_SCRIPTS].forEach(s => {
      const idx = (SCRIPT_PRIORITY[s.type] || []).indexOf(eventType);
      if (idx !== -1) rel.push({ ...s, _rank: idx });
      else oth.push(s);
    });
    rel.sort((a, b) => a._rank - b._rank);
    return { relevant: rel, others: oth };
  }, [eventType]);

  const sorted = showAll ? [...relevant, ...others] : relevant;

  const isPriority = (scriptType) => eventType && (SCRIPT_PRIORITY[scriptType] || [])[0] === eventType;

  return (
    <div>
      <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', marginBottom: 14, gap: 12, flexWrap: 'wrap' }}>
        <div>
          <div style={{ fontSize: T.body, fontWeight: FW.semibold, color: C.text, marginBottom: 4 }}>Vendor Outreach Scripts</div>
          <div style={{ fontSize: T.secondary, color: C.muted }}>
            {eventType
              ? `${relevant.length} script${relevant.length !== 1 ? 's' : ''} for ${eventType} events.`
              : 'Ready-to-send templates for email or phone outreach.'}
            {eventType && others.length > 0 && !showAll && (
              <button onClick={() => setShowAll(true)}
                style={{ marginLeft: 8, fontSize: T.caption, fontWeight: FW.semibold, color: C.accent, background: 'none', border: 'none', cursor: 'pointer', padding: 0 }}>
                +{others.length} more types
              </button>
            )}
            {showAll && (
              <button onClick={() => setShowAll(false)}
                style={{ marginLeft: 8, fontSize: T.caption, fontWeight: FW.semibold, color: C.muted, background: 'none', border: 'none', cursor: 'pointer', padding: 0 }}>
                Show relevant only
              </button>
            )}
          </div>
        </div>
        <div style={{ display: 'flex', gap: 4, flexShrink: 0 }}>
          <button onClick={() => setMode('email')} style={{ ...s.btn(mode === 'email' ? 'primary' : 'ghost'), fontSize: T.caption, padding: '5px 12px' }}>Email</button>
          <button onClick={() => setMode('phone')} style={{ ...s.btn(mode === 'phone' ? 'primary' : 'ghost'), fontSize: T.caption, padding: '5px 12px' }}>Phone</button>
        </div>
      </div>
      {!profile?.name && (
        // Sprint 60.N Phase 4: was amber+18 wash. Now Carbon body +
        // amber chip + steel-gray copy. No background blend.
        <div style={{
          position: 'relative',
          padding: '10px 14px 10px 17px',
          background: C.surface,
          borderRadius: 8, marginBottom: 14,
          display: 'flex', alignItems: 'center', gap: 10,
        }}>
          <div style={{ position: 'absolute', left: 0, top: 6, bottom: 6, width: 3, background: C.muted, borderRadius: 2 }} />
          <span style={{
            fontSize: T.eyebrow, fontWeight: FW.bold, letterSpacing: '0.14em',
            textTransform: 'uppercase', color: C.muted,
            padding: '2px 7px', borderRadius: 4,
            border: `1px solid ${C.muted}55`, flexShrink: 0,
          }}>Heads up</span>
          <span style={{ fontSize: T.secondary, color: C.muted, lineHeight: 1.45 }}>
            Set your name and business info in your Profile to auto-fill these scripts.
          </span>
        </div>
      )}
      <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
        {sorted.map((script, idx) => {
          const isOpen    = openIdx === idx;
          const priority  = isPriority(script.type);
          const filled    = fillScript(mode === 'email' ? script.body : script.phoneScript);
          const accentClr = priority ? C.accent : C.border;
          return (
            <div key={script.type} style={{ border: `1px solid ${isOpen ? C.accent + '88' : accentClr + (priority ? 'aa' : '')}`, borderRadius: 10, overflow: 'hidden', transition: 'border-color 0.15s' }}>
              <button
                onClick={() => setOpenIdx(isOpen ? null : idx)}
                style={{ width: '100%', display: 'flex', alignItems: 'center', gap: 10, padding: '12px 16px', background: isOpen ? C.accent + '0c' : 'transparent', border: 'none', cursor: 'pointer', textAlign: 'left', transition: 'background 0.15s' }}
              >
                <div style={{ flex: 1 }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 7 }}>
                    <span style={{ fontSize: T.secondary, fontWeight: FW.semibold, color: C.text }}>{script.type}</span>
                    {priority && <span style={{ fontSize: T.caption, fontWeight: FW.bold, color: C.accent, background: C.accent + '18', borderRadius: 4, padding: '1px 6px', textTransform: 'uppercase', letterSpacing: '0.06em' }}>Priority</span>}
                  </div>
                  {mode === 'email' && <div style={{ fontSize: T.caption, color: C.muted, marginTop: 1 }}>Subject: {script.subject}</div>}
                  {mode === 'phone' && <div style={{ fontSize: T.caption, color: C.muted, marginTop: 1 }}>Phone talking points</div>}
                </div>
                <span style={{ color: C.muted, fontSize: T.body, flexShrink: 0, transform: isOpen ? 'rotate(90deg)' : 'none', transition: 'transform 0.15s' }}>›</span>
              </button>
              {isOpen && (
                <div style={{ padding: '0 16px 16px' }}>
                  {mode === 'email' && (
                    <>
                      <div style={{ fontSize: T.caption, fontWeight: FW.semibold, textTransform: 'uppercase', letterSpacing: '0.08em', color: C.muted, marginBottom: 6 }}>Subject line</div>
                      <div style={{ fontSize: T.secondary, padding: '8px 12px', background: C.bg, border: `1px solid ${C.border}`, borderRadius: 6, marginBottom: 12, color: C.text, fontFamily: 'monospace' }}>{script.subject}</div>
                      <div style={{ fontSize: T.caption, fontWeight: FW.semibold, textTransform: 'uppercase', letterSpacing: '0.08em', color: C.muted, marginBottom: 6 }}>Email body</div>
                    </>
                  )}
                  {mode === 'phone' && (
                    <div style={{ fontSize: T.caption, fontWeight: FW.semibold, textTransform: 'uppercase', letterSpacing: '0.08em', color: C.muted, marginBottom: 6 }}>Phone talking points</div>
                  )}
                  <pre style={{ fontSize: T.secondary, lineHeight: 1.7, padding: '12px 14px', background: C.bg, border: `1px solid ${C.border}`, borderRadius: 6, whiteSpace: 'pre-wrap', wordBreak: 'break-word', color: C.text, fontFamily: FF, margin: 0, marginBottom: 12 }}>{filled}</pre>
                  <div style={{ display: 'flex', gap: 8 }}>
                    {mode === 'email' ? (
                      <>
                        <button onClick={() => copyText(idx, `Subject: ${script.subject}\n\n${filled}`)} style={{ ...s.btn('primary'), fontSize: T.secondary }}>
                          {copied === idx ? '✓ Copied!' : 'Copy Email'}
                        </button>
                        <button onClick={() => copyText(idx, filled)} style={{ ...s.btn(), fontSize: T.secondary }}>Body only</button>
                      </>
                    ) : (
                      <button onClick={() => copyText(idx, filled)} style={{ ...s.btn('primary'), fontSize: T.secondary }}>
                        {copied === idx ? '✓ Copied!' : 'Copy Talking Points'}
                      </button>
                    )}
                  </div>
                  {aiInputOn(aiKey) && (
                    <div style={{ marginTop: 8 }}>
                      {personalizedText && personalizedIdx === idx ? (
                        <div>
                          <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', marginBottom:6 }}>
                            <span style={{ fontSize: T.caption, fontWeight: FW.bold, color:C.accent }}>Personalized</span>
                            <div style={{ display:'flex', gap:6 }}>
                              <button onClick={()=>{ navigator.clipboard?.writeText(personalizedText); copyText(-1, personalizedText); }} style={{ ...s.btn(), fontSize: T.caption, padding:'3px 8px' }}>Copy</button>
                              <button aria-label="Remove" onClick={()=>{ setPersonalizedText(''); setPersonalizedIdx(null); }} style={{ background:'none', border:'none', cursor:'pointer', fontSize: T.caption, color:C.muted }}>✕</button>
                            </div>
                          </div>
                          <pre style={{ fontSize: T.secondary, lineHeight:1.6, whiteSpace:'pre-wrap', fontFamily:'inherit', background:C.surface, border:`1px solid ${C.accent}33`, borderRadius:8, padding:'12px 14px', margin:0 }}>{personalizedText}</pre>
                        </div>
                      ) : (
                        <AIBtn onClick={()=>{ setPersonalizedIdx(idx); personalize(script, fillScript(mode==='email'?script.body:script.phoneScript)); }} loading={personalizing && personalizedIdx===idx} label="Personalize for this event" />
                      )}
                    </div>
                  )}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

// Sprint 49 closure: legacy Vendors component (~700 lines) deleted. The
// canonical vendor surface is EventVendorsTab (uses VendorPlanningWorkspace
// from /plan/, with VendorModal for inline edits).

// TaskRow hoisted to module scope so React never creates a new component type
// across Timeline re-renders (avoids full unmount/remount of every row).
// onToggleSubtask(taskId, subId) — optional; enables the inline collapsible drawer.
function TaskRow({ t, C, s, bp, isOverdue, toggle, setModalId, urgency, onToggleSubtask, foodChoices }) {
  const overdue = isOverdue(t);
  const showOverdueChip = overdue && !t.done && !urgency;
  const urgencyTone = urgency
    ? (urgency.tone === 'danger' ? C.danger
      : urgency.tone === 'warn'   ? C.muted
      : urgency.tone === 'accent' ? C.accent2
      : C.muted)
    : null;
  const subs  = (Array.isArray(t.subtasks) ? t.subtasks : []).filter(s => !subtaskSkipped(s, foodChoices));
  const hasSubs = subs.length > 0;
  const subsDone  = subs.filter(sub => sub.done).length;
  const subsTotal = subs.length;
  const allDone   = subsTotal > 0 && subsDone === subsTotal;
  const [open, setOpen] = useState(false);

  return (
    <div data-testid="task-row" style={{ borderTop: `1px solid ${C.border}` }}>
      {/* Main row — clicking title area opens the modal; progress pill toggles the drawer */}
      <div
        onClick={() => setModalId(t.id)}
        style={{ display: 'flex', alignItems: 'center', gap: 10, padding: (bp === 'mobile' || bp === 'tablet') ? '14px 4px' : '10px 0', cursor: 'pointer' }}
        onMouseEnter={e => { e.currentTarget.style.background = C.surface2; }}
        onMouseLeave={e => { e.currentTarget.style.background = ''; }}>
        <button aria-label="Toggle done" onClick={e => { e.stopPropagation(); toggle(t.id); }}
          style={{ flexShrink: 0, width: 22, height: 22, borderRadius: '50%', background: t.done ? C.success + '22' : 'none', border: `2px solid ${t.done ? C.success : overdue ? C.danger : C.border}`, cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', color: C.success, fontSize: T.caption }}>
          {t.done ? '✓' : ''}
        </button>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontSize: T.secondary, fontWeight: FW.semibold, textDecoration: t.done ? 'line-through' : 'none', color: t.done ? C.muted : overdue ? C.danger : C.text, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: (bp === 'mobile' || bp === 'tablet') ? 'normal' : 'nowrap' }}>
            {t.task || <em style={{ color: C.muted }}>Untitled task</em>}
          </div>
          {t.owner && <div style={{ fontSize: T.caption, color: C.muted, marginTop: 1 }}>{t.owner}</div>}
          {hasSubs && (
            // Clicking the progress pill toggles the drawer (stops row→modal navigation).
            <button type="button" onClick={e => { e.stopPropagation(); setOpen(o => !o); }}
              style={{ display: 'inline-flex', alignItems: 'center', gap: 4, marginTop: 3, background: 'none', border: 'none', padding: 0, cursor: 'pointer', fontFamily: 'inherit' }}>
              <span style={{ fontSize: T.caption, fontWeight: FW.semibold, color: allDone ? C.success : (C.accentTopGrad || C.accent) }}>
                ✓ {subsDone} of {subsTotal} steps
              </span>
              <span style={{ fontSize: T.caption, color: C.muted, transition: 'transform 180ms ease', display: 'inline-block', transform: open ? 'rotate(180deg)' : 'none' }}>▾</span>
            </button>
          )}
        </div>
        {urgency && !t.done && (
          <span title={urgency.explanation}
            style={{ fontSize: T.eyebrow, fontWeight: FW.bold, letterSpacing: '0.05em', textTransform: 'uppercase',
              color: urgencyTone, background: urgencyTone + '18',
              border: `1px solid ${urgencyTone}44`, borderRadius: 8,
              padding: '2px 7px', whiteSpace: 'nowrap', flexShrink: 0 }}>
            {urgency.short}
          </span>
        )}
        {showOverdueChip && <span style={{ ...s.pill(C.danger), fontSize: T.caption, whiteSpace: 'nowrap', flexShrink: 0 }}>Overdue</span>}
        <span style={{ color: C.muted, fontSize: T.body, flexShrink: 0 }}>›</span>
      </div>

      {/* Collapsible subtask drawer */}
      {hasSubs && open && (
        <div style={{ paddingLeft: 32, paddingBottom: 10, display: 'flex', flexDirection: 'column', gap: 1 }}>
          {subs.map(sub => (
            <button key={sub.id} type="button"
              onClick={e => { e.stopPropagation(); onToggleSubtask && onToggleSubtask(t.id, sub.id); }}
              style={{ display: 'flex', alignItems: 'center', gap: 9, width: '100%', background: 'none', border: 'none', padding: '6px 4px', borderRadius: 7, cursor: onToggleSubtask ? 'pointer' : 'default', fontFamily: 'inherit', textAlign: 'left' }}
              onMouseEnter={e => { if (onToggleSubtask) e.currentTarget.style.background = C.surface2; }}
              onMouseLeave={e => { e.currentTarget.style.background = 'none'; }}>
              <span style={{ flexShrink: 0, width: 16, height: 16, borderRadius: 4, border: `1.5px solid ${sub.done ? C.success : C.border}`, background: sub.done ? C.success : 'transparent', color: '#fff', fontSize: T.caption, fontWeight: FW.heavy, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                {sub.done ? '✓' : ''}
              </span>
              <span style={{ fontSize: T.secondary, color: sub.done ? C.muted : C.text, textDecoration: sub.done ? 'line-through' : 'none', lineHeight: 1.4 }}>
                {sub.text || <em style={{ color: C.muted }}>Step</em>}
              </span>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

// ─── Timeline ─────────────────────────────────────────────────────────────────

function Timeline({ timeline, setTimeline, eventDate, openId, eventType, foodChoices }) {
  const C  = useT();
  const s  = makeS(C);
  const bp = useContext(BpCtx);
  const [modalId, setModalId] = useState(openId || null);
  const [tlSearch, setTlSearch] = useState('');
  const [quickTask, setQuickTask] = useState('');
  // Sprint 57f.1: derive live compression urgency for every task. We compute
  // once per render and look up by task id when rendering rows. The summary
  // also feeds the "Tight timeline" filter pill and the section header.
  const compressionSummary = useMemo(
    () => deriveEventCompressionSummary(
      { type: eventType, date: eventDate, timeline },
      daysUntil,
      PHASE_OFFSET,
    ),
    [eventType, eventDate, timeline],
  );
  const urgencyForTask = (task) => {
    if (!eventDate || !eventType) return null;
    const days = daysUntil(eventDate);
    const u = classifyTemplateTaskUrgency(task, days, eventType, PHASE_OFFSET);
    return (u && u.urgency !== 'standard') ? u : null;
  };

  const quickAdd = () => {
    if (!quickTask.trim() || selectedPhase === '__overdue__') return;
    const ng = { id: uid(), week: selectedPhase, task: quickTask.trim(), done: false, owner: '', notes: '' };
    setTimeline(t => [...t, ng]);
    setQuickTask('');
  };

  const toggle = (id) => setTimeline(t => t.map(r => r.id === id ? { ...r, done: !r.done } : r));
  const toggleSubtask = (taskId, subId) => setTimeline(prev => prev.map(r => {
    if (r.id !== taskId) return r;
    const updated = { ...r, subtasks: (r.subtasks || []).map(s => s.id === subId ? { ...s, done: !s.done } : s) };
    // Auto-complete the parent task when every visible subtask is checked off.
    // "Visible" excludes subtasks hidden by skipWhenChoice (they're irrelevant for completion).
    const visibleSubs = (updated.subtasks || []).filter(s => !subtaskSkipped(s, foodChoices));
    if (visibleSubs.length > 0 && visibleSubs.every(s => s.done)) updated.done = true;
    // Un-complete if at least one visible subtask is unchecked (user can still toggle back).
    if (visibleSubs.some(s => !s.done)) updated.done = false;
    return updated;
  }));
  const add    = (week) => {
    const ng = { id: uid(), week: week || 'Custom', task: '', done: false, owner: '', notes: '' };
    setTimeline(t => [...t, ng]);
    setModalId(ng.id);
  };
  const del = (id) => { setTimeline(t => t.filter(r => r.id !== id)); setModalId(null); };
  const upd = (id, key, val) => setTimeline(t => t.map(r => r.id === id ? { ...r, [key]: val } : r));
  const isOverdue = (task) => isTaskOverdue(task, eventDate, eventType);

  const phaseOrder = Object.keys(PHASE_OFFSET);
  const done = timeline.filter(t => t.done).length;
  const overdueCount = timeline.filter(isOverdue).length;

  // All phases that have tasks, in phase order
  const allPhases = [
    ...phaseOrder.filter(p => timeline.some(t => t.week === p)),
    ...timeline.filter(t => !phaseOrder.includes(t.week)).map(t => t.week).filter((v, i, a) => a.indexOf(v) === i),
  ];

  // Auto-select on mount: first overdue → first incomplete → first phase
  const defaultPhase = overdueCount > 0 ? '__overdue__'
    : allPhases.find(p => timeline.filter(t => t.week === p).some(t => !t.done))
    || allPhases[0] || null;

  const [selectedPhase, setSelectedPhase] = useState(() => {
    // Sprint 57f.1: '__compressed__' is a sentinel openId emitted by the
    // Event Command "Open compressed tasks" CTA. Honor it directly so the
    // planner lands on the Tight-timeline filter scoped to do_now + swap.
    if (openId === '__compressed__') return '__compressed__';
    if (openId) {
      const task = timeline.find(t => t.id === openId);
      return task ? task.week : defaultPhase;
    }
    return defaultPhase;
  });
  // 60G — elapsed phases collapse under a "N earlier steps" line (host choice b),
  // so an imminent event doesn't show a wall of past-dated, undone phases.
  const [showPastPhases, setShowPastPhases] = useState(false);

  // Tasks for currently selected phase, optionally filtered by search.
  // Sprint 57f.1: '__compressed__' is a virtual phase showing do_now +
  // risk_lost across all phases when the timeline is compressed. Order is
  // intentional: do_now first (the planner's first move), then consider-swap.
  const phaseTasks = (phase) => {
    let base;
    if (phase === '__overdue__') {
      base = timeline.filter(isOverdue);
    } else if (phase === '__compressed__') {
      const doNowIds = new Set(compressionSummary?.doNow.map(t => t.id) || []);
      const swapIds  = new Set(compressionSummary?.considerSwap.map(t => t.id) || []);
      base = timeline
        .filter(t => !t.done && (doNowIds.has(t.id) || swapIds.has(t.id)))
        .sort((a, b) => Number(swapIds.has(a.id)) - Number(swapIds.has(b.id)));
    } else {
      base = timeline.filter(t => t.week === phase);
    }
    if (!tlSearch) return base;
    const q = tlSearch.toLowerCase();
    return base.filter(t => t.task.toLowerCase().includes(q) || (t.owner || '').toLowerCase().includes(q));
  };

  const currentTasks = selectedPhase ? phaseTasks(selectedPhase) : [];
  const modalTask = timeline.find(t => t.id === modalId);

  // TaskRow is defined below at module scope to prevent remounts on each Timeline render

  return (
    <div>
      {/* Stats */}
      <div style={{ display: 'flex', gap: 12, marginBottom: 20, flexWrap: 'wrap' }}>
        {/* HERO is conditional: if anything is overdue, Overdue shouts (red, large);
            otherwise Complete% is the hero (you're on track). Only one survives the squint. */}
        <StatCard tier="evidence" label="Total Tasks" value={timeline.length} />
        <StatCard tier={overdueCount > 0 ? 'evidence' : undefined} label="Complete" value={done} color={C.success} sub={timeline.length ? `${Math.round((done/timeline.length)*100)}%` : '—'} />
        <StatCard tier="evidence" label="Remaining"   value={timeline.length - done} />
        <StatCard tier={overdueCount > 0 ? undefined : 'evidence'} label="Overdue" value={overdueCount} color={overdueCount > 0 ? C.danger : undefined} />
      </div>

      {timeline.length === 0 ? (
        <div style={{ ...s.card, padding: '28px 24px' }}>
          <div style={{ fontSize: T.caption, fontWeight: FW.bold, letterSpacing: '0.08em', color: C.muted, textTransform: 'uppercase', marginBottom: 8 }}>Planning Tasks</div>
          <div style={{ fontSize: T.body, fontWeight: FW.bold, color: C.text, marginBottom: 6 }}>Build your planning checklist</div>
          <div style={{ fontSize: T.secondary, color: C.muted, lineHeight: 1.7, marginBottom: 18, maxWidth: 380 }}>
            Organize tasks by phase — 12 months out through day-of. Track ownership, deadlines, and completion across every stage of the event.
          </div>
          <button style={{ ...s.btn('primary'), padding: '9px 18px', fontSize: T.secondary }} onClick={() => add('12 Months Out')}>Add first task</button>
        </div>
      ) : (
        <>
          {/* Phase timeline stepper */}
          {(() => {
            const knownPhases = phaseOrder.filter(p => allPhases.includes(p));
            const customPhases = allPhases.filter(p => !phaseOrder.includes(p));
            const steppablePhases = knownPhases; // custom phases shown separately
            // 60G — split elapsed vs live by the phase's REAL date and collapse the
            // elapsed ones, so an imminent event shows what's left, not a past wall.
            const _today0 = getToday(); _today0.setHours(0, 0, 0, 0);
            const phaseIsPast = (phase) => {
              if (!eventDate || !(phase in PHASE_OFFSET)) return false;
              const d = new Date(eventDate + 'T00:00:00');
              d.setDate(d.getDate() + PHASE_OFFSET[phase]);
              return d < _today0;
            };
            const pastPhases = steppablePhases.filter(phaseIsPast);
            let livePhases = steppablePhases.filter(p => !phaseIsPast(p));
            if (!livePhases.length) livePhases = steppablePhases.slice(-1); // never hide everything
            const shownPhases = showPastPhases ? steppablePhases : livePhases;
            return (
              <div style={{ marginBottom: 20 }}>
                {/* 60G — collapsed elapsed-steps line (honest, expandable) */}
                {pastPhases.length > 0 && (
                  <button onClick={() => setShowPastPhases(v => !v)} style={{
                    background: 'none', border: 'none', cursor: 'pointer', padding: '0 0 8px', fontFamily: 'inherit',
                    display: 'flex', alignItems: 'center', gap: 6, color: C.muted, fontSize: T.caption, fontWeight: FW.semibold,
                  }}>
                    <span style={{ fontSize: T.caption }}>{showPastPhases ? '▾' : '▸'}</span>
                    {showPastPhases
                      ? `Hide ${pastPhases.length} earlier step${pastPhases.length === 1 ? '' : 's'}`
                      : `${pastPhases.length} earlier step${pastPhases.length === 1 ? '' : 's'} — the window passed`}
                  </button>
                )}
                {/* Stepper row — scroll horizontally */}
                <div style={{ overflowX: 'auto', WebkitOverflowScrolling: 'touch', paddingBottom: 8 }}>
                  <div style={{ display: 'flex', alignItems: 'flex-start', minWidth: 'max-content', padding: '4px 4px 0', position: 'relative' }}>
                    {shownPhases.map((phase, idx) => {
                      const tasks  = timeline.filter(t => t.week === phase);
                      const pDone  = tasks.filter(t => t.done).length;
                      const pOver  = tasks.some(isOverdue);
                      const allD   = tasks.length > 0 && pDone === tasks.length;
                      const nodeClr = allD ? C.success : pOver ? C.danger : pDone > 0 ? C.accent2 : C.border;
                      const isAct  = selectedPhase === phase;
                      const pDate  = phaseDate(phase, eventDate);
                      const abbr      = phase.replace(' Months Out', 'mo').replace(' Month Out', 'mo').replace(' Weeks Out', 'wk').replace('Week Of', 'WK');
                      const focusLbl  = PHASE_FOCUS[phase] || '';
                      const isLast    = idx === shownPhases.length - 1;
                      return (
                        <div key={phase} style={{ display: 'flex', alignItems: 'flex-start', flexShrink: 0 }}>
                          <button onClick={() => setSelectedPhase(phase)} title={focusLbl ? `${phase} — ${focusLbl}` : phase} style={{
                            background: 'none', border: 'none', cursor: 'pointer', padding: 0,
                            display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 5, width: 76,
                          }}>
                            {/* Node circle */}
                            <div style={{
                              width: isAct ? 32 : 24, height: isAct ? 32 : 24,
                              borderRadius: '50%', flexShrink: 0,
                              background: isAct ? nodeClr : nodeClr + '33',
                              border: `2px solid ${nodeClr}`,
                              display: 'flex', alignItems: 'center', justifyContent: 'center',
                              transition: 'all 0.15s', boxShadow: isAct ? `0 0 0 3px ${nodeClr}22` : 'none',
                            }}>
                              <span style={{ fontSize: isAct ? 9 : 8, fontWeight: FW.bold, color: isAct ? C.bg : nodeClr, lineHeight: 1 }}>
                                {allD ? '✓' : pOver ? '!' : abbr}
                              </span>
                            </div>
                            {/* Label + focus + date */}
                            <div style={{ textAlign: 'center' }}>
                              {pDate ? (
                                <>
                                  <div style={{ fontSize: T.eyebrow, fontWeight: FW.bold, color: isAct ? nodeClr : C.muted, whiteSpace: 'nowrap' }}>{pDate.replace(/,\s*\d{4}$/, '')}</div>
                                  {focusLbl && <div style={{ fontSize: T.eyebrow, fontWeight: isAct ? 600 : 400, color: isAct ? C.text : C.muted, marginTop: 1, maxWidth: 96, lineHeight: 1.2, display: '-webkit-box', WebkitLineClamp: 2, WebkitBoxOrient: 'vertical', overflow: 'hidden' }}>{focusLbl}</div>}
                                </>
                              ) : (
                                <>
                                  <div style={{ fontSize: T.eyebrow, fontWeight: FW.bold, color: isAct ? nodeClr : C.muted, whiteSpace: 'nowrap' }}>{abbr}</div>
                                  {focusLbl && <div style={{ fontSize: T.eyebrow, fontWeight: isAct ? 600 : 400, color: isAct ? C.text : C.muted, marginTop: 1, maxWidth: 96, lineHeight: 1.2, display: '-webkit-box', WebkitLineClamp: 2, WebkitBoxOrient: 'vertical', overflow: 'hidden' }}>{focusLbl}</div>}
                                </>
                              )}
                              <div style={{ fontSize: T.eyebrow, color: allD ? C.success : pOver ? C.danger : C.border, marginTop: 1 }}>{pDone}/{tasks.length}</div>
                            </div>
                          </button>
                          {/* Connector line between nodes */}
                          {!isLast && (
                            <div style={{ width: 20, height: 2, background: allD ? C.success + '66' : C.border, marginTop: 15, flexShrink: 0, alignSelf: 'flex-start' }} />
                          )}
                        </div>
                      );
                    })}
                    {/* Event endpoint */}
                    {eventDate && steppablePhases.length > 0 && (
                      <div style={{ display: 'flex', alignItems: 'flex-start', flexShrink: 0 }}>
                        <div style={{ width: 20, height: 2, background: C.border, marginTop: 15, flexShrink: 0 }} />
                        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 5, width: 52 }}>
                          <div style={{ width: 24, height: 24, borderRadius: 6, background: C.accent + '22', border: `2px solid ${C.accent}`, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                            <span style={{ fontSize: T.eyebrow, fontWeight: FW.bold, color: C.accent }}>DAY</span>
                          </div>
                          <div style={{ textAlign: 'center' }}>
                            <div style={{ fontSize: T.eyebrow, fontWeight: FW.bold, color: C.accent, whiteSpace: 'nowrap' }}>Event</div>
                            <div style={{ fontSize: T.eyebrow, color: C.border }}>{fmtDate(eventDate).replace(/,\s*\d{4}$/, '')}</div>
                          </div>
                        </div>
                      </div>
                    )}
                  </div>
                </div>

                {/* Overdue alert + compressed-priorities + custom phases + search */}
                <div style={{ display: 'flex', gap: 6, alignItems: 'center', flexWrap: 'wrap', marginTop: 4 }}>
                  {overdueCount > 0 && (
                    <button onClick={() => setSelectedPhase('__overdue__')} style={{
                      ...s.btn(selectedPhase === '__overdue__' ? 'danger' : 'ghost'),
                      fontSize: T.caption, padding: '4px 10px',
                    }}>⚠ {overdueCount} Overdue</button>
                  )}
                  {/* Sprint 57f.1: compressed plan priorities pill — only when
                      the timeline is genuinely compressed AND there's something
                      to act on. Friendly label, not a red siren. */}
                  {compressionSummary?.significant && (
                    <button
                      id="tight-timeline-filter"
                      onClick={() => setSelectedPhase('__compressed__')} style={{
                      ...s.btn(selectedPhase === '__compressed__' ? 'primary' : 'ghost'),
                      fontSize: T.caption, padding: '4px 10px',
                      // Sprint 57f.1: use the shorthand `border` to match
                      // s.btn('ghost') instead of mixing shorthand+borderColor,
                      // which trips a React "conflicting style property" warn.
                      ...(selectedPhase === '__compressed__' ? {} : { color: C.muted, border: `1px solid ${C.muted}55` }),
                    }} title="Tasks that moved to the front because the timeline is tight">
                      ⏱ Tight timeline · {compressionSummary.totalUrgent}
                    </button>
                  )}
                  {customPhases.map(phase => {
                    const tasks = timeline.filter(t => t.week === phase);
                    const pDone = tasks.filter(t => t.done).length;
                    return (
                      <button key={phase} onClick={() => setSelectedPhase(phase)} style={{
                        ...s.btn(selectedPhase === phase ? 'primary' : 'ghost'), fontSize: T.caption, padding: '4px 10px',
                      }}>{phase} {pDone}/{tasks.length}</button>
                    );
                  })}
                  <div style={{ marginLeft: 'auto', flex: bp === 'mobile' ? 1 : 'none' }}>
                    <input style={{ ...s.input, fontSize: T.caption, padding: '4px 10px', width: bp === 'mobile' ? '100%' : 140 }} value={tlSearch} onChange={e => setTlSearch(e.target.value)} placeholder="Search…" />
                  </div>
                </div>
              </div>
            );
          })()}

          {/* Phase content panel */}
          {selectedPhase && (
            <div style={s.card}>
              {/* Phase header */}
              <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 12 }}>
                <div style={{ flex: 1 }}>
                  {selectedPhase === '__overdue__' ? (
                    <div style={{ fontSize: T.secondary, fontWeight: FW.heavy, textTransform: 'uppercase', letterSpacing: '0.14em', color: C.danger }}>Overdue Tasks{overdueCount > 0 ? ` (${overdueCount})` : ''}</div>
                  ) : selectedPhase === '__compressed__' ? (
                    <>
                      <div style={{ fontSize: T.secondary, fontWeight: FW.heavy, textTransform: 'uppercase', letterSpacing: '0.14em', color: C.muted }}>Compressed plan priorities</div>
                      <div style={{ fontSize: T.caption, color: C.muted, marginTop: 2 }}>
                        {compressionSummary?.headline || 'Tasks moved to the front because the timeline is tight.'}
                      </div>
                    </>
                  ) : (() => {
                    const pD = phaseDate(selectedPhase, eventDate);
                    return pD ? (
                      <>
                        <div style={{ display: 'flex', alignItems: 'baseline', gap: 8, flexWrap: 'wrap' }}>
                          <div style={{ fontSize: T.body, fontWeight: FW.heavy, color: C.text }}>{pD}</div>
                          {PHASE_FOCUS[selectedPhase] && <div style={{ fontSize: T.secondary, color: C.muted }}>— {PHASE_FOCUS[selectedPhase]}</div>}
                        </div>
                        <div style={{ fontSize: T.caption, fontWeight: FW.bold, color: C.accent, textTransform: 'uppercase', letterSpacing: '0.08em', marginTop: 2 }}>{selectedPhase}</div>
                      </>
                    ) : (
                      <>
                        <div style={{ display: 'flex', alignItems: 'baseline', gap: 8, flexWrap: 'wrap' }}>
                          <div style={{ fontSize: T.secondary, fontWeight: FW.bold, textTransform: 'uppercase', letterSpacing: '0.06em', color: C.accent }}>{selectedPhase}</div>
                          {PHASE_FOCUS[selectedPhase] && <div style={{ fontSize: T.secondary, fontWeight: FW.semibold, color: C.text }}>{PHASE_FOCUS[selectedPhase]}</div>}
                        </div>
                        <div style={{ fontSize: T.caption, color: C.muted, marginTop: 2 }}>Set an event date to see target dates</div>
                      </>
                    );
                  })()}
                </div>
                {selectedPhase !== '__overdue__' && selectedPhase !== '__compressed__' && (
                  <button style={{ ...s.btn('primary'), fontSize: T.caption, padding: '5px 12px' }} onClick={() => add(selectedPhase)}>+ Task</button>
                )}
              </div>

              {/* Progress bar — skip for virtual filter phases (overdue / compressed) */}
              {selectedPhase !== '__compressed__' && (() => {
                const tasks = timeline.filter(t => selectedPhase === '__overdue__' ? isOverdue(t) : t.week === selectedPhase);
                const pDone = tasks.filter(t => t.done).length;
                const pct = tasks.length ? Math.round((pDone / tasks.length) * 100) : 0;
                const clr = tasks.some(isOverdue) ? C.danger : pDone === tasks.length && tasks.length > 0 ? C.success : C.accent;
                return <ProgressBar pct={pct} color={clr} />;
              })()}

              {/* Event-type milestone guidance for this phase */}
              {selectedPhase !== '__overdue__' && selectedPhase !== '__compressed__' && (() => {
                const guidance = (WORKFLOW_FOCUS[eventType] || {})[selectedPhase];
                if (!guidance) return null;
                return (
                  <div style={{ padding: '10px 14px', background: C.accent + '0d', border: `1px solid ${C.accent}22`, borderRadius: 8, marginTop: 10, marginBottom: 4 }}>
                    <div style={{ fontSize: T.caption, fontWeight: FW.bold, color: C.accent, marginBottom: 5, textTransform: 'uppercase', letterSpacing: '0.08em' }}>
                      {eventType} · {guidance.focus}
                    </div>
                    {guidance.tips.map((tip, i) => (
                      <div key={i} style={{ fontSize: T.secondary, color: C.muted, display: 'flex', gap: 6, alignItems: 'flex-start', marginTop: i > 0 ? 3 : 0 }}>
                        <span style={{ color: C.accent, flexShrink: 0 }}>·</span>
                        <span>{tip}</span>
                      </div>
                    ))}
                  </div>
                );
              })()}

              {/* Quick-add task — disabled inside virtual filter phases */}
              {selectedPhase !== '__overdue__' && selectedPhase !== '__compressed__' && (
                <div style={{ display: 'flex', gap: 8, marginBottom: 10 }}>
                  <input
                    style={{ ...s.input, flex: 1, fontSize: T.secondary }}
                    value={quickTask}
                    placeholder="Quick-add a task… (Enter to save)"
                    onChange={e => setQuickTask(e.target.value)}
                    onKeyDown={e => { if (e.key === 'Enter') quickAdd(); }}
                  />
                  <button style={s.btn('primary')} onClick={quickAdd} disabled={!quickTask.trim()}>Add</button>
                </div>
              )}

              {/* Task rows */}
              <div style={{ marginTop: 4 }}>
                {currentTasks.length === 0 && tlSearch && (
                  <div style={{ fontSize: T.secondary, color: C.muted, textAlign: 'center', padding: '20px 0' }}>No tasks match "{tlSearch}"</div>
                )}
                {currentTasks.length === 0 && !tlSearch && selectedPhase !== '__overdue__' && selectedPhase !== '__compressed__' && (
                  <div style={{ fontSize: T.secondary, color: C.muted, textAlign: 'center', padding: '20px 0' }}>
                    No tasks in this phase yet.
                    <button style={{ ...s.btn('ghost'), fontSize: T.caption, marginLeft: 10 }} onClick={() => add(selectedPhase)}>+ Add one</button>
                  </div>
                )}
                {currentTasks.length === 0 && selectedPhase === '__compressed__' && !tlSearch && (
                  <div style={{ fontSize: T.secondary, color: C.muted, textAlign: 'center', padding: '20px 0' }}>
                    Nothing to surface here right now — the timeline is back in shape.
                  </div>
                )}
                {currentTasks.map(t => <TaskRow key={t.id} t={t} C={C} s={s} bp={bp} isOverdue={isOverdue} toggle={toggle} setModalId={setModalId} urgency={urgencyForTask(t)} onToggleSubtask={toggleSubtask} foodChoices={foodChoices} />)}
              </div>
            </div>
          )}

          {/* Bottom action row */}
          <div style={{ marginTop: 12, display: 'flex', gap: 6, flexWrap: 'wrap', alignItems: 'center' }}>
            <button style={{ background: 'none', border: 'none', cursor: 'pointer', color: C.accent, fontWeight: FW.semibold, fontSize: T.caption, padding: '2px 4px', minHeight: 0 }} onClick={() => add('Custom')}>+ New Phase Task</button>
            {selectedPhase && selectedPhase !== '__overdue__' && selectedPhase !== '__compressed__' && (
              <button style={{ background: 'none', border: 'none', cursor: 'pointer', color: C.accent, fontWeight: FW.semibold, fontSize: T.caption, padding: '2px 4px', minHeight: 0 }} onClick={() => add(selectedPhase)}>+ Task to {selectedPhase}</button>
            )}
          </div>
        </>
      )}

      {modalTask && (
        <TaskModal task={modalTask} eventDate={eventDate} foodChoices={foodChoices} onClose={() => setModalId(null)} onChange={(key, val) => upd(modalTask.id, key, val)} onDelete={() => del(modalTask.id)} />
      )}
    </div>
  );
}

// ─── Host Run of Show — the calm, read-mostly timeline (Figma 1445:2) ──────────
// The HOST's "Day" tab. A quiet vertical run-of-show that DERIVES entirely from
// effectiveRos(event) — never fabricates a cue. Done cues dim/strike; the current
// cue (by time-of-day, same nextCue logic as the focus home) carries a "NOW"
// marker on the event day. The eyebrow + footer ADAPT to proximity: before the
// day it reads "STARTS SOON" and "wakes up when the day begins"; on the day the
// NOW marker goes live. Studio Matte: dark, steel, no amber — escalation = reduction.
// Planners keep the editable RunOfShow below; this never renders for them.
function HostRunOfShowTimeline({ event, profile, ctx = null }) {
  const C = useT();
  const T = useType();
  const bp = useContext(BpCtx);
  const isMobile = bp === 'mobile';
  // Local draft hand-off (Communications FROZEN + Ruthless Host Lens): we NEVER open an
  // in-app thread/compose/DM. The host model is DRAFT → share to their OWN group chat.
  // "Send everyone their part" reuses draftHelperBrief → the shared DraftSheet, exactly
  // like the home day-of card (~21520). This surface adds NO message bubbles, NO compose bar.
  const [rosDraftSheet, setRosDraftSheet] = useState(null);
  const cues = (() => { try { return effectiveRos(event) || []; } catch { return []; } })();

  // No authored/derived cues → the honest empty state (don't invent a schedule).
  const hasCues = Array.isArray(cues) && cues.length > 0;

  const steelLabel  = C.steel?.blue400 || C.accent;     // #8BA0AA — eyebrow / NOW
  const live        = C.success || C.accent;            // GREEN — the LIVE / happening-now state (event day)
  const steelTime   = C.steel?.blue600 || C.muted;      // #566F7D — times, details, footer
  const textPrimary = C.text;                            // #eef0f4 — headlines
  const textSub     = C.muted;                           // #849eb8 — date subline

  const toMins = (t) => { const m = /^(\d{1,2}):(\d{2})\s*(am|pm)?/i.exec(String(t || '').trim()); if (!m) return null; let h = Number(m[1]); const ap = (m[3] || '').toLowerCase(); if (ap === 'pm' && h < 12) h += 12; if (ap === 'am' && h === 12) h = 0; return h * 60 + Number(m[2]); }; // honors both 24h ("14:00") and 12h ("2:00 PM") cue times so the NOW marker lands right (M5)
  const isCueDone = (r) => !!(r && (r.done || r.confirmed === true && r.type === 'past'));
  // A cue is "done" when explicitly marked done. (confirmed=true on a vendor row is
  // a logistics flag, not a done state, so we only honour an explicit `done`.)
  const cueDone = (r) => !!(r && r.done);

  // Proximity drives the eyebrow + footer + whether NOW is live.
  const daysUntil = (() => {
    if (!event || !event.date) return null;
    try {
      const d = new Date(event.date + 'T00:00:00');
      const now = new Date(); now.setHours(0, 0, 0, 0);
      return Math.round((d - now) / 86400000);
    } catch { return null; }
  })();
  const isDayOf = daysUntil === 0;

  // Sorted by time; rows with no time fall to the end (kept, never dropped).
  // Sort by ABSOLUTE minutes (_min) when present. A generated late-night ROS wraps past midnight —
  // an 11:30 PM start yields a 3:30 AM cleanup cue whose DISPLAY time is "03:30". Sorting by that
  // wrapped clock time floats the 3:30 AM cue to the TOP; _min keeps true chronological order.
  const rosSortKey = (r) => (r && r._min != null) ? r._min : (toMins(r.time) ?? 1e9);
  const sorted = [...cues].sort((a, b) => rosSortKey(a) - rosSortKey(b));

  // NOW cue — same logic as the focus home's nextCue: the first OPEN cue at/after
  // the current minute, else the first open cue. Live only on the event day.
  const nowMins = (() => { try { const d = new Date(); return d.getHours() * 60 + d.getMinutes(); } catch { return -1; } })();
  const nowCue = isDayOf
    ? (sorted.filter(r => !cueDone(r)).filter(r => { const mm = toMins(r.time); return mm !== null && mm >= nowMins; })[0]
       || sorted.filter(r => !cueDone(r))[0]
       || null)
    : null;
  const nowCueId = nowCue ? nowCue.id : null;
  // M5 timing — where the NOW node sits down the spine (0=top … 1=bottom), so the ignite
  // fires AS the sweep reaches it, not on a fixed delay (the old desync that read as "strange").
  const nowIndex = nowCueId ? sorted.findIndex((r) => r.id === nowCueId) : -1;
  const nowRatio = (nowIndex >= 0 && sorted.length > 1) ? nowIndex / (sorted.length - 1) : 0;
  // Fire the NOW ignite WHEN the light actually reaches the node down the spine, accounting
  // for the sweep's 240ms start delay + travel time. Critically this fixes a TOP now (ratio 0):
  // it no longer ignites at 140ms (before the sweep even appears) — it waits ~420ms for the
  // light to arrive, so even the first cue gets a coherent sweep→ignite→rise beat with runway.
  const igniteDelay = Math.round(420 + nowRatio * 980); // 420ms (top) … 1400ms (bottom), tracking the delayed sweep

  // Header subline — weekday, Mon D, and the start time (the earliest cue, the most
  // honest run-of-show anchor; falls back to event.startTime if no cue time).
  const dateLine = (() => {
    if (!event || !event.date) return '';
    try { return new Date(event.date + 'T00:00:00').toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric' }); }
    catch { return event.date; }
  })();
  const firstCueTime = sorted.map(r => r.time).find(t => toMins(t) !== null);
  const startLabel = firstCueTime ? fmtTime12(firstCueTime) : (event && event.startTime ? String(event.startTime) : '');
  const subline = [dateLine, startLabel ? `${startLabel} start` : ''].filter(Boolean).join(' · ');

  // Every cue done → the day is COMPLETE. Keep a green hero (the caught-up reward) instead of
  // losing the "happening now" panel to an empty list. The sweep won't re-wake a finished day.
  const allDone = isDayOf && hasCues && sorted.length > 0 && sorted.every((r) => cueDone(r));

  // Live clock — the day-of hero's operational anchor (board verdict). Ticks only on the day itself.
  const [clockNow, setClockNow] = useState(() => { try { return new Date(); } catch { return null; } });
  useEffect(() => {
    if (!isDayOf) return undefined;
    let id; try { id = setInterval(() => { try { setClockNow(new Date()); } catch {} }, 30000); } catch {}
    return () => { try { clearInterval(id); } catch {} };
  }, [isDayOf]);
  const timeStr = (isDayOf && clockNow) ? clockNow.toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' }) : '';
  const clockDateStr = clockNow ? clockNow.toLocaleDateString(undefined, { weekday: 'short', month: 'short', day: 'numeric' }) : '';

  // On the day, float the "Happening now" cue toward the TOP of the viewport (after the spine mounts +
  // animates), so the host lands on what's live — clearing the sticky header with a little air above it.
  const nowCardRef = useRef(null);
  useEffect(() => {
    if (!isDayOf || !nowCueId) return undefined;
    const t = setTimeout(() => {
      try {
        if (!nowCardRef.current) return;
        const y = nowCardRef.current.getBoundingClientRect().top + window.scrollY - 96; // clear the sticky header + breathing room
        window.scrollTo({ top: Math.max(0, y), behavior: 'smooth' });
      } catch {}
    }, 650);
    return () => clearTimeout(t);
  }, [isDayOf, nowCueId]);

  // Is the NOW cue actually happening (its start has passed) vs still on deck?
  const nowCueActive = !!(nowCue && toMins(nowCue.time) !== null && toMins(nowCue.time) <= nowMins);
  // On-deck (NEXT) cue — first open cue AFTER the NOW cue. Board verdict: a quiet NEXT marker lives on
  // the spine (in true time order), NOT as a duplicate line in the hero.
  const nextCueId = (isDayOf && nowCueId) ? (() => {
    const idx = sorted.findIndex((r) => r.id === nowCueId);
    for (let j = idx + 1; j < sorted.length; j++) { if (!cueDone(sorted[j])) return sorted[j].id; }
    return null;
  })() : null;

  // Eyebrow + footer adapt to proximity — state-named + colored (board verdict).
  const eyebrow = allDone ? 'ALL CLEAR' : !isDayOf ? 'THE DAY · STARTS SOON' : nowCueActive ? 'NOW' : 'NEXT UP';
  const eyebrowColor = (allDone || (isDayOf && nowCueActive)) ? live : steelLabel;
  const footer = allDone
    ? 'Every moment handled. That’s a wrap — go enjoy it.'
    : isDayOf
    ? 'Your run-of-show is live. Work it top to bottom — done falls away.'
    : 'Your run-of-show is ready. It wakes up when the day begins.';

  const ROW_FONT = { fontFamily: 'inherit' };

  // ── "Who's helping" roster (Figma A1 1554:6) — DERIVED, never a CRM. Each distinct
  // ROS owner (other than the host themselves / "Everyone") becomes a person row: their
  // name + the segments they own + their FIRST time. Vendors that are coming with a real
  // arrival time join as helpers too (role = their category). Ruthless Host Lens: NO
  // "vendors"/"contacts"/"CRM" words on screen, read-only, no message bubbles. Honest:
  // we only list people the run-of-show / vendor data actually names.
  const helpers = (() => {
    try {
      const hostNames = new Set(['host', 'you', 'me', 'everyone', '']);
      const byOwner = new Map(); // key(lower) → { name, segs:[{time,seg}], firstMin }
      for (const r of cues) {
        if (!r) continue;
        const seg = String(r.segment || '').trim();
        const owner = String(r.owner || '').trim();
        if (!seg || !owner || hostNames.has(owner.toLowerCase())) continue;
        const key = owner.toLowerCase();
        const mm = toMins(r.time);
        if (!byOwner.has(key)) byOwner.set(key, { name: owner, segs: [], firstMin: mm ?? 1e9 });
        const rec = byOwner.get(key);
        rec.segs.push({ time: r.time, seg });
        if (mm !== null && mm < rec.firstMin) rec.firstMin = mm;
      }
      const fromRos = [...byOwner.values()].map((rec) => ({
        kind: 'person',
        name: rec.name,
        role: rec.segs.map((s) => s.seg).slice(0, 2).join(' · '),
        time: rec.segs.slice().sort((a, b) => (toMins(a.time) ?? 1e9) - (toMins(b.time) ?? 1e9)).map((s) => s.time).find((t) => toMins(t) !== null) || null,
        firstMin: rec.firstMin,
      }));
      // Vendors arriving with a real time (coming = confirmed/contracted/deposit) — their
      // category is the role. Skip any whose name already appears as a ROS owner.
      const vendorComing = new Set(['confirmed', 'contracted', 'deposit paid']);
      const seen = new Set(fromRos.map((p) => p.name.toLowerCase()));
      const fromVendors = (Array.isArray(event && event.vendors) ? event.vendors : [])
        .filter((v) => v && String(v.name || '').trim() && String(v.arrivalTime || '').trim())
        .filter((v) => vendorComing.has(String(v.status || '').toLowerCase()))
        .filter((v) => !seen.has(String(v.name).trim().toLowerCase()))
        .map((v) => ({
          kind: 'person',
          name: String(v.name).trim(),
          role: String(v.category || 'Helping out').trim(),
          time: v.arrivalTime,
          firstMin: toMins(v.arrivalTime) ?? 1e9,
        }));
      // Single-source caterer lever: if the host chose to cook everything, the caterer is no
      // longer helping — drop any caterer row (a ROS owner OR a vendor still on file from before
      // the switch). Mirrors how foodApproach drops caterer tasks/cues/budget elsewhere.
      const cooking = (() => { try { return hostIsCooking(event); } catch { return false; } })();
      const isCaterer = (p) => /cater(er|ing)/i.test(`${p.name || ''} ${p.role || ''}`);
      return [...fromRos, ...fromVendors].filter((p) => !(cooking && isCaterer(p))).sort((a, b) => a.firstMin - b.firstMin);
    } catch { return []; }
  })();

  const initialOf = (name) => {
    const parts = String(name || '').trim().split(/\s+/).filter(Boolean);
    if (!parts.length) return '?';
    return (parts[0][0] + (parts.length > 1 ? parts[parts.length - 1][0] : '')).toUpperCase();
  };

  // "Send everyone their part" — DRAFT, never an in-app message. Reuses draftHelperBrief
  // (the same writer the home day-of card uses) → shared DraftSheet → host shares to
  // their own group chat. Only meaningful once there are owned segments to brief from.
  const hasBriefable = cues.some((r) => r && String(r.segment || '').trim());
  const openHelperBrief = () => {
    try {
      const d = draftHelperBrief(event, profile, { ros: cues });
      setRosDraftSheet({ title: 'Everyone’s part', intro: 'Pulled from your run of show — what each person’s on today, ready to drop in the group chat. Make it yours, then send.', draft: d, shareTitle: d.subject, kind: 'recap' });
    } catch { /* never block the day-of view */ }
  };

  // Shared card style for the two day-of coordination blocks.
  const coordCard = { background: C.surface, border: `1px solid ${C.border}`, borderRadius: 14, padding: 18 };

  if (!hasCues) {
    // Honest empty state — no cues to show, so we don't fabricate any.
    return (
      <div style={{ padding: '0 20px 40px' }}>
        <div style={{ fontSize: T.eyebrow, fontWeight: FW.semibold, letterSpacing: '0.13em', color: isDayOf ? live : steelLabel, textTransform: 'uppercase' }}>{eyebrow}</div>
        {subline && <div style={{ fontSize: T.secondary, color: textSub, marginTop: 8 }}>{subline}</div>}
        <div style={{ marginTop: 40, textAlign: 'center', maxWidth: 330, marginLeft: 'auto', marginRight: 'auto' }}>
          <div style={{ fontSize: T.body, color: textPrimary, fontWeight: FW.semibold, lineHeight: 1.4 }}>No run-of-show yet</div>
          <div style={{ fontSize: T.secondary, color: steelTime, marginTop: 8, lineHeight: 1.55 }}>When you sketch the day, the timeline lands here and wakes up when the day begins.</div>
        </div>
      </div>
    );
  }

  return (
    <div style={{ padding: '0 20px 32px', position: 'relative' }}>
      {/* Command hero (parity) — The Day now leads with a proper hero CARD like every other host tab:
          state eyebrow · the date headline · the start + cue-count context (was a bare eyebrow line). */}
      <div style={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 14, padding: isMobile ? '14px 16px' : '16px 18px', marginBottom: 22, display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 14 }}>
        <div style={{ minWidth: 0 }}>
          <div style={{ fontSize: T.eyebrow, fontWeight: FW.heavy, letterSpacing: '0.13em', color: eyebrowColor, textTransform: 'uppercase' }}>{eyebrow}</div>
          <div style={{ fontSize: T.section, fontWeight: FW.heavy, color: textPrimary, marginTop: 7, lineHeight: 1.2 }}>{dateLine || 'The day'}</div>
          <div style={{ fontSize: T.secondary, color: textSub, marginTop: 4 }}>{[startLabel ? `${startLabel} start` : '', `${sorted.length} cue${sorted.length === 1 ? '' : 's'} to run`].filter(Boolean).join(' · ')}</div>
        </div>
        {/* Live clock (board verdict) — the day-of operational anchor, big + tabular, day-of only. */}
        {isDayOf && timeStr && (
          <div style={{ textAlign: 'right', flexShrink: 0 }}>
            <div style={{ fontSize: T.statXl, fontWeight: FW.heavy, color: textPrimary, letterSpacing: '-0.03em', lineHeight: 1, fontVariantNumeric: 'tabular-nums' }}>{timeStr}</div>
            <div style={{ fontSize: T.caption, color: steelTime, marginTop: 4, letterSpacing: '0.04em' }}>{clockDateStr}</div>
          </div>
        )}
      </div>

      {/* Sprint PC-2: same compound-event note Reveal/Host Home already show —
          consumed via ctx, not re-derived. Only renders for compound events. */}
      <ExperienceContinuityNote ctx={ctx} C={C} T={T}
        card={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 14, padding: isMobile ? '14px 16px' : '16px 18px', marginBottom: 22 }}
        eyebrow={{ fontSize: T.eyebrow, fontWeight: FW.heavy, letterSpacing: '0.13em', textTransform: 'uppercase' }}
      />

      {/* Day complete — every cue done. The green hero stays (caught-up reward) so the
          "happening now" panel is never lost to an all-done, empty list. */}
      {allDone && (
        <div style={{ marginTop: 22, border: `1px solid ${live}`, borderRadius: 12, padding: '14px 16px', background: `${live}0d`, boxShadow: `0 0 22px ${live}22`, animation: `ceRise 520ms ${CE_EASE} both` }}>
          <div style={{ display: 'inline-flex', alignItems: 'center', gap: 6, fontSize: T.eyebrow, fontWeight: FW.heavy, letterSpacing: '0.08em', color: live, ...ROW_FONT }}>
            <span style={{ width: 6, height: 6, borderRadius: 99, background: live, boxShadow: `0 0 6px ${live}` }} />EVERYTHING HANDLED
          </div>
          <div style={{ fontSize: T.body, fontWeight: FW.bold, color: textPrimary, marginTop: 6, lineHeight: 1.3, ...ROW_FONT }}>That’s a wrap — every moment’s done.</div>
          <div style={{ fontSize: T.caption, color: steelTime, marginTop: 4, lineHeight: 1.4, ...ROW_FONT }}>Go enjoy it. Nothing left on the run-of-show.</div>
        </div>
      )}

      {/* Timeline — a thin spine down the left with a dot per cue. (ce-daywake: the day-of
          "the day wakes" hero moment stays animated even under reduced-motion — product call.) */}
      <div className="ce-daywake" style={{ position: 'relative', marginTop: 26, paddingLeft: 28 }}>
        {/* Spine line */}
        <div aria-hidden style={{ position: 'absolute', left: 4, top: 6, bottom: 6, width: 2, borderRadius: 2, background: isDayOf ? live : (carbonStrong || C.border), opacity: isDayOf ? 0.55 : 0.4 }} />
        {/* M5 — the day wakes: a travelling light runs down the spine once (clipped to the
            rail). Day-of only; the lead-up timeline stays asleep. */}
        {isDayOf && !allDone && (
          <div aria-hidden style={{ position: 'absolute', left: -4, top: 6, bottom: 6, width: 16, overflow: 'hidden', pointerEvents: 'none' }}>
            {/* Bright white-green core so the travelling light reads on a phone; the wider rail
                lets its glow show (the old 2px rail clipped the glow to a dim thread). */}
            <div style={{ position: 'absolute', top: 0, left: 7, width: 3, height: '40%', borderRadius: 3, background: `linear-gradient(to bottom, transparent, ${live}, #eafff3, ${live}, transparent)`, boxShadow: `0 0 18px ${live}, 0 0 7px #eafff3`, willChange: 'transform', animation: `ceSweep 1300ms cubic-bezier(0.4,0,0.2,1) 240ms both` }} />
          </div>
        )}
        {sorted.map((r, i) => {
          const done = cueDone(r);
          const isNow = r.id === nowCueId;
          const isNext = r.id === nextCueId;
          // Detail line = owner + a short note/location if present.
          const detailBits = [
            (r.owner || '').trim(),
            (r.notes || '').trim() || (r.location || '').trim(),
          ].filter(Boolean);
          const detail = detailBits.join(' · ');
          return (
            <div key={r.id || i} style={{ position: 'relative', paddingBottom: i === sorted.length - 1 ? 0 : 30, opacity: (!isDayOf || isNow) ? 1 : (done ? 0.3 : 0.44), transition: 'opacity 320ms ease' }}>
              {/* Dot — done: faint filled · NOW: bigger green node (M5·C) · upcoming: hollow */}
              <div aria-hidden style={{
                position: 'absolute', left: isNow ? -30 : -28, top: isNow ? 6 : 4, width: isNow ? 13 : 9, height: isNow ? 13 : 9, borderRadius: 999,
                background: isNow ? live : (isNext ? `${steelLabel}22` : 'transparent'),
                border: `1.5px solid ${isNow ? live : isNext ? steelLabel : (done ? C.tier3 : steelTime)}`,
                opacity: done ? 0.5 : 1,
                boxShadow: isNow ? `0 0 0 4px ${live}33, 0 0 12px ${live}` : 'none',
                // M5 — the NOW node ignites as the sweep reaches it (delay scaled to its
                // position so the light "lands" on the node instead of a fixed offset).
                ...(isNow ? { animation: `ceIgnite 520ms ${CE_EASE} ${igniteDelay}ms both` } : {}),
              }} />
              {isNow ? (
                /* M5·C — the live task in a green-bordered card with its eyebrow + time. */
                <div ref={nowCardRef} style={{ border: `1px solid ${live}`, borderRadius: 12, padding: '12px 14px', background: `${live}0d`, boxShadow: `0 0 22px ${live}22`, animation: `ceRise 520ms ${CE_EASE} ${igniteDelay + 120}ms both` }}>
                  <div style={{ display: 'inline-flex', alignItems: 'center', gap: 6, fontSize: T.eyebrow, fontWeight: FW.heavy, letterSpacing: '0.08em', color: live, ...ROW_FONT }}>
                    <span style={{ width: 6, height: 6, borderRadius: 99, background: live, boxShadow: `0 0 6px ${live}` }} />HAPPENING NOW{r.time ? ` · ${fmtTime12(r.time)}` : ''}
                  </div>
                  <div style={{ fontSize: T.body, fontWeight: FW.bold, color: textPrimary, marginTop: 6, lineHeight: 1.3, ...ROW_FONT }}>{r.segment || 'Untitled'}</div>
                  {detail && <div style={{ fontSize: T.caption, color: steelTime, marginTop: 4, lineHeight: 1.4, ...ROW_FONT }}>{detail}</div>}
                </div>
              ) : (
                <>
                  <div style={{ fontSize: T.eyebrow, fontWeight: isNext ? FW.heavy : FW.semibold, letterSpacing: isNext ? '0.1em' : '0.05em', textTransform: isNext ? 'uppercase' : 'none', color: isNext ? steelLabel : steelTime, opacity: done ? 0.55 : 1, ...ROW_FONT }}>
                    {isNext ? `Next · ${r.time ? fmtTime12(r.time) : 'on deck'}` : (r.time ? fmtTime12(r.time) : '')}
                  </div>
                  <div style={{ fontSize: T.secondary, fontWeight: FW.semibold, color: textPrimary, marginTop: 4, lineHeight: 1.35, opacity: done ? 0.45 : 1, textDecoration: done ? 'line-through' : 'none', ...ROW_FONT }}>{r.segment || 'Untitled'}</div>
                  {detail && <div style={{ fontSize: T.caption, color: steelTime, marginTop: 3, opacity: done ? 0.55 : 0.85, lineHeight: 1.4, ...ROW_FONT }}>{detail}</div>}
                </>
              )}
            </div>
          );
        })}
      </div>

      {/* ── Day-of coordination (Figma A1 1553:3) — "Send everyone their part" + the
          "Who's helping" roster. DRAFT-and-share only; no in-app thread (Communications
          FROZEN). The roster is read-only, derived from the run of show + arriving vendors. */}
      {hasBriefable && (
        <div style={{ marginTop: 40 }}>
          <button
            type="button"
            onClick={openHelperBrief}
            style={{ ...coordCard, width: '100%', textAlign: 'left', cursor: 'pointer', borderColor: `${steelLabel}55`, display: 'block' }}
          >
            <div style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', gap: 12 }}>
              <span style={{ fontSize: T.eyebrow, fontWeight: FW.heavy, letterSpacing: '0.13em', textTransform: 'uppercase', color: steelLabel }}>SHARE THE PLAN</span>
              <span style={{ fontSize: T.secondary, fontWeight: FW.bold, color: steelLabel, flexShrink: 0 }}>Share to the group →</span>
            </div>
            <div style={{ fontSize: T.title, fontWeight: FW.heavy, color: textPrimary, marginTop: 8, lineHeight: 1.25 }}>Send everyone their part</div>
            <div style={{ fontSize: T.secondary, color: steelTime, marginTop: 6, lineHeight: 1.5 }}>One message with who’s doing what and when. Drop it in the group chat so nobody has to ask twice.</div>
          </button>
        </div>
      )}

      {helpers.length > 0 && (
        <div style={{ marginTop: 28 }}>
          <div style={{ fontSize: T.eyebrow, fontWeight: FW.semibold, letterSpacing: '0.13em', color: steelLabel, textTransform: 'uppercase', marginBottom: 12 }}>WHO’S HELPING</div>
          <div style={{ display: 'flex', flexDirection: 'column' }}>
            {helpers.map((p, i) => (
              <div key={`${p.name}-${i}`} style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '12px 0', borderTop: i === 0 ? 'none' : `1px solid ${C.border}` }}>
                {/* Initial avatar — calm, no photos, no status hue */}
                <div aria-hidden style={{ width: 38, height: 38, borderRadius: 999, flexShrink: 0, background: C.surface, border: `1px solid ${C.border}`, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: T.caption, fontWeight: FW.bold, color: steelLabel, position: 'relative' }}>
                  {initialOf(p.name)}
                </div>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ fontSize: T.secondary, fontWeight: FW.bold, color: textPrimary, lineHeight: 1.3, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{p.name}</div>
                  {p.role && <div style={{ fontSize: T.caption, color: steelTime, marginTop: 2, lineHeight: 1.4, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{p.role}</div>}
                </div>
                {p.time && <div style={{ fontSize: T.secondary, fontWeight: FW.semibold, color: steelTime, flexShrink: 0, fontVariantNumeric: 'tabular-nums' }}>{fmtTime12(p.time)}</div>}
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Footer — muted, centered. */}
      <div style={{ marginTop: 56, textAlign: 'center' }}>
        <div style={{ fontSize: T.secondary, color: steelTime, maxWidth: 330, marginLeft: 'auto', marginRight: 'auto', lineHeight: 1.5 }}>{footer}</div>
      </div>

      {/* DRAFT hand-off — the shared sheet. NOT a thread: the host shares to their own chat. */}
      {rosDraftSheet && (
        <DraftSheet title={rosDraftSheet.title} intro={rosDraftSheet.intro} draft={rosDraftSheet.draft} shareTitle={rosDraftSheet.shareTitle} kind={rosDraftSheet.kind}
          onClose={() => setRosDraftSheet(null)} C={C} isMobile={isMobile} />
      )}
    </div>
  );
}

// ─── Run of Show ──────────────────────────────────────────────────────────────

function RunOfShow({ ros = [], setRos, vendors = [], eventName, eventDate, eventVenue, eventId, eventType = '', isDayOf = false, honoree = '', meaning = {}, isHost = false, authored = false }) {
  const C        = useT();
  const T = useType();
  const s        = makeS(C);
  const stageCLR = STAGE_CLR(C);
  const rosCLR   = ROS_CLR(C);
  const bp = useContext(BpCtx);
  // Only offer "Add vendor arrivals" when the event actually HAS vendors — pulling
  // arrivals from an empty vendor list is a dead control (the reported confusion).
  const hasVendors = (vendors || []).some(v => v && String(v.name || '').trim());
  const aiKey = useAIKey();
  // Quiet-input style for the schedule grid — the board flagged the bordered
  // "spreadsheet" inputs as the heaviest, most off-system surface. At rest the
  // cell reads like a plain row (transparent, no inset fill); the box only
  // appears on hover/focus so it stays obviously editable.
  const qInput = { ...s.input, background: 'transparent', border: '1px solid transparent', borderRadius: 7, transition: 'background 0.12s, border-color 0.12s' };
  const qFocus = e => { e.currentTarget.style.background = C.bg; e.currentTarget.style.borderColor = C.border; };
  const qBlur  = e => { e.currentTarget.style.background = 'transparent'; e.currentTarget.style.borderColor = 'transparent'; };
  const ownerOptions = [...new Set(['You', 'Day-of Coordinator', 'Venue manager', 'Catering captain',
    ...(vendors || []).flatMap(v => [v.onSiteContactName, v.name].filter(Boolean))])];
  const [modalId, setModalId] = useState(null);
  const modalEntry = ros.find(r => r.id === modalId);
  const [rosFilter, setRosFilter] = useState('all');
  const [rosDraftLoad, setRosDraftLoad] = useState(false);
  const [rosActionsOpen, setRosActionsOpen] = useState(false);
  // Honesty (board): the draft/sync actions must report what actually happened —
  // never spin-then-silence, never claim a complete sync. { kind: 'ok'|'err', text }.
  const [rosActionMsg, setRosActionMsg] = useState(null);
  const isMobileRos = bp === 'mobile' || bp === 'tablet';
  // Delete a layer (Apple): the minute-by-minute schedule is day-of detail. For a host
  // whose event is weeks out, leading with a dense editor is premature — it reads as a
  // wall of work before there's any reason to plan the timeline. Far out, we show a calm
  // lead-in and keep the editor one tap away; near the day (or once they open it), the
  // full schedule leads. Planner view is unchanged.
  const [daySketchOpen, setDaySketchOpen] = useState(false);
  // Funnel depth — the host opened event-day mode (the run of show is live). Once per
  // event per browser, only on the event day itself.
  useEffect(() => {
    if (!isDayOf) return;
    try { trackOnce(`ngw-daymode-${eventId}`, EVENTS.DAY_MODE_OPENED, { event_id: eventId, event_type: eventType }); } catch {}
  }, [isDayOf, eventId]); // eslint-disable-line react-hooks/exhaustive-deps
  const rosDaysOut = eventDate ? Math.round((new Date(eventDate + 'T00:00:00') - new Date()) / 86400000) : null;
  const farOut = isHost && !isDayOf && rosDaysOut != null && rosDaysOut > 21 && !authored;
  const scheduleHidden = farOut && !daySketchOpen;

  const draftFullSchedule = async () => {
    if (!aiInputOn(aiKey)) return;
    setRosDraftLoad(true);
    setRosActionMsg(null);
    const vendorLines = vendors.filter(v=>['Confirmed','Contracted','Deposit Paid'].includes(v.status))
      .map(v=>`${v.name} (${v.category})${v.arrivalTime?' arrives '+v.arrivalTime:''}`).join('\n');
    const existingSegments = ros.map(r=>`${r.time||'?'} — ${r.segment}`).join('\n');
    const prompt = `Generate a complete event-day schedule as JSON array. Each item: { time (HH:MM 24h), segment (string), type ("setup"|"ceremony"|"reception"|"vendor"|"break"|"event"), owner (string), notes (string) }. Include vendor arrivals, setup windows, key event moments, and wind-down. Times should be realistic and sequential. Return ONLY the JSON array, no explanation.\n\nVendors:\n${vendorLines||'(none yet)'}\nExisting segments:\n${existingSegments||'(none)'}\nEvent context: ${ros.length > 0 ? 'Extend/fill gaps in the existing schedule' : 'Create a complete schedule for a full event day'}\n\nJSON:`;
    try {
      const raw = await askNGW('schedule', prompt, { maxTokens: 900, aiKey });
      const match = raw.match(/\[[\s\S]*\]/);
      const items = match ? JSON.parse(match[0]) : [];
      if (Array.isArray(items) && items.length > 0) {
        // Provenance: AI-suggested rows are marked so the planner knows these
        // times are a draft to confirm, not data they entered (board: Trust).
        const newRows = items.map(item => ({ id: uid(), time: item.time||'', segment: item.segment||'', type: item.type||'event', owner: item.owner||'', location: '', confirmed: false, aiDraft: true, notes: item.notes||'' }));
        setRos(r => [...r, ...newRows].sort((a,b)=>(a.time||'').localeCompare(b.time||'')));
        setRosActionMsg({ kind: 'ok', text: `Added ${newRows.length} draft segment${newRows.length !== 1 ? 's' : ''} — review the times and confirm.` });
      } else {
        setRosActionMsg({ kind: 'err', text: 'The draft came back empty. Try again, or add segments manually.' });
      }
    } catch(e) {
      setRosActionMsg({ kind: 'err', text: 'Couldn’t generate a draft — check your connection and try again.' });
    }
    setRosDraftLoad(false);
  };

  const add = () => {
    track(EVENTS.ROS_ITEM_ADDED, { source: 'manual' });
    const nr = { id: uid(), time: '', segment: '', location: '', type: 'event', owner: '', confirmed: false, notes: '' };
    setRos(r => [...r, nr]);
    setModalId(nr.id);
  };
  const del = (id) => { setRos(r => r.filter(e => e.id !== id)); setModalId(null); };
  // Editing a row means the planner has taken ownership — clear the AI-draft mark.
  const upd = (id, key, val) => setRos(r => r.map(e => e.id === id ? { ...e, [key]: val, ...(e.aiDraft && (key === 'time' || key === 'segment' || key === 'owner') ? { aiDraft: false } : {}) } : e));

  const syncVendors = () => {
    setRosActionMsg(null);
    const existing = new Set(ros.filter(r => r.type === 'vendor').map(r => r.vendorName || r.owner));
    const eligible = vendors.filter(v => ['Confirmed','Contracted','Deposit Paid'].includes(v.status) && !existing.has(v.name));
    // Honesty (board): a vendor with no arrival time can't be placed on the schedule.
    // Count and name those so the planner never thinks the sync was complete.
    const skipped  = eligible.filter(v => !v.arrivalTime);
    const newRows  = eligible
      .filter(v => v.arrivalTime)
      // Carry the day-of operational data into the run of show: load-in order,
      // who they report to, and the ON-SITE cell (not the office line).
      .map(v => ({
        id: uid(), time: v.arrivalTime, segment: `${v.name} arrives`,
        location: v.loadInOrder || '', type: 'vendor',
        owner: v.reportsTo || v.name, confirmed: false, vendorName: v.name,
        notes: [
          v.loadInOrder ? `Load-in: ${v.loadInOrder}` : '',
          (v.onSiteContactName || v.onSitePhone) ? `On-site: ${v.onSiteContactName || v.name}${v.onSitePhone ? ' · ' + v.onSitePhone : ''}` : '',
        ].filter(Boolean).join(' · '),
      }));
    if (newRows.length > 0) setRos(r => [...r, ...newRows].sort((a, b) => (a.time || '').localeCompare(b.time || '')));
    const parts = [];
    parts.push(newRows.length > 0 ? `Added ${newRows.length} vendor arrival${newRows.length !== 1 ? 's' : ''}.` : 'No new vendor arrivals to add.');
    if (skipped.length > 0) parts.push(`${skipped.length} skipped (no arrival time): ${skipped.slice(0, 3).map(v => v.name).join(', ')}${skipped.length > 3 ? '…' : ''}.`);
    setRosActionMsg({ kind: skipped.length > 0 && newRows.length === 0 ? 'err' : 'ok', text: parts.join(' ') });
  };

  const sorted = [...ros]
    .filter(r => rosFilter === 'all' || r.type === rosFilter)
    .sort((a, b) => (a.time || '').localeCompare(b.time || ''));
  // Day-of contact bug fix (board 2026-06-10): the number that PRINTS must be
  // the number that's ANSWERED on event day — the on-site cell, not the office
  // line ("the office rings to voicemail at 6am"). Prefer onSitePhone, and show
  // the on-site contact name when set.
  const dayOfPhone = (v) => v.onSitePhone || v.phone || '';
  const dayOfContactName = (v) => v.onSiteContactName || v.contactName || v.name;
  // Roster load-in board: compact COI gate dot. Delegates to the canonical
  // getVendorCOIState (with the EVENT DATE) so a verified-but-EXPIRED cert reads
  // red here too — the previous local copy returned green for any coiVerified===true,
  // green-lighting lapsed coverage on the exact board the venue uses to refuse entry.
  const coiDot = (v) => {
    const coi = getVendorCOIState(v, { date: eventDate });
    if (!coi || !coi.required) return null;
    if (coi.level === 'critical')   return { c: C.danger,  t: coi.label };
    if (coi.status === 'verified')  return { c: C.success, t: 'COI verified valid' };
    if (coi.level === 'attention')  return { c: C.muted,    t: coi.label };
    return null;
  };
  const emergencyContacts = vendors.filter(v => dayOfPhone(v)).sort((a, b) => (a.arrivalTime || '').localeCompare(b.arrivalTime || ''));
  const unconfirmed = sorted.filter(r => r.type === 'vendor' && !r.confirmed).length;

  // Sprint 60.W — operational phase grouping. Each row gets a phase label
  // (Prep / Arrivals / Ceremony / Reception / Wrap for weddings; the same
  // bucketing reads sensibly for any event type via keyword + time fallback).
  const phaseOf = (entry) => {
    if (!entry) return 'prep';
    const seg = (entry.segment || '').toLowerCase();
    const own = (entry.owner   || '').toLowerCase();
    const text = `${seg} ${own}`;
    const min = entry.time ? parseMin(entry.time) : null;
    // Wrap / ceremony / reception keywords win regardless of time.
    if (/wrap|breakdown|load[ -]?out|departure|teardown|cleanup/.test(text))                    return 'wrap';
    if (/ceremony|vows|processional|recessional|officiant|first look/.test(text))               return 'ceremony';
    if (/cocktail|dinner|reception|toast|dance|cake|bar opens|appetizer|hors/.test(text))       return 'reception';
    // Sprint 60.W tweak — morning setup/load-in (before 12pm) reads as Prep,
    // even if it's a vendor doing it. Afternoon vendor arrivals are Arrivals.
    if (min !== null && min < 12 * 60)                                                          return 'prep';
    if (entry.type === 'prep')                                                                  return 'prep';
    if (entry.type === 'vendor' || /arriv|load[ -]?in|setup begins|setup|venue opens/.test(text)) return 'arrivals';
    if (min === null) return 'prep';
    if (min < 14 * 60) return 'arrivals';
    if (min < 17 * 60) return 'ceremony';
    if (min < 22 * 60) return 'reception';
    return 'wrap';
  };
  const PHASE_LABEL = { prep: 'Prep', arrivals: 'Arrivals', ceremony: 'Ceremony', reception: 'Reception', wrap: 'Wrap' };
  const PHASE_ORDER = ['prep', 'arrivals', 'ceremony', 'reception', 'wrap'];

  // Sprint 60.W — readiness derivation. Surfaces the rows the planner most
  // needs to fix before Day-of: missing owner / missing time / missing
  // location / vendor unconfirmed / time overlap.
  const readiness = (() => {
    const out = { missingOwner: 0, missingTime: 0, missingLocation: 0, vendorUnconfirmed: 0, overlaps: 0, total: sorted.length };
    sorted.forEach((r) => {
      if (!(r.owner || '').trim())    out.missingOwner++;
      if (!(r.time  || '').trim())    out.missingTime++;
      if (!(r.location || '').trim()) out.missingLocation++;
      if (r.type === 'vendor' && !r.confirmed) out.vendorUnconfirmed++;
    });
    // P4 — PAIRWISE interval overlap (was adjacent-only): a long segment colliding with
    // a non-adjacent later segment is now caught. See lib/rosOverlap.
    out.overlaps = rosOverlapCount(sorted);
    return out;
  })();

  const fmtTime12 = (t) => {
    if (!t) return '—';
    const [h, m] = t.split(':').map(Number);
    return `${h % 12 || 12}:${String(m).padStart(2, '0')} ${h >= 12 ? 'PM' : 'AM'}`;
  };

  // Print / PDF — opens a clean, print-formatted day-of schedule (use browser "Save as PDF")
  const printROS = () => {
    const esc = (str) => String(str || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    const all = [...ros].sort((a, b) => (a.time || '').localeCompare(b.time || ''));
    const typeLabel = { vendor: 'Vendor', event: 'Event', prep: 'Prep', setup: 'Setup', ceremony: 'Ceremony', reception: 'Reception', break: 'Break' };
    const rows = all.map(r => `
      <tr>
        <td class="time">${esc(fmtTime12(r.time))}${r.endTime ? ' – ' + esc(fmtTime12(r.endTime)) : ''}</td>
        <td><strong>${esc(r.segment) || '<span class="muted">Untitled</span>'}</strong>${r.notes ? `<div class="notes">${esc(r.notes)}</div>` : ''}</td>
        <td>${esc(r.location)}</td>
        <td>${esc(r.owner)}</td>
        <td class="type">${esc(typeLabel[r.type] || r.type || '')}</td>
      </tr>`).join('');
    const contactRows = emergencyContacts.map(v => `
      <tr><td><strong>${esc(v.name)}</strong> <span class="muted">${esc(v.category)}${v.onSiteContactName ? ' · ' + esc(v.onSiteContactName) : ''}</span></td><td>${esc(v.arrivalTime ? fmtTime12(v.arrivalTime) : '')}</td><td>${esc(dayOfPhone(v))}${v.onSitePhone ? '' : ' <span class="muted">(office — no day-of cell)</span>'}</td></tr>`).join('');
    const win = window.open('', '_blank');
    if (!win) return;
    win.document.write(`<!DOCTYPE html><html><head><title>${esc(eventName || 'Event Day Schedule')} — Event Day Schedule</title>
      <style>
        * { box-sizing: border-box; }
        body { font-family: -apple-system, system-ui, 'Segoe UI', Arial, sans-serif; color: #111; margin: 0; padding: 36px 44px; }
        h1 { font-size: 22px; margin: 0 0 2px; }
        .sub { color: #555; font-size: 13px; margin-bottom: 4px; }
        .meta { color: #888; font-size: 11px; margin-bottom: 24px; }
        h2 { font-size: 13px; text-transform: uppercase; letter-spacing: 0.08em; color: #444; margin: 28px 0 8px; border-bottom: 2px solid #111; padding-bottom: 4px; }
        table { width: 100%; border-collapse: collapse; font-size: 12px; }
        th { text-align: left; font-size: 10px; text-transform: uppercase; letter-spacing: 0.06em; color: #888; padding: 6px 8px; border-bottom: 1px solid #ccc; }
        td { padding: 8px; border-bottom: 1px solid #eee; vertical-align: top; }
        td.time { font-weight: 700; white-space: nowrap; width: 90px; font-variant-numeric: tabular-nums; }
        td.type { color: #888; font-size: 11px; white-space: nowrap; }
        .notes { color: #666; font-size: 11px; margin-top: 2px; font-weight: 400; }
        .muted { color: #aaa; font-weight: 400; }
        @media print { body { padding: 0; } @page { margin: 0.6in; } }
      </style></head><body>
      <h1>${esc(eventName || 'Event Day Schedule')}</h1>
      <div class="sub">Event Day Schedule${eventVenue ? ' · ' + esc(eventVenue) : ''}${eventDate ? ' · ' + esc(fmtDate(eventDate)) : ''}</div>
      <div class="meta">${all.length} segment${all.length !== 1 ? 's' : ''} · Generated ${esc(fmtDate(today8601()))}</div>
      <table>
        <thead><tr><th>Time</th><th>Item</th><th>Location</th><th>In charge</th><th>Type</th></tr></thead>
        <tbody>${rows || '<tr><td colspan="5" class="muted">No schedule items yet.</td></tr>'}</tbody>
      </table>
      ${contactRows ? `<h2>Day-of Contacts</h2><table><thead><tr><th>Vendor</th><th>Arrives</th><th>Phone</th></tr></thead><tbody>${contactRows}</tbody></table>` : ''}
      <script>window.onload=function(){window.print();}<\/script>
      </body></html>`);
    win.document.close();
    win.focus();
  };

  // Sprint 60.T Phase 2 — Day-of Schedule timeline lock.
  // When event is in dayMode, render the operational NOW / NEXT / LATER /
  // DONE bucketing instead of the full planning layout. Buckets derive
  // from current time vs r.time; "Now" = current item (last started
  // within 60 min and no later item yet); "Next" = next 2 upcoming;
  // "Later" = remaining future; "Done" = completed/past collapsed.
  if (isDayOf) {
    const now = new Date();
    const nowMin = now.getHours() * 60 + now.getMinutes();
    const items = [...ros]
      .filter(r => r.time)
      .map(r => ({ ...r, _min: parseMin(r.time) }))
      .filter(r => r._min !== null)
      .sort((a, b) => a._min - b._min);
    // Sprint 60.Y RoS Phase 1 — execution state. NOW follows what the planner
    // actually STARTED (r.actualStart, minutes-of-day), not the wall clock, so a
    // late segment no longer makes the schedule lie. Clock is only the fallback
    // before anything has been started.
    const nonDone = items.filter(r => !r.done);
    const doneMarked = items.filter(r => r.done);
    let nowItem = null, passed = [], rest = [];
    const startedIdx = nonDone.findIndex(r => r.actualStart != null);
    if (startedIdx >= 0) {
      nowItem = nonDone[startedIdx];
      passed = nonDone.slice(0, startedIdx);
      rest   = nonDone.slice(startedIdx + 1);
    } else {
      let idx = -1;
      for (let i = nonDone.length - 1; i >= 0; i--) { if (nonDone[i]._min <= nowMin) { idx = i; break; } }
      nowItem = idx >= 0 ? nonDone[idx] : null;
      passed  = idx >= 0 ? nonDone.slice(0, idx) : [];
      rest    = idx >= 0 ? nonDone.slice(idx + 1) : nonDone;
    }
    const nextItems  = rest.slice(0, 2);
    const laterItems = rest.slice(2);
    const doneItems  = [...passed, ...doneMarked].sort((a, b) => a._min - b._min);

    // Ahead/behind drift — only once a segment is actually started (honest: no
    // claim before there's real execution data).
    const drift = (nowItem && nowItem.actualStart != null) ? nowItem.actualStart - nowItem._min : null;
    const driftLabel = drift == null ? null
      : Math.abs(drift) <= 3 ? { txt: 'On time',                col: C.success }
      : drift > 0            ? { txt: `${drift} min behind`,    col: C.muted }
      :                        { txt: `${-drift} min ahead`,    col: C.accent2 };

    const nowMinutes = () => { const d = new Date(); return d.getHours() * 60 + d.getMinutes(); };
    const startSeg = (id) => upd(id, 'actualStart', nowMinutes());
    const doneSeg  = (id) => setRos(r => r.map(e => e.id === id ? { ...e, done: true } : e));
    const undoSeg  = (id) => setRos(r => r.map(e => e.id === id ? { ...e, done: false, actualStart: null } : e));

    const panelRaise = [
      'inset 0 1px 0 rgba(255,255,255,0.05)',
      '0 1px 0 rgba(255,255,255,0.02)',
      '0 4px 10px rgba(0,0,0,0.30)',
      '0 14px 28px rgba(0,0,0,0.22)',
    ].join(', ');

    // Board #18 — when one person runs everything (a solo home host), repeating their
    // name on every row is noise. Collapse it to a single banner and reclaim the space.
    const distinctOwners = [...new Set((ros || []).map(r => String(r.owner || '').trim().toLowerCase()).filter(Boolean))];
    const soloRun = distinctOwners.length <= 1;
    const Card = ({ r, color, dim = false, kind }) => (
      // #6 — tap any event-day item to open its editable drawer (fields + sub-tasks).
      // #12 — data-deeplink so a CTA routing to a specific run-of-show moment
      // (timelineId) scrolls + flashes the row via the global deep-link effect.
      <div role="button" tabIndex={0} data-deeplink={r.id} onClick={() => setModalId(r.id)}
        onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setModalId(r.id); } }}
        style={{ ...s.card, padding: '14px 16px 14px 19px', borderRadius: 14, borderLeft: `3px solid ${color}`, boxShadow: dim ? 'none' : panelRaise, opacity: dim ? 0.62 : 1, cursor: 'pointer' }}>
        <div style={{ display: 'flex', alignItems: 'flex-start', gap: 12 }}>
          <span style={{ fontFamily: 'monospace', fontSize: T.title, fontWeight: FW.heavy, color: dim ? C.muted : C.text, minWidth: 72, flexShrink: 0, lineHeight: 1.15 }}>
            {fmtTime12(r.time)}
            {r.endTime && <span style={{ display: 'block', fontSize: T.secondary, fontWeight: FW.semibold, color: C.muted }}>–{fmtTime12(r.endTime)}</span>}
          </span>
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{ fontSize: T.body, fontWeight: FW.bold, color: dim ? C.muted : C.text }}>{r.segment || '(untitled)'}</div>
            {((!soloRun && r.owner) || r.location) && <div style={{ fontSize: T.secondary, color: C.muted, marginTop: 3 }}>{[soloRun ? null : r.owner, r.location].filter(Boolean).join(' · ')}</div>}
            {Array.isArray(r.subtasks) && r.subtasks.length > 0 && (() => {
              const dn = r.subtasks.filter((x) => x.done).length;
              return <div style={{ fontSize: T.secondary, fontWeight: FW.semibold, color: dn === r.subtasks.length ? C.success : (C.accentTopGrad || C.accent), marginTop: 4 }}>✓ {dn} of {r.subtasks.length} steps</div>;
            })()}
            {/* Cue notes — the coordinator's cue sheet, surfaced (was dropped before). */}
            {r.notes && <div style={{ fontSize: T.secondary, color: kind === 'now' ? C.text : C.muted, marginTop: 5, lineHeight: 1.45, fontStyle: kind === 'now' ? 'normal' : 'italic' }}>{r.notes}</div>}
            {kind === 'now' && r.actualStart != null && <div style={{ fontSize: T.secondary, color: C.muted, marginTop: 4 }}>Started {fmtTime12(`${String(Math.floor(r.actualStart / 60)).padStart(2, '0')}:${String(r.actualStart % 60).padStart(2, '0')}`)}</div>}
          </div>
        </div>
        {kind === 'now' && (
          <div style={{ display: 'flex', gap: 8, marginTop: 12 }}>
            {/* Board fix (tired-planner + grandmother): until a segment is STARTED,
                the dominant action is Start — never show the finish/skip action
                louder than the begin action. Once started, Done becomes primary. */}
            {r.actualStart == null
              ? <button onClick={() => startSeg(r.id)} style={{ ...s.btn('primary'), fontSize: T.body, padding: '11px 16px', minHeight: 46, flex: 1 }}>▶ Start now</button>
              : <button onClick={() => doneSeg(r.id)} style={{ ...s.btn('primary'), fontSize: T.body, padding: '11px 16px', minHeight: 46, flex: 1 }}>✓ Done</button>}
          </div>
        )}
        {kind === 'next' && (
          <div style={{ marginTop: 10 }}>
            <button onClick={() => startSeg(r.id)} style={{ ...s.btn(), fontSize: T.secondary, padding: '9px 14px', minHeight: 44 }}>Skip to this</button>
          </div>
        )}
        {kind === 'done' && (
          <button onClick={() => undoSeg(r.id)} style={{ background: 'none', border: 'none', color: C.muted, fontSize: T.secondary, cursor: 'pointer', padding: '6px 0 0', fontFamily: 'inherit' }}>↶ Not done yet</button>
        )}
      </div>
    );

    const Section = ({ label, color, items: secItems, dim = false, kind }) => {
      if (secItems.length === 0) return null;
      return (
        <div style={{ marginBottom: 18 }}>
          <div style={{ fontSize: T.secondary, fontWeight: FW.bold, letterSpacing: '0.14em', textTransform: 'uppercase', color, marginBottom: 8, paddingLeft: 4 }}>{label}</div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
            {secItems.map(r => <Card key={r.id} r={r} color={color} dim={dim} kind={kind} />)}
          </div>
        </div>
      );
    };

    return (
      <div style={{ paddingBottom: 80 }}>
        {/* Header + drift badge */}
        <div style={{ marginBottom: 16, paddingLeft: 4, display: 'flex', alignItems: 'flex-start', gap: 12, flexWrap: 'wrap' }}>
          <div style={{ flex: 1, minWidth: 180 }}>
            <div style={{ fontSize: T.section, fontWeight: FW.bold, letterSpacing: '-0.01em', color: C.text, marginBottom: 4 }}>Today's schedule</div>
            <div style={{ fontSize: T.body, color: C.muted, lineHeight: 1.4 }}>Tap Start / Done as the day runs — it tracks reality, not the clock.</div>
          </div>
          {driftLabel && (
            <div style={{ fontSize: T.secondary, fontWeight: FW.heavy, color: driftLabel.col, background: driftLabel.col + '1e', border: `1px solid ${driftLabel.col}55`, borderRadius: 8, padding: '7px 13px', flexShrink: 0 }}>{driftLabel.txt}</div>
          )}
        </div>
        {/* Board #18 — solo run: one banner instead of "You" stamped on every row. */}
        {soloRun && items.length > 0 && (
          <div style={{ ...s.card, padding: '11px 15px', borderRadius: 12, marginBottom: 14, fontSize: T.secondary, color: C.muted, borderLeft: `3px solid ${C.accent}` }}>
            You're running all of it — every cue below is on you.
          </div>
        )}
        {items.length === 0 ? (
          <div style={{ ...s.card, padding: '24px 16px', textAlign: 'center', borderRadius: 14 }}>
            <div style={{ fontSize: T.body, color: C.muted }}>
              No schedule yet. Add segments in planning to surface them on event day.
            </div>
          </div>
        ) : (
          <>
            {nowItem && <Section label="Now" color={C.muted} items={[nowItem]} kind="now" />}
            {nextItems.length > 0 && <Section label="Next up" color={C.accent2} items={nextItems} kind="next" />}
            {laterItems.length > 0 && <Section label="Later" color={C.muted} items={laterItems} kind="later" />}
            {doneItems.length > 0 && <Section label={`Done · ${doneItems.length}`} color={C.success} items={doneItems} dim kind="done" />}
          </>
        )}
      </div>
    );
  }

  return (
    <div>
      {modalEntry && (
        <ROSModal
          entry={modalEntry}
          ownerOptions={ownerOptions}
          onClose={() => setModalId(null)}
          onChange={(key, val) => upd(modalId, key, val)}
          onDelete={() => del(modalId)}
        />
      )}

      {/* "Heart of the night" (board 2026-06-12): the meaning-first intake feeds
          straight into the day-of so the planner runs the night against what it's
          supposed to FEEL like — not just the logistics. Only shows once the
          intake's been filled. */}
      {(() => {
        const story    = (meaning.story    || '').trim();
        const feeling  = (meaning.feeling  || '').trim();
        const why      = (meaning.why      || '').trim();
        const mustHave = (meaning.mustHave || '').trim();
        if (!story && !feeling && !why && !mustHave) return null;
        const feelWords = feeling ? feeling.split(/[·,]/).map(w => w.trim()).filter(Boolean) : [];
        // The Day's ONE hue moment (board ruling): the heart of the night glows in the
        // event's OWN identity color — whose night this is — never on the cue rows below.
        // Somber events stay on the neutral accent (no festive hue).
        const _di = evtIdentity(eventType, C);
        const hh = C.accent; // no cultural/identity color in cards (user rule) — neutral accent, mono icon
        return (
          <div style={{ ...s.card, marginBottom: 18, padding: '16px 20px', borderLeft: `3px solid ${hh}`, background: `linear-gradient(180deg, ${hh}12 0%, ${hh}05 100%)` }}>
            <div style={{ fontSize: T.caption, fontWeight: FW.heavy, letterSpacing: '0.18em', color: hh, textTransform: 'uppercase', marginBottom: 9, display: 'flex', alignItems: 'center', gap: 8 }}>
              <span aria-hidden style={{ display: 'flex' }}><Icon name={_di.icon} size={15} stroke={1.9} /></span> The heart of the night
            </div>
            {feelWords.length > 0 && (
              <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap', marginBottom: story || why || mustHave ? 9 : 0 }}>
                {feelWords.map((w, i) => (
                  <span key={i} style={{ fontSize: T.secondary, fontWeight: FW.semibold, color: C.text, background: `${hh}1A`, border: `1px solid ${hh}40`, padding: '2px 9px', borderRadius: 999 }}>{w}</span>
                ))}
              </div>
            )}
            {why && <div style={{ fontSize: T.secondary, color: C.text, lineHeight: 1.5, marginBottom: story || mustHave ? 7 : 0 }}>{why}</div>}
            {story && <div style={{ fontSize: T.secondary, color: C.muted, lineHeight: 1.5, marginBottom: mustHave ? 7 : 0 }}>{story}</div>}
            {mustHave && (
              <div style={{ fontSize: T.secondary, color: C.text, lineHeight: 1.45, display: 'flex', gap: 7, alignItems: 'baseline' }}>
                <span aria-hidden style={{ color: hh, fontWeight: FW.heavy }}>★</span>
                <span><strong style={{ color: hh }}>Must-have moment:</strong> {mustHave}</span>
              </div>
            )}
          </div>
        );
      })()}

      {/* "Honoree does nothing" guard (board 2026-06-12, VenueOps): the guest of
          honor should be celebrated, not coordinating. Flag any day-of moment
          assigned to them so the planner reassigns it. */}
      {(() => {
        const hn = (honoree || '').trim().toLowerCase();
        if (!hn) return null;
        const first = hn.split(' ')[0];
        const mine = (ros || []).filter(r => { const o = (r.owner || '').trim().toLowerCase(); return o && (o === hn || o === first || first === o.split(' ')[0]); });
        if (!mine.length) return null;
        return (
          <div style={{ ...s.card, marginBottom: 14, padding: '11px 14px', borderLeft: `3px solid ${C.muted}`, background: `${C.muted}12`, display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
            <span aria-hidden style={{ color: C.muted, fontWeight: FW.heavy }}>⚠</span>
            <span style={{ fontSize: T.secondary, color: C.text, lineHeight: 1.45, flex: 1, minWidth: 180 }}>
              <strong>{honoree}</strong> is running {mine.length} moment{mine.length !== 1 ? 's' : ''} — they should be <em>celebrating</em>, not working. Reassign so they can enjoy their night.
            </span>
          </div>
        );
      })()}

      {/* ROS mobile action sheet */}
      {rosActionsOpen && (
        <>
          <div onClick={() => setRosActionsOpen(false)} style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.45)', zIndex: 97 }} />
          <div style={{ position: 'fixed', left: 0, right: 0, bottom: 0, background: C.surface, borderTop: `1px solid ${C.border}`, borderRadius: '20px 20px 0 0', zIndex: 98, paddingBottom: 'env(safe-area-inset-bottom)' }}>
            <SheetGrip isMobile />
            <div style={{ padding: '4px 16px 20px' }}>
              {[
                ...(hasVendors ? [{ label: 'Add vendor arrivals', action: () => { syncVendors(); setRosActionsOpen(false); } }] : []),
                { label: 'Print / PDF', action: () => { printROS(); setRosActionsOpen(false); } },
                ...(aiInputOn(aiKey) ? [{ label: rosDraftLoad ? 'Drafting…' : 'Draft schedule (AI)', action: () => { draftFullSchedule(); setRosActionsOpen(false); }, disabled: rosDraftLoad }] : []),
              ].map(({ label, action, disabled }) => (
                <button key={label} onClick={action} disabled={disabled}
                  style={{ ...s.btn(), width: '100%', justifyContent: 'flex-start', display: 'flex', padding: '13px 16px', fontSize: T.body, marginBottom: 6, opacity: disabled ? 0.6 : 1 }}>
                  {label}
                </button>
              ))}
              <button onClick={() => setRosActionsOpen(false)}
                style={{ ...s.btn(), width: '100%', padding: '13px 16px', fontSize: T.body, marginTop: 4, color: C.muted }}>
                Cancel
              </button>
            </div>
          </div>
        </>
      )}

      {/* The ops console (segments/arrivals/prep/unconfirmed counts) is planner
          logistics shorthand — a host reads it as software jargon. Hidden for hosts. */}
      {!isHost && (
        <div id="ros-stats" style={{ display: 'flex', gap: 16, marginBottom: 24, flexWrap: 'wrap' }}>
          <StatCard label="What's planned"    value={ros.length} />
          <StatCard label="Vendors arriving"  value={ros.filter(r => r.type === 'vendor').length} color={C.accent2} />
          <StatCard label="Setup steps"       value={ros.filter(r => r.type === 'prep').length}   color={C.muted} />
          <StatCard label="Need confirmation" value={unconfirmed} color={unconfirmed > 0 ? C.danger : C.success} sub={unconfirmed > 0 ? 'tap to fix' : 'all confirmed'} />
        </div>
      )}

      {/* Draft versions — planner tooling (rain-plan alternates). Hidden for hosts. */}
      {!isHost && (
        <DraftVersionBar
          draftKey={`schedule:${eventId || 'event'}`}
          content={ros}
          onRestore={(c) => setRos(Array.isArray(c) ? c : [])}
          saveLabel="Save this schedule"
          emptyHint="Save the schedule to keep alternates — e.g. a rain plan — and switch between them."
        />
      )}

      {/* Sprint 60.W — Readiness strip. Surfaces the rows the planner needs
          to fix before Day-of: missing owner / time / location / vendor
          unconfirmed / overlap. Hidden when everything is clean.
          Host fix: an auto-generated draft flagging its own "Time overlap /
          Missing location" reads to a host as "you broke it." Planner-only. */}
      {!isHost && sorted.length > 0 && (() => {
        const steelTopROS = C.accentTopGrad || C.accent;
        const issues = [
          { key: 'overlaps',          n: readiness.overlaps,          label: 'Time overlap',       color: C.danger },
          { key: 'vendorUnconfirmed', n: readiness.vendorUnconfirmed, label: 'Vendor unconfirmed', color: C.muted   },
          { key: 'missingTime',       n: readiness.missingTime,       label: 'Missing time',       color: C.muted   },
          { key: 'missingOwner',      n: readiness.missingOwner,      label: 'Missing owner',      color: C.muted   },
          { key: 'missingLocation',   n: readiness.missingLocation,   label: 'Missing location',   color: C.muted  },
        ].filter(i => i.n > 0);
        const allClear = issues.length === 0;
        return (
          <div style={{
            marginBottom: 16,
            background: `linear-gradient(180deg, ${steelTopROS}14 0%, ${steelTopROS}07 100%)`,
            border: `1px solid ${steelTopROS}33`,
            borderLeft: `3px solid ${allClear ? C.success : steelTopROS}`,
            borderRadius: 10,
            padding: '10px 14px',
            display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: 10,
          }}>
            <span aria-hidden style={{
              flexShrink: 0, width: 22, height: 22, borderRadius: '50%',
              background: allClear ? `${C.success}22` : `${steelTopROS}22`,
              color: allClear ? C.success : steelTopROS,
              display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
              fontSize: T.secondary, fontWeight: FW.heavy,
            }}>{allClear ? '✓' : '◐'}</span>
            <span style={{ fontSize: T.caption, fontWeight: FW.heavy, letterSpacing: '0.14em', textTransform: 'uppercase', color: steelTopROS }}>Readiness</span>
            {allClear ? (
              <span style={{ fontSize: T.secondary, fontWeight: FW.semibold, color: C.text }}>Every segment has a time, owner, and location filled in, and all vendor rows are confirmed.</span>
            ) : (
              <>
                {issues.map(i => (
                  <span key={i.key} style={{ fontSize: T.secondary, fontWeight: FW.bold, color: i.color, background: `${i.color}14`, border: `1px solid ${i.color}44`, padding: '3px 9px', borderRadius: 999, letterSpacing: '0.04em', textTransform: 'uppercase' }}>
                    {i.n} · {i.label}
                  </span>
                ))}
              </>
            )}
          </div>
        );
      })()}

      {scheduleHidden && (
        <div style={{ ...s.card, borderLeft: `3px solid ${C.accent}` }}>
          <div style={s.cardTitle}>Your run of the day</div>
          <div style={{ fontSize: T.body, color: C.muted, marginTop: 8, lineHeight: 1.55 }}>
            {rosDaysOut > 60
              ? `Your event's about ${Math.round(rosDaysOut / 7)} weeks out — there's no rush on the minute-by-minute yet.`
              : `Your event's ${rosDaysOut} days out — the timeline comes together best a few weeks before.`}
            {' '}We'll have a starting shape ready when it's time. Want to sketch it now? Go for it.
          </div>
          <button type="button" onClick={() => setDaySketchOpen(true)}
            style={{ marginTop: 12, minHeight: 40, padding: '0 16px', borderRadius: 10, border: `1px solid ${C.border}`, background: 'transparent', color: C.text, fontSize: T.secondary, fontWeight: FW.bold, cursor: 'pointer', fontFamily: 'inherit' }}>
            Sketch the day now →
          </button>
        </div>
      )}
      <CollapsibleCard id="ros-schedule" isMobile={isMobileRos} title={isHost ? 'Your run of the day' : 'Event Day Schedule'} style={scheduleHidden ? { display: 'none' } : undefined}>
        <div style={{ display: 'flex', justifyContent: 'flex-end', alignItems: 'center', marginBottom: 16, flexWrap: 'wrap', gap: 8 }}>
          {isMobileRos ? (
            <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
              <select style={{ ...s.input, width: 'auto', padding: '5px 10px', fontSize: T.secondary }}
                value={rosFilter} onChange={e => setRosFilter(e.target.value)}>
                <option value="all">All</option>
                <option value="vendor">Vendors</option>
                <option value="event">Event</option>
                <option value="prep">Prep</option>
              </select>
              <button style={s.btn('primary')} onClick={add}>+ Add</button>
              <button onClick={() => setRosActionsOpen(true)}
                style={{ width: 36, height: 36, borderRadius: 8, border: `1px solid ${C.border}`, background: 'transparent', color: C.text, cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
                <Icon name="ellipsis" size={16} />
              </button>
            </div>
          ) : (
            <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', alignItems: 'center' }}>
              <select style={{ ...s.input, width: 'auto', padding: '5px 10px', fontSize: T.secondary }}
                value={rosFilter} onChange={e => setRosFilter(e.target.value)}>
                <option value="all">All types</option>
                {hasVendors && <option value="vendor">Vendors</option>}
                <option value="event">Event</option>
                <option value="prep">Prep</option>
              </select>
              {hasVendors && <button style={s.btn('teal')} onClick={syncVendors}>Add vendor arrivals</button>}
              <button aria-label="Open a print-ready schedule — use your browser's Save as PDF" style={s.btn()} onClick={printROS} title="Open a print-ready schedule — use your browser's Save as PDF">Print / PDF</button>
              <AIBtn onClick={draftFullSchedule} loading={rosDraftLoad} label="Draft schedule" />
              <button style={s.btn('primary')} onClick={add}>+ Add</button>
            </div>
          )}
        </div>

        {/* The HOST'S must-have moment — the heart "Plan the moment" CTA lands here.
            Their custom moment (e.g. "The elders get served first") isn't in the authored
            menu below, so without this card the CTA dropped them on a schedule with no way
            to add THEIR moment ("takes me to nothing"). One tap puts it on the run of show
            and opens the editor for a time + owner. data-deeplink so the CTA scrolls to it. */}
        {!isDayOf && meaning && isMeaningfulMustHave(meaning.mustHave) && !ros.some(r => r && r.heart) && (
          <div data-deeplink="musthave" style={{ marginBottom: 16, padding: '14px 16px', border: `1px solid ${C.accent}`, borderLeft: `3px solid ${C.accent}`, borderRadius: 10, background: `${C.accent}10` }}>
            <div style={{ fontSize: T.caption, fontWeight: FW.bold, letterSpacing: '0.1em', textTransform: 'uppercase', color: C.accent, marginBottom: 6 }}>The one thing that has to happen</div>
            <div style={{ fontSize: T.body, fontWeight: FW.bold, color: C.text, lineHeight: 1.4, marginBottom: 10 }}>{meaning.mustHave}</div>
            <button type="button" onClick={() => {
                const id = uid();
                setRos(r => [...r, { id, time: '', segment: meaning.mustHave, owner: 'You', type: 'event', heart: true, notes: 'The one thing that has to happen — set a time and assign who leads it.' }]);
                setModalId(id); // open the editor so they give it a time + owner right away
              }}
              style={{ fontSize: T.secondary, fontWeight: FW.bold, padding: '10px 16px', borderRadius: 10, border: 'none', cursor: 'pointer', background: C.accent, color: '#fff' }}>+ Put it on the run of show</button>
          </div>
        )}

        {/* Sprint 60F — Moment Library (ROS-only, pi.moments). One tap puts the
            moment a host cares about on the schedule WITH an owner. Authored menu
            per event type; only moments not already scheduled are offered. */}
        {momentsOn() && !isDayOf && (() => {
          const sugg = suggestableMoments(eventType, ros);
          if (!sugg.length) return null;
          const addMoment = (m) => { track(EVENTS.ROS_ITEM_ADDED, { source: 'moment', moment: m.id }); setRos(r => [...r, { id: uid(), ...buildMomentSegment(m) }]); };
          return (
            <div style={{ marginBottom: 16, padding: '10px 12px', border: `1px dashed ${C.border}`, borderRadius: 8 }}>
              <div style={{ fontSize: T.caption, fontWeight: FW.bold, letterSpacing: '0.1em', textTransform: 'uppercase', color: C.muted, marginBottom: 8 }}>{isHost ? 'Moments that matter · one tap drops it into your day' : 'Moments that matter · one tap adds it with an owner'}</div>
              <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6 }}>
                {sugg.map(m => (
                  <button key={m.id} onClick={() => addMoment(m)}
                    title={m.note ? `Owner: ${m.owner} · ${m.note}` : `Owner: ${m.owner}`}
                    style={{ fontSize: T.caption, fontWeight: FW.semibold, padding: '5px 11px', borderRadius: 16, cursor: 'pointer', border: `1px solid ${C.border}`, background: 'transparent', color: C.text }}>
                    + {m.label}
                  </button>
                ))}
              </div>
            </div>
          );
        })()}

        {rosActionMsg && (
          <div role="status" style={{
            display: 'flex', alignItems: 'flex-start', gap: 8, marginBottom: 14,
            background: `${rosActionMsg.kind === 'err' ? C.muted : C.success}14`,
            border: `1px solid ${rosActionMsg.kind === 'err' ? C.muted : C.success}44`,
            borderRadius: 8, padding: '8px 12px', fontSize: T.secondary, color: C.text,
          }}>
            <span aria-hidden style={{ color: rosActionMsg.kind === 'err' ? C.muted : C.success, fontWeight: FW.heavy, flexShrink: 0 }}>{rosActionMsg.kind === 'err' ? '⚠' : '✓'}</span>
            <span style={{ flex: 1 }}>{rosActionMsg.text}</span>
            <button onClick={() => setRosActionMsg(null)} aria-label="Dismiss" style={{ background: 'transparent', border: 'none', color: C.muted, cursor: 'pointer', fontSize: T.body, lineHeight: 1, flexShrink: 0 }}>×</button>
          </div>
        )}

        {/* Owner directive 2026-06-24: a HOST never gets the wide 9-column spreadsheet grid —
            it wastes real estate and reads as software (Ruthless Host Lens). Hosts (any
            viewport) get the compact CATEGORY → task-list reader (phase header → stacked
            items, each tap-to-edit with sub-tasks). Only a PLANNER on desktop keeps the
            inline editing grid. */}
        {(bp === 'mobile' || bp === 'tablet' || isHost) ? (
          <div>
            {sorted.length === 0 && <div style={{ fontSize: T.secondary, color: C.muted, textAlign: 'center', padding: '20px 0' }}>No schedule yet — tap "+ Add" to start</div>}
            {sorted.map((entry, i) => {
              const typeColor = rosCLR[entry.type] || C.muted;
              const next      = sorted[i + 1];
              const gapMin    = (entry.time && next?.time) ? parseMin(next.time) - parseMin(entry.time) : null;
              const gapLabel  = gapMin !== null && gapMin > 0 ? fmtDur(gapMin) : null;
              const phase     = phaseOf(entry);
              const prevPhase = i > 0 ? phaseOf(sorted[i - 1]) : null;
              const showPhase = phase !== prevPhase;
              const steelTopROS = C.accentTopGrad || C.accent;
              return (
                <div key={entry.id}>
                  {showPhase && (
                    <div style={{
                      display: 'flex', alignItems: 'center', gap: 8,
                      padding: '14px 4px 6px',
                      borderTop: i === 0 ? 'none' : `1px solid ${C.border}`,
                      marginTop: i === 0 ? 0 : 4,
                    }}>
                      <span style={{ fontSize: T.caption, fontWeight: FW.heavy, letterSpacing: '0.16em', textTransform: 'uppercase', color: steelTopROS }}>
                        {PHASE_LABEL[phase]}
                      </span>
                    </div>
                  )}
                  <div onClick={() => setModalId(entry.id)}
                    style={{ display: 'flex', gap: 12, padding: bp === 'mobile' ? '12px 4px' : '11px 2px', borderTop: `1px solid ${C.border}`, cursor: 'pointer', alignItems: 'flex-start' }}
                    onMouseEnter={e => { e.currentTarget.style.background = C.surface2; }}
                    onMouseLeave={e => { e.currentTarget.style.background = ''; }}
                  >
                    {/* Time gutter — the schedule's scan anchor down the left edge (board
                        2026-06-24 "organize this better"). Time LEADS; the item + who follow,
                        so a run-of-day reads like a timeline, not a wall of paragraphs. */}
                    <div style={{ width: 66, flexShrink: 0, textAlign: 'right', paddingTop: 1 }}>
                      <div style={{ fontFamily: 'monospace', fontSize: T.secondary, fontWeight: FW.bold, color: entry.time ? C.text : C.muted, letterSpacing: '-0.02em', whiteSpace: 'nowrap' }}>{entry.time ? fmtTime12(entry.time) : '—'}</div>
                      {entry.endTime && <div style={{ fontFamily: 'monospace', fontSize: T.caption, color: C.muted, whiteSpace: 'nowrap', marginTop: 1 }}>{fmtTime12(entry.endTime)}</div>}
                    </div>
                    <div style={{ width: 3, borderRadius: 99, background: typeColor, alignSelf: 'stretch', flexShrink: 0 }} />
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ fontWeight: FW.semibold, fontSize: T.body, minWidth: 0, lineHeight: 1.35, overflowWrap: 'anywhere' }}>{entry.segment || <em style={{ color: C.muted, fontWeight: FW.regular }}>Untitled segment</em>}</div>
                      <div style={{ display: 'flex', gap: 8, marginTop: 4, flexWrap: 'wrap', alignItems: 'center' }}>
                        {/* UX-SAAS — a host doesn't get "event/prep/vendor" ops tags, and
                            "Host" on every row (they're the host) is noise. Show only a
                            real helper's name. Planner keeps the full taxonomy. */}
                        {!isHost && <span style={s.pill(typeColor)}>{entry.type}</span>}
                        {entry.aiDraft && <span style={{ fontSize: T.caption, fontWeight: FW.bold, color: C.muted, letterSpacing: '0.04em' }}>AI DRAFT</span>}
                        {entry.location && <span style={{ fontSize: T.secondary, color: C.muted }}>{entry.location}</span>}
                        {entry.owner && !(isHost && /^(host|you)$/i.test(String(entry.owner).trim())) && <span style={{ fontSize: T.secondary, color: C.muted }}>{entry.owner}</span>}
                        {entry.type === 'vendor' && entry.confirmed && <span style={{ fontSize: T.secondary, color: C.success, fontWeight: FW.semibold }}>✓ Confirmed</span>}
                        {entry.type === 'vendor' && !entry.confirmed && <span style={{ fontSize: T.secondary, color: C.muted }}>⚠ Unconfirmed</span>}
                      </div>
                    </div>
                    <span style={{ color: C.muted, fontSize: T.body, flexShrink: 0, marginTop: 2 }}>›</span>
                  </div>
                  {gapLabel && i < sorted.length - 1 && (
                    <div style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '4px 12px', color: C.muted, fontSize: T.caption }}>
                      <div style={{ flex: 1, height: 1, background: C.border }} />
                      <span>{gapLabel}</span>
                      <div style={{ flex: 1, height: 1, background: C.border }} />
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        ) : (
          <>
            {/* Header */}
            <div style={{ display: 'grid', gridTemplateColumns: '64px 3px 1fr 80px 130px 1fr 30px 32px', gap: '8px', marginBottom: 8, padding: '0 0 8px', borderBottom: `1px solid ${C.border}` }}>
              {['Time', '', 'Item / Location', 'Type', 'In charge', 'Notes', '✓', ''].map((h, i) => (
                <div key={i} style={{ fontSize: T.secondary, fontWeight: FW.semibold, color: C.muted, textTransform: 'uppercase', letterSpacing: '0.08em' }}>{h}</div>
              ))}
            </div>

            {/* "In charge" dropdown options — the people who can own a run-of-show
                item: standard day-of roles + each vendor (and their on-site contact).
                A datalist keeps it a dropdown while still allowing a custom name. */}

            {sorted.length === 0 && (
              <div style={{ textAlign: 'center', padding: '36px 16px', color: C.muted }}>
                <div style={{ fontSize: T.body, fontWeight: FW.semibold, color: C.text, marginBottom: 6 }}>No schedule yet</div>
                <div style={{ fontSize: T.secondary, lineHeight: 1.5, maxWidth: 420, margin: '0 auto' }}>
                  Press <strong style={{ color: C.text }}>+ Add</strong> to build it item by item{hasVendors ? <>, or <strong style={{ color: C.text }}>Add vendor arrivals</strong> to pull in confirmed vendor arrivals as a starting point</> : ''}.
                </div>
              </div>
            )}

            {sorted.map((entry, i) => {
              const typeColor = rosCLR[entry.type] || C.muted;
              const next      = sorted[i + 1];
              const gapMin    = (entry.time && next?.time) ? parseMin(next.time) - parseMin(entry.time) : null;
              const gapLabel  = gapMin !== null && gapMin > 0 ? fmtDur(gapMin) : null;
              const isVendor  = entry.type === 'vendor';
              const phase     = phaseOf(entry);
              const prevPhase = i > 0 ? phaseOf(sorted[i - 1]) : null;
              const showPhase = phase !== prevPhase;
              const steelTopROS = C.accentTopGrad || C.accent;

              return (
                <Fragment key={entry.id}>
                  {showPhase && (
                    <div style={{
                      gridColumn: '1 / -1',
                      display: 'flex', alignItems: 'center', gap: 10,
                      marginTop: i === 0 ? 4 : 16,
                      marginBottom: 6,
                      paddingBottom: 4,
                      borderBottom: `1px solid ${C.border}`,
                    }}>
                      <span style={{ fontSize: T.caption, fontWeight: FW.heavy, letterSpacing: '0.16em', textTransform: 'uppercase', color: steelTopROS }}>
                        {PHASE_LABEL[phase]}
                      </span>
                      <span style={{ fontSize: T.secondary, color: C.muted }}>
                        {sorted.filter(e => phaseOf(e) === phase).length} segment{sorted.filter(e => phaseOf(e) === phase).length === 1 ? '' : 's'}
                      </span>
                    </div>
                  )}
                  <div>
                  <div style={{ display: 'grid', gridTemplateColumns: '64px 3px 2.2fr 80px 130px 1fr 30px 30px 32px', gap: '8px', alignItems: 'start', marginBottom: gapLabel ? 4 : 6 }}>
                    <div>
                      <input style={{ ...qInput, padding: '6px 8px', textAlign: 'center', fontVariantNumeric: 'tabular-nums' }} onFocus={qFocus} onBlur={qBlur} value={entry.time} placeholder="09:00" onChange={e => upd(entry.id, 'time', e.target.value)} />
                      {entry.aiDraft && <div title="AI-suggested — confirm the time" style={{ fontSize: T.eyebrow, fontWeight: FW.heavy, color: C.muted, textAlign: 'center', marginTop: 3, letterSpacing: '0.06em' }}>AI DRAFT</div>}
                    </div>
                    <div style={{ width: 3, minHeight: 36, borderRadius: 99, background: typeColor, marginTop: 4 }} />
                    <div>
                      {/* Owner directive 2026-06-24: a run-of-day item must read in FULL. An
                          <input> can't wrap (it clips long text in the grid's ITEM column),
                          so this is a WRAPPING auto-grow textarea — every word stays visible. */}
                      <textarea rows={1} style={{ ...qInput, fontSize: T.body, fontWeight: FW.semibold, resize: 'none', overflow: 'hidden', lineHeight: 1.3 }}
                        ref={el => { if (el) { el.style.height = 'auto'; el.style.height = el.scrollHeight + 'px'; } }}
                        onFocus={qFocus} onBlur={qBlur} value={entry.segment} placeholder="What's happening"
                        onChange={e => { upd(entry.id, 'segment', e.target.value); e.target.style.height = 'auto'; e.target.style.height = e.target.scrollHeight + 'px'; }} />
                      <input style={{ ...qInput, fontSize: T.secondary, marginTop: 4, color: C.muted, padding: '4px 8px' }} onFocus={qFocus} onBlur={qBlur} value={entry.location || ''} placeholder="Location" onChange={e => upd(entry.id, 'location', e.target.value)} />
                    </div>
                    <select style={{ ...qInput, padding: '6px 8px', color: typeColor }} onFocus={qFocus} onBlur={qBlur} value={entry.type} onChange={e => upd(entry.id, 'type', e.target.value)}>
                      <option value="event">Event</option>
                      <option value="vendor">Vendor</option>
                      <option value="prep">Prep</option>
                    </select>
                    <OwnerSelect value={entry.owner} options={ownerOptions} onChange={v => upd(entry.id, 'owner', v)} style={qInput} />
                    <input style={qInput} onFocus={qFocus} onBlur={qBlur} value={entry.notes} placeholder="Notes / cues" onChange={e => upd(entry.id, 'notes', e.target.value)} />
                    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', paddingTop: 6 }}>
                      {isVendor ? (
                        <input
                          type="checkbox"
                          checked={entry.confirmed || false}
                          onChange={e => upd(entry.id, 'confirmed', e.target.checked)}
                          title="Vendor confirmed"
                          style={{ accentColor: C.success, cursor: 'pointer', width: 14, height: 14 }}
                        />
                      ) : <div />}
                    </div>
                    {/* #6 — open the full editable side panel (full title + steps/sub-tasks). */}
                    <button aria-label="Open steps & details" title="Steps & details" onClick={() => setModalId(entry.id)}
                      style={{ ...s.btn('ghost'), padding: '6px 6px', fontSize: T.secondary, position: 'relative', color: (Array.isArray(entry.subtasks) && entry.subtasks.length) ? (C.accentTopGrad || C.accent) : C.muted }}>
                      ⤢{Array.isArray(entry.subtasks) && entry.subtasks.length > 0 && <span style={{ position: 'absolute', top: -3, right: -3, fontSize: T.eyebrow, fontWeight: FW.heavy, background: C.accent, color: '#fff', borderRadius: 99, padding: '0 3px', lineHeight: 1.4 }}>{entry.subtasks.filter((x) => x.done).length}/{entry.subtasks.length}</span>}
                    </button>
                    <button aria-label="Remove" style={{ ...s.btn('danger'), padding: '6px 8px' }} onClick={() => del(entry.id)}>✕</button>
                  </div>
                  {gapLabel && i < sorted.length - 1 && (
                    <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 6, paddingLeft: 72 }}>
                      <div style={{ flex: 1, height: 1, background: C.border }} />
                      <span style={{ fontSize: T.caption, color: C.muted, whiteSpace: 'nowrap' }}>{gapLabel}</span>
                      <div style={{ flex: 1, height: 1, background: C.border }} />
                    </div>
                  )}
                  </div>
                  {i < sorted.length - 1 && gapMin !== null && gapMin <= 0 && (
                    <div style={{ display: 'flex', alignItems: 'center', gap: 6, padding: '2px 12px', marginBottom: 4, color: C.danger, fontSize: T.secondary, fontWeight: FW.semibold }}>
                      <span style={{ width: 6, height: 6, borderRadius: '50%', background: C.danger, display: 'inline-block', flexShrink: 0 }} />
                      {gapMin === 0 ? 'Same time as next — possible conflict' : 'Time overlap — check order'}
                    </div>
                  )}
                </Fragment>
              );
            })}
          </>
        )}
      </CollapsibleCard>

      {/* Emergency contacts */}
      {emergencyContacts.length > 0 && (
        <div style={s.card}>
          <div style={s.cardTitle}>Day-of Roster · load-in order &amp; contacts</div>
          <table style={s.table}>
            <thead>
              <tr>{['Vendor', 'Load-in', 'Arrives', 'On-site phone', 'COI', 'Status'].map(h => <th key={h} style={s.th}>{h}</th>)}</tr>
            </thead>
            <tbody>
              {emergencyContacts.map(v => {
                const coi = coiDot(v);
                return (
                <tr key={v.id}>
                  <td style={{ ...s.td, fontWeight: FW.medium }}>{v.name}{v.onSiteContactName ? <span style={{ color: C.muted, fontWeight: FW.regular }}> · {v.onSiteContactName}</span> : null}</td>
                  {/* Load-in order — the sequence/dock the venue runs on. */}
                  <td style={{ ...s.td, color: v.loadInOrder ? C.text : C.muted, fontSize: T.caption }}>{v.loadInOrder || '—'}</td>
                  <td style={{ ...s.td, color: C.muted, fontSize: T.caption }}>{v.arrivalTime || '—'}</td>
                  {/* On-site cell, flagged if it falls back to the office line. */}
                  <td style={{ ...s.td, fontFamily: 'monospace', color: v.onSitePhone ? C.accent2 : C.muted }}>{dayOfPhone(v)}{v.onSitePhone ? <span style={{ color: C.success, fontSize: T.caption, marginLeft: 6, fontFamily: 'inherit' }}>on-site</span> : <span style={{ color: C.muted, fontSize: T.caption, marginLeft: 6, fontFamily: 'inherit' }}>office</span>}</td>
                  {/* COI gate dot — venue can refuse entry at a glance. */}
                  <td style={s.td}>{coi ? <span title={coi.t} style={{ display: 'inline-flex', alignItems: 'center', gap: 5, fontSize: T.secondary, color: coi.c }}><span style={{ width: 8, height: 8, borderRadius: '50%', background: coi.c, display: 'inline-block', flexShrink: 0 }} />{coi.c === C.success ? 'Valid' : coi.c === C.danger ? 'Missing' : 'Unverified'}</span> : <span style={{ color: C.muted, fontSize: T.secondary }}>—</span>}</td>
                  <td style={s.td}><span style={s.pill(stageCLR[v.status] || C.muted)}>{v.status}</span></td>
                </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

// ─── Calendar View ────────────────────────────────────────────────────────────

// Sprint 57: Build a minimal RFC-5545 .ics file from the event's calendar
// items (event day + RoS schedule + payment due dates + timeline tasks).
// No backend, no sync — single-click download the planner can drag into
// Google Calendar / Apple Calendar / Outlook. Closes the "Calendar sync"
// gap from the integration inventory at the lowest possible cost.
function buildICS({ eventDate, eventName, vendors, ros, timeline }) {
  const pad = (n) => String(n).padStart(2, '0');
  // All-day format YYYYMMDD; date-time format YYYYMMDDTHHMMSS
  const fmtDate = (iso) => iso.replace(/-/g, '');
  const fmtDateTime = (iso, time) => {
    const [h, m] = (time || '00:00').split(':');
    return `${fmtDate(iso)}T${pad(h)}${pad(m)}00`;
  };
  const escapeText = (s) => String(s || '').replace(/\\/g, '\\\\').replace(/,/g, '\\,').replace(/;/g, '\\;').replace(/\n/g, '\\n');
  const nowStamp = () => {
    const d = new Date();
    return `${d.getUTCFullYear()}${pad(d.getUTCMonth() + 1)}${pad(d.getUTCDate())}T${pad(d.getUTCHours())}${pad(d.getUTCMinutes())}${pad(d.getUTCSeconds())}Z`;
  };
  const lines = [
    'BEGIN:VCALENDAR',
    'VERSION:2.0',
    'PRODID:-//NGW Event Boss//Event Calendar//EN',
    'CALSCALE:GREGORIAN',
  ];
  const push = (uid, summary, start, end, allDay, description) => {
    lines.push('BEGIN:VEVENT');
    lines.push(`UID:${uid}@ngw-events`);
    lines.push(`DTSTAMP:${nowStamp()}`);
    if (allDay) {
      lines.push(`DTSTART;VALUE=DATE:${start}`);
      lines.push(`DTEND;VALUE=DATE:${end || start}`);
    } else {
      lines.push(`DTSTART:${start}`);
      lines.push(`DTEND:${end || start}`);
    }
    lines.push(`SUMMARY:${escapeText(summary)}`);
    if (description) lines.push(`DESCRIPTION:${escapeText(description)}`);
    lines.push('END:VEVENT');
  };
  // Event day (all day)
  if (eventDate) {
    push(`event-day-${eventDate}`, eventName || 'Event Day', fmtDate(eventDate), fmtDate(eventDate), true, `Event day for ${eventName || 'this event'}.`);
  }
  // Planning phase milestones (all-day) — parity with the Runway view so the
  // exported calendar carries the same countdown the planner sees in-app.
  if (eventDate && Array.isArray(timeline)) {
    const phaseGroups = {};
    timeline.forEach(task => {
      if (!(task.week in PHASE_OFFSET)) return;
      const d = new Date(eventDate + 'T00:00:00');
      d.setDate(d.getDate() + PHASE_OFFSET[task.week]);
      const ds = `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
      if (!phaseGroups[ds]) phaseGroups[ds] = { phase: task.week, total: 0, done: 0 };
      phaseGroups[ds].total++; if (task.done) phaseGroups[ds].done++;
    });
    Object.entries(phaseGroups).forEach(([ds, g]) => {
      push(`phase-${String(g.phase).replace(/\s+/g, '-')}-${ds}`, `${g.phase}: ${g.done}/${g.total} planning tasks`, fmtDate(ds), fmtDate(ds), true, `Planning checkpoint — ${g.phase}.`);
    });
  }
  // Run-of-show entries (time-specific on event day)
  (ros || []).forEach((r, i) => {
    if (!eventDate || !r.time) return;
    const start = fmtDateTime(eventDate, r.time);
    // 30-minute default duration if no explicit end
    const [hh, mm] = r.time.split(':').map(Number);
    const endDate = new Date(`${eventDate}T${pad(hh)}:${pad(mm)}:00`);
    endDate.setMinutes(endDate.getMinutes() + 30);
    const endIso = `${endDate.getFullYear()}-${pad(endDate.getMonth() + 1)}-${pad(endDate.getDate())}`;
    const endTime = `${pad(endDate.getHours())}:${pad(endDate.getMinutes())}`;
    push(`ros-${i}-${eventDate}`, `${r.segment || r.title || r.activity || 'Schedule item'}`, start, fmtDateTime(endIso, endTime), false, [r.location && `Location: ${r.location}`, r.owner && `Owner: ${r.owner}`, r.vendorName && `Vendor: ${r.vendorName}`, r.notes].filter(Boolean).join('\n'));
  });
  // Vendor payment due dates (all-day reminders)
  (vendors || []).forEach((v) => {
    if (!v.payDueDate || v.balancePaid) return;
    push(`pay-${v.id || v.name}-${v.payDueDate}`, `Payment due: ${v.name || 'vendor'}`, fmtDate(v.payDueDate), fmtDate(v.payDueDate), true, v.cost ? `Balance owed: $${v.cost.toLocaleString()}` : '');
  });
  // Vendor arrival times (event-day time-specific reminders)
  (vendors || []).forEach((v, i) => {
    if (!eventDate || !v.arrivalTime) return;
    const start = fmtDateTime(eventDate, v.arrivalTime);
    const [hh, mm] = v.arrivalTime.split(':').map(Number);
    const endDate = new Date(`${eventDate}T${pad(hh)}:${pad(mm)}:00`);
    endDate.setMinutes(endDate.getMinutes() + 30);
    const endIso = `${endDate.getFullYear()}-${pad(endDate.getMonth() + 1)}-${pad(endDate.getDate())}`;
    const endTime = `${pad(endDate.getHours())}:${pad(endDate.getMinutes())}`;
    push(`arrival-${v.id || i}-${eventDate}`, `${v.name || 'Vendor'} arrives`, start, fmtDateTime(endIso, endTime), false, v.category ? `${v.category} — ${v.contactName || v.contact || ''}` : '');
  });
  lines.push('END:VCALENDAR');
  return lines.join('\r\n');
}

function downloadICS(filename, ics) {
  const blob = new Blob([ics], { type: 'text/calendar;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 0);
}

function CalendarView({ timeline, vendors, eventDate, ros, onTabChange, eventName }) {
  const C        = useT();
  const s        = makeS(C);
  const bp       = useContext(BpCtx);
  const isMobile = bp === 'mobile';
  const rosCLR   = ROS_CLR(C);
  const eventMonth = eventDate ? new Date(eventDate + 'T00:00:00') : null;
  const [viewDate,    setViewDate]    = useState(() => new Date(getToday().getFullYear(), getToday().getMonth(), 1));
  const [selectedDay, setSelectedDay] = useState(() => eventDate || today8601());
  // Calendar Rework (board memory): a MONTH GRID is the wrong primitive for a
  // SINGLE event — one date + a runway of deadlines = a ~90%-empty grid. Default
  // to the RUNWAY: a vertical countdown of the event's dated items (task phases,
  // payment due dates, vendor arrivals, event day) — what's due + when, no empty
  // cells to page through. Month/Day stay one tap away via the toggle.
  const [calView,     setCalView]     = useState('list'); // 'list' (runway) | 'month' | 'day'

  const year  = viewDate.getFullYear();
  const month = viewDate.getMonth();

  // Build items map + phase detail map
  const items      = {};
  const phaseByDay = {}; // dateStr → { phase, tasks, date, color }
  const add = (dateStr, item) => { if (dateStr) { items[dateStr] = items[dateStr] || []; items[dateStr].push(item); } };

  if (eventDate) add(eventDate, { label: 'Event Day', color: C.accent, type: 'event' });

  const phaseGroups = {};
  timeline.forEach(task => {
    if (!(task.week in PHASE_OFFSET) || !eventDate) return;
    const d = new Date(eventDate + 'T00:00:00');
    d.setDate(d.getDate() + PHASE_OFFSET[task.week]);
    const ds = d.toISOString().slice(0, 10);
    if (!phaseGroups[ds]) phaseGroups[ds] = { phase: task.week, tasks: [], date: d };
    phaseGroups[ds].tasks.push(task);
  });
  Object.values(phaseGroups).forEach(({ phase, tasks, date }) => {
    const ds      = date.toISOString().slice(0, 10);
    const done    = tasks.filter(t => t.done).length;
    const overdue = tasks.filter(t => !t.done && date <= getToday()).length;
    const total   = tasks.length;
    const color   = overdue > 0 ? C.danger : done === total ? C.success : C.accent2;
    const label   = done === total ? `${phase}: all done`
      : overdue > 0 ? `${phase}: ${overdue} overdue`
      : `${phase}: ${done}/${total} done`;
    add(ds, { label, color, type: 'task', title: phase });
    phaseByDay[ds] = { phase, tasks, date, color };
  });

  vendors.forEach(v => {
    if (v.payDueDate && !v.balancePaid && v.name)
      add(v.payDueDate, { label: `${v.name} payment`, color: C.muted, type: 'payment' });
  });

  const arrivingVendors = eventDate
    ? [...vendors.filter(v => v.arrivalTime && v.name && v.status === 'Confirmed')]
        .sort((a, b) => a.arrivalTime.localeCompare(b.arrivalTime))
    : [];
  if (arrivingVendors.length > 0) {
    add(eventDate, {
      label: `${arrivingVendors.length} vendor${arrivingVendors.length > 1 ? 's' : ''} arriving from ${arrivingVendors[0].arrivalTime}`,
      color: C.accent2, type: 'vendor',
      title: arrivingVendors.map(v => `${v.name} @ ${v.arrivalTime}`).join('\n'),
    });
  }

  // Grid
  const firstDay    = new Date(year, month, 1);
  const lastDay     = new Date(year, month + 1, 0);
  const startOffset = firstDay.getDay();
  const totalCells  = Math.ceil((startOffset + lastDay.getDate()) / 7) * 7;

  const cells = Array.from({ length: totalCells }, (_, i) => {
    const dayNum = i - startOffset + 1;
    if (dayNum < 1 || dayNum > lastDay.getDate()) return null;
    const d  = new Date(year, month, dayNum);
    const ds = d.toISOString().slice(0, 10);
    return { dayNum, ds, isToday: ds === today8601(), isEvent: ds === eventDate, dayItems: items[ds] || [] };
  });

  const monthLabel    = firstDay.toLocaleDateString('en-US', { month: 'long', year: 'numeric' });
  const isEventMonth  = eventMonth && eventMonth.getFullYear() === year && eventMonth.getMonth() === month;
  const goToEvent     = () => eventDate && setViewDate(new Date(new Date(eventDate + 'T00:00:00').getFullYear(), new Date(eventDate + 'T00:00:00').getMonth(), 1));
  const goToToday     = () => { setViewDate(new Date(getToday().getFullYear(), getToday().getMonth(), 1)); setSelectedDay(today8601()); };

  const thisMonthItems = cells.filter(Boolean).flatMap(c => c.dayItems);
  const criticalCount  = thisMonthItems.filter(i => i.color === C.danger).length;
  const paymentCount   = thisMonthItems.filter(i => i.type === 'payment').length;

  // Day view data — all events on the selected day with time context
  const selIsEventDay = selectedDay === eventDate;
  const dayRosItems   = selIsEventDay
    ? [...(ros || [])].sort((a, b) => (a.time || '').localeCompare(b.time || ''))
    : [];
  const dayVendors    = selIsEventDay
    ? [...vendors.filter(v => v.arrivalTime && v.name && v.status === 'Confirmed')]
        .sort((a, b) => a.arrivalTime.localeCompare(b.arrivalTime))
    : [];
  const dayPayments   = vendors.filter(v => v.payDueDate === selectedDay && !v.balancePaid);
  const dayPhase      = phaseByDay[selectedDay];

  return (
    <div>
      {/* Nav bar */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16, flexWrap: 'wrap', gap: 10 }}>
        <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
          {calView === 'list' ? (
            <span style={{ fontSize: T.section, fontWeight: FW.bold, letterSpacing: '-0.01em' }}>Runway · what's ahead</span>
          ) : calView === 'month' ? (
            <>
              <button aria-label="Previous month" style={{ ...s.btn(), minWidth: 44, minHeight: 40, fontSize: T.body, lineHeight: 1 }} onClick={() => setViewDate(new Date(year, month - 1, 1))}>←</button>
              <span style={{ fontSize: T.body, fontWeight: FW.bold, minWidth: 160, textAlign: 'center' }}>{monthLabel}</span>
              <button aria-label="Next month" style={{ ...s.btn(), minWidth: 44, minHeight: 40, fontSize: T.body, lineHeight: 1 }} onClick={() => setViewDate(new Date(year, month + 1, 1))}>→</button>
            </>
          ) : (
            <>
              <button style={s.btn()} onClick={() => {
                const d = new Date(selectedDay + 'T00:00:00');
                d.setDate(d.getDate() - 1);
                setSelectedDay(d.toISOString().slice(0, 10));
              }}>←</button>
              <span style={{ fontSize: T.body, fontWeight: FW.bold, minWidth: 200, textAlign: 'center' }}>
                {new Date(selectedDay + 'T00:00:00').toLocaleDateString('en-US', { weekday: 'short', month: 'long', day: 'numeric' })}
              </span>
              <button style={s.btn()} onClick={() => {
                const d = new Date(selectedDay + 'T00:00:00');
                d.setDate(d.getDate() + 1);
                setSelectedDay(d.toISOString().slice(0, 10));
              }}>→</button>
            </>
          )}
        </div>
        <div style={{ display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap' }}>
          {criticalCount > 0 && <span style={s.pill(C.danger)}>{criticalCount} overdue</span>}
          {paymentCount > 0 && <span style={s.pill(C.muted)}>{paymentCount} payment{paymentCount > 1 ? 's' : ''} due</span>}
          {calView === 'month' && isEventMonth && <span style={s.pill(C.accent)}>Event this month</span>}
          {calView === 'month' && eventDate && !isEventMonth && <button style={{ ...s.btn('ghost'), fontSize: T.caption, color: C.accent }} onClick={goToEvent}>Jump to event →</button>}
          <button style={{ ...s.btn('ghost'), fontSize: T.caption, color: C.muted }} onClick={goToToday}>Today</button>
          {eventDate && <button style={{ ...s.btn('ghost'), fontSize: T.caption, color: C.accent }} onClick={() => { setSelectedDay(eventDate); setCalView('day'); }}>Event Day</button>}
          {/* Sprint 57: .ics export — single-click download of event day, RoS,
              arrivals, and payment-due dates as a calendar file. Drag into
              Google Cal / Apple Cal / Outlook. */}
          {eventDate && (
            <button
              style={{ ...s.btn('ghost'), fontSize: T.caption, color: C.muted }}
              onClick={() => {
                const ics = buildICS({ eventDate, eventName, vendors, ros, timeline });
                const safeName = (eventName || 'event').replace(/[^a-z0-9]+/gi, '-').toLowerCase();
                downloadICS(`${safeName}.ics`, ics);
              }}
              title="Download .ics for Google / Apple / Outlook calendar"
              aria-label="Download calendar as .ics file"
            >
              .ics ↓
            </button>
          )}
          {/* View toggle */}
          <div style={{ display: 'flex', borderRadius: 8, overflow: 'hidden', border: `1px solid ${C.border}` }}>
            {['list', 'month', 'day'].map(v => (
              <button key={v} onClick={() => setCalView(v)} style={{
                padding: '5px 12px', border: 'none', cursor: 'pointer', fontSize: T.caption, fontWeight: FW.semibold,
                background: calView === v ? C.accent : 'transparent',
                color: calView === v ? '#fff' : C.muted,
                transition: 'all 0.15s',
              }}>{v === 'list' ? 'Runway' : v === 'month' ? 'Month' : 'Day'}</button>
            ))}
          </div>
        </div>
      </div>

      {calView === 'list' ? (
        // ── Runway: vertical countdown of every dated item ──────────────────
        (() => {
          const runwayDays = Object.keys(items).sort().map(ds => ({ ds, date: new Date(ds + 'T00:00:00'), dayItems: items[ds] }));
          if (runwayDays.length === 0) {
            return (
              <div style={{ padding: '28px 6px', fontSize: T.secondary, color: C.muted, lineHeight: 1.6, fontStyle: 'italic' }}>
                Nothing dated yet. Task phases, payment due dates, vendor arrivals, and the event day appear here as a countdown.
              </div>
            );
          }
          return (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
              {runwayDays.map(({ ds, date, dayItems }) => {
                const diff    = Math.round((date - getToday()) / 86400000);
                const isEvent = ds === eventDate;
                const isPast  = diff < 0;
                const hasCrit = dayItems.some(i => i.color === C.danger);
                const rel = isEvent ? 'Event day' : diff === 0 ? 'Today' : isPast ? `${Math.abs(diff)}d ago` : `in ${diff}d`;
                const relColor = isEvent ? C.accent : (isPast && hasCrit) ? C.danger : diff >= 0 && diff <= 7 ? C.warn : C.muted;
                return (
                  <button key={ds} onClick={() => { setSelectedDay(ds); setCalView('day'); }} style={{
                    display: 'flex', gap: 14, alignItems: 'center', width: '100%', textAlign: 'left', cursor: 'pointer',
                    padding: '12px 14px', borderRadius: 10,
                    background: isEvent ? C.accent + '12' : C.surface,
                    border: `1px solid ${isEvent ? C.accent + '55' : hasCrit ? C.danger + '44' : C.border}`,
                  }}>
                    <div style={{ flexShrink: 0, width: 84 }}>
                      <div style={{ fontSize: T.secondary, fontWeight: FW.bold, color: C.text }}>{date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}</div>
                      <div style={{ fontSize: T.caption, fontWeight: FW.bold, color: relColor, textTransform: 'uppercase', letterSpacing: '0.04em', marginTop: 1 }}>{rel}</div>
                    </div>
                    <div style={{ flex: 1, minWidth: 0, display: 'flex', flexDirection: 'column', gap: 5 }}>
                      {dayItems.map((item, j) => (
                        <div key={j} style={{ display: 'flex', alignItems: 'center', gap: 8 }} title={item.title || item.label}>
                          <span style={{ width: 6, height: 6, borderRadius: '50%', background: item.color, flexShrink: 0 }} />
                          <span style={{ fontSize: T.secondary, color: C.text, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{item.label}</span>
                        </div>
                      ))}
                    </div>
                    <span style={{ color: C.muted, fontSize: T.body, flexShrink: 0 }}>›</span>
                  </button>
                );
              })}
            </div>
          );
        })()
      ) : calView === 'month' ? (
        <>
          {/* Day-of-week headers */}
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: 2, marginBottom: 2 }}>
            {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(d => (
              <div key={d} style={{ textAlign: 'center', fontSize: T.caption, fontWeight: FW.semibold, color: C.muted, padding: '4px 0', letterSpacing: '0.06em', userSelect: 'none' }}>{d}</div>
            ))}
          </div>

          {/* Calendar grid */}
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: 2 }}>
            {cells.map((cell, i) => {
              if (!cell) return <div key={`empty-${i}`} style={{ minHeight: 80, background: C.bg + '88', borderRadius: 6 }} />;
              const { dayNum, ds, isToday, isEvent, dayItems } = cell;
              const isSelected  = ds === selectedDay;
              const hasCritical = dayItems.some(it => it.color === C.danger);
              return (
                <div role="button" tabIndex={0} onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); e.currentTarget.click(); } }} key={ds} onClick={() => { setSelectedDay(ds); setCalView('day'); }} style={{
                  minHeight: 80, padding: '6px 6px 4px', borderRadius: 6, cursor: 'pointer',
                  background: isEvent ? C.accent + '1a' : isSelected ? C.accent2 + '12' : C.surface,
                  border: `1px solid ${isSelected ? C.accent2 + 'aa' : isEvent ? C.accent + '66' : isToday ? C.accent2 + '55' : hasCritical ? C.danger + '44' : C.border}`,
                  boxShadow: isSelected ? `0 0 0 1px ${C.accent2 + '33'}` : isEvent ? `0 0 0 1px ${C.accent + '33'}` : 'none',
                  userSelect: 'none', transition: 'background 0.1s, border-color 0.1s',
                }}>
                  <div style={{ fontSize: T.caption, fontWeight: isToday || isEvent || isSelected ? 700 : 400, color: isSelected ? C.accent2 : isEvent ? C.accent : isToday ? C.accent2 : C.muted, marginBottom: 3, display: 'flex', alignItems: 'center', gap: 3 }}>
                    {dayNum}
                    {isToday && <span style={{ fontSize: T.eyebrow, background: C.accent2, color: C.bg, borderRadius: 3, padding: '0 3px', fontWeight: FW.bold }}>NOW</span>}
                    {isEvent && <span style={{ fontSize: T.eyebrow, background: C.accent, color: C.bg, borderRadius: 3, padding: '0 3px', fontWeight: FW.bold }}>EVENT</span>}
                  </div>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                    {dayItems.slice(0, 3).map((item, j) => (
                      <div key={j} title={item.title || item.label} style={{
                        fontSize: T.eyebrow, fontWeight: FW.medium, borderRadius: 3, padding: '1px 4px',
                        background: item.color + '22', color: item.color,
                        overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', lineHeight: 1.4,
                      }}>
                        {item.label}
                      </div>
                    ))}
                    {dayItems.length > 3 && <div style={{ fontSize: T.eyebrow, color: C.muted, paddingLeft: 2 }}>+{dayItems.length - 3} more</div>}
                  </div>
                </div>
              );
            })}
          </div>
        </>
      ) : (
        /* ── Day View ── */
        <div style={{ ...metalEdge(C), borderRadius: 12, overflow: 'hidden' }}>
          {/* Day header */}
          <div style={{ padding: '14px 20px', borderBottom: `1px solid ${C.border}`, display: 'flex', alignItems: 'center', gap: 10, flexWrap: 'wrap' }}>
            <div style={{ fontSize: T.section, fontWeight: FW.bold, letterSpacing: '-0.01em' }}>
              {new Date(selectedDay + 'T00:00:00').toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' })}
            </div>
            {selectedDay === today8601() && <span style={s.pill(C.accent2)}>Today</span>}
            {selectedDay === eventDate && <span style={s.pill(C.accent)}>Event Day</span>}
            {dayPayments.length > 0 && <span style={s.pill(C.muted)}>{dayPayments.length} payment{dayPayments.length > 1 ? 's' : ''} due</span>}
          </div>

          {/* All-day items (phase tasks, payments) */}
          {(dayPhase || dayPayments.length > 0) && (
            <div style={{ padding: '12px 20px', borderBottom: `1px solid ${C.border}`, background: C.surface2 + '88', display: 'flex', flexDirection: 'column', gap: 8 }}>
              {dayPhase && (
                <div>
                  <div style={{ fontSize: T.caption, fontWeight: FW.bold, textTransform: 'uppercase', letterSpacing: '0.08em', color: dayPhase.color, marginBottom: 6, display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                    <span>Planning Milestone — {dayPhase.phase}</span>
                    {onTabChange && (
                      <button onClick={() => onTabChange('Planning Tasks')} style={{ fontSize: T.caption, color: C.accent, background: 'none', border: 'none', cursor: 'pointer', padding: 0, fontWeight: FW.semibold }}>
                        → Planning Tasks
                      </button>
                    )}
                  </div>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
                    {dayPhase.tasks.map(t => {
                      const ov = dayPhase.date <= getToday() && !t.done;
                      return (
                        <div key={t.id} style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: T.secondary }}>
                          <span style={{ color: t.done ? C.success : ov ? C.danger : C.muted }}>{t.done ? '✓' : ov ? '!' : '○'}</span>
                          <span style={{ color: t.done ? C.muted : C.text, textDecoration: t.done ? 'line-through' : 'none' }}>{t.task}</span>
                          {t.owner && <span style={{ color: C.muted, marginLeft: 'auto' }}>{t.owner}</span>}
                        </div>
                      );
                    })}
                  </div>
                </div>
              )}
              {dayPayments.map(v => {
                const bal = vendorBalance(v);
                return (
                  <div key={v.id} style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '6px 10px 6px 13px', background: C.surface2, borderRadius: 6, borderLeft: `3px solid ${C.muted}` }}>
                    <span style={{ fontSize: T.caption, color: C.muted, fontWeight: FW.bold }}>💳 Payment Due</span>
                    <span style={{ fontSize: T.secondary, color: C.text, flex: 1 }}>{v.name}</span>
                    <span style={{ fontSize: T.secondary, fontWeight: FW.bold, color: C.muted }}>{fmtD(bal)}</span>
                  </div>
                );
              })}
            </div>
          )}

          {/* Time grid */}
          {(selIsEventDay && (dayRosItems.length > 0 || dayVendors.length > 0)) ? (
            <div>
              {/* Build merged time-sorted list of ROS + vendor arrivals */}
              {(() => {
                const slots = [];
                dayVendors.forEach(v => slots.push({ time: v.arrivalTime, label: `${v.name} arrival`, sub: v.category, color: C.accent2, type: 'vendor' }));
                dayRosItems.forEach(r => {
                  const clr = rosCLR[r.type] || C.muted;
                  slots.push({ time: r.time || '', label: r.segment || r.label || r.task || '—', sub: r.owner || r.type, color: clr, type: 'ros', duration: r.duration });
                });
                slots.sort((a, b) => (a.time || '').localeCompare(b.time || ''));

                const minHour = slots.length > 0 && slots[0].time
                  ? Math.max(0, Math.floor(parseMin(slots[0].time) / 60) - 1)
                  : 6;
                const maxHour = slots.length > 0 && slots[slots.length - 1].time
                  ? Math.min(24, Math.ceil(parseMin(slots[slots.length - 1].time) / 60) + 2)
                  : 22;
                const hours = Array.from({ length: maxHour - minHour }, (_, i) => minHour + i);

                return (
                  <div style={{ padding: '8px 0', maxHeight: 'min(480px, 55vh)', overflowY: 'auto' }}>
                    {hours.map(h => {
                      const hLabel = h === 0 ? '12 AM' : h < 12 ? `${h} AM` : h === 12 ? '12 PM' : `${h - 12} PM`;
                      const slotItems = slots.filter(s => {
                        if (!s.time) return false;
                        const sm = parseMin(s.time);
                        return sm >= h * 60 && sm < (h + 1) * 60;
                      });
                      return (
                        <div key={h} style={{ display: 'flex', gap: 0, minHeight: 44, borderTop: `1px solid ${C.border}33` }}>
                          <div style={{ width: 56, flexShrink: 0, padding: '10px 12px 0', fontSize: T.caption, color: C.border, textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{hLabel}</div>
                          <div style={{ flex: 1, padding: '4px 16px 4px 12px', display: 'flex', flexDirection: 'column', gap: 4 }}>
                            {slotItems.map((item, j) => (
                              <div key={j} style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '4px 10px', borderRadius: 6, background: item.color + '18', borderLeft: `3px solid ${item.color}` }}>
                                <span style={{ fontSize: T.caption, fontWeight: FW.bold, color: item.color, minWidth: 36, fontVariantNumeric: 'tabular-nums' }}>{item.time}</span>
                                <span style={{ fontSize: T.secondary, color: C.text, flex: 1 }}>{item.label}</span>
                                {item.duration && <span style={{ fontSize: T.caption, color: C.muted }}>{fmtDur(item.duration)}</span>}
                                <span style={{ fontSize: T.caption, color: item.color, textTransform: 'capitalize' }}>{item.sub}</span>
                              </div>
                            ))}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                );
              })()}
              <div style={{ padding: '8px 20px 12px', fontSize: T.caption, color: C.muted, display: 'flex', alignItems: 'center', gap: 10 }}>
                Full day-of schedule
                {onTabChange && (
                  <button onClick={() => onTabChange('Event Day Schedule')} style={{ fontSize: T.caption, color: C.accent, background: 'none', border: 'none', cursor: 'pointer', padding: 0, fontWeight: FW.semibold }}>
                    → Event Day Schedule
                  </button>
                )}
              </div>
            </div>
          ) : (
            <div style={{ padding: '24px 20px', fontSize: T.secondary, color: C.muted, fontStyle: 'italic' }}>
              {selIsEventDay ? 'No confirmed vendor arrivals or Event Day Schedule items set.' : 'No timed events on this day.'}
              {!selIsEventDay && dayPhase && ' '}
            </div>
          )}
        </div>
      )}

      {/* Legend — shown in month AND day view (PL-8): it's the color key that
          decodes the status dots, and the calendar now opens on Day on mobile. */}
      {(calView === 'month' || calView === 'day') && (
        <div style={{ display: 'flex', gap: 14, marginTop: 12, flexWrap: 'wrap' }}>
          {[
            { color: C.accent,  label: 'Event Day' },
            { color: C.success, label: 'Phase complete' },
            { color: C.accent2, label: 'Phase in progress' },
            { color: C.danger,  label: 'Overdue phase' },
            { color: C.muted,    label: 'Payment due' },
          ].map(({ color, label }) => (
            <div key={label} style={{ display: 'flex', alignItems: 'center', gap: 5 }}>
              <div style={{ width: 8, height: 8, borderRadius: 2, background: color, flexShrink: 0 }} />
              <span style={{ fontSize: T.caption, color: C.muted }}>{label}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// ─── Master Calendar ──────────────────────────────────────────────────────────

function MasterCalendarView({ events, onSelectEvent }) {
  // Sprint 60.N: removed the local Sprint 46/48 Studio Matte override —
  // master calendar now inherits the locked outer DARK theme (Mid Carbon
  // #111519 page, steel-blue accent, punched #E84850 critical).
  const _themeCtx = useContext(ThemeCtx);
  const C = _themeCtx.C;
  const _childThemeCtx = _themeCtx;
  const s      = useMemo(() => makeS(C), [C]);
  const evtCLR = useMemo(() => EVT_CLR(C), [C]);
  const rosCLR = useMemo(() => ROS_CLR(C), [C]);
  const bp     = useContext(BpCtx);
  const [viewDate,    setViewDate]    = useState(() => new Date(getToday().getFullYear(), getToday().getMonth(), 1));
  const [selectedDay, setSelectedDay] = useState(() => today8601());
  // Board L1 audit fix #4 (Calendar Rework): the calendar opened on the Week grid,
  // which lands on an empty 7-column wall of "—" whenever nothing falls in the
  // current week — the exact "90% empty grid" the rework flagged. Default to the
  // LIST/agenda view: a chronological RUNWAY of the next event days, milestones,
  // and payment due dates. Never an empty grid; always the next thing ahead.
  // Month/Week/Day remain one tap away via the toggle.
  const [calView,     setCalView]     = useState('list'); // 'month' | 'week' | 'day' | 'list'
  // B2 runway: This Week + This Month open (the operative horizon — avoids the empty
  // void the board flagged); Later folded.
  const [calBands,    setCalBands]    = useState({ week: true, month: true, later: false });

  const fmtTime12 = (t) => { if (!t) return ''; const [h, m] = t.split(':').map(Number); const ampm = h >= 12 ? 'PM' : 'AM'; const hr = h % 12 || 12; return `${hr}:${String(m || 0).padStart(2, '0')} ${ampm}`; };

  const year  = viewDate.getFullYear();
  const month = viewDate.getMonth();

  // Aggregate items across all events
  const items      = {};  // dateStr → [{label, color, type, eventId, ...}]
  const phaseStore = {};  // dateStr → [{eventId, eventName, phase, tasks, date, color}]
  const addItem = (ds, item) => { if (ds) { items[ds] = items[ds] || []; items[ds].push(item); } };

  events.forEach(ev => {
    const evColor  = evtCLR[ev.type] || C.muted;
    const evDate   = ev.date;
    if (evDate) addItem(evDate, { type: 'event', label: ev.name, color: evColor, eventId: ev.id, venue: ev.venue || '' });

    // Phase milestones per event
    const phaseGroups = {};
    (ev.timeline || []).forEach(task => {
      if (!(task.week in PHASE_OFFSET) || !evDate) return;
      const d  = new Date(evDate + 'T00:00:00');
      d.setDate(d.getDate() + PHASE_OFFSET[task.week]);
      const ds = d.toISOString().slice(0, 10);
      if (!phaseGroups[ds]) phaseGroups[ds] = { phase: task.week, tasks: [], date: d };
      phaseGroups[ds].tasks.push(task);
    });
    Object.values(phaseGroups).forEach(({ phase, tasks, date }) => {
      const ds      = date.toISOString().slice(0, 10);
      const done    = tasks.filter(t => t.done).length;
      const overdue = tasks.filter(t => !t.done && date <= getToday()).length;
      const total   = tasks.length;
      const chipColor = overdue > 0 ? C.danger : done === total ? C.success : evColor;
      const label     = `${ev.name}: ${done}/${total} done`;
      addItem(ds, { type: 'task', label, color: chipColor, eventId: ev.id, title: `${ev.name} — ${phase}` });
      phaseStore[ds] = phaseStore[ds] || [];
      phaseStore[ds].push({ eventId: ev.id, eventName: ev.name, phase, tasks, date, color: chipColor, evColor });
    });

    // Payments
    (ev.vendors || []).forEach(v => {
      if (v.payDueDate && !v.balancePaid && v.name)
        addItem(v.payDueDate, { type: 'payment', label: `${v.name}`, color: C.muted, eventId: ev.id, eventName: ev.name, vendor: v });
    });

    // Vendor arrivals chip on event day
    const arriving = (ev.vendors || []).filter(v => v.arrivalTime && v.name && v.status === 'Confirmed')
      .sort((a, b) => a.arrivalTime.localeCompare(b.arrivalTime));
    if (arriving.length > 0 && evDate)
      addItem(evDate, { type: 'vendor', label: `${arriving.length} vendor${arriving.length > 1 ? 's' : ''} arriving`, color: C.accent2, eventId: ev.id, title: arriving.map(v => `${v.name} @ ${v.arrivalTime}`).join('\n') });
  });

  // Grid
  const firstDay    = new Date(year, month, 1);
  const lastDay     = new Date(year, month + 1, 0);
  const startOffset = firstDay.getDay();
  const totalCells  = Math.ceil((startOffset + lastDay.getDate()) / 7) * 7;
  const cells = Array.from({ length: totalCells }, (_, i) => {
    const dayNum = i - startOffset + 1;
    if (dayNum < 1 || dayNum > lastDay.getDate()) return null;
    const d  = new Date(year, month, dayNum);
    const ds = d.toISOString().slice(0, 10);
    return { dayNum, ds, isToday: ds === today8601(), dayItems: items[ds] || [] };
  });

  const monthLabel     = firstDay.toLocaleDateString('en-US', { month: 'long', year: 'numeric' });
  const thisMonthItems = cells.filter(Boolean).flatMap(c => c.dayItems);
  const criticalCount  = thisMonthItems.filter(i => i.color === C.danger).length;
  const paymentCount   = thisMonthItems.filter(i => i.type === 'payment').length;
  const eventDays      = thisMonthItems.filter(i => i.type === 'event').length;
  // Sprint 48+: "Today" returns to the current view's representation of today
  // rather than forcing month view — respects whichever lens the user is in.
  const goToToday      = () => { setViewDate(new Date(getToday().getFullYear(), getToday().getMonth(), 1)); setSelectedDay(today8601()); };

  // Day detail data
  const selEventDay = events.filter(ev => ev.date === selectedDay);
  const selPhases   = phaseStore[selectedDay] || [];
  const selPayments = (items[selectedDay] || []).filter(i => i.type === 'payment');

  // Day view: time grid — merge vendor arrivals + ROS items across all events on this day
  const daySlots = [];
  selEventDay.forEach(ev => {
    const evColor = evtCLR[ev.type] || C.muted;
    (ev.vendors || []).filter(v => v.arrivalTime && v.name && v.status === 'Confirmed')
      .forEach(v => daySlots.push({ time: v.arrivalTime, label: `${v.name} arrival`, sub: `${ev.name} · ${v.category || ''}`, color: C.accent2, type: 'vendor', evId: ev.id }));
    (ev.ros || []).forEach(r => {
      const clr = rosCLR[r.type] || C.muted;
      daySlots.push({ time: r.time || '', label: r.segment || r.label || r.task || '—', sub: `${ev.name}${r.owner ? ` · ${r.owner}` : ''}`, color: clr, type: 'ros', duration: r.duration, evId: ev.id });
    });
  });
  daySlots.sort((a, b) => (a.time || '').localeCompare(b.time || ''));

  const hasTimedContent = daySlots.length > 0;

  // Day-view prev/next
  const shiftDay = (delta) => {
    const d = new Date(selectedDay + 'T00:00:00');
    d.setDate(d.getDate() + delta);
    setSelectedDay(d.toISOString().slice(0, 10));
  };

  return (
    <ThemeCtx.Provider value={_childThemeCtx}>
    <div style={{ background: C.bg, minHeight: '100%', color: C.text }}>
      {/* Board L1 audit fix #4: the full NO-GUESSWORK card was scaffolding above
          the calendar itself. Condensed to one quiet line — the legend below the
          calendar already names each chip type, so this doesn't need a hero card. */}
      <div style={{ marginBottom: 12, fontSize: T.caption, color: C.muted, lineHeight: 1.5, display: 'flex', alignItems: 'center', gap: 7, flexWrap: 'wrap' }}>
        <span aria-hidden style={{ color: C.success, fontWeight: FW.heavy }}>✓</span>
        <span><span style={{ fontWeight: FW.semibold, color: C.text }}>One calendar across every event.</span> Event days, milestones, and payment due dates — tap any to jump into the event.</span>
      </div>

      {/* Nav */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16, flexWrap: 'wrap', gap: 10 }}>
        <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
          {calView === 'month' ? (
            <>
              <button aria-label="Previous month" style={{ ...s.btn(), minWidth: 44, minHeight: 40, fontSize: T.body, lineHeight: 1 }} onClick={() => setViewDate(new Date(year, month - 1, 1))}>←</button>
              <span style={{ fontSize: T.body, fontWeight: FW.bold, minWidth: 160, textAlign: 'center' }}>{monthLabel}</span>
              <button aria-label="Next month" style={{ ...s.btn(), minWidth: 44, minHeight: 40, fontSize: T.body, lineHeight: 1 }} onClick={() => setViewDate(new Date(year, month + 1, 1))}>→</button>
            </>
          ) : calView === 'week' ? (
            <>
              <button aria-label="Previous week" style={{ ...s.btn(), minWidth: 44, minHeight: 40, fontSize: T.body, lineHeight: 1 }} onClick={() => shiftDay(-7)}>←</button>
              <span style={{ fontSize: T.body, fontWeight: FW.bold, minWidth: 220, textAlign: 'center' }}>
                {(() => {
                  const d = new Date(selectedDay + 'T00:00:00');
                  const sun = new Date(d); sun.setDate(d.getDate() - d.getDay());
                  const sat = new Date(sun); sat.setDate(sun.getDate() + 6);
                  return `${sun.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })} – ${sat.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}`;
                })()}
              </span>
              <button aria-label="Next week" style={{ ...s.btn(), minWidth: 44, minHeight: 40, fontSize: T.body, lineHeight: 1 }} onClick={() => shiftDay(7)}>→</button>
            </>
          ) : calView === 'list' ? (
            <span style={{ fontSize: T.body, fontWeight: FW.bold, minWidth: 200, textAlign: 'center' }}>
              Upcoming · all events
            </span>
          ) : (
            <>
              <button style={s.btn()} onClick={() => shiftDay(-1)}>←</button>
              <span style={{ fontSize: T.body, fontWeight: FW.bold, minWidth: 200, textAlign: 'center' }}>
                {new Date(selectedDay + 'T00:00:00').toLocaleDateString('en-US', { weekday: 'short', month: 'long', day: 'numeric' })}
              </span>
              <button style={s.btn()} onClick={() => shiftDay(1)}>→</button>
            </>
          )}
        </div>
        <div style={{ display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap' }}>
          {bp !== 'mobile' && criticalCount > 0 && <span style={s.pill(C.danger)}>{criticalCount} overdue</span>}
          {bp !== 'mobile' && paymentCount  > 0 && <span style={s.pill(C.muted)}>{paymentCount} payment{paymentCount > 1 ? 's' : ''} due</span>}
          {bp !== 'mobile' && eventDays     > 0 && <span style={s.pill(C.accent)}>{eventDays} event{eventDays > 1 ? 's' : ''} this month</span>}
          <button style={{ ...s.btn('ghost'), fontSize: T.caption, color: C.muted }} onClick={goToToday}>Today</button>
          {/* View toggle — Sprint 49: added List alongside Month / Week / Day */}
          <div style={{ display: 'flex', borderRadius: 8, overflow: 'hidden', border: `1px solid ${C.border}` }}>
            {['month', 'week', 'day', 'list'].map(v => (
              <button key={v} onClick={() => setCalView(v)} style={{
                padding: '5px 12px', border: 'none', cursor: 'pointer', fontSize: T.caption, fontWeight: FW.semibold,
                background: calView === v ? C.accent : 'transparent',
                color: calView === v ? '#fff' : C.muted,
                transition: 'all 0.15s',
              }}>{v === 'month' ? 'Month' : v === 'week' ? 'Week' : v === 'list' ? 'List' : 'Day'}</button>
            ))}
          </div>
        </div>
      </div>

      {calView === 'month' ? (
        <>
          {/* Day-of-week headers */}
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: 2, marginBottom: 2 }}>
            {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(d => (
              <div key={d} style={{ textAlign: 'center', fontSize: T.caption, fontWeight: FW.semibold, color: C.muted, padding: '4px 0', letterSpacing: '0.06em', userSelect: 'none' }}>{d}</div>
            ))}
          </div>

          {/* Grid */}
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: 2 }}>
            {cells.map((cell, i) => {
              if (!cell) return <div key={`empty-${i}`} style={{ minHeight: 80, background: C.bg + '88', borderRadius: 6 }} />;
              const { dayNum, ds, isToday, dayItems } = cell;
              const isSelected  = ds === selectedDay;
              const hasCritical = dayItems.some(it => it.color === C.danger);
              const isEventDay  = dayItems.some(it => it.type === 'event');
              return (
                <div role="button" tabIndex={0} onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); e.currentTarget.click(); } }} key={ds} onClick={() => { setSelectedDay(ds); setCalView('day'); }} style={{
                  minHeight: 80, padding: '6px 6px 4px', borderRadius: 6, cursor: 'pointer',
                  background: isEventDay ? C.accent + '12' : isSelected ? C.accent2 + '10' : C.surface,
                  border: `1px solid ${isSelected ? C.accent2 + 'aa' : isEventDay ? C.accent + '55' : isToday ? C.accent2 + '44' : hasCritical ? C.danger + '33' : C.border}`,
                  boxShadow: isSelected ? `0 0 0 1px ${C.accent2 + '33'}` : 'none',
                  userSelect: 'none', transition: 'background 0.1s, border-color 0.1s',
                }}>
                  <div style={{ fontSize: T.caption, fontWeight: isToday || isSelected ? 700 : 400, color: isSelected ? C.accent2 : isToday ? C.accent2 : C.muted, marginBottom: 3, display: 'flex', alignItems: 'center', gap: 3 }}>
                    {dayNum}
                    {isToday && <span style={{ fontSize: T.eyebrow, background: C.accent2, color: C.bg, borderRadius: 3, padding: '0 3px', fontWeight: FW.bold }}>NOW</span>}
                    {isEventDay && <span style={{ fontSize: T.eyebrow, background: C.accent, color: C.bg, borderRadius: 3, padding: '0 3px', fontWeight: FW.bold }}>EVENT</span>}
                  </div>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                    {dayItems.slice(0, 3).map((item, j) => (
                      <div key={j} title={item.title || item.label} style={{
                        fontSize: T.eyebrow, fontWeight: FW.medium, borderRadius: 3, padding: '1px 4px',
                        background: item.color + '22', color: item.color,
                        overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', lineHeight: 1.4,
                      }}>{item.label}</div>
                    ))}
                    {dayItems.length > 3 && <div style={{ fontSize: T.eyebrow, color: C.muted, paddingLeft: 2 }}>+{dayItems.length - 3} more</div>}
                  </div>
                </div>
              );
            })}
          </div>

          {/* Legend — month view only */}
          <div style={{ display: 'flex', gap: 14, marginTop: 12, flexWrap: 'wrap' }}>
            {[
              { color: C.accent,  label: 'Event Day' },
              { color: C.success, label: 'Phase complete' },
              { color: C.accent2, label: 'Vendor / in progress' },
              { color: C.danger,  label: 'Overdue phase' },
              { color: C.muted,    label: 'Payment due' },
            ].map(({ color, label }) => (
              <div key={label} style={{ display: 'flex', alignItems: 'center', gap: 5 }}>
                <div style={{ width: 8, height: 8, borderRadius: 2, background: color, flexShrink: 0 }} />
                <span style={{ fontSize: T.caption, color: C.muted }}>{label}</span>
              </div>
            ))}
          </div>
        </>
      ) : calView === 'week' ? (
        /* ── Week View — Sprint 48+: 7 vertical columns with full day chips ── */
        (() => {
          const sel = new Date(selectedDay + 'T00:00:00');
          const sun = new Date(sel); sun.setDate(sel.getDate() - sel.getDay());
          const weekDays = Array.from({ length: 7 }, (_, i) => {
            const d = new Date(sun); d.setDate(sun.getDate() + i);
            const ds = d.toISOString().slice(0, 10);
            return {
              date: d, ds,
              dayNum: d.getDate(),
              label: d.toLocaleDateString('en-US', { weekday: 'short' }),
              isToday: ds === today8601(),
              isEvent: events.some(ev => ev.date === ds),
              items: items[ds] || [],
            };
          });
          return (
            <>
              {/* Day-of-week + date headers */}
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: 2, marginBottom: 6 }}>
                {weekDays.map(d => (
                  <div key={d.ds} style={{
                    textAlign: 'center', padding: '8px 4px', borderRadius: 6,
                    background: d.isToday ? C.accent2 + '12' : 'transparent',
                    border: `1px solid ${d.isToday ? C.accent2 + '55' : 'transparent'}`,
                  }}>
                    <div style={{ fontSize: T.caption, fontWeight: FW.semibold, color: C.muted, letterSpacing: '0.08em', textTransform: 'uppercase' }}>{d.label}</div>
                    <div style={{
                      fontSize: T.title, fontWeight: FW.bold, marginTop: 3,
                      color: d.isToday ? C.accent2 : C.text, letterSpacing: '-0.02em',
                    }}>{d.dayNum}</div>
                  </div>
                ))}
              </div>

              {/* Day columns with chips */}
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: 2 }}>
                {weekDays.map(d => (
                  <div role="button" tabIndex={0} onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); e.currentTarget.click(); } }} key={d.ds} onClick={() => { setSelectedDay(d.ds); setCalView('day'); }} style={{
                    minHeight: 320, padding: '8px 6px', borderRadius: 8, cursor: 'pointer',
                    background: d.isEvent ? C.accent + '10' : C.surface,
                    border: `1px solid ${d.isEvent ? C.accent + '55' : d.isToday ? C.accent2 + '44' : C.border}`,
                    display: 'flex', flexDirection: 'column', gap: 4,
                    transition: 'background 0.12s, border-color 0.12s',
                  }}>
                    {d.items.length === 0 ? (
                      <div style={{ fontSize: T.caption, color: C.muted, opacity: 0.5, textAlign: 'center', marginTop: 12 }}>—</div>
                    ) : d.items.map((item, j) => (
                      <div key={j} title={item.title || item.label} style={{
                        fontSize: T.caption, fontWeight: FW.medium, borderRadius: 4, padding: '4px 7px',
                        background: item.color + '22', color: item.color,
                        overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
                        borderLeft: `2px solid ${item.color}`,
                      }}>{item.label}</div>
                    ))}
                  </div>
                ))}
              </div>

              {/* Legend — same as month */}
              <div style={{ display: 'flex', gap: 14, marginTop: 12, flexWrap: 'wrap' }}>
                {[
                  { color: C.accent,  label: 'Event Day' },
                  { color: C.success, label: 'Phase complete' },
                  { color: C.accent2, label: 'Vendor / in progress' },
                  { color: C.danger,  label: 'Overdue phase' },
                  { color: C.muted,    label: 'Payment due' },
                ].map(it => (
                  <div key={it.label} style={{ display: 'flex', alignItems: 'center', gap: 5, fontSize: T.caption, color: C.muted }}>
                    <span style={{ width: 8, height: 8, borderRadius: '50%', background: it.color }} />
                    {it.label}
                  </div>
                ))}
              </div>
            </>
          );
        })()
      ) : calView === 'list' ? (
        /* ── List View — Sprint 49: chronological "what's next" feed across
           all dated items (events, phases, payments, vendor arrivals) ── */
        (() => {
          // Build a flat sorted list of every dated item from TODAY onward, so
          // "Upcoming · all events" is actually upcoming. Board fix: the old
          // window reached 30 days into the PAST, so a far-future event's early
          // milestone (e.g. RiseHQ "12 Months Out" = May 2026, already gone)
          // showed up as "upcoming." Past dates are not upcoming — start at today.
          const today = new Date(); today.setHours(0, 0, 0, 0);
          const start = today;
          const end   = new Date(today); end.setDate(end.getDate() + 365);
          const startISO = start.toISOString().slice(0, 10);
          const endISO   = end.toISOString().slice(0, 10);
          const flat = [];
          Object.entries(items).forEach(([ds, dayItems]) => {
            if (ds < startISO || ds > endISO) return;
            dayItems.forEach(it => flat.push({ ds, ...it }));
          });
          flat.sort((a, b) => a.ds.localeCompare(b.ds));
          // B2 runway: band by time-from-today (This Week / This Month / Later),
          // collapsible, with a today-anchored "Next up" hero — not a flat month dump.
          const todayISO = today8601();
          const t0 = today.getTime();
          const bandOf = (ds) => {
            const dd = Math.round((new Date(ds + 'T00:00:00').getTime() - t0) / 86400000);
            return dd <= 7 ? 'week' : dd <= 31 ? 'month' : 'later';
          };
          const bands = { week: [], month: [], later: [] };
          flat.forEach(it => bands[bandOf(it.ds)].push(it));
          const BAND_META = [
            { key: 'week',  label: 'This Week' },
            { key: 'month', label: 'This Month' },
            { key: 'later', label: 'Later' },
          ];
          // Next-up hero — soonest event day + its engine binding.
          const nextEvIt = flat.find(it => it.type === 'event');
          const nextEv   = nextEvIt ? events.find(e => e.id === nextEvIt.eventId) : null;
          const nextDays = nextEvIt ? Math.round((new Date(nextEvIt.ds + 'T00:00:00').getTime() - t0) / 86400000) : null;
          let nextBind = null;
          try { if (nextEv) { const p = engineNextAction(nextEv); if (p && p.binding) nextBind = { name: p.binding.name, flag: p.flag }; } } catch (e) { /* ignore */ }
          if (flat.length === 0) {
            return (
              <div style={{ ...metalEdge(C), borderRadius: 12, padding: 48, textAlign: 'center' }}>
                <div style={{ fontSize: T.body, fontWeight: FW.semibold, color: C.text, marginBottom: 6 }}>Nothing on the calendar</div>
                <div style={{ fontSize: T.secondary, color: C.muted }}>Events, payments, and phase milestones will appear here as they're added.</div>
              </div>
            );
          }
          const renderRow = (it, i) => {
            const isToday = it.ds === todayISO;
            const d = new Date(it.ds + 'T00:00:00');
            const dayLabel = d.toLocaleDateString('en-US', { weekday: 'short' }).toUpperCase().slice(0, 3);
            const dayNum = d.getDate();
            // Sprint 54E — type tagging by SHAPE + color (never color alone, for
            // colour-blind scannability): event → calendar icon, bold title, venue ·
            // payment → dollar icon, amount, green · milestone → clipboard, steel ·
            // vendor arrival → store icon, steel.
            const isEvent = it.type === 'event', isPay = it.type === 'payment', isTask = it.type === 'task', isVendor = it.type === 'vendor';
            const accent  = isPay ? C.success : isEvent ? (it.color || C.text) : C.accent2;
            const iconName = isEvent ? 'calendar' : isPay ? 'dollar' : isTask ? 'clipboard' : isVendor ? 'store' : 'list';
            const amt = isPay && it.vendor ? vendorBalance(it.vendor) : 0;
            return (
              <div
                key={`${it.ds}-${it.eventId}-${i}`}
                onClick={() => { if (it.eventId) onSelectEvent(it.eventId); else { setSelectedDay(it.ds); setCalView('day'); } }}
                style={{
                  display: 'flex', alignItems: 'center', gap: 12, padding: '12px 20px',
                  borderBottom: `1px solid ${C.border}`, cursor: 'pointer',
                  background: isToday ? C.accent2 + '08' : 'transparent', transition: 'background 0.12s',
                }}
                onMouseEnter={e => { e.currentTarget.style.background = C.surface2 || C.surface; }}
                onMouseLeave={e => { e.currentTarget.style.background = isToday ? C.accent2 + '08' : 'transparent'; }}
              >
                <div style={{ width: 44, flexShrink: 0, display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
                  <span style={{ fontSize: T.eyebrow, fontWeight: FW.bold, letterSpacing: '0.10em', color: isToday ? C.accent2 : C.muted }}>{dayLabel}</span>
                  <span style={{ fontSize: T.title, fontWeight: FW.bold, letterSpacing: '-0.02em', color: isToday ? C.accent2 : C.text, marginTop: 1, lineHeight: 1 }}>{dayNum}</span>
                </div>
                <div style={{ width: 3, height: 32, borderRadius: 2, background: accent, flexShrink: 0 }} />
                <span aria-label={`${it.type} item`} title={it.type} style={{ flexShrink: 0, display: 'inline-flex', alignItems: 'center', color: accent }}>
                  <Icon name={iconName} size={15} />
                </span>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ fontSize: T.secondary, fontWeight: isEvent ? 700 : 600, color: C.text, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                    {it.title || it.label}
                    {isEvent && it.venue && <span style={{ color: C.muted, fontWeight: FW.regular }}> · {it.venue}</span>}
                  </div>
                  <div style={{ fontSize: T.caption, color: C.muted, marginTop: 2 }}>
                    {isEvent ? 'Event day' : isTask ? 'Phase milestone' : isPay ? 'Payment due' : isVendor ? 'Vendor arrival' : it.type}
                    {isPay && amt > 0 && <span style={{ color: C.success, fontWeight: FW.bold }}> · {fmtD(amt)}</span>}
                    {isToday && <span style={{ color: C.accent2, fontWeight: FW.semibold }}> · today</span>}
                  </div>
                </div>
                <span style={{ color: C.muted, fontSize: T.body }}>›</span>
              </div>
            );
          };
          return (
            <div>
              {nextEvIt && (
                <div onClick={() => onSelectEvent(nextEvIt.eventId)}
                  style={{ ...metalEdge(C), borderLeft: `3px solid ${C.accent}`, borderRadius: 12, padding: '14px 18px', marginBottom: 12, cursor: 'pointer' }}>
                  <div style={{ fontSize: T.eyebrow, fontWeight: FW.heavy, letterSpacing: '0.14em', textTransform: 'uppercase', color: C.accent, marginBottom: 5 }}>
                    Next up · {nextDays <= 0 ? 'today' : nextDays === 1 ? 'tomorrow' : `in ${nextDays} days`}
                  </div>
                  <div style={{ fontSize: T.body, fontWeight: FW.bold, color: C.text }}>{nextEvIt.label}</div>
                  {nextBind && <div style={{ fontSize: T.secondary, color: C.muted, marginTop: 3 }}>{nextBind.flag} Next: <span style={{ color: C.text, fontWeight: FW.semibold }}>{nextBind.name}</span></div>}
                </div>
              )}
              <div style={{ ...metalEdge(C), borderRadius: 12, overflow: 'hidden' }}>
                {BAND_META.map(b => {
                  const list = bands[b.key];
                  if (!list.length) return null;
                  const open = calBands[b.key];
                  return (
                    <div key={b.key}>
                      <div onClick={() => setCalBands(s => ({ ...s, [b.key]: !s[b.key] }))}
                        style={{ padding: '10px 20px', background: C.bg, borderBottom: `1px solid ${C.border}`, display: 'flex', alignItems: 'center', justifyContent: 'space-between', cursor: 'pointer', fontSize: T.caption, fontWeight: FW.bold, letterSpacing: '0.12em', textTransform: 'uppercase', color: C.muted }}>
                        <span>{b.label} · {list.length}</span>
                        <span style={{ fontSize: T.secondary }}>{open ? '▾' : '▸'}</span>
                      </div>
                      {open && list.map((it, i) => renderRow(it, i))}
                    </div>
                  );
                })}
              </div>
            </div>
          );
        })()
      ) : (
        /* ── Day View ── */
        <div style={{ ...metalEdge(C), borderRadius: 12, overflow: 'hidden' }}>
          {/* Day header */}
          <div style={{ padding: '14px 20px', borderBottom: `1px solid ${C.border}`, display: 'flex', alignItems: 'center', gap: 10, flexWrap: 'wrap' }}>
            <div style={{ fontSize: T.section, fontWeight: FW.bold, letterSpacing: '-0.01em' }}>
              {new Date(selectedDay + 'T00:00:00').toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' })}
            </div>
            {selectedDay === today8601() && <span style={s.pill(C.accent2)}>Today</span>}
            {selEventDay.length > 0 && <span style={s.pill(C.accent)}>{selEventDay.length} event{selEventDay.length > 1 ? 's' : ''}</span>}
            {selPayments.length > 0 && <span style={s.pill(C.muted)}>{selPayments.length} payment{selPayments.length > 1 ? 's' : ''} due</span>}
          </div>

          {/* Events on this day */}
          {selEventDay.length > 0 && (
            <div style={{ padding: '12px 20px', borderBottom: `1px solid ${C.border}` }}>
              <div style={{ fontSize: T.caption, fontWeight: FW.bold, textTransform: 'uppercase', letterSpacing: '0.08em', color: C.accent, marginBottom: 8 }}>Event Day</div>
              {selEventDay.map(ev => (
                <div role="button" tabIndex={0} onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); e.currentTarget.click(); } }} key={ev.id} onClick={() => onSelectEvent(ev.id)} style={{
                  display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '10px 14px',
                  background: (evtCLR[ev.type] || C.muted) + '12', borderRadius: 8,
                  border: `1px solid ${(evtCLR[ev.type] || C.muted) + '44'}`, cursor: 'pointer', marginBottom: 6,
                }}
                  onMouseEnter={e => e.currentTarget.style.background = (evtCLR[ev.type] || C.muted) + '22'}
                  onMouseLeave={e => e.currentTarget.style.background = (evtCLR[ev.type] || C.muted) + '12'}
                >
                  <div>
                    <div style={{ fontSize: T.secondary, fontWeight: FW.bold, color: C.text }}>{ev.name}</div>
                    <div style={{ fontSize: T.caption, color: C.muted }}>{ev.venue || ev.type}</div>
                  </div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                    <span style={s.pill(evtCLR[ev.type] || C.muted)}>{ev.type}</span>
                    <span style={{ color: C.muted, fontSize: T.body }}>›</span>
                  </div>
                </div>
              ))}
            </div>
          )}

          {/* Phase milestones + payments */}
          {(selPhases.length > 0 || selPayments.length > 0) && (
            <div style={{ padding: '12px 20px', borderBottom: `1px solid ${C.border}`, background: C.surface2 + '88', display: 'flex', flexDirection: 'column', gap: 10 }}>
              {selPhases.map((ph, i) => {
                const done = ph.tasks.filter(t => t.done).length;
                const overdue = ph.tasks.filter(t => !t.done && ph.date <= getToday()).length;
                return (
                  <div key={i}>
                    <div style={{ fontSize: T.caption, fontWeight: FW.bold, textTransform: 'uppercase', letterSpacing: '0.08em', color: ph.color, marginBottom: 6 }}>
                      Planning Milestone — {ph.phase} · {ph.eventName}
                    </div>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
                      {ph.tasks.map(t => {
                        const ov = ph.date <= getToday() && !t.done;
                        return (
                          <div role="button" tabIndex={0} onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); e.currentTarget.click(); } }} key={t.id} onClick={() => onSelectEvent(ph.eventId)} style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: T.secondary, cursor: 'pointer', padding: '2px 4px', borderRadius: 4 }}
                            onMouseEnter={e => e.currentTarget.style.background = C.accent + '0d'}
                            onMouseLeave={e => e.currentTarget.style.background = 'transparent'}
                          >
                            <span style={{ color: t.done ? C.success : ov ? C.danger : C.muted }}>{t.done ? '✓' : ov ? '!' : '○'}</span>
                            <span style={{ color: t.done ? C.muted : C.text, textDecoration: t.done ? 'line-through' : 'none', flex: 1 }}>{t.task}</span>
                            {t.owner && <span style={{ color: C.muted }}>{t.owner}</span>}
                          </div>
                        );
                      })}
                    </div>
                    <div style={{ fontSize: T.caption, color: ph.color, fontWeight: FW.semibold, marginTop: 4 }}>{done}/{ph.tasks.length} done{overdue > 0 ? ` · ${overdue} overdue` : ''}</div>
                  </div>
                );
              })}
              {selPayments.map((item, i) => {
                const v = item.vendor;
                const bal = v ? vendorBalance(v) : 0;
                return (
                  <div role="button" tabIndex={0} onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); e.currentTarget.click(); } }} key={i} onClick={() => onSelectEvent(item.eventId)} style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '6px 10px 6px 13px', background: C.surface2, borderRadius: 6, borderLeft: `3px solid ${C.muted}`, cursor: 'pointer' }}>
                    <span style={{ fontSize: T.caption, color: C.muted, fontWeight: FW.bold }}>💳 Payment Due</span>
                    <span style={{ fontSize: T.secondary, color: C.text, flex: 1 }}>{item.label} · <span style={{ color: C.muted }}>{item.eventName}</span></span>
                    <span style={{ fontSize: T.secondary, fontWeight: FW.bold, color: C.muted }}>{fmtD(bal)}</span>
                  </div>
                );
              })}
            </div>
          )}

          {/* Time grid — vendor arrivals + ROS across all events this day */}
          {hasTimedContent ? (() => {
            const timed   = daySlots.filter(s => s.time);
            const untimed = daySlots.filter(s => !s.time);
            const minHour = timed.length > 0 ? Math.max(0, Math.floor(parseMin(timed[0].time) / 60) - 1) : 6;
            const maxHour = timed.length > 0 ? Math.min(24, Math.ceil(parseMin(timed[timed.length - 1].time) / 60) + 2) : 22;
            const hours   = Array.from({ length: maxHour - minHour }, (_, i) => minHour + i);
            return (
              <div>
                <div style={{ padding: '8px 0', maxHeight: 'min(480px, 55vh)', overflowY: 'auto' }}>
                  {hours.map(h => {
                    const hLabel = h === 0 ? '12 AM' : h < 12 ? `${h} AM` : h === 12 ? '12 PM' : `${h - 12} PM`;
                    const slotItems = timed.filter(sl => { const sm = parseMin(sl.time); return sm >= h * 60 && sm < (h + 1) * 60; });
                    return (
                      <div key={h} style={{ display: 'flex', gap: 0, minHeight: 44, borderTop: `1px solid ${C.border}33` }}>
                        <div style={{ width: 56, flexShrink: 0, padding: '10px 12px 0', fontSize: T.caption, color: C.border, textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{hLabel}</div>
                        <div style={{ flex: 1, padding: '4px 16px 4px 12px', display: 'flex', flexDirection: 'column', gap: 4 }}>
                          {slotItems.map((item, j) => (
                            <div role="button" tabIndex={0} onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); e.currentTarget.click(); } }} key={j} onClick={() => onSelectEvent(item.evId)} style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '4px 10px', borderRadius: 6, background: item.color + '18', borderLeft: `3px solid ${item.color}`, cursor: 'pointer' }}>
                              <span style={{ fontSize: T.caption, fontWeight: FW.bold, color: item.color, minWidth: 42, fontVariantNumeric: 'tabular-nums' }}>{fmtTime12(item.time)}</span>
                              <span style={{ fontSize: T.secondary, color: C.text, flex: 1 }}>{item.label}</span>
                              {item.duration && <span style={{ fontSize: T.caption, color: C.muted }}>{fmtDur(item.duration)}</span>}
                              <span style={{ fontSize: T.caption, color: item.color }}>{item.sub}</span>
                            </div>
                          ))}
                        </div>
                      </div>
                    );
                  })}
                </div>
                {untimed.length > 0 && (
                  <div style={{ padding: '8px 20px 12px', borderTop: `1px solid ${C.border}33` }}>
                    <div style={{ fontSize: T.caption, fontWeight: FW.bold, textTransform: 'uppercase', letterSpacing: '0.06em', color: C.muted, marginBottom: 6 }}>No time set</div>
                    {untimed.map((item, j) => (
                      <div role="button" tabIndex={0} onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); e.currentTarget.click(); } }} key={j} onClick={() => onSelectEvent(item.evId)} style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '4px 10px', borderRadius: 6, background: item.color + '12', borderLeft: `3px solid ${item.color}`, marginBottom: 3, cursor: 'pointer' }}>
                        <span style={{ fontSize: T.secondary, color: C.text, flex: 1 }}>{item.label}</span>
                        <span style={{ fontSize: T.caption, color: item.color }}>{item.sub}</span>
                      </div>
                    ))}
                  </div>
                )}
                <div style={{ padding: '6px 20px 10px', fontSize: T.caption, color: C.muted }}>Click any item to open the event</div>
              </div>
            );
          })() : (
            <div style={{ padding: '24px 20px', fontSize: T.secondary, color: C.muted, fontStyle: 'italic' }}>
              {selEventDay.length > 0 ? 'No confirmed vendor arrivals or Event Day Schedule items set for this event.' : selPhases.length > 0 || selPayments.length > 0 ? '' : 'Nothing scheduled — clear day.'}
            </div>
          )}
        </div>
      )}
    </div>
    </ThemeCtx.Provider>
  );
}

