// kept elsewhere in App.js continue to serve the live message paths.


// ─── Event Day Mode — helpers + components ───────────────────────────────────

const getTaskTargetDateStr = (task, eventDate) => {
  if (!eventDate || !task.week || !(task.week in PHASE_OFFSET)) return null;
  const d = new Date(eventDate + 'T00:00:00');
  d.setDate(d.getDate() + PHASE_OFFSET[task.week]);
  return d.toISOString().slice(0, 10);
};

const bucketTasks = (tasks, eventDate, eventType) => {
  const td = today8601();
  const inSeven = (() => { const d = new Date(td + 'T00:00:00'); d.setDate(d.getDate() + 7); return d.toISOString().slice(0, 10); })();
  const now = [], next = [], later = [];
  tasks.filter(t => !t.done).forEach(t => {
    const over   = isTaskOverdue(t, eventDate, eventType);
    const target = getTaskTargetDateStr(t, eventDate);
    if (over || target === td)              now.push(t);
    else if (target && target <= inSeven)   next.push(t);
    else                                    later.push(t);
  });
  return { now, next, later };
};

// computeDayAlerts — day-of severity reader. Sprint 64 (Figma B2 1558:49): each
// alert now carries a 3-tier `tier` ('critical' | 'warning' | 'heads-up'), a
// bold `headline` (what's happening), and a separate `move` (the "→ your move"
// action sentence — never one blob). `sev`/`text` are kept as aliases so the
// planner EventDayBar (clock-strip) keeps reading them unchanged. The host
// surface renders these as a calm 3-tier card stack (HostDaySeverityStack).
// heads-up = informational time/opportunity cues (golden-hour photo, next ROS
// segment) — escalation by REDUCTION, the calm tier.
const computeDayAlerts = (event) => {
  const td = today8601();
  const nowMin = new Date().getHours() * 60 + new Date().getMinutes();
  const alerts = [];
  const push = (a) => alerts.push({ ...a, sev: a.tier, text: a.text || a.headline });

  if (event.date === td) {
    (event.vendors || [])
      .filter(v => v.arrivalTime && ['Confirmed','Contracted','Deposit Paid'].includes(v.status)
                && v.arrivalStatus !== 'arrived' && v.arrivalStatus !== 'completed')
      .forEach(v => {
        const vm = parseMin(v.arrivalTime);
        if (vm !== null && vm < nowMin - 10)
          push({ id: `ov-${v.id}`, tier: 'critical', headline: `${v.name} hasn't arrived`, move: `Call ${v.name} now — they were due at ${fmtTime12(v.arrivalTime)}.`, navTo: 'Arrivals' });
      });

    // Confirmed-but-unconfirmed-arrival vendor with an arrival time still ahead —
    // a day-of "make sure they're coming" critical (the Figma "Caterer hasn't
    // confirmed arrival" case). Only the soonest one, to stay calm.
    const unconfirmed = (event.vendors || [])
      .filter(v => v.name && v.arrivalTime && ['Confirmed','Contracted','Deposit Paid'].includes(v.status)
                && v.arrivalStatus !== 'arrived' && v.arrivalStatus !== 'completed' && v.arrivalStatus !== 'delayed')
      .map(v => ({ v, m: parseMin(v.arrivalTime) }))
      .filter(x => x.m !== null && x.m >= nowMin - 10 && x.m <= nowMin + 90)
      .sort((a, b) => a.m - b.m);
    if (unconfirmed.length) {
      const { v } = unconfirmed[0];
      push({ id: `confirm-${v.id}`, tier: 'critical', headline: `${v.name} hasn't confirmed arrival`, move: `Call ${v.name} now — they're set for ${fmtTime12(v.arrivalTime)}.`, navTo: 'Arrivals' });
    }
  }

  const pending = (event.commClient || []).filter(m => m.message_type === 'approval_request' && (!m.approval_status || m.approval_status === 'pending'));
  if (pending.length)
    push({ id: 'approvals', tier: 'warning', headline: `${pending.length} approval${pending.length > 1 ? 's' : ''} waiting on a reply`, move: `Nudge them so the day-of plan can lock.`, navTo: 'Communication' });

  (event.vendors || []).filter(v => v.payDueDate === td && !v.balancePaid && v.name).forEach(v =>
    push({ id: `pay-${v.id}`, tier: 'warning', headline: `Payment due today: ${v.name}`, move: `Send the balance so they're squared away.`, navTo: 'Vendors' })
  );

  // RSVPs still outstanding — headcount may shift (Figma B2 warning case).
  const yesCount = (event.guests || []).filter(g => g.rsvp === 'Yes').length;
  const pendingRsvp = (event.guests || []).filter(g => g && g.name && (!g.rsvp || g.rsvp === 'Pending' || g.rsvp === 'Maybe')).length;
  if (event.date === td && pendingRsvp > 0)
    push({ id: 'rsvp-pending', tier: 'warning', headline: `${pendingRsvp} haven't RSVP'd`, move: yesCount > 0 ? `Headcount may shift — text them, or plan for ${yesCount} to be safe.` : `Headcount may shift — text them so you can plan portions.`, navTo: 'Guests' });

  const overdueCount = (event.timeline || []).filter(t => !t.done && isTaskOverdue(t, event.date, event.type)).length;
  if (overdueCount)
    push({ id: 'overdue-tasks', tier: 'warning', headline: `${overdueCount} thing${overdueCount > 1 ? 's' : ''} still open`, move: `Knock them out or let them go — the day's already here.`, navTo: 'Planning Tasks' });

  // Guests with allergies + catering confirmed — on event day, confirm with caterer
  if (event.date === td) {
    const allergyGuests = (event.guests || []).filter(g => g.rsvp === 'Yes' && g.needs && /allerg/i.test(g.needs));
    const hasCaterer = (event.vendors || []).some(v => /cater|f&b|food|beverage/i.test(v.category) && ['Confirmed','Contracted','Deposit Paid'].includes(v.status));
    if (allergyGuests.length && hasCaterer)
      push({ id: 'dietary', tier: 'critical', headline: `${allergyGuests.length} guest${allergyGuests.length > 1 ? 's' : ''} with allergies`, move: `Confirm the swaps with your caterer before service.`, navTo: 'Guests' });
  }

  // HEADS-UP (informational, calm) — time/opportunity cues from the authored
  // run-of-show. A golden-hour / photo segment becomes "get the group photo";
  // otherwise the next upcoming segment is a gentle "next up" cue. Only on the
  // day itself, only one, never with an alarm color.
  if (event.date === td) {
    let ros = [];
    try { ros = effectiveRos(event) || []; } catch { ros = []; }
    const timed = ros.filter(r => r && r.time && r.segment).sort((a, b) => (a.time || '').localeCompare(b.time || ''));
    const photoSeg = timed.find(r => /golden|photo|portrait|group.?shot|sunset/i.test(r.segment) && (parseMin(r.time) ?? -1) >= nowMin - 30);
    const nextSeg = timed.find(r => { const m = parseMin(r.time); return m !== null && m >= nowMin; });
    if (photoSeg)
      push({ id: 'heads-photo', tier: 'heads-up', headline: `Golden hour at ${fmtTime12(photoSeg.time)}`, move: `Get the group photo before the light goes.`, navTo: 'Event Day Schedule' });
    else if (nextSeg)
      push({ id: 'heads-next', tier: 'heads-up', headline: `Next up at ${fmtTime12(nextSeg.time)} — ${nextSeg.segment}`, move: `A little ahead of time keeps the day calm.`, navTo: 'Event Day Schedule' });
  }

  return alerts;
};

// ─── WeatherAlert — Sprint 63: outdoor event weather risk ────────────────────
// Event types that are outdoor by nature (the weather check shouldn't depend only on
// venue keywords for these). Cookouts, BBQs, fish fries, boils, day parties, picnics.
function isOutdoorEventType(type) {
  return /cookout|bbq|barbecue|fish fry|crab feast|crawfish|low ?country boil|boil|picnic|day party|block party|tailgate|luau|beach|garden party|graduation|juneteenth|family reunion|reunion/i.test(String(type || ''));
}

function WeatherAlert({ event, onNavTo }) {
  const C = useT();
  const T = useType();
  const s = makeS(C);
  const [wx, setWx] = useState(null);
  const [loading, setLoading] = useState(false);
  const [dismissed, setDismissed] = useState(false);
  const [shareStatus, setShareStatus] = useState('');

  const days = event?.date ? daysUntil(event.date) : null;
  // Outdoor by venue keyword OR by event TYPE — a cookout/BBQ/fish fry is outdoor by
  // nature even if the venue is just "Atlanta, GA". (Board audit #3: the cookout was
  // silently getting no forecast because the gate only read venue keywords.)
  const outdoor = isLikelyOutdoor(event?.venue, event?.notes) || isOutdoorEventType(event?.type);
  const shouldFetch = isWeatherConfigured() && outdoor && days !== null && days >= 0 && days <= 14;

  useEffect(() => {
    if (!shouldFetch || dismissed) return;
    let cancelled = false;
    setLoading(true);
    (async () => {
      try {
        // Geocode a clean "City, ST, US" (structured city/state → picked metro →
        // venue) so OpenWeather resolves it; free-text venues alone often don't.
        const coords = await geocodeVenue(eventGeoQuery(event) || event.venue);
        if (!coords || cancelled) return;
        const risk = await getEventWeatherRisk(coords.lat, coords.lon, event.date);
        if (!cancelled) setWx(risk);
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => { cancelled = true; };
  }, [event?.id, event?.date, event?.venue, shouldFetch, dismissed]); // eslint-disable-line react-hooks/exhaustive-deps

  // WARNING — a real weather RISK surfaces (rain/heat on an outdoor day): a sharp-but-
  // calm double + low alert tone, once. Eyes-now, no dread (Sound Map · ALERT).
  const wxAlertedRef = useRef(false);
  useEffect(() => {
    if (wx && wx.risk === 'high' && !wxAlertedRef.current) { wxAlertedRef.current = true; try { feedbackAlert(); } catch {} }
  }, [wx]);

  // Rain plan (#56): show the forecast even on a CLEAR day — the host asked "is there a
  // chance of rain?" and a calm "10% — you're clear, no rain plan needed" is an answer,
  // not noise. Only truly nothing-to-show states (no fetch / loading / no data) return null.
  if (!shouldFetch || dismissed || loading || !wx) return null;

  const riskColor = wx.risk === 'high' ? C.danger : C.muted;
  // Board #2 — the forecast drives concrete day-of adjustments (ice, shade, water,
  // tent), not just a banner. Sized to this event's guest count.
  const guests = Number(event?.guestCount) || (Array.isArray(event?.guests) ? event.guests.length : 0);
  const adjustments = weatherLogistics(wx, { guests });
  // #3-(b) — the AUTHORED contingency that matches this weather, surfaced as a concrete
  // "here's the move" instead of staying dark inside confirmCopy.
  const contingency = (() => { try { return playbookContingencyForWeather(event, wx); } catch { return null; } })();
  const wxIcon = wx.risk === 'clear' ? '☀️' : wx.kind === 'heat' ? '☀️' : wx.kind === 'snow' ? '❄️' : wx.kind === 'cold' ? '🥶' : wx.risk === 'high' ? '⛈' : '🌧';

  // Sprint 64 (Figma B1 1556:2): the weather "your move" CTA is a one-tap host
  // group-chat draft — "Text guests the plan →" — not "Review vendors". Build a
  // short, honest message from the REAL forecast (summary + what changes + the
  // authored move). Never fabricated: it only assembles signals already shown.
  const weatherPlanMessage = (() => {
    const lines = [];
    const name = (event?.name || '').trim();
    lines.push(name ? `Heads up for ${name}:` : 'Heads up for today:');
    if (wx.summary) lines.push(wx.summary);
    if (contingency?.plan) lines.push(contingency.plan);
    else if (adjustments.length) lines.push(adjustments.map(a => a.text.replace(/\s*\([^)]*\)/g, '')).slice(0, 2).join(' '));
    lines.push("We're covered either way — see you there.");
    return lines.filter(Boolean).join('\n\n');
  })();
  const textGuestsThePlan = async () => {
    const r = await shareOrCopy({ title: event?.name ? `${event.name} — weather plan` : 'Weather plan', text: weatherPlanMessage });
    if (r === 'shared') setShareStatus('Shared');
    else if (r === 'copied') setShareStatus('Copied — paste into your group chat');
    if (r === 'shared' || r === 'copied') setTimeout(() => setShareStatus(''), 2600);
  };

  return (
    <div style={{
      margin: '0 0 12px', padding: '10px 16px', borderRadius: 8,
      background: riskColor + '12', border: `1px solid ${riskColor}44`,
    }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
        <span style={{ fontSize: T.body }}>{wxIcon}</span>
        <div style={{ flex: 1 }}>
          <div style={{ fontSize: T.secondary, fontWeight: FW.bold, color: riskColor, marginBottom: 2 }}>
            Weather forecast · {wx.daysOut}d out
          </div>
          <div style={{ fontSize: T.caption, color: C.text }}>{wx.summary}</div>
          {wx.sunset && <div style={{ fontSize: T.caption, color: C.text, marginTop: 2 }}>🌇 Sun sets {wx.sunset} — plan lighting + golden-hour photos before then.</div>}
          <div style={{ fontSize: T.caption, color: C.muted, marginTop: 2 }}>{wx.disclaimer}</div>
        </div>
        <button onClick={() => setDismissed(true)} title="Dismiss" style={{ ...s.btn('ghost'), padding: '3px 6px', fontSize: T.secondary, color: C.muted }}>×</button>
      </div>
      {adjustments.length > 0 && (
        <div style={{ marginTop: 9, paddingTop: 9, borderTop: `1px solid ${riskColor}22`, display: 'flex', flexDirection: 'column', gap: 6 }}>
          <div style={{ fontSize: T.eyebrow, fontWeight: FW.heavy, letterSpacing: '0.1em', textTransform: 'uppercase', color: riskColor }}>What that changes</div>
          {adjustments.map((a) => (
            <div key={a.key} style={{ display: 'flex', alignItems: 'flex-start', gap: 8, fontSize: T.caption, color: C.text, lineHeight: 1.45 }}>
              <span aria-hidden style={{ flexShrink: 0 }}>{a.icon}</span>
              <span>{a.text}</span>
            </div>
          ))}
        </div>
      )}
      {(contingency || adjustments.length > 0) && (
        <div style={{ marginTop: 9, paddingTop: 9, borderTop: `1px solid ${riskColor}22` }}>
          <div style={{ fontSize: T.eyebrow, fontWeight: FW.heavy, letterSpacing: '0.1em', textTransform: 'uppercase', color: riskColor, marginBottom: 4 }}>Your move</div>
          {contingency && <div style={{ fontSize: T.caption, color: C.text, lineHeight: 1.45, marginBottom: 8 }}>{contingency.plan}</div>}
          {/* Figma B1 1556:2 — one-tap host group-chat draft. Native share → clipboard. */}
          <button
            onClick={textGuestsThePlan}
            data-testid="weather-text-guests"
            style={{ ...s.btn('primary'), padding: '7px 14px', fontSize: T.secondary, fontWeight: FW.semibold, display: 'inline-flex', alignItems: 'center', gap: 7 }}
          >
            Text guests the plan →
          </button>
          {shareStatus && <span style={{ marginLeft: 10, fontSize: T.caption, color: C.muted }}>{shareStatus}</span>}
        </div>
      )}
    </div>
  );
}

// ─── EventDayBar ─────────────────────────────────────────────────────────────
function EventDayBar({ event, alerts, dismissed, onDismiss, onNavTo, bp }) {
  const C = useT();
  const T = useType();
  const isMobile = bp === 'mobile';
  const [now, setNow] = useState(() => new Date());
  // Sprint 60.R Day-of calm — collapse non-critical alerts on mobile so
  // the calm command station (DayTaskView hero + sections) lands first.
  // The alarm wall only expands when the user opts in. Critical alerts
  // still render up top because they need immediate visibility.
  const [alertsExpanded, setAlertsExpanded] = useState(false);
  useEffect(() => { const t = setInterval(() => setNow(new Date()), 1000); return () => clearInterval(t); }, []);

  const days    = daysUntil(event.date);
  const nowMin  = now.getHours() * 60 + now.getMinutes();
  const nextSeg = effectiveRos(event)
    .filter(r => r.time && r.segment)
    .sort((a, b) => (a.time || '').localeCompare(b.time || ''))
    .find(r => { const m = parseMin(r.time); return m !== null && m >= nowMin; });

  const timeStr   = now.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', second: '2-digit', hour12: true });
  const isEvtDay  = days === 0;
  const visible   = alerts.filter(a => !dismissed.has(a.id));
  // Split critical from non-critical so the calm pass keeps true emergencies visible.
  const criticalAlerts = visible.filter(a => a.sev === 'critical');
  const otherAlerts    = visible.filter(a => a.sev !== 'critical');
  // On mobile: always show critical rows; collapse the others behind a
  // single "N more · View" affordance. Desktop unchanged.
  const renderRows = isMobile
    ? (alertsExpanded ? visible : criticalAlerts)
    : visible;

  return (
    <div>
      {/* Clock / context strip */}
      <div style={{ background: C.surface2, borderBottom: `1px solid ${C.border}`, padding: isMobile ? '9px 14px' : '10px 28px', display: 'flex', alignItems: 'center', gap: isMobile ? 10 : 18, flexWrap: 'wrap' }}>
        <span style={{ fontFamily: 'monospace', fontSize: isMobile ? 14 : 16, fontWeight: FW.bold, color: C.text, letterSpacing: '0.04em', flexShrink: 0 }}>{timeStr}</span>
        {isEvtDay && <span style={{ fontSize: T.caption, fontWeight: FW.heavy, color: C.accent, textTransform: 'uppercase', letterSpacing: '0.1em', flexShrink: 0, padding: '2px 8px', borderRadius: 6, background: 'transparent', border: `1px solid ${C.accent}66` }}>Event Day</span>}
        {days !== null && !isEvtDay && <span style={{ fontSize: T.caption, color: C.muted, flexShrink: 0 }}>{days > 0 ? `${days}d to event` : `${Math.abs(days)}d post`}</span>}
        {nextSeg && !isMobile && (
          <span style={{ fontSize: T.caption, color: C.muted, flex: 1, minWidth: 0, lineHeight: 1.35 }}>
            Next: <span style={{ color: C.text, fontWeight: FW.semibold }}>{fmtTime12(nextSeg.time)} — {nextSeg.segment}</span>
          </span>
        )}
        {visible.length > 0 ? (
          <span style={{ marginLeft: 'auto', display: 'inline-flex', alignItems: 'center', gap: 5, padding: '4px 10px', borderRadius: 8, border: `1px solid ${C.danger}44`, background: C.danger + '10', color: C.danger, fontSize: T.caption, fontWeight: FW.bold, flexShrink: 0 }}>
            <Icon name="alertTriangle" size={12} /> {visible.length} alert{visible.length > 1 ? 's' : ''}
          </span>
        ) : (
          <span style={{ marginLeft: 'auto', fontSize: T.caption, color: C.success, fontWeight: FW.bold, flexShrink: 0 }}>● All clear</span>
        )}
      </div>
      {/* Next segment — mobile second row */}
      {nextSeg && isMobile && (
        <div style={{ background: C.surface2, borderBottom: `1px solid ${C.border}`, padding: '5px 14px', fontSize: T.caption, color: C.muted }}>
          Next: <span style={{ color: C.text, fontWeight: FW.semibold }}>{fmtTime12(nextSeg.time)} — {nextSeg.segment}</span>
        </div>
      )}
      {/* Sprint 60.V — Day-of command station structure. Alert rows are
          now labeled "NEEDS ACTION NOW" so the planner reads a structured
          command station, not a raw panic stack. Steel-blue eyebrow over
          the critical rows; muted eyebrow over the collapsed/non-critical
          group when expanded. */}
      {criticalAlerts.length > 0 && (
        <div style={{
          padding: isMobile ? '8px 14px 4px 17px' : '8px 28px 4px 31px',
          background: C.surface,
          borderBottom: `1px solid ${C.border}`,
          display: 'flex', alignItems: 'center', gap: 8,
        }}>
          <span style={{ fontSize: T.caption, fontWeight: FW.heavy, letterSpacing: '0.16em', textTransform: 'uppercase', color: C.accentTopGrad || C.accent }}>
            Needs action now
          </span>
          <span style={{ fontSize: T.caption, fontWeight: FW.bold, color: C.danger }}>{criticalAlerts.length}</span>
        </div>
      )}
      {/* Alert rows — critical first, then non-critical (when expanded on mobile). */}
      {renderRows.map((a, idx) => {
        const showWaitHeader = isMobile && alertsExpanded && a.sev !== 'critical'
          && idx > 0 && renderRows[idx - 1]?.sev === 'critical';
        return (
          <Fragment key={a.id}>
            {showWaitHeader && (
              <div style={{
                padding: '8px 14px 4px 17px',
                background: C.surface,
                borderBottom: `1px solid ${C.border}`,
                display: 'flex', alignItems: 'center', gap: 8,
              }}>
                <span style={{ fontSize: T.caption, fontWeight: FW.heavy, letterSpacing: '0.16em', textTransform: 'uppercase', color: C.muted }}>
                  What can wait
                </span>
                <span style={{ fontSize: T.caption, fontWeight: FW.bold, color: C.muted }}>{otherAlerts.length}</span>
              </div>
            )}
            <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: isMobile ? '8px 14px 8px 17px' : '8px 28px 8px 31px', background: C.surface, borderBottom: `1px solid ${C.border}`, borderLeft: `3px solid ${a.sev === 'critical' ? C.danger : C.muted}` }}>
              <span style={{ flexShrink: 0, color: a.sev === 'critical' ? C.danger : C.muted, display: 'flex' }}><Icon name="alertTriangle" size={13} /></span>
              <span style={{ flex: 1, fontSize: T.secondary, color: a.sev === 'critical' ? C.danger : C.text, fontWeight: a.sev === 'critical' ? 600 : 400 }}>{a.text}</span>
              {a.navTo && <button onClick={() => onNavTo(a.navTo)} style={{ fontSize: T.secondary, color: C.accent, background: 'none', border: 'none', cursor: 'pointer', padding: '4px 8px', minHeight: 40, fontFamily: 'inherit', fontWeight: FW.semibold, flexShrink: 0 }}>Go →</button>}
              <button onClick={() => onDismiss(a.id)} style={{ width: 32, height: 32, borderRadius: 6, border: 'none', background: 'transparent', color: C.muted, cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
                <Icon name="x" size={13} />
              </button>
            </div>
          </Fragment>
        );
      })}
      {/* Mobile collapse affordance — only renders when non-critical alerts exist and aren't already shown. */}
      {isMobile && !alertsExpanded && otherAlerts.length > 0 && (
        <button
          onClick={() => setAlertsExpanded(true)}
          style={{
            display: 'flex', alignItems: 'center', justifyContent: 'space-between',
            width: '100%', padding: '10px 14px 10px 17px',
            background: C.surface, borderBottom: `1px solid ${C.border}`,
            borderLeft: `3px solid ${C.muted}`,
            cursor: 'pointer', textAlign: 'left',
            border: 'none', borderRadius: 0, fontFamily: 'inherit',
          }}
        >
          <span style={{ fontSize: T.secondary, color: C.muted, fontWeight: FW.semibold }}>
            {otherAlerts.length} more alert{otherAlerts.length !== 1 ? 's' : ''} below
          </span>
          <span style={{ fontSize: T.secondary, color: C.accent, fontWeight: FW.semibold }}>View ›</span>
        </button>
      )}
      {/* Collapse-back when expanded */}
      {isMobile && alertsExpanded && otherAlerts.length > 0 && (
        <button
          onClick={() => setAlertsExpanded(false)}
          style={{
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            width: '100%', padding: '8px 14px',
            background: 'transparent', borderBottom: `1px solid ${C.border}`,
            cursor: 'pointer', border: 'none', fontFamily: 'inherit',
            fontSize: T.secondary, color: C.muted, fontWeight: FW.medium,
          }}
        >
          Collapse alerts
        </button>
      )}
    </div>
  );
}

// ─── HostDaySeverityStack ────────────────────────────────────────────────────
// Sprint 64 (Figma B2 1558:49). The HOST day-of severity surface: a CALM 3-tier
// CARD STACK, not the planner's dense clock-strip. Each alert is a card with a
// colored left rail + dot + tier eyebrow + bold headline + a quieter "→ your
// move" action line. Escalation = REDUCTION: critical reads loud (red rail),
// warning steady (amber), heads-up whispers (steel). Closes with "Everything
// else is on track." when nothing is critical. Host-gated by the caller
// (hostNavActive) — the planner never sees this; it keeps EventDayBar.
function HostDaySeverityStack({ alerts, dismissed, onDismiss, onNavTo, isMobile }) {
  const C = useT();
  const T = useType();
  const visible = (alerts || []).filter(a => !dismissed.has(a.id));
  // Tier order: critical first, then warning, then the calm heads-up tier.
  const rank = { critical: 0, warning: 1, 'heads-up': 2 };
  const ordered = [...visible].sort((a, b) => (rank[a.tier] ?? 3) - (rank[b.tier] ?? 3));
  const hasCritical = ordered.some(a => a.tier === 'critical');

  const tierCfg = (tier) => {
    if (tier === 'critical') return { rail: C.danger, eyebrow: 'CRITICAL · NEEDS YOU', wash: C.danger + '12' };
    if (tier === 'warning')  return { rail: C.warn,   eyebrow: 'WARNING',            wash: 'transparent' };
    return { rail: C.muted, eyebrow: 'HEADS-UP', wash: 'transparent' };
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 14, padding: isMobile ? '14px 16px 4px' : '16px 28px 6px' }}>
      {ordered.map((a) => {
        const cfg = tierCfg(a.tier);
        return (
          <div key={a.id} style={{
            position: 'relative',
            background: cfg.wash !== 'transparent' ? cfg.wash : C.surface,
            border: `1px solid ${C.border}`,
            borderRadius: 12,
            padding: isMobile ? '14px 16px 14px 18px' : '16px 18px 16px 20px',
            overflow: 'hidden',
          }}>
            {/* colored left rail */}
            <div style={{ position: 'absolute', left: 0, top: 0, bottom: 0, width: 4, background: cfg.rail, borderTopLeftRadius: 12, borderBottomLeftRadius: 12 }} />
            <div style={{ display: 'flex', alignItems: 'flex-start', gap: 8 }}>
              <div style={{ flex: 1, minWidth: 0 }}>
                {/* dot + tier eyebrow */}
                <div style={{ display: 'flex', alignItems: 'center', gap: 7, marginBottom: 6 }}>
                  <span style={{ width: 7, height: 7, borderRadius: '50%', background: cfg.rail, flexShrink: 0 }} />
                  <span style={{ fontSize: T.eyebrow, fontWeight: FW.heavy, letterSpacing: '0.12em', textTransform: 'uppercase', color: cfg.rail }}>{cfg.eyebrow}</span>
                </div>
                {/* bold headline */}
                <div style={{ fontSize: T.body, fontWeight: FW.bold, color: C.text, lineHeight: 1.3, marginBottom: a.move ? 6 : 0 }}>{a.headline}</div>
                {/* quieter "→ your move" action line */}
                {a.move && (
                  <button
                    onClick={() => a.navTo && onNavTo && onNavTo(a.navTo)}
                    disabled={!a.navTo}
                    style={{ display: 'flex', alignItems: 'flex-start', gap: 8, background: 'none', border: 'none', padding: 0, textAlign: 'left', cursor: a.navTo ? 'pointer' : 'default', fontFamily: 'inherit', width: '100%' }}
                  >
                    <span aria-hidden style={{ color: cfg.rail, flexShrink: 0, fontWeight: FW.bold }}>→</span>
                    <span style={{ fontSize: T.secondary, color: C.muted, lineHeight: 1.45 }}>{a.move}</span>
                  </button>
                )}
              </div>
              <button onClick={() => onDismiss(a.id)} aria-label="Dismiss" style={{ width: 28, height: 28, borderRadius: 7, border: 'none', background: 'transparent', color: C.muted, cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
                <Icon name="x" size={13} />
              </button>
            </div>
          </div>
        );
      })}
      {/* Closing reassurance — only when nothing critical is on the board. */}
      {!hasCritical && (
        <div style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '2px 2px 6px' }}>
          <span style={{ width: 7, height: 7, borderRadius: '50%', background: C.success, flexShrink: 0 }} />
          <span style={{ fontSize: T.secondary, color: C.muted }}>Everything else is on track.</span>
        </div>
      )}
    </div>
  );
}

// ─── VendorArrivalView ────────────────────────────────────────────────────────
const ARRIVAL_STATUS_CFG = {
  pending:   'Pending',
  arrived:   'Arrived',
  delayed:   'Delayed',
  completed: 'Done',
};

function VendorArrivalView({ vendors, setVendors, event, onOpenVendor }) {
  const C = useT();
  const T = useType();
  const s = makeS(C);
  const bp = useContext(BpCtx);
  const isMobile = bp === 'mobile';

  const arrivals = (vendors || [])
    .filter(v => v.arrivalTime && ['Confirmed','Contracted','Deposit Paid'].includes(v.status))
    .sort((a, b) => (a.arrivalTime || '').localeCompare(b.arrivalTime || ''));

  // Sprint 59H: confirmed vendors who don't have an arrivalTime yet are
  // invisible in the arrivals list above. On event day that's a problem —
  // surface them in a small "Missing arrival times" panel with an inline
  // mailto handoff (when v.contact exists) plus a route to the cockpit.
  const missingArrivalTime = (vendors || [])
    .filter(v => !v.arrivalTime && ['Confirmed','Contracted','Deposit Paid'].includes(v.status));

  const setStatus = (id, status) => setVendors(vs => vs.map(v => v.id === id ? { ...v, arrivalStatus: status } : v));

  // Sprint 59H: only short-circuit when BOTH lists are empty. If we have
  // confirmed vendors missing arrival times, we want to render the
  // "Missing arrival times" panel even when no arrivals are scheduled.
  if (arrivals.length === 0 && missingArrivalTime.length === 0) {
    // Sprint 60.L Phase 7: use locked EmptyStateCard component for
    // consistency with Documents / Guests / Budget empty surfaces.
    return (
      <EmptyStateCard
        tag="Arrivals"
        title="No vendor arrivals set."
        body="Add arrival times to confirmed vendors in the Vendors tab. Vendors with an arrival time will show here on event day so you can track who's on site, en route, or running late."
        primaryCta="Open vendors"
        onPrimary={() => onOpenVendor && onOpenVendor()}
      />
    );
  }

  const nowMin = new Date().getHours() * 60 + new Date().getMinutes();
  const isEvtDay = event.date === today8601();

  return (
    <div>
      <div style={{ display: 'flex', gap: 12, marginBottom: 16, flexWrap: 'wrap' }}>
        <StatCard label="Total"    value={arrivals.length} />
        <StatCard label="Arrived"  value={arrivals.filter(v => v.arrivalStatus === 'arrived').length}   color={C.success} />
        <StatCard label="Pending"  value={arrivals.filter(v => !v.arrivalStatus || v.arrivalStatus === 'pending').length} color={C.muted} />
        <StatCard label="Delayed"  value={arrivals.filter(v => v.arrivalStatus === 'delayed').length}   color={C.danger} />
      </div>

      {/* Sprint 59H — Missing arrival times panel. Confirmed vendors with no
          arrivalTime never appeared in the day-of arrivals list before; the
          planner had to discover them by absence. This panel makes the gap
          visible AND offers a one-tap email handoff (mailto, so it's honest
          — opens the planner's email app, doesn't send anything). */}
      {missingArrivalTime.length > 0 && (
        <div style={{ ...s.card, padding: '14px 16px', marginBottom: 16, borderLeft: `3px solid ${C.muted}` }}>
          <div style={{ fontSize: T.caption, fontWeight: FW.bold, letterSpacing: '0.08em', textTransform: 'uppercase', color: C.muted, marginBottom: 6 }}>
            Missing arrival times · {missingArrivalTime.length}
          </div>
          <div style={{ fontSize: T.caption, color: C.muted, marginBottom: 10, lineHeight: 1.5 }}>
            Confirmed vendors who haven't shared an arrival time yet. Ask them or open the vendor record to add it.
          </div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
            {missingArrivalTime.map(v => {
              const mailto = v.contact
                ? `mailto:${v.contact}?subject=${encodeURIComponent(`Arrival time for ${event?.name || 'event'}`)}&body=${encodeURIComponent(`Hi ${v.name || ''},\n\nWhat time should we expect you on event day? Just need it for the event day schedule and the team's check-in list.\n\nThanks.`)}`
                : null;
              return (
                <div key={v.id} style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '8px 10px', borderRadius: 8, background: C.bg, border: `1px solid ${C.border}`, flexWrap: 'wrap' }}>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ fontSize: T.secondary, fontWeight: FW.semibold, color: C.text, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{v.name}</div>
                    <div style={{ fontSize: T.caption, color: C.muted, marginTop: 1 }}>
                      {v.category || 'vendor'}{v.contact ? ` · ${v.contact}` : ' · no contact on file'}
                    </div>
                  </div>
                  {mailto ? (
                    <a href={mailto} target="_blank" rel="noopener noreferrer"
                      title="Opens your email app with a draft. Nothing is sent until you send it."
                      style={{ ...s.btn('ghost'), fontSize: T.caption, padding: '5px 10px', textDecoration: 'none', flexShrink: 0 }}>
                      Open email draft
                    </a>
                  ) : (
                    <span style={{ fontSize: T.caption, color: C.muted, fontStyle: 'italic', flexShrink: 0 }}>No email on file</span>
                  )}
                  {onOpenVendor && (
                    <button onClick={() => onOpenVendor(v.id, 'contract')} title={`Open ${v.name}'s contract details`}
                      style={{ ...s.btn('ghost'), fontSize: T.caption, padding: '5px 10px', flexShrink: 0 }}>
                      Open contract details →
                    </button>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* Sprint 60.L F11/DOF2: arrivals grouped by operational state with
          counts. Late first (highest priority). Then On site / En route /
          Coming up. The spec's 4th group ("Pending / no ETA") for vendors
          with NO arrival time is the Missing Arrival Times panel above. */}
      {(() => {
        const groups = { late: [], onsite: [], enroute: [], comingup: [] };
        arrivals.forEach(v => {
          const st = v.arrivalStatus || 'pending';
          const vm = parseMin(v.arrivalTime);
          const isLate = isEvtDay && vm !== null && vm < nowMin - 10 && st !== 'arrived' && st !== 'completed';
          if (st === 'arrived' || st === 'completed') groups.onsite.push(v);
          else if (isLate || st === 'delayed') groups.late.push(v);
          else if (vm !== null && vm - nowMin <= 60) groups.enroute.push(v);
          else groups.comingup.push(v);
        });
        const sections = [
          { id: 'late',     label: 'Late · needs attention', color: C.muted,    vendors: groups.late },
          { id: 'onsite',   label: 'On site',                 color: C.success, vendors: groups.onsite },
          { id: 'enroute',  label: 'En route',                color: C.muted,    vendors: groups.enroute },
          { id: 'comingup', label: 'Coming up',               color: C.muted,   vendors: groups.comingup },
        ].filter(sec => sec.vendors.length > 0);
        return sections.map(sec => (
          <div key={sec.id} style={{ marginBottom: 18 }}>
            <div style={{
              display: 'flex', alignItems: 'center', gap: 8,
              marginBottom: 10, paddingLeft: 4,
            }}>
              <span style={{
                fontSize: T.secondary, fontWeight: FW.bold,
                letterSpacing: '0.14em', textTransform: 'uppercase',
                color: sec.color,
              }}>{sec.label}</span>
              <span style={{
                fontSize: T.secondary, fontWeight: FW.bold, color: sec.color,
                background: sec.color + '22',
                borderRadius: 999, padding: '1px 9px', lineHeight: 1.5,
              }}>{sec.vendors.length}</span>
            </div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
        {sec.vendors.map(v => {
          const st     = v.arrivalStatus || 'pending';
          const vm     = parseMin(v.arrivalTime);
          const late   = isEvtDay && vm !== null && vm < nowMin - 10 && st !== 'arrived' && st !== 'completed';
          const stColor = st === 'arrived' ? C.success : st === 'delayed' || late ? C.danger : st === 'completed' ? C.warn : C.muted;
          return (
            <div key={v.id} style={{ ...s.card, padding: '14px 16px', borderLeft: `3px solid ${stColor}`, borderRadius: 14, boxShadow: 'inset 0 1px 0 rgba(255,255,255,0.05), 0 1px 0 rgba(255,255,255,0.02), 0 4px 10px rgba(0,0,0,0.30), 0 14px 28px rgba(0,0,0,0.22)' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 12 }}>
                <span style={{ fontFamily: 'monospace', fontSize: isMobile ? 18 : 20, fontWeight: FW.heavy, color: late ? C.danger : C.text, minWidth: 70, flexShrink: 0 }}>{fmtTime12(v.arrivalTime)}</span>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ fontWeight: FW.bold, fontSize: T.body, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{v.name}</div>
                  <div style={{ fontSize: T.caption, color: C.muted }}>{v.category}</div>
                  {late && <div style={{ fontSize: T.caption, fontWeight: FW.bold, color: C.danger, marginTop: 2 }}>OVERDUE</div>}
                </div>
                <span style={{ ...s.pill(stColor), fontWeight: FW.bold, flexShrink: 0, fontSize: T.caption }}>{ARRIVAL_STATUS_CFG[st] || st}</span>
              </div>
              {/* Status tap buttons — 48px min height, thumb-friendly */}
              <div style={{ display: 'flex', gap: 6 }}>
                {Object.entries(ARRIVAL_STATUS_CFG).map(([key, label]) => {
                  const kColor = key === 'arrived' ? C.success : key === 'delayed' ? C.danger : key === 'completed' ? C.warn : C.muted;
                  return (
                    <button key={key} onClick={() => setStatus(v.id, key)}
                      style={{ flex: 1, minHeight: 44, padding: '6px 4px', borderRadius: 8, border: `1.5px solid ${st === key ? kColor : C.border}`, background: st === key ? kColor + '18' : 'transparent', color: st === key ? kColor : C.muted, fontSize: T.caption, fontWeight: st === key ? 700 : 400, cursor: 'pointer', fontFamily: 'inherit', transition: 'all 0.1s' }}>
                      {label}
                    </button>
                  );
                })}
              </div>
              {(v.phone || v.notes || v.name) && (
                <div style={{ display: 'flex', gap: 12, marginTop: 10, alignItems: 'center', flexWrap: 'wrap', paddingTop: 10, borderTop: `1px solid ${C.border}` }}>
                  {v.phone && <a href={`tel:${v.phone}`} style={{ display: 'inline-flex', alignItems: 'center', gap: 5, fontSize: T.secondary, color: C.accent2, textDecoration: 'none', fontWeight: FW.semibold }}><Icon name="phone" size={13} /> {v.phone}</a>}
                  <a href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(v.name + (v.serviceArea ? ', ' + v.serviceArea : ''))}`} target="_blank" rel="noreferrer" style={{ display: 'inline-flex', alignItems: 'center', gap: 5, fontSize: T.secondary, color: C.accent2, textDecoration: 'none', fontWeight: FW.semibold }}><Icon name="pin" size={13} /> Directions</a>
                  {v.notes && <span style={{ fontSize: T.caption, color: C.muted, flex: 1, minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{v.notes}</span>}
                </div>
              )}
            </div>
          );
        })}
            </div>
          </div>
        ));
      })()}
    </div>
  );
}

// ─── DayTaskView ──────────────────────────────────────────────────────────────
function DayTaskView({ timeline, eventDate, setTimeline, eventType, foodChoices }) {
  const C  = useT();
  const T  = useType(); // responsive type tokens (parity sweep)
  const s  = makeS(C);
  const bp = useContext(BpCtx);
  const isMobile = bp === 'mobile';
  const [modalId, setModalId] = useState(null);
  const modalTask = timeline.find(t => t.id === modalId);

  const toggle   = (id) => setTimeline(t => t.map(r => r.id === id ? { ...r, done: !r.done } : r));
  const toggleSubtask = (taskId, subId) => setTimeline(prev => prev.map(r => {
    if (r.id !== taskId) return r;
    const updated = { ...r, subtasks: (r.subtasks || []).map(s => s.id === subId ? { ...s, done: !s.done } : s) };
    const visibleSubs = (updated.subtasks || []).filter(s => !subtaskSkipped(s, foodChoices));
    if (visibleSubs.length > 0 && visibleSubs.every(s => s.done)) updated.done = true;
    if (visibleSubs.some(s => !s.done)) updated.done = false;
    return updated;
  }));
  const upd      = (id, key, val) => setTimeline(t => t.map(r => r.id === id ? { ...r, [key]: val } : r));
  const del      = (id) => { setTimeline(t => t.filter(r => r.id !== id)); setModalId(null); };
  const isOverdue = (task) => isTaskOverdue(task, eventDate, eventType);

  const { now, next, later } = bucketTasks(timeline, eventDate, eventType);
  const doneCount = timeline.filter(t => t.done).length;

  // Sprint 60.P Day-of Now hero — live operational time + state-aware headline.
  // Re-derives every minute so the clock stays honest. Headline + eyebrow
  // follow the locked hero copy system from Home: state name → plain truth
  // → one action.
  const [tick, setTick] = useState(0);
  useEffect(() => {
    const id = setInterval(() => setTick(t => t + 1), 60_000);
    return () => clearInterval(id);
  }, []);
  const nowDate = new Date();
  const timeStr = nowDate.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' });
  const dateStr = nowDate.toLocaleDateString('en-US', { weekday: 'long', month: 'short', day: 'numeric' });
  void tick; // explicit dependency
  const hour = nowDate.getHours();
  const greet = hour < 12 ? 'Good morning' : hour < 17 ? 'Good afternoon' : 'Good evening';
  const heroState =
    now.length > 0   ? 'critical' :
    next.length > 0  ? 'attention' :
                       'allclear';
  const heroLabel =
    heroState === 'critical'  ? 'NOW · ACT IMMEDIATELY' :
    heroState === 'attention' ? 'NEXT UP' :
                                'ALL CLEAR';
  const heroLabelColor =
    heroState === 'critical'  ? C.danger :
    heroState === 'attention' ? C.muted :
                                C.success;
  const heroHeadline =
    heroState === 'critical'  ? (now[0]?.task || `${now.length} task${now.length !== 1 ? 's' : ''} need${now.length === 1 ? 's' : ''} you right now.`) :
    heroState === 'attention' ? (next[0]?.task || `${next.length} thing${next.length !== 1 ? 's' : ''} still ahead today.`) :
                                `${greet}. Day-of operations are running smoothly.`;
  const heroBody =
    heroState === 'critical'  ? (now.length > 1 ? `${now.length} need you now — knock them out before anything downstream stalls.` : 'Knock this out before anything downstream stalls.') :
    heroState === 'attention' ? `${next.length} thing${next.length !== 1 ? 's' : ''} still ahead today. Nothing's blocking this minute — stay ahead of the clock.` :
                                doneCount > 0 ? `${doneCount} task${doneCount !== 1 ? 's' : ''} complete. Nothing outstanding right now.` : 'No outstanding tasks.';
  const panelRaise = [
    'inset 0 1px 0 rgba(255,255,255,0.05)',
    '0 1px 0 rgba(255,255,255,0.02)',
    '0 4px 10px rgba(0,0,0,0.30)',
    '0 14px 28px rgba(0,0,0,0.22)',
  ].join(', ');

  const TaskSection = ({ title, tasks, color }) => {
    if (tasks.length === 0) return null;
    return (
      <div style={{ marginBottom: 18 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 6 }}>
          <div style={{ width: 8, height: 8, borderRadius: 2, background: color, flexShrink: 0 }} />
          <span style={{ fontSize: T.caption, fontWeight: FW.heavy, textTransform: 'uppercase', letterSpacing: '0.1em', color }}>{title}</span>
          <span style={{ fontSize: T.caption, color: C.muted }}>({tasks.length})</span>
        </div>
        {/* Sprint 60.P Day-of: TaskSection cards join the Studio Matte
            raise family. Border-radius bumped to match the hero. */}
        <div style={{ ...s.card, borderRadius: 14, boxShadow: panelRaise }}>
          {tasks.map(t => <TaskRow key={t.id} t={t} C={C} s={s} bp={bp} isOverdue={isOverdue} toggle={toggle} setModalId={setModalId} onToggleSubtask={toggleSubtask} foodChoices={foodChoices} />)}
        </div>
      </div>
    );
  };

  return (
    <div>
      {/* Sprint 60.P Day-of Now hero — big live clock + state-aware
          locked hero copy. Single command voice (NOW / NEXT UP / ALL
          CLEAR eyebrow), plain truth headline, body explains, the rail
          color signals urgency. Carbon panel + Studio Matte raise. */}
      <div style={{
        position: 'relative',
        marginBottom: 18,
        padding: isMobile ? '18px 18px 18px 21px' : '22px 26px 22px 29px',
        background: C.surface,
        border: `1px solid ${C.border}`,
        borderLeft: `3px solid ${heroLabelColor}`,
        borderRadius: 14,
        boxShadow: panelRaise,
      }}>
        {/* Top row: live time + locked-state eyebrow */}
        <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 14, marginBottom: 10, flexWrap: 'wrap' }}>
          <div>
            <div style={{
              fontSize: T.eyebrow,
              fontWeight: FW.bold,
              letterSpacing: '0.14em', textTransform: 'uppercase',
              color: heroLabelColor,
              padding: '2px 7px', borderRadius: 4,
              border: `1px solid ${heroLabelColor}55`,
              display: 'inline-block',
              marginBottom: 8,
            }}>
              {heroLabel}
            </div>
            <h2 style={{
              margin: 0,
              fontSize: T.display,
              fontWeight: FW.heavy, letterSpacing: '-0.025em',
              lineHeight: 1.2, color: C.text,
            }}>
              {heroHeadline}
            </h2>
          </div>
          {/* Live clock — operational weight */}
          <div style={{ textAlign: isMobile ? 'left' : 'right', flexShrink: 0 }}>
            <div style={{
              fontSize: T.statXl,
              fontWeight: FW.heavy, color: C.text,
              letterSpacing: '-0.03em', lineHeight: 1,
              fontVariantNumeric: 'tabular-nums',
            }}>
              {timeStr}
            </div>
            <div style={{ fontSize: T.caption, color: C.muted, marginTop: 4, letterSpacing: '0.04em' }}>
              {dateStr}
            </div>
          </div>
        </div>
        <p style={{
          margin: 0, fontSize: T.secondary,
          color: C.muted, lineHeight: 1.5, maxWidth: 720,
        }}>
          {heroBody}
        </p>
      </div>

      <div style={{ display: 'flex', gap: 12, marginBottom: 18, flexWrap: 'wrap' }}>
        <StatCard label="Now"   value={now.length}   color={now.length   > 0 ? C.danger  : C.muted} />
        <StatCard label="Next"  value={next.length}  color={next.length  > 0 ? C.muted    : C.muted} />
        <StatCard label="Later" value={later.length} color={later.length > 0 ? C.muted   : C.muted} />
        <StatCard label="Done"  value={doneCount}    color={doneCount    > 0 ? C.success : C.muted} />
      </div>
      <TaskSection title="Now — Act Immediately" tasks={now}   color={C.danger} />
      <TaskSection title="Next — Within 7 Days"  tasks={next}  color={C.muted}   />
      <TaskSection title="Later"                 tasks={later} color={C.muted}  />
      {modalTask && (
        <TaskModal task={modalTask} eventDate={eventDate} foodChoices={foodChoices} onClose={() => setModalId(null)}
          onChange={(key, val) => upd(modalTask.id, key, val)} onDelete={() => del(modalTask.id)} />
      )}
    </div>
  );
}

// ─── Event Planner ────────────────────────────────────────────────────────────

// Sprint 48: 'Command' added as the operational center of gravity — first in
// the list and the default landing tab.
// Sprint 49: 'Decisions' (Item 3) · 'Timeline' (Item 5) · 'Checklist' (Item 6)
// added as canonical L4 specialist tabs. 'Planning Tasks' remains as the
// list-based task editor — complementary to the other three lenses.
// Sprint 51 Path B: Overview retired as a canonical tab. Its unique signals
// were migrated — meal counts already lived in Guests; caterer drift moved
// to Command Center's vendor row; phase tips moved to Timeline tab's phase
// focus band. Command was already the default landing surface (Sprint 48).
//
// Sprint 57: Tab grouping tightened from 4 clusters (PLANNING / WORK /
// OPERATIONS / EXECUTION) to 3 friendlier ones (Plan / People / Day of).
// The 4-cluster grouping was structurally correct but too granular for
// first-time hosts per the v2 audit. Three buckets read like plain English:
//   • Plan      — money, schedule, decisions, conversation
//   • People    — clients, guests, vendors, seating
//   • Day of    — what happens on event day
// Command stays pinned at the top. Pure visual reorganization — no tab
// merges, no hidden tabs, no logic changes. The Sprint 46/49 specialist
// doctrine is preserved.
// Desktop sidebar order now mirrors the mobile 5-lane IA (Command / Planning /
// People / Money / Comms) so both viewports speak ONE vocabulary. Desktop has the
// room to also surface DAY OF + EVENT as their own sections (mobile hides those under
// "More"). Still pure visual reorganization — no tab merges, no hidden tabs, no
// routing change. Budget + Documents now cluster as MONEY (matching the mobile lane).
const PLANNER_TABS = [
  'Command',
  // MESSAGES — coordinators open this 10-30x per day
  'Communication',
  // PLANNING — the work of planning (List / Timeline / Checklist live inside 'Planning')
  'Planning', 'Decisions',
  // PEOPLE — who's involved
  'Client Intake', 'Vendors', 'Crew', 'Guests', 'Seating',
  // MONEY — budget + the files/contracts that cost money
  'Budget', 'Documents',
  // DAY OF — event-day surfaces (mobile: under "More")
  'Calendar', 'Event Day Schedule',
  // EVENT — identity + venue truth (mobile: under "More")
  'Event Details',
];
const TAB_GROUP_HEADERS = {
  'Communication':  'MESSAGES',
  'Planning':       'PLANNING',
  'Client Intake':  'PEOPLE',
  'Budget':         'MONEY',
  'Calendar':       'DAY OF',
  'Event Details':  'EVENT',
};
const TAB_ICONS = { 'Command': 'zap', 'Budget': 'dollar', 'Guests': 'users', 'Seating': 'seating', 'Vendors': 'store', 'Decisions': 'alertTriangle', 'Planning': 'check', 'Timeline': 'history', 'Checklist': 'check2', 'Planning Tasks': 'check', 'Calendar': 'calendar', 'Event Day Schedule': 'clipboard', 'Agenda': 'file', 'Communication': 'message', 'Documents': 'file', 'Event Details': 'settings' };
// Display labels — route keys are unchanged (routing depends on them),
// but the tab UI shows these friendlier names where they differ.
// Display-label overrides (routing keys are unchanged → zero routing risk).
// "Command" → "Overview" (the screen INSIDE an event; "Home" is reserved for the
// app's landing/all-events screen, so the two don't collide). "Run of Show" →
// "Event Day Schedule". Routing keys unchanged.
const TAB_LABELS = { 'Communication': 'Messages', 'Command': 'Overview', 'Event Day Schedule': 'Event Day Schedule' };

// ─── Sprint 59B: legacy → canonical tab-route normalization ────────────────
// Pre-59B the three planning surfaces shipped as separate L4 tabs:
//   'Planning Tasks' → list editor of event.timeline
//   'Timeline'       → TimelineBuilder visual phase grid
//   'Checklist'      → ChecklistGenerator
// All three wrote to the same event.timeline array. 59B merges them into a
// single 'Planning' tab with three view modes (list | timeline | checklist).
// Callers (Home attention queue, CommandCenter compressed CTAs, Sprint 57f
// '__compressed__' sentinel routes) still emit the legacy tab names — we
// normalize at the EventPlanner entrypoint so every old route lands in the
// right Planning view with the right item id, including the compressed
// sentinel. Returns: { tab, planningView, openId } — planningView is null
// for non-Planning targets.
const PLANNING_VIEWS = ['list', 'timeline', 'checklist'];
const normalizeEventTabRoute = (rawTab, itemId) => {
  if (rawTab === 'Overview')        return { tab: 'Command',  planningView: null,        openId: null };
  // Legacy alias: the day-of tab's route key was renamed 'Run of Show' →
  // 'Event Day Schedule' to match the UI. Persisted sessions / deep links / old
  // initialNav may still emit 'Run of Show' — resolve it to the new key.
  if (rawTab === 'Run of Show')     return { tab: 'Event Day Schedule', planningView: null, openId: itemId || null };
  if (rawTab === 'Planning Tasks')  return { tab: 'Planning', planningView: 'list',      openId: itemId || null };
  if (rawTab === 'Timeline')        return { tab: 'Planning', planningView: 'timeline',  openId: itemId || null };
  if (rawTab === 'Checklist')       return { tab: 'Planning', planningView: 'checklist', openId: itemId || null };
  return { tab: rawTab, planningView: null, openId: itemId || null };
};

// ─── Sprint 49: EventVendorsTab — canonical Vendors L4 specialist ────────────
// Wraps VendorPlanningWorkspace (Sprint 46 PLAN-overlay component) with the
// editing capabilities the simple Vendors component used to provide. Opens a
// VendorModal for full edits, supports Add, Delete, and `openId` selection
// from Command Center routing. This is the single source of truth for vendor
// work — the PLAN-overlay Vendors sidebar entry is being deprecated in the
// same sprint.
function EventVendorsTab({ event, setEvent, setVendors, budget, openId, openSection, sectionPing, ros, profile, allEvents, isMobile, onBack, onRouteToLinked, onSaveVendorToBank, promptDecision }) {
  const [editingVendor, setEditingVendor] = useState(null);
  // Sprint Add Vendor 10+ — wizard state. Replaces the single-shot
  // Add → VendorModal path with a 3-step flow that previews the
  // category playbook before the user creates anything.
  const [wizardOpen, setWizardOpen] = useState(false);
  const [lastAdded, setLastAdded] = useState(null);
  const themeC = useT();
  const themeS = makeS(themeC);
  const budgetCategories = (budget || []).map(b => b.category).filter(Boolean);
  // Sprint 54: AI Readiness Copilot wiring. Pulls the planner's BYOK Anthropic
  // key from AICtx — if absent, aiAvailable is false and the cockpit shows the
  // rule-based preview only. onAskAi wraps the existing askClaude() helper
  // (browser-direct call) so the plan module stays insulated from fetch logic.
  const aiKey = useAIKey();
  const aiAvailable = aiInputOn(aiKey);
  const onAskAi = aiAvailable
    ? (prompt) => askNGW('readiness', prompt, { maxTokens: 1200, aiKey })
    : null;
  // Sprint 50 gap fix #15: append entries to the targeted vendor's log so the
  // F Activity tab can write back to host state. Uses today's date (ISO date
  // string) so feed sorting works consistently across entries.
  const onAddLog = (vendorId, text) => {
    if (!vendorId || !text) return;
    const today = new Date().toISOString().slice(0, 10);
    setVendors(prev => (prev || []).map(v => v.id === vendorId
      ? { ...v, log: [...(v.log || []), { date: today, text }] }
      : v
    ));
  };
  // Sprint 51 follow-up #1: caterer drift one-click update. Sets
  // event.catererCount AND appends an activity log entry so the vendor
  // history records what changed and when. Closes the loop migrated from
  // the retired Overview tab.
  const onMarkCatererUpdated = (vendorId, count) => {
    if (typeof count !== 'number') return;
    setEvent(e => ({ ...e, catererCount: count }));
    onAddLog(vendorId, `Headcount updated to ${count} confirmed guests.`);
  };
  // Sprint 56c: shallow-merge mutator powering the cockpit's NEXT ACTION CTAs
  // (Mark balance paid / Mark contract signed / Mark confirmed / etc.). Goes
  // through the same setVendors wrapper as the legacy modal flow, so cloud
  // sync + localStorage persistence all keep working.
  const onPatchVendor = (vendorId, patch) => {
    if (!vendorId || !patch) return;
    // first_value: a vendor commitment (status → Confirmed) or a recorded payment
    // is an engine-directed action. The user-level once-guard dedupes across both.
    if (patch.status === 'Confirmed') recordFirstValue('vendor_confirmed', event, 'vendor_stepper');
    if (patch.depositPaid === true || patch.balancePaid === true) recordFirstValue('payment_recorded', event, 'vendor_payment');
    // Sprint 58C — Decision Memory: a vendor commitment is a meaningful decision.
    // Prompt for the rationale (non-blocking; the status change applies regardless).
    const oldV = (event.vendors || []).find(v => v.id === vendorId);
    if (patch.status === 'Confirmed' && oldV && oldV.status !== 'Confirmed' && promptDecision) {
      promptDecision({ decisionType: 'vendor_selection', subjectId: vendorId, subjectLabel: oldV.name || 'this vendor',
        decision: `Confirmed ${oldV.name || 'vendor'}${oldV.category ? ' (' + oldV.category + ')' : ''}`, question: 'Why this vendor?' });
    }
    setVendors(prev => (prev || []).map(v => v.id === vendorId ? { ...v, ...patch } : v));
  };
  // Sprint Add Vendor 10+ — Create handler. Runs once at the end of
  // Step 3. Persists the vendor + selected promise tracker, optionally
  // saves a snapshot to the workspace vendor bank, and surfaces the
  // success state. No keystroke-autosave for the wizard flow — the
  // record exists only after Create.
  const handleCreate = ({ identity, selectedPromiseKeys, saveToBank, details = {} }) => {
    // Board #2: the wizard must capture VALUES, not just checkbox labels. A vendor
    // born with cost:0 / no COI is a record that tracks nothing — the budget reads
    // $0, the deposit clock never ticks, and the dock board stays dark. Persist the
    // operational facts the planner entered so the engine lights up from creation.
    const num = (x) => { const n = Number(x); return Number.isFinite(n) && n > 0 ? n : 0; };
    const cost = num(details.cost);
    const depositAmt = num(details.depositAmt);
    const coiRequired = !!details.coiRequired;
    const newVendor = {
      id: uid(),
      name: identity.name.trim(),
      category: identity.category,
      // Tie the new vendor into the event budget from the start — without a
      // budgetCategory it never shows up in the Budget sections (board: "budget
      // sections not working on vendor creation").
      budgetCategory: identity.category,
      cost, depositAmt, depositPaid: false, balancePaid: false,
      payDueDate: details.payDueDate || null,
      arrivalTime: details.arrivalTime || '',
      tags: Array.isArray(identity.tags) ? [...identity.tags] : [],
      // A captured quote means the vendor is genuinely 'Quoted', not merely
      // 'Considering' — but we never auto-promote to a committed stage (that's
      // the planner's call as they contract).
      status: cost > 0 ? 'Quoted' : 'Considering',
      // COI seeded at creation so the day-of dock board + readiness gate light up
      // now, not weeks later. 'requested' = required-but-not-yet-collected.
      ...(coiRequired ? {
        coiStatus: 'requested', coiVerified: false,
        insuranceStatus: 'COI requested',
        ...(details.coiExpiry ? { coiExpiryDate: details.coiExpiry } : {}),
        ...(details.coiHolder ? { coiHolder: details.coiHolder.trim() } : {}),
      } : {}),
      contact_name: (identity.contactName || '').trim(),
      contact: (identity.email || '').trim(), // VendorModal uses `contact` for email
      email: (identity.email || '').trim(),
      phone: (identity.phone || '').trim(),
      website: (identity.website || '').trim(),
      // Persist the wizard's playbook selection so VendorModal can
      // hydrate the Promise Tracker view without re-deriving.
      selectedPromiseKeys: Array.isArray(selectedPromiseKeys) ? [...selectedPromiseKeys] : [],
      createdAt: new Date().toISOString().slice(0, 10),
    };
    // Sprint 61B — stamp a stable Vendor Bank id at the create site so cross-event
    // vendor history stops fragmenting on normalized names. Written UNCONDITIONALLY
    // (clean capture from event #1); only the READER surface stays pi.memory-gated.
    // Resolve-or-create a bank entry keyed on name+category, then stamp bankId.
    try {
      const bank = readVendorBank();
      let bankId = resolveBankId(bank, newVendor.name, newVendor.category);
      if (!bankId) {
        bankId = `pv-${Date.now()}`;
        saveVendor({
          id: bankId,
          name: newVendor.name,
          category: newVendor.category,
          contact: newVendor.email || '',
          phone: newVendor.phone || '',
          website: newVendor.website || '',
          notes: '',
          rehireCount: 0,
          addedAt: new Date().toISOString(),
        });
      }
      newVendor.bankId = bankId;
    } catch { /* bank stamp is best-effort; never block vendor creation */ }
    setVendors(prev => [...(prev || []), newVendor]);
    // Seed the event-level COI requirement so the readiness gate (event.coiNeeded)
    // and the dock board recognize this event collects insurance — once set, every
    // future vendor inherits the expectation.
    if (coiRequired && typeof setEvent === 'function') {
      setEvent(prev => (prev && prev.coiNeeded === 'required') ? prev : { ...prev, coiNeeded: 'required' });
    }
    let savedToBank = false;
    if (saveToBank && typeof onSaveVendorToBank === 'function') {
      try { onSaveVendorToBank(newVendor); savedToBank = true; }
      catch { savedToBank = false; }
    }
    setLastAdded({ ...newVendor, savedToBank });
    setWizardOpen(false);
  };

  return (
    <>
      {/* Caterer reconciliation — HOST view only. The host flipped to cooking everything but a
          caterer is still on their hire list. Calm, one-tap removal; never auto-delete a manual
          entry (foodApproach/hostIsCooking = the single-source food lever). */}
      {(() => {
        let isHostV = false; try { isHostV = hostNavActive(event); } catch {}
        if (!isHostV || !hostIsCooking(event)) return null;
        const caterers = (event.vendors || []).filter(v => v && /cater/i.test(v.category || ''));
        if (!caterers.length) return null;
        const names = caterers.map(v => (v.name || '').trim()).filter(Boolean);
        const label = names.length ? names.join(', ') : `the caterer${caterers.length > 1 ? 's' : ''}`;
        const plural = caterers.length > 1;
        const tone = themeC.warn || themeC.accentTopGrad || themeC.accent;
        const removeCaterers = () => { const ids = new Set(caterers.map(v => v.id)); setVendors(prev => (prev || []).filter(v => !ids.has(v.id))); try { feedbackSelect(); } catch {} };
        return (
          <div style={{ margin: '0 0 16px', padding: '14px 16px', borderRadius: 12, background: `${tone}12`, border: `1px solid ${tone}38`, display: 'flex', flexDirection: 'column', gap: 10 }}>
            <div style={{ fontSize: 15, color: themeC.text, lineHeight: 1.45 }}>You’re cooking everything now — but <strong>{label}</strong> {plural ? 'are' : 'is'} still on your hire list.</div>
            <div style={{ display: 'flex', alignItems: 'center', gap: 12, flexWrap: 'wrap' }}>
              <button type="button" onClick={removeCaterers} style={{ padding: '8px 16px', borderRadius: 9, border: 'none', cursor: 'pointer', background: themeC.accent, color: '#fff', fontWeight: FW.bold, fontFamily: 'inherit', fontSize: 14 }}>Remove {plural ? 'them' : 'it'}</button>
              <span style={{ fontSize: 13, color: themeC.muted }}>or keep {plural ? 'them' : 'it'} if you still need {plural ? 'them' : 'it'}.</span>
            </div>
          </div>
        );
      })()}
      <VendorPlanningWorkspace
        event={event}
        allEvents={allEvents}
        isMobile={isMobile}
        openId={openId}
        openSection={openSection}
        sectionPing={sectionPing}
        onBack={onBack}
        onEditVendor={(v) => setEditingVendor(v)}
        onAddVendor={() => setWizardOpen(true)}
        onAddLog={onAddLog}
        onMarkCatererUpdated={onMarkCatererUpdated}
        onPatchVendor={onPatchVendor}
        aiAvailable={aiAvailable}
        onAskAi={onAskAi}
        onRouteToLinked={onRouteToLinked}
      />
      {wizardOpen && (
        <AddVendorWizard
          C={themeC} s={themeS}
          event={event}
          bankAvailable={typeof onSaveVendorToBank === 'function'}
          alreadyInBank={readVendorBank()}
          onCancel={() => setWizardOpen(false)}
          onCreate={handleCreate}
        />
      )}
      {editingVendor && (
        <VendorModal
          vendor={editingVendor}
          budgetCategories={budgetCategories}
          onClose={() => setEditingVendor(null)}
          onChange={(updated) => {
            setEditingVendor(updated);
            setVendors(prev => {
              const exists = (prev || []).some(v => v.id === updated.id);
              if (exists) return prev.map(v => v.id === updated.id ? updated : v);
              return [...(prev || []), updated];
            });
          }}
          onDelete={() => {
            setVendors(prev => (prev || []).filter(v => v.id !== editingVendor.id));
            setEditingVendor(null);
          }}
          event={event}
          ros={ros}
          profile={profile}
        />
      )}
      {lastAdded && (
        <VendorCreatedSuccess
          C={themeC} s={themeS}
          vendor={lastAdded}
          eventName={event?.name || 'this event'}
          savedToBank={!!lastAdded.savedToBank}
          promiseCount={(lastAdded.selectedPromiseKeys || []).length}
          evidenceCount={(() => {
            try {
              const pb = getVendorPlaybook(lastAdded.category);
              const need = new Set(pb?.evidenceNeeded || []);
              return (lastAdded.selectedPromiseKeys || []).filter(k => need.has(k)).length;
            } catch { return 0; }
          })()}
          onClose={() => setLastAdded(null)}
          onOpen={() => { setEditingVendor(lastAdded); setLastAdded(null); }}
          onAddAnother={() => { setLastAdded(null); setWizardOpen(true); }}
          onDraftFollowUp={() => {
            try {
              const promises = inferPromisesFromVendor(lastAdded, event);
              const draft = generateVendorFollowUpDraft(lastAdded, event, promises, { commLive: false, emailEnabled: false });
              const text = `Subject: ${draft.subject}\n\n${draft.body}`;
              // Two honest actions per the 6-state comms contract:
              //   1. Copy to clipboard (always allowed)
              //   2. Open mailto draft if vendor has an email (always
              //      allowed — opens the user's mail client, no send).
              if (navigator?.clipboard?.writeText) {
                navigator.clipboard.writeText(text);
              } else {
                const el = document.createElement('textarea');
                el.value = text;
                document.body.appendChild(el);
                el.select();
                try { document.execCommand('copy'); } catch {}
                document.body.removeChild(el);
              }
              const to = (lastAdded.email || '').trim();
              if (to) {
                const mailto = `mailto:${encodeURIComponent(to)}`
                  + `?subject=${encodeURIComponent(draft.subject || '')}`
                  + `&body=${encodeURIComponent(draft.body || '')}`;
                try { window.open(mailto, '_blank'); } catch {}
              }
              return { copied: true, mailtoOpened: !!to };
            } catch { return { copied: false, mailtoOpened: false }; }
          }}
        />
      )}
    </>
  );
}

// ─── Sprint Add Vendor 10+ — 3-step wizard ─────────────────────────────
// Replaces the single-shot Add → VendorModal path. The wizard answers
// the 8 No-Guesswork questions before any record is written:
//   Step 1 (Who):    Identity + bank toggle + "no messages will be sent"
//   Step 2 (Track):  Category playbook preview with editable promise checklist
//                    and one-line why-it-matters per item. Evidence-needed
//                    items are labeled.
//   Step 3 (Review): Itemized summary + Create.
// Nothing is persisted until Create is tapped on Step 3.
function AddVendorWizard({ C, s, event, bankAvailable, alreadyInBank = [], onCancel, onCreate }) {
  const steelTop  = C.accentTopGrad || C.accent;
  const steelDeep = C.accentDeep    || C.accent;
  // Lock background scroll behind the wizard.
  useEffect(() => {
    const prev = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => { document.body.style.overflow = prev; };
  }, []);
  const [step, setStep] = useState(1);
  const [identity, setIdentity] = useState({
    name: '', category: '', tags: [], contactName: '', email: '', phone: '', website: '',
  });
  const [saveToBank, setSaveToBank] = useState(false);
  // Board #2: capture the operational VALUES at creation. At-home gatherings are
  // not business engagements, so COI defaults OFF there; a venue event defaults
  // COI ON with the venue pre-filled as the certificate holder.
  const atHome = !!(event && isAtHomeType(event.type));
  const [details, setDetails] = useState(() => ({
    cost: '', depositAmt: '', payDueDate: '', arrivalTime: '',
    coiRequired: !!(event && !atHome && event.venue),
    coiHolder: (event && event.venue) || '',
    coiExpiry: '',
  }));
  const setDet = (k, v) => setDetails(d => ({ ...d, [k]: v }));
  const lblStyle = { display: 'block', fontSize: T.caption, fontWeight: FW.bold, letterSpacing: '0.06em', textTransform: 'uppercase', color: C.muted, marginBottom: 4 };
  // Engine-aware category scoping: only present the categories THIS event type
  // calls for (board: "don't show options the event doesn't call for"), with an
  // escape hatch to the full list. Derived from the same rosters the engine uses.
  const relevantCats = useMemo(() => {
    if (!event) return null;
    const types = eventTypesOf(event);
    const cats = types && types.length ? mergeVendorStubs(...types) : proposedVendorCategories(event.type);
    return cats && cats.length ? [...new Set(cats)] : null;
  }, [event]);
  const [showAllCats, setShowAllCats] = useState(false);
  const useFilteredCats = relevantCats && !showAllCats;
  // Playbook for the chosen category, derived live.
  const playbook = useMemo(() => identity.category ? getVendorPlaybook(identity.category) : null, [identity.category]);
  const evidenceSet = useMemo(() => new Set(playbook?.evidenceNeeded || []), [playbook]);
  const whyMap = playbook?.whyItMattersByField || {};
  // Default: all common promises selected. User can uncheck on Step 2.
  // Reset whenever the category changes.
  const [selectedKeys, setSelectedKeys] = useState(() => new Set());
  useEffect(() => {
    if (!playbook) { setSelectedKeys(new Set()); return; }
    setSelectedKeys(new Set((playbook.commonPromises || []).map(p => p.key)));
  }, [playbook]);


  const canContinue1 = identity.name.trim().length > 0 && identity.category.length > 0;
  const dedupeKey = `${identity.name.toLowerCase().trim()}|${identity.category.toLowerCase().trim()}`;
  const alreadyInBankHit = (alreadyInBank || []).some(v => `${(v.name || '').toLowerCase().trim()}|${(v.category || '').toLowerCase().trim()}` === dedupeKey);

  const togglePromise = (key) => {
    setSelectedKeys(prev => {
      const next = new Set(prev);
      if (next.has(key)) next.delete(key); else next.add(key);
      return next;
    });
  };

  const selectedCount = selectedKeys.size;
  const evidenceCount = useMemo(() => {
    let n = 0;
    for (const k of selectedKeys) if (evidenceSet.has(k)) n++;
    return n;
  }, [selectedKeys, evidenceSet]);

  const sheetStyle = {
    position: 'fixed', left: '50%', top: '50%',
    transform: 'translate(-50%, -50%)',
    width: 'min(520px, calc(100vw - 24px))',
    maxHeight: 'calc(100vh - 48px)', display: 'flex', flexDirection: 'column',
    ...metalEdge(C),
    borderRadius: 16,
    boxShadow: '0 20px 60px rgba(0,0,0,0.50)',
    zIndex: 71,
  };

  const StepDots = () => (
    <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
      {[1, 2, 3].map(n => (
        <span key={n} aria-current={n === step ? 'step' : undefined} style={{
          width: n === step ? 24 : 8, height: 8, borderRadius: 4,
          background: n <= step ? steelTop : C.border,
          transition: 'all 200ms ease',
        }} />
      ))}
      <span style={{ fontSize: T.caption, fontWeight: FW.heavy, letterSpacing: '0.12em', color: C.muted, textTransform: 'uppercase', marginLeft: 6 }}>
        Step {step} of 3
      </span>
    </div>
  );

  const PrimaryButton = ({ children, onClick, disabled, testId }) => (
    <button
      type="button"
      onClick={onClick}
      disabled={disabled}
      data-testid={testId}
      style={{
        background: disabled
          ? `${C.border}`
          : `linear-gradient(180deg, ${steelTop} 0%, ${steelDeep} 100%)`,
        color: disabled ? C.muted : (C.accentText || '#fff'),
        border: 'none', borderRadius: 8,
        padding: '9px 18px', fontSize: T.secondary, fontWeight: FW.bold,
        cursor: disabled ? 'not-allowed' : 'pointer',
        boxShadow: disabled ? 'none' : 'inset 0 1px 0 rgba(255,255,255,0.12), 0 1px 2px rgba(0,0,0,0.32)',
      }}>
      {children}
    </button>
  );

  return (
    <>
      <div onClick={onCancel} style={{
        position: 'fixed', inset: 0,
        background: 'rgba(0,0,0,0.55)',
        backdropFilter: 'blur(6px)', WebkitBackdropFilter: 'blur(6px)',
        zIndex: 70,
      }} />
      <div role="dialog" aria-label={`Add vendor — step ${step} of 3`} data-testid="add-vendor-wizard" style={sheetStyle}>
        {/* Header */}
        <div style={{ padding: '18px 22px 12px', borderBottom: `1px solid ${C.border}`, flexShrink: 0 }}>
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 10 }}>
            <div style={{ fontSize: T.eyebrow, fontWeight: FW.heavy, letterSpacing: '0.16em', color: steelTop, textTransform: 'uppercase' }}>Add Vendor</div>
            <button type="button" aria-label="Close wizard" onClick={onCancel} style={{ ...s.btn('ghost'), fontSize: T.body, padding: '2px 8px', marginTop: -2 }}>✕</button>
          </div>
          <div style={{ fontSize: T.title, fontWeight: FW.bold, color: C.text, lineHeight: 1.25, marginBottom: 10 }}>
            {step === 1 && <>Who is this vendor?</>}
            {step === 2 && <>What should Event Boss track?</>}
            {step === 3 && <>Review and create</>}
          </div>
          <StepDots />
        </div>

        {/* Body */}
        <div style={{ flex: 1, overflowY: 'auto', padding: '16px 22px 18px' }}>
          {step === 1 && (
            <>
              <div style={{ background: C.bg, border: `1px solid ${C.border}`, borderRadius: 10, padding: '10px 12px', marginBottom: 14, display: 'flex', alignItems: 'center', gap: 10 }}>
                <span aria-hidden style={{ width: 22, height: 22, borderRadius: '50%', background: `${steelTop}22`, color: steelTop, display: 'inline-flex', alignItems: 'center', justifyContent: 'center', fontSize: T.caption, fontWeight: FW.heavy }}>✓</span>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ fontSize: T.caption, fontWeight: FW.bold, letterSpacing: '0.10em', color: C.muted, textTransform: 'uppercase' }}>Linked event</div>
                  <div style={{ fontSize: T.secondary, fontWeight: FW.semibold, color: C.text, marginTop: 1 }}>{event?.name || 'this event'}</div>
                </div>
              </div>

              {/* At-home gatherings aren't full-service business events — set the
                  expectation so the planner adds only what they're truly hiring. */}
              {event && isAtHomeType(event.type) && (
                <div style={{ background: C.bg, border: `1px solid ${C.border}`, borderRadius: 10, padding: '10px 12px', marginBottom: 14, fontSize: T.secondary, color: C.muted, lineHeight: 1.5 }}>
                  🏠 <span style={{ color: C.text, fontWeight: FW.semibold }}>Hosting at home.</span> This isn't a full-service event — add only the few vendors you're actually hiring (caterer, bar, rentals). Many at-home gatherings need none at all.
                </div>
              )}

              <div style={{ marginBottom: 12 }}>
                <label htmlFor="av-name" style={{ display: 'block', fontSize: T.caption, fontWeight: FW.bold, color: C.muted, textTransform: 'uppercase', letterSpacing: '0.06em', marginBottom: 5 }}>
                  Vendor name <span style={{ color: steelTop }}>*</span>
                </label>
                <input
                  id="av-name"
                  data-testid="av-name"
                  value={identity.name}
                  onChange={e => setIdentity(d => ({ ...d, name: e.target.value }))}
                  placeholder="Bluebell Venue"
                  style={s.input}
                  autoFocus
                />
              </div>

              <div style={{ marginBottom: 14 }}>
                <label htmlFor="av-category" style={{ display: 'block', fontSize: T.caption, fontWeight: FW.bold, color: C.muted, textTransform: 'uppercase', letterSpacing: '0.06em', marginBottom: 5 }}>
                  Category <span style={{ color: steelTop }}>*</span>
                </label>
                <select
                  id="av-category"
                  data-testid="av-category"
                  value={identity.category}
                  onChange={e => setIdentity(d => ({ ...d, category: e.target.value }))}
                  style={{ ...s.input, cursor: 'pointer' }}>
                  <option value="">Choose one…</option>
                  {useFilteredCats ? (
                    <optgroup label={`Suggested for ${eventTypeLabel(event) || 'this event'}`}>
                      {relevantCats.map(c => <option key={c} value={c}>{c}</option>)}
                      {identity.category && !relevantCats.includes(identity.category) && <option value={identity.category}>{identity.category}</option>}
                    </optgroup>
                  ) : (
                    CATEGORY_GROUPS.map(g => (
                      <optgroup key={g.group} label={g.group}>
                        {g.cats.map(c => <option key={c} value={c}>{c}</option>)}
                      </optgroup>
                    ))
                  )}
                </select>
                {relevantCats && (
                  <button type="button" onClick={() => setShowAllCats(v => !v)}
                    style={{ background: 'none', border: 'none', padding: '6px 0 0', color: C.accent, fontSize: T.caption, fontWeight: FW.semibold, cursor: 'pointer', fontFamily: 'inherit' }}>
                    {showAllCats ? `Show only ${eventTypeLabel(event) || 'relevant'} categories` : 'Need something else? Show all categories'}
                  </button>
                )}
                {identity.category && playbook && (
                  <div style={{ fontSize: T.caption, color: C.muted, marginTop: 6, lineHeight: 1.5 }}>{playbook.plainDescription}</div>
                )}
                {/* Attribute tags — optional cross-cutting qualities. */}
                <div style={{ marginTop: 12 }}>
                  <div style={{ fontSize: T.caption, color: C.muted, marginBottom: 6 }}>Attributes <span style={{ opacity: 0.7 }}>(optional)</span></div>
                  <TagChips value={identity.tags} onChange={(tags) => setIdentity(d => ({ ...d, tags }))} options={attrsForVendorCategory(identity.category)} />
                </div>
              </div>

              <div style={{ marginBottom: 12 }}>
                <div style={{ fontSize: T.caption, fontWeight: FW.bold, letterSpacing: '0.10em', color: C.muted, textTransform: 'uppercase', marginBottom: 6 }}>Optional · add later</div>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8 }}>
                  <input data-testid="av-contact-name" value={identity.contactName} onChange={e => setIdentity(d => ({ ...d, contactName: e.target.value }))} placeholder="Contact name" style={s.input} />
                  <input data-testid="av-phone" value={identity.phone} onChange={e => setIdentity(d => ({ ...d, phone: e.target.value }))} placeholder="Phone" style={s.input} />
                  <input data-testid="av-email" value={identity.email} onChange={e => setIdentity(d => ({ ...d, email: e.target.value }))} placeholder="Email" type="email" style={{ ...s.input, gridColumn: '1 / -1', borderColor: (identity.email && !isEmail(identity.email)) ? C.danger : undefined }} />
                  <input data-testid="av-website" value={identity.website} onChange={e => setIdentity(d => ({ ...d, website: e.target.value }))} placeholder="Website (https://…)" type="url" style={{ ...s.input, gridColumn: '1 / -1' }} />
                </div>
              </div>

              <label style={{ display: 'flex', alignItems: 'flex-start', gap: 10, padding: '10px 12px', background: C.bg, border: `1px solid ${C.border}`, borderRadius: 10, marginBottom: 10, cursor: bankAvailable ? 'pointer' : 'not-allowed', opacity: bankAvailable ? 1 : 0.6 }}>
                <input
                  type="checkbox"
                  data-testid="av-bank-toggle"
                  checked={saveToBank}
                  onChange={e => setSaveToBank(e.target.checked)}
                  disabled={!bankAvailable}
                  style={{ marginTop: 3, width: 18, height: 18, accentColor: steelTop }}
                />
                <div style={{ flex: 1 }}>
                  <div style={{ fontSize: T.secondary, fontWeight: FW.semibold, color: C.text }}>Save to my vendor bank</div>
                  <div style={{ fontSize: T.caption, color: C.muted, marginTop: 2, lineHeight: 1.45 }}>
                    {bankAvailable
                      ? alreadyInBankHit
                        ? 'Already in your bank — toggling this won\'t duplicate.'
                        : 'Reuse this vendor on future events without re-typing details.'
                      : 'Vendor bank wiring not available in this view.'}
                  </div>
                </div>
              </label>

              {/* Sprint Add Vendor 10+ — explicit 4-line trust block per
                  spec. No tooltip, no ambiguity. */}
              <div data-testid="av-trust-block" style={{ background: C.bg, border: `1px solid ${C.border}`, borderRadius: 10, padding: '10px 12px', marginTop: 10 }}>
                {[
                  'Messages sent: None',
                  'Notifications sent: None',
                  'Client/vendor will not be contacted',
                  'Vendor is not created until final review',
                ].map((line, i) => (
                  <div key={line} style={{ display: 'flex', alignItems: 'center', gap: 8, paddingTop: i ? 6 : 0 }}>
                    <span aria-hidden style={{ flexShrink: 0, color: steelTop, fontSize: T.caption, fontWeight: FW.heavy }}>✓</span>
                    <span style={{ fontSize: T.caption, color: C.text, lineHeight: 1.45 }}>{line}</span>
                  </div>
                ))}
              </div>
            </>
          )}

          {step === 2 && (
            <>
              {!playbook && (
                <div style={{ fontSize: T.secondary, color: C.muted, padding: 20, textAlign: 'center' }}>Pick a category in Step 1 to see the playbook.</div>
              )}
              {playbook && (
                <>
                  <div style={{ fontSize: T.secondary, color: C.muted, lineHeight: 1.55, marginBottom: 10 }}>
                    For a <span style={{ color: C.text, fontWeight: FW.bold }}>{playbook.displayName}</span>, Event Boss usually tracks these. Uncheck anything that doesn't fit — <span style={{ color: C.text, fontWeight: FW.semibold }}>you can change this any time later</span>.
                  </div>
                  {/* PT-7: select-all / clear-all so the planner isn't toggling 10 boxes by hand. */}
                  <div style={{ display: 'flex', gap: 8, marginBottom: 10 }}>
                    <button type="button" onClick={() => setSelectedKeys(new Set((playbook.commonPromises || []).map(p => p.key)))}
                      style={{ background: 'transparent', border: `1px solid ${C.border}`, borderRadius: 7, color: C.accent, fontFamily: 'inherit', fontSize: T.caption, fontWeight: FW.bold, padding: '6px 11px', minHeight: 34, cursor: 'pointer' }}>Select all</button>
                    <button type="button" onClick={() => setSelectedKeys(new Set())}
                      style={{ background: 'transparent', border: `1px solid ${C.border}`, borderRadius: 7, color: C.muted, fontFamily: 'inherit', fontSize: T.caption, fontWeight: FW.bold, padding: '6px 11px', minHeight: 34, cursor: 'pointer' }}>Clear all</button>
                  </div>
                  <div style={{ background: C.bg, border: `1px solid ${C.border}`, borderRadius: 10 }}>
                    {(playbook.commonPromises || []).map((p, idx, arr) => {
                      const checked = selectedKeys.has(p.key);
                      const evi = evidenceSet.has(p.key);
                      return (
                        <label key={p.key} data-testid={`av-promise-${p.key}`}
                          onMouseEnter={e => { e.currentTarget.style.background = C.surface2 || C.surface; }}
                          onMouseLeave={e => { e.currentTarget.style.background = 'transparent'; }}
                          style={{
                          display: 'flex', alignItems: 'flex-start', gap: 12,
                          padding: '12px 14px', minHeight: 44, boxSizing: 'border-box',
                          borderBottom: idx < arr.length - 1 ? `1px solid ${C.border}` : 'none',
                          cursor: 'pointer', background: 'transparent', transition: 'background 0.12s',
                        }}>
                          <input
                            type="checkbox"
                            checked={checked}
                            onChange={() => togglePromise(p.key)}
                            style={{ marginTop: 2, width: 18, height: 18, flexShrink: 0, accentColor: steelTop }}
                          />
                          <div style={{ flex: 1, minWidth: 0 }}>
                            {/* PT-4: label takes the space, the badge stays anchored on the same line. */}
                            <div style={{ display: 'flex', alignItems: 'flex-start', gap: 8 }}>
                              <span style={{ flex: 1, minWidth: 0, fontSize: T.secondary, fontWeight: FW.semibold, color: C.text, lineHeight: 1.35 }}>{p.label}</span>
                              {evi && (
                                <span style={{
                                  fontSize: T.caption, fontWeight: FW.heavy, letterSpacing: '0.08em',
                                  textTransform: 'uppercase', color: steelTop,
                                  padding: '2px 6px', borderRadius: 3, whiteSpace: 'nowrap', flexShrink: 0,
                                  border: `1px solid ${steelTop}55`,
                                }}>Proof needed</span>
                              )}
                            </div>
                            {/* PT-7: never leave a checkbox unexplained — show the why, or an honest default note. */}
                            <div style={{ fontSize: T.caption, color: C.muted, marginTop: 3, lineHeight: 1.5 }}>
                              {whyMap[p.key] || 'Tracked by default — uncheck if it doesn’t apply to this vendor.'}
                            </div>
                          </div>
                        </label>
                      );
                    })}
                  </div>
                  <div data-testid="av-promise-summary" style={{ fontSize: T.caption, color: C.muted, marginTop: 10, lineHeight: 1.5 }}>
                    <span data-testid="av-promise-count" style={{ color: C.text, fontWeight: FW.bold }}>{selectedCount}</span> tracked · <span data-testid="av-evidence-count" style={{ color: C.text, fontWeight: FW.bold }}>{evidenceCount}</span> need proof.
                  </div>
                </>
              )}

              {/* Board #2 — capture VALUES, not just checkbox labels. The few facts
                  that drive the budget, the payment countdown, and the day-of board.
                  All optional; skip what you don't have yet. */}
              <div style={{ marginTop: 18 }}>
                <div style={{ fontSize: T.caption, fontWeight: FW.heavy, letterSpacing: '0.1em', textTransform: 'uppercase', color: C.muted, marginBottom: 4 }}>Add what you know</div>
                <div style={{ fontSize: T.caption, color: C.muted, lineHeight: 1.5, marginBottom: 12 }}>
                  These power the budget, the payment countdown, and the day-of board. Skip anything you don't have yet — you can add it later.
                </div>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10 }}>
                  <div>
                    <label style={lblStyle}>Estimated cost</label>
                    <div style={{ position: 'relative' }}>
                      <span style={{ position: 'absolute', left: 11, top: '50%', transform: 'translateY(-50%)', color: C.muted, fontSize: T.secondary, pointerEvents: 'none' }}>$</span>
                      <input inputMode="decimal" value={details.cost} onChange={e => setDet('cost', e.target.value.replace(/[^0-9.]/g, ''))} placeholder="0" style={{ ...s.input, paddingLeft: 22 }} />
                    </div>
                  </div>
                  <div>
                    <label style={lblStyle}>Deposit</label>
                    <div style={{ position: 'relative' }}>
                      <span style={{ position: 'absolute', left: 11, top: '50%', transform: 'translateY(-50%)', color: C.muted, fontSize: T.secondary, pointerEvents: 'none' }}>$</span>
                      <input inputMode="decimal" value={details.depositAmt} onChange={e => setDet('depositAmt', e.target.value.replace(/[^0-9.]/g, ''))} placeholder="0" style={{ ...s.input, paddingLeft: 22 }} />
                    </div>
                  </div>
                  <div>
                    <label style={lblStyle}>Payment due</label>
                    <input type="date" value={details.payDueDate} onChange={e => setDet('payDueDate', e.target.value)} style={s.input} />
                  </div>
                  <div>
                    <label style={lblStyle}>Arrival / load-in</label>
                    <input type="time" value={details.arrivalTime} onChange={e => setDet('arrivalTime', e.target.value)} style={s.input} />
                  </div>
                </div>
                {/* COI — only for business events; an at-home gathering doesn't ask a
                    friend bringing food for a certificate of insurance. */}
                {!atHome && (
                  <div style={{ marginTop: 12, border: `1px solid ${C.border}`, borderRadius: 10, padding: '11px 13px' }}>
                    <label onClick={() => setDet('coiRequired', !details.coiRequired)} style={{ display: 'flex', alignItems: 'flex-start', gap: 10, cursor: 'pointer', userSelect: 'none' }}>
                      <div style={{ width: 18, height: 18, borderRadius: 4, marginTop: 1, border: `2px solid ${details.coiRequired ? C.accent : C.muted}`, background: details.coiRequired ? C.accent : 'transparent', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
                        {details.coiRequired && <span style={{ fontSize: T.caption, color: C.accentText || '#fff', fontWeight: FW.bold }}>✓</span>}
                      </div>
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <div style={{ fontSize: T.secondary, fontWeight: FW.semibold, color: C.text }}>Insurance certificate (COI) required</div>
                        <div style={{ fontSize: T.caption, color: C.muted, marginTop: 2, lineHeight: 1.45 }}>Most venues require it. Seeds the day-of dock board and the readiness check now, not weeks later.</div>
                      </div>
                    </label>
                    {details.coiRequired && (
                      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10, marginTop: 11 }}>
                        <div>
                          <label style={lblStyle}>Certificate holder</label>
                          <input value={details.coiHolder} onChange={e => setDet('coiHolder', e.target.value)} placeholder="Who must be named" style={s.input} />
                        </div>
                        <div>
                          <label style={lblStyle}>Expires</label>
                          <input type="date" value={details.coiExpiry} onChange={e => setDet('coiExpiry', e.target.value)} style={s.input} />
                        </div>
                      </div>
                    )}
                  </div>
                )}
              </div>
            </>
          )}

          {step === 3 && (
            <>
              <div style={{ background: C.bg, border: `1px solid ${C.border}`, borderRadius: 10, padding: '12px 14px', marginBottom: 12 }}>
                <div style={{ fontSize: T.caption, fontWeight: FW.bold, letterSpacing: '0.10em', color: C.muted, textTransform: 'uppercase', marginBottom: 8 }}>Review</div>
                {[
                  { label: 'Vendor added to',     value: event?.name || 'this event' },
                  { label: 'Vendor name',         value: identity.name.trim() || '—' },
                  { label: 'Category',            value: identity.category || '—' },
                  { label: 'Saved to vendor bank', value: saveToBank && bankAvailable ? (alreadyInBankHit ? 'Already in bank — no duplicate' : 'Yes') : 'No' },
                  { label: 'Estimated cost',      value: details.cost ? fmtD(Number(details.cost)) : 'Not set yet' },
                  { label: 'Deposit',             value: details.depositAmt ? `${fmtD(Number(details.depositAmt))}${details.payDueDate ? ` · due ${details.payDueDate}` : ''}` : (details.payDueDate ? `Due ${details.payDueDate}` : 'Not set yet') },
                  { label: 'Insurance (COI)',     value: atHome ? 'Not required — home event' : details.coiRequired ? (details.coiHolder ? `Required · names ${details.coiHolder}${details.coiExpiry ? ` · exp ${details.coiExpiry}` : ''}` : 'Required · to collect') : 'Not required' },
                  { label: 'Promise tracker',     value: `${selectedCount} selected item${selectedCount === 1 ? '' : 's'}` },
                  { label: 'Proof needed',     value: `${evidenceCount} item${evidenceCount === 1 ? '' : 's'}` },
                ].map((row, i, arr) => (
                  <div key={row.label} style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 12, paddingTop: i ? 8 : 0, paddingBottom: i === arr.length - 1 ? 0 : 8, borderBottom: i === arr.length - 1 ? 'none' : `1px solid ${C.border}` }}>
                    <div style={{ fontSize: T.caption, color: C.muted, flexShrink: 0 }}>{row.label}</div>
                    <div style={{ fontSize: T.secondary, fontWeight: FW.semibold, color: C.text, textAlign: 'right', maxWidth: '60%' }}>{row.value}</div>
                  </div>
                ))}
              </div>
              <div style={{ fontSize: T.caption, color: C.muted, lineHeight: 1.55 }}>
                Tapping Create saves this vendor to the event. You can still edit anything later — and Event Boss only sends messages when you explicitly ask it to.
              </div>
            </>
          )}
        </div>

        {/* Footer */}
        <div style={{ padding: '14px 22px', borderTop: `1px solid ${C.border}`, display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 8, flexShrink: 0 }}>
          <button type="button" onClick={step === 1 ? onCancel : () => setStep(s => s - 1)} style={{ background: 'none', border: 'none', cursor: 'pointer', color: C.accent, fontWeight: FW.semibold, fontSize: T.secondary, padding: '4px 4px', minHeight: 0 }}>
            {step === 1 ? 'Cancel' : 'Back'}
          </button>
          {step < 3 && (
            <PrimaryButton
              testId="av-continue"
              onClick={() => setStep(s => s + 1)}
              disabled={step === 1 ? !canContinue1 : false}>
              Continue
            </PrimaryButton>
          )}
          {step === 3 && (
            <PrimaryButton
              testId="av-create"
              onClick={() => onCreate({
                identity,
                selectedPromiseKeys: Array.from(selectedKeys),
                saveToBank: saveToBank && bankAvailable && !alreadyInBankHit,
                details,
              })}>
              Create vendor
            </PrimaryButton>
          )}
        </div>
      </div>
    </>
  );
}

// Legacy intro retained for any caller that imports it (none in this
// build) — kept as a thin alias so a partial migration doesn't break.
function AddVendorIntro({ C, s, eventName, onCancel, onContinue }) {
  const steelTop  = C.accentTopGrad || C.accent;
  const steelDeep = C.accentDeep    || C.accent;
  useEffect(() => {
    const prev = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => { document.body.style.overflow = prev; };
  }, []);
  return (
    <>
      <div onClick={onCancel} style={{
        position: 'fixed', inset: 0,
        background: 'rgba(0,0,0,0.55)',
        backdropFilter: 'blur(6px)', WebkitBackdropFilter: 'blur(6px)',
        zIndex: 70,
      }} />
      <div role="dialog" aria-label="Add a vendor" style={{
        position: 'fixed', left: '50%', top: '50%',
        transform: 'translate(-50%, -50%)',
        width: 'min(440px, calc(100vw - 32px))',
        maxHeight: 'calc(100vh - 64px)', overflowY: 'auto',
        ...metalEdge(C),
        borderRadius: 16,
        boxShadow: '0 20px 60px rgba(0,0,0,0.50)',
        zIndex: 71, padding: 22,
      }}>
        <div style={{ fontSize: T.eyebrow, fontWeight: FW.heavy, letterSpacing: '0.16em', color: steelTop, textTransform: 'uppercase', marginBottom: 4 }}>Add Vendor</div>
        <div style={{ fontSize: T.title, fontWeight: FW.bold, color: C.text, marginBottom: 4, lineHeight: 1.25 }}>
          Add a vendor to <span style={{ color: steelTop }}>{eventName}</span>
        </div>
        <div style={{ fontSize: T.secondary, color: C.muted, lineHeight: 1.55, marginBottom: 16 }}>
          You'll set a name and category. Event Boss will draft a few category-based things to track (deposit, contract, arrival window) — nothing is sent and nothing is shared.
        </div>

        <div style={{ background: C.bg, border: `1px solid ${C.border}`, borderRadius: 10, padding: '12px 14px', marginBottom: 12 }}>
          <div style={{ fontSize: T.caption, fontWeight: FW.bold, letterSpacing: '0.10em', color: C.muted, textTransform: 'uppercase', marginBottom: 8 }}>What happens when you save</div>
          {[
            { label: 'Added to event',         value: eventName },
            { label: 'Saved to vendor bank',   value: 'No (workspace bank is separate — coming soon)' },
            { label: 'Promise tracker',        value: 'Drafted from category playbook · you can edit' },
            { label: 'Messages sent',          value: 'None' },
            { label: 'Notifications sent',     value: 'None' },
          ].map((row) => (
            <div key={row.label} style={{ display: 'flex', alignItems: 'flex-start', gap: 10, marginTop: 6 }}>
              <span aria-hidden style={{ flexShrink: 0, width: 14, height: 14, borderRadius: '50%', border: `1.5px solid ${steelTop}`, color: steelTop, display: 'inline-flex', alignItems: 'center', justifyContent: 'center', fontSize: T.eyebrow, fontWeight: FW.heavy, marginTop: 1 }}>·</span>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: T.caption, fontWeight: FW.semibold, color: C.text }}>{row.label}</div>
                <div style={{ fontSize: T.caption, color: C.muted, marginTop: 1, lineHeight: 1.45 }}>{row.value}</div>
              </div>
            </div>
          ))}
        </div>

        <div style={{ fontSize: T.caption, color: C.muted, marginBottom: 16, lineHeight: 1.5 }}>
          Required: <span style={{ color: C.text, fontWeight: FW.semibold }}>name</span> and <span style={{ color: C.text, fontWeight: FW.semibold }}>category</span>. Contact info, deposit, contract — you can add later.
        </div>

        <div style={{ display: 'flex', gap: 8, justifyContent: 'flex-end' }}>
          <button type="button" onClick={onCancel} style={{ background: 'none', border: 'none', cursor: 'pointer', color: C.accent, fontWeight: FW.semibold, fontSize: T.secondary, padding: '4px 4px', minHeight: 0 }}>Cancel</button>
          <button type="button" onClick={onContinue} style={{
            background: `linear-gradient(180deg, ${steelTop} 0%, ${steelDeep} 100%)`,
            color: C.accentText || '#fff',
            border: 'none', borderRadius: 8,
            padding: '9px 18px', fontSize: T.secondary, fontWeight: FW.bold,
            cursor: 'pointer',
            boxShadow: 'inset 0 1px 0 rgba(255,255,255,0.12), 0 1px 2px rgba(0,0,0,0.32)',
          }}>Continue</button>
        </div>
      </div>
    </>
  );
}

// ─── Sprint Add Vendor 10+ — Success state ─────────────────────────────
// Itemized post-create confirmation. No fake send — "Draft follow-up"
// uses the generator and copies to clipboard. Sending stays gated by
// the comms 6-state contract and the deeper Communication workflow.
function VendorCreatedSuccess({ C, s, vendor, eventName, savedToBank, promiseCount, evidenceCount, onClose, onOpen, onAddAnother, onDraftFollowUp }) {
  const steelTop  = C.accentTopGrad || C.accent;
  const steelDeep = C.accentDeep    || C.accent;
  const [draftStatus, setDraftStatus] = useState(null);
  useEffect(() => {
    const prev = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => { document.body.style.overflow = prev; };
  }, []);
  const handleDraft = () => {
    const res = onDraftFollowUp ? onDraftFollowUp() : { copied: false, mailtoOpened: false };
    if (res && (res.copied || res.mailtoOpened)) {
      setDraftStatus(res);
      setTimeout(() => setDraftStatus(null), 3200);
    }
  };
  return (
    <>
      <div onClick={onClose} style={{
        position: 'fixed', inset: 0,
        background: 'rgba(0,0,0,0.55)',
        backdropFilter: 'blur(6px)', WebkitBackdropFilter: 'blur(6px)',
        zIndex: 70,
      }} />
      <div role="status" aria-live="polite" data-testid="vendor-created-success" style={{
        position: 'fixed', left: '50%', top: '50%',
        transform: 'translate(-50%, -50%)',
        width: 'min(460px, calc(100vw - 24px))',
        maxHeight: 'calc(100vh - 48px)', overflowY: 'auto',
        ...metalEdge(C),
        borderRadius: 16,
        boxShadow: '0 20px 60px rgba(0,0,0,0.50)',
        zIndex: 71, padding: 22,
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 14 }}>
          <span aria-hidden style={{ width: 32, height: 32, borderRadius: '50%', background: `${C.success}22`, color: C.success, display: 'inline-flex', alignItems: 'center', justifyContent: 'center', fontSize: T.body, fontWeight: FW.heavy }}>✓</span>
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{ fontSize: T.eyebrow, fontWeight: FW.heavy, letterSpacing: '0.16em', color: C.success, textTransform: 'uppercase' }}>Vendor added</div>
            <div style={{ fontSize: T.body, fontWeight: FW.bold, color: C.text, marginTop: 1, lineHeight: 1.25 }}>{vendor?.name || 'New vendor'}</div>
            {vendor?.category && (
              <div style={{ fontSize: T.caption, color: C.muted, marginTop: 1 }}>{vendor.category}</div>
            )}
          </div>
        </div>

        <div style={{ background: C.bg, border: `1px solid ${C.border}`, borderRadius: 10, padding: '12px 14px', marginBottom: 14 }}>
          {[
            { label: 'Added to event',         value: eventName },
            { label: 'Saved to vendor bank',   value: savedToBank ? 'Yes' : 'No' },
            { label: 'Promise tracker created', value: `${promiseCount} item${promiseCount === 1 ? '' : 's'}` },
            { label: 'Proof needed',        value: `${evidenceCount} item${evidenceCount === 1 ? '' : 's'}` },
            { label: 'Messages sent',          value: 'None' },
            { label: 'Notifications sent',     value: 'None' },
          ].map((row, idx, arr) => (
            <div key={row.label} style={{ display: 'flex', alignItems: 'flex-start', gap: 10, paddingTop: idx ? 8 : 0, paddingBottom: idx === arr.length - 1 ? 0 : 8, borderBottom: idx === arr.length - 1 ? 'none' : `1px solid ${C.border}` }}>
              <span aria-hidden style={{ flexShrink: 0, width: 14, height: 14, borderRadius: '50%', background: `${C.success}22`, color: C.success, border: `1.5px solid ${C.success}`, display: 'inline-flex', alignItems: 'center', justifyContent: 'center', fontSize: T.eyebrow, fontWeight: FW.heavy, marginTop: 1 }}>✓</span>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: T.caption, fontWeight: FW.semibold, color: C.text }}>{row.label}</div>
                <div style={{ fontSize: T.caption, color: C.muted, marginTop: 1, lineHeight: 1.45 }}>{row.value}</div>
              </div>
            </div>
          ))}
        </div>

        <div style={{ fontSize: T.caption, fontWeight: FW.bold, letterSpacing: '0.10em', color: C.muted, textTransform: 'uppercase', marginBottom: 8 }}>Next best action</div>
        <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', alignItems: 'center' }}>
          <button type="button" data-testid="vcs-open" onClick={onOpen} style={{ ...s.btn('primary') }}>Open vendor</button>
          <button type="button" data-testid="vcs-draft-followup" onClick={handleDraft} title="Opens a category-aware draft in your mail client (when an email is set) and copies it to the clipboard. Nothing is sent." style={{ ...s.btn('ghost') }}>
            {draftStatus ? (draftStatus.mailtoOpened ? 'Draft opened' : 'Copied') : 'Draft follow-up'}
          </button>
          <button type="button" data-testid="vcs-add-another" onClick={onAddAnother} style={{ ...s.btn('ghost'), fontSize: T.secondary, padding: '8px 14px' }}>Add another</button>
          <button type="button" data-testid="vcs-done" onClick={onClose} style={{ ...s.btn('ghost'), fontSize: T.secondary, padding: '8px 14px', marginLeft: 'auto' }}>Done</button>
        </div>
        <div style={{ fontSize: T.caption, color: C.muted, marginTop: 10, lineHeight: 1.5 }}>
          "Draft follow-up" prepares a category-aware draft in your mail client (when an email is set) and copies the same text to your clipboard. Sending stays manual — Event Boss never reaches out to a vendor without you.
        </div>
      </div>
    </>
  );
}

// Retained for backward compatibility — earlier audit pass used these names.
function VendorAddedToast(props) { return <VendorCreatedSuccess {...props} savedToBank={false} evidenceCount={0} />; }

// ─── Sprint 49: EventDecisionsTab — canonical Decisions L4 specialist ────────
// Wraps DecisionApprovalCenter with persistence hooks. Decisions resolve by
// marking the underlying timeline task done. Approval actions mutate the
// corresponding commClient entry. Both flow through setEvent so all other
// surfaces (Home Attention Queue, Command Center, Events Index 4-axis) update
// in real time.
// Sprint 59G: EventChecklistTab + EventTimelineTab removed. Both were
// thin Sprint-49 wrappers that became dead code in Sprint 59B when the
// Planning surface absorbed their views (List / Timeline / Checklist) into
// `EventPlanningTab`. ChecklistGenerator + TimelineBuilder + Timeline list
// remain live — they're rendered as views inside EventPlanningTab.

// ─── Sprint 49: EventCommTab — canonical Communication L4 specialist ────────
// Sprint 58: onSend attempts the FastAPI comms backend.
// Sprint 58.2: email delivery via Resend. The composer now receives three
// mode signals:
//   commLive      — backend API is reachable and planner can authenticate
//   emailEnabled  — backend reports RESEND_API_KEY is configured
//   resolveEmail  — function(thread) → { email, name } | null
// The CTA is honest: "Send email" only when all three conditions align for
// the active thread. "Send via app" when backend is live but no email.
// "Log to thread" when neither.
function EventCommTab({ event, setEvent, client, setClient, openId, isMobile, onBack, profile, clients, onRouteToLinked }) {
  const commLive = isCommApiConfigured() && canAuthenticatePlanner();
  const emailEnabled = isEmailConfigured();

  // Resolve recipient email from event data. Client threads → client.email,
  // Vendor threads → vendor.contact. Team → null (internal, never emailed).
  const resolveEmail = (thread) => {
    if (!thread) return null;
    // Client thread: find matching client by name in event.clients → app clients
    if (thread.tab === 'Client') {
      const ec = (event.clients || []).find(c => c.name === thread.name || c.id === thread.clientId);
      if (ec?.email) return { email: ec.email, name: ec.name || thread.name };
      // Fallback: check the top-level clients array
      const ac = (clients || []).find(c =>
        (event.clients || []).some(ec2 => ec2.id === c.id) ||
        c.name === thread.name
      );
      if (ac?.email) return { email: ac.email, name: ac.name || thread.name };
      return null;
    }
    // Vendor thread: find matching vendor by name
    if (thread.tab === 'Vendors' || thread.tab === 'Vendor') {
      const v = (event.vendors || []).find(
        vn => (vn.name || vn.vendor_name) === thread.name
      );
      if (v?.contact) return { email: v.contact, name: v.contactName || v.name || thread.name };
      return null;
    }
    // Team threads are internal — never email
    return null;
  };

  const onSend = async (thread, body, opts = {}) => {
    const now = new Date().toISOString();
    const channel = thread?.tab === 'Vendor' || thread?.tab === 'Vendors' ? 'vendor'
                  : thread?.tab === 'Team'   ? 'team'
                  : 'client';
    const baseMsg = {
      id: `m-${Date.now()}`,
      channel,
      direction: 'outbound',
      sender: 'planner',
      senderName: profile?.name || 'Planner',
      body, text: body,
      createdAt: now,
      vendor_name: (thread?.tab === 'Vendor' || thread?.tab === 'Vendors') ? thread.name : undefined,
      // Approval request created from the Messages composer — surfaces the same
      // approval flow (sticky Approve/Reject card) the planner already uses.
      message_type: opts.asApproval ? 'approval_request' : 'standard',
      approval_status: opts.asApproval ? 'pending' : undefined,
      subject: opts.subject?.trim() || undefined,
    };

    // Sprint 58.2: email delivery path
    const wantsEmail = opts.deliverEmail === true;
    const recipient = wantsEmail ? resolveEmail(thread) : null;

    if (commLive && event?.id) {
      try {
        const payload = {
          message_type: opts.asApproval ? 'approval_request' : 'standard',
          approval_status: opts.asApproval ? 'pending' : undefined,
          subject: opts.subject?.trim() || undefined,
          author_role:  'planner',
          author_name:  profile?.name || 'Planner',
          body,
        };
        // Attach email delivery fields when the planner explicitly chose "Send email"
        if (wantsEmail && recipient?.email && emailEnabled) {
          payload.deliver_email   = true;
          payload.recipient_email = recipient.email;
          payload.recipient_name  = recipient.name || undefined;
          // Fix #9: Professional subject format with event date + type context
          const evDate = event.date ? new Date(event.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) : null;
          const threadLabel = thread?.tab === 'Vendors' ? thread.name : 'Client update';
          payload.subject = opts.subject?.trim()
            || `${evDate ? evDate + ' ' : ''}${event.name || 'Your event'} — ${threadLabel}`;
          payload.reply_to        = profile?.email || undefined;
        }

        const result = await commApi.createMessage(event.id, channel, payload);

        // Determine delivery status from backend response.
        // "accepted" = Resend accepted for delivery (not yet confirmed delivered).
        // Webhook updates to "delivered", "bounced", "complained", or "deferred".
        const delivery = result?.metadata?.delivery;
        let deliveryStatus = 'sent-via-app';
        if (delivery?.status === 'accepted') deliveryStatus = 'email-accepted';
        else if (delivery?.status === 'sent') deliveryStatus = 'email-accepted'; // legacy compat
        else if (delivery?.status === 'failed') deliveryStatus = 'email-failed';
        else if (delivery?.status === 'provider_not_configured') deliveryStatus = 'local-only';

        setEvent(e => ({
          ...e,
          commClient: [...(e.commClient || []), { ...baseMsg, deliveryStatus, deliveryProvider: delivery?.provider }],
        }));
        return { ok: true, status: deliveryStatus === 'email-sent' ? 'email-sent' : 'sent', fallback: false };
      } catch (err) {
        setEvent(e => ({
          ...e,
          commClient: [...(e.commClient || []), { ...baseMsg, deliveryStatus: 'local-only', fallbackReason: err?.message || 'backend error' }],
        }));
        return { ok: true, status: 'logged', fallback: true };
      }
    }

    // Backend not configured — log locally.
    setEvent(e => ({
      ...e,
      commClient: [...(e.commClient || []), { ...baseMsg, deliveryStatus: 'local-only' }],
    }));
    return { ok: true, status: 'logged', fallback: true };
  };
  // Sprint 60.T Phase 4 — canonical approval handler.
  // Writes approval_status to the message in event.commClient, records
  // resolvedAt timestamp + resolvedBy (planner name when available).
  // No fake notification, no duplicate state — single source of truth
  // is the message.approval_status field on the existing message in
  // event.commClient (same field the bubble already reads in
  // CommunicationHub for the isApproved / isRejected branches).
  const onApprove = (messageId, verdict) => {
    if (!messageId || !verdict) return;
    if (!['approved', 'rejected'].includes(verdict)) return;
    const now = new Date().toISOString();
    const actor = profile?.name || 'Planner';
    setEvent(e => ({
      ...e,
      commClient: (e.commClient || []).map(m => m.id === messageId
        ? { ...m, approval_status: verdict, resolvedAt: now, resolvedBy: actor }
        : m),
    }));
  };
  // Delete a message from the thread (the planner's local comm log).
  const onDeleteMessage = (messageId) => {
    if (!messageId) return;
    setEvent(e => ({ ...e, commClient: (e.commClient || []).filter(m => m.id !== messageId) }));
  };
  // Edit a message body (planner-authored messages only — see the bubble gate).
  const onEditMessage = (messageId, newBody) => {
    if (!messageId || typeof newBody !== 'string') return;
    setEvent(e => ({
      ...e,
      commClient: (e.commClient || []).map(m => m.id === messageId
        ? { ...m, body: newBody, text: newBody, editedAt: new Date().toISOString() }
        : m),
    }));
  };
  // Sprint 60.Q Comms #2: day-of detection mirrors the Event Command
  // Center logic (explicit dayMode overrides date-based auto-engage).
  // CommunicationHub uses this to scale up bubbles + simplify the
  // composer for live operational use.
  const isDayOf = event?.dayMode === true
              || (event?.dayMode !== false && event?.date === today8601());

  // Comms innovation — AI message drafting. Builds a context-aware draft from the
  // thread + event and streams it into the composer. Honest: copy-only, the
  // planner reviews and sends. Null when no Anthropic key (button hides).
  const aiKey = profile?.anthropicKey || '';
  // OpenAI is the default draft provider — wired via the secure server-side proxy
  // (OPENAI_API_KEY lives on the backend, no per-planner key needed). A planner's
  // own Anthropic key is only a fallback when the proxy isn't configured.
  const draftViaOpenAI = isAiProxyConfigured();
  const onAiDraft = (draftViaOpenAI || aiKey) ? async (thread, onChunk) => {
    if (!thread) return null;
    const recent = (thread.messages || []).slice(-6).map(m => {
      const mine = m.direction === 'outbound' || m.sender === 'planner';
      const txt = (m.body || m.text || m.message || '').trim();
      return `${mine ? 'Planner' : (m.senderName || thread.name || 'Them')}: ${txt}`;
    }).filter(l => l.split(': ')[1]).join('\n');
    const who = `${thread.name || 'the recipient'}${thread.tab ? ` (${String(thread.tab).toLowerCase()})` : ''}`;
    const prompt = `You are Event Boss, helping a planner write a message. Write a SHORT, warm, professional message FROM the planner TO ${who} about this event. Plainspoken and specific; no subject line, no markdown, no sign-off block. If it reads like a reply, skip the greeting. Return ONLY the message body.\n\nEvent: ${event.name || 'event'} · ${eventTypeLabel(event) || event.type || ''} · ${event.date ? fmtDate(event.date) : 'date TBD'}${event.venue ? ` · ${event.venue}` : ''}\nPlanner: ${profile?.name || 'the planner'}${profile?.businessName ? `, ${profile.businessName}` : ''}\nRecipient: ${who}\n${recent ? `Recent conversation:\n${recent}\n` : ''}\nMessage:`;
    let out;
    if (draftViaOpenAI) {
      // OpenAI GPT-4o via the backend proxy. No client-side streaming — deliver
      // the full draft in one shot via onChunk so the composer fills in.
      try {
        const data = await callAiFeature('vendor_followup', prompt, { recipient: who, eventName: event.name });
        out = data?.text || '';
        if (out && onChunk) onChunk(out);
      } catch (e) {
        // Fall back to the planner's own Anthropic key if they have one.
        if (aiKey) out = await askNGW('vendor_followup', prompt, { aiKey, maxTokens: 320, onChunk });
        else throw e;
      }
    } else {
      out = await askNGW('vendor_followup', prompt, { aiKey, maxTokens: 320, onChunk });
    }
    // Count every draft the planner generates (persists on the event's jsonb).
    if (out) setEvent(e => ({ ...e, aiDraftsCreated: (e.aiDraftsCreated || 0) + 1 }));
    return out;
  } : null;

  return (
    <CommunicationHub
      event={event}
      client={client}
      isMobile={isMobile}
      onAiDraft={onAiDraft}
      isDayOf={isDayOf}
      openId={openId}
      onBack={onBack}
      onSend={onSend}
      onApprove={onApprove}
      onDeleteMessage={onDeleteMessage}
      onEditMessage={onEditMessage}
      onUpdateContact={(thread, patch) => {
        // Update the vendor/client contact behind a thread (board: edit contact
        // from Messages). Vendors store email on `contact`; clients on `email`.
        if (thread.tab === 'Vendors') {
          setEvent(e => ({ ...e, vendors: (e.vendors || []).map(v =>
            (v.name || v.vendor_name) === thread.name
              ? { ...v, contact: patch.email, phone: patch.phone }
              : v
          ) }));
        } else if (thread.tab === 'Client') {
          // The client is a separate entity (not on the event). Write through
          // setClient when available; fall back to event.client otherwise.
          if (setClient) setClient(c => ({ ...(c || {}), email: patch.email, phone: patch.phone }));
          else setEvent(e => ({ ...e, client: { ...(e.client || {}), email: patch.email, phone: patch.phone } }));
        }
      }}
      commLive={commLive}
      emailEnabled={emailEnabled}
      resolveEmail={resolveEmail}
      onRouteToTab={onRouteToLinked}
    />
  );
}

// ─── Sprint 50: EventClientIntakeTab — canonical Client Intake L4 specialist ─
// Wraps the Figma C 7-step intake flow. Persists the draft into the host
// event state via onPersist (mirrors the Sprint 49 promoted-tab pattern).
// Only the intake-shaped fields are merged back into the event — guards
// against the embedded draft accidentally overwriting unrelated event keys.
function EventClientIntakeTab({ event, setEvent, isMobile, intakeMode, onBack }) {
  const onPersist = (draft) => {
    // Allow-list the fields that the 7 steps actually edit, to avoid the
    // draft (which seeded from `...event`) overwriting unrelated state on
    // save. Steps 1-7: basics, contact, guests, budget, vision, vendors.
    const ALLOWED = ['name', 'type', 'date', 'venue', 'guestEstimate',
                     'budget', 'vendors', 'clients', 'vision',
                     'priorities', 'mustHaves', 'dealBreakers',
                     'vipConcerns', 'commPrefs', 'intake', '_intakeStep',
                     // Step 5 Vision & Style — meaning-first intake (board 2026-06-12).
                     // These top-level keys were being dropped on save; the meaning
                     // questions drive the toast prompt, day-of moments, and briefs.
                     'meaning_host', 'honoree_story', 'feeling_words',
                     'must_have_moment', 'meaning_why', 'honoree_song',
                     'honoree_drink', 'meaning_people', 'meaning_cry_moment',
                     'meaning_avoid', 'style_vibe', 'color_palette',
                     'floral_direction', 'lighting_notes', 'ceremony_type',
                     'officiant', 'ceremony_length', 'special_rituals',
                     'first_dance_song', 'dinner_format', 'inspiration_notes'];
    const patch = {};
    ALLOWED.forEach(k => { if (k in draft) patch[k] = draft[k]; });
    setEvent(e => ({ ...e, ...patch, intakeSavedAt: new Date().toISOString() }));
  };
  return (
    <ClientIntakeFlow
      event={event}
      isMobile={isMobile}
      intakeMode={intakeMode}
      onBack={onBack}
      onPersist={onPersist}
    />
  );
}

function EventDecisionsTab({ event, setEvent, openId, isMobile, onBack, onRouteToLinked, promptDecision }) {
  const C = useT();
  const T = useType();
  const [copied, setCopied] = useState(false);
  // Sprint 66: client approvals from portal (stored in localStorage by client)
  const [clientApprovals, setClientApprovals] = useState({});
  // Sprint 59D: legacy decisions migration state
  const commLive = isCommApiConfigured() && canAuthenticatePlanner();
  const [migrating, setMigrating] = useState(false);
  const [migrationResult, setMigrationResult] = useState(null); // { ok, moved, failed, error? }
  const [bannerDismissed, setBannerDismissed] = useState(false);

  // Read client portal approvals from localStorage
  useEffect(() => {
    if (!event?.id) return;
    try {
      const stored = JSON.parse(localStorage.getItem(`ngw-client-approvals-${event.id}`) || '{}');
      setClientApprovals(stored);
    } catch {}
  }, [event?.id]);

  // Generate a portal token if one doesn't exist and persist it on the event
  const ensureToken = () => {
    if (event?.portalToken) return event.portalToken;
    const tok = `pt-${event.id}-${Math.random().toString(36).slice(2, 10)}`;
    setEvent(e => ({ ...e, portalToken: tok }));
    return tok;
  };

  const copyPortalLink = () => {
    const tok = ensureToken();
    const base = window.location.origin + window.location.pathname;
    const url  = `${base}?portal=${tok}`;
    navigator.clipboard.writeText(url).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }).catch(() => {
      // Fallback for browsers without clipboard API
      const el = document.createElement('textarea');
      el.value = url;
      document.body.appendChild(el);
      el.select();
      document.execCommand('copy');
      document.body.removeChild(el);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    });
  };

  const onResolveDecision = (taskId) => {
    track(EVENTS.APPROVAL_RECORDED, { kind: 'decision', action: 'resolved' });
    recordFirstValue('decision_resolved', event, 'decision_panel');
    setEvent(e => ({
      ...e,
      timeline: (e.timeline || []).map(t => t.id === taskId ? { ...t, done: true, resolvedAt: new Date().toISOString() } : t),
    }));
  };
  // Decision actions so a planner can act ON the decision inline (no hunting):
  // Extend pushes the deadline a week (snooze); Reassign changes the owner.
  const onExtendDecision = (taskId) => {
    // Sprint 58C — Decision Memory: deferring an engine-flagged decision is a
    // planner override. Capture why (non-blocking; the snooze applies regardless).
    if (promptDecision) {
      const t = (event.timeline || []).find(x => x.id === taskId);
      promptDecision({ decisionType: 'planner_override', subjectId: taskId, subjectLabel: (t && t.task) || 'this item',
        decision: `Deferred 7 days: ${(t && t.task) || 'item'}`, question: 'Why defer this now?' });
    }
    setEvent(e => ({
      ...e,
      timeline: (e.timeline || []).map(t => {
        if (t.id !== taskId) return t;
        const until = new Date(); until.setDate(until.getDate() + 7);
        return { ...t, snoozedUntil: until.toISOString().slice(0, 10), extendedAt: new Date().toISOString() };
      }),
    }));
  };
  const onReassignDecision = (taskId, owner) => {
    if (!owner || !owner.trim()) return;
    setEvent(e => ({
      ...e,
      timeline: (e.timeline || []).map(t => t.id === taskId ? { ...t, owner: owner.trim() } : t),
    }));
  };
  const onActApproval = (messageId, action) => {
    track(EVENTS.APPROVAL_RECORDED, { kind: 'approval', action });
    recordFirstValue('approval_recorded', event, 'approval_action');
    const next = action === 'approve' ? 'approved' : action === 'reject' ? 'rejected' : 'awaiting';
    setEvent(e => ({
      ...e,
      commClient: (e.commClient || []).map(m => m.id === messageId ? { ...m, approval_status: next, actedAt: new Date().toISOString() } : m),
    }));
  };

  // Count pending decisions so planner can see if client has responded
  const pendingDecisions  = (event?.decisions || []).filter(d => d.status === 'pending');
  const clientRespondedN  = Object.keys(clientApprovals).length;
  const hasClientActivity = clientRespondedN > 0;

  // ─── Sprint 59D: legacy decisions migration ──────────────────────────────
  // A legacy decision = an entry in `event.decisions[]` (local-only truth
  // that pre-dates the Sprint 58P.4c backend approval_request canon). The
  // bridge banner offers opt-in migration to durable backend records when
  // the backend is reachable; otherwise it honestly says so. Originals are
  // preserved until each backend write succeeds. Re-runs are idempotent:
  // we skip any decision whose `migratedToMessageId` is already set.
  const unmigrated = (event?.decisions || []).filter(d => !d.migratedToMessageId);
  const showLegacyBanner = unmigrated.length > 0 && !bannerDismissed && !migrationResult;

  const runDecisionsMigration = async () => {
    if (!commLive || !event?.id || migrating || unmigrated.length === 0) return;
    setMigrating(true);
    setMigrationResult(null);
    const moved = [];
    const failed = [];
    for (const d of unmigrated) {
      const legacyVerdict = clientApprovals[d.id]; // 'approved' | 'rejected' | undefined
      // Body carries the legacy markers so the migrated record is traceable
      // even though the backend MessageCreate schema doesn't accept custom
      // metadata fields today. The frontend stores the link by message id.
      const bodyLines = [
        d.title || '(untitled decision)',
        d.notes ? `\n${d.notes}` : '',
        legacyVerdict ? `\n[Client portal verdict: ${legacyVerdict}]` : '',
        d.status === 'resolved' && d.verdict ? `\n[Resolved: ${d.verdict}]` : '',
        `\n— Migrated from legacy decisions on ${new Date().toISOString().slice(0, 10)}.`,
      ].join('');
      const subject = d.title ? `[Legacy decision] ${d.title}` : '[Legacy decision]';
      try {
        const created = await commApi.createMessage(event.id, 'CLIENT', {
          message_type: 'approval_request',
          author_role:  'planner',
          author_name:  'Migration · legacy decisions',
          body:         bodyLines,
          subject,
          approval_context: d.title || '(untitled decision)',
        });
        moved.push({ id: d.id, messageId: created?.id || null });
      } catch (err) {
        failed.push({ id: d.id, error: (err && err.message) || 'unknown error' });
      }
    }
    // Preserve originals. Only attach `migratedToMessageId` for the ones
    // that actually wrote to the backend. Failures stay flagged so the
    // banner can offer a retry.
    if (moved.length) {
      const movedMap = Object.fromEntries(moved.map(m => [m.id, m.messageId]));
      setEvent(e => ({
        ...e,
        decisions: (e.decisions || []).map(d => movedMap[d.id]
          ? { ...d, migratedToMessageId: movedMap[d.id] || true, migratedAt: new Date().toISOString() }
          : d
        ),
      }));
    }
    setMigrating(false);
    setMigrationResult({ ok: failed.length === 0, moved: moved.length, failed: failed.length });
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
      {/* Sprint 61.F — Decisions NO GUESSWORK rail. */}
      {(() => {
        const steelTopD = C.accentTopGrad || C.accent;
        return (
          <div style={{
            margin: '10px 14px 12px',
            padding: '10px 12px',
            background: `linear-gradient(180deg, ${steelTopD}14 0%, ${steelTopD}07 100%)`,
            border: `1px solid ${steelTopD}33`,
            borderLeft: `3px solid ${steelTopD}`,
            borderRadius: 8,
            display: 'flex', gap: 10, alignItems: 'flex-start',
          }}>
            <span aria-hidden style={{
              flexShrink: 0, width: 20, height: 20, borderRadius: '50%',
              background: `${steelTopD}22`, color: steelTopD,
              display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
              fontSize: T.caption, fontWeight: FW.heavy, marginTop: 1,
            }}>✓</span>
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{ fontSize: T.eyebrow, fontWeight: FW.heavy, letterSpacing: '0.16em', color: steelTopD, textTransform: 'uppercase' }}>No Guesswork</div>
              <div style={{ fontSize: T.caption, color: C.text, lineHeight: 1.45, marginTop: 1 }}>
                Decisions block downstream work. Each row shows who owns it, what's blocking, and the next action. Approvals you send via the client portal show up here as soon as the client responds.
              </div>
            </div>
          </div>
        );
      })()}
      {/* Sprint 59D: legacy decisions bridge banner. Renders only when the
          event has decisions that haven't been moved into the backend
          approval history. Backend-unavailable state is honestly labeled —
          no silent pretend-migration. Originals are never destroyed in this
          sprint; on success the decision row is marked with
          `migratedToMessageId` so the banner stops showing. */}
      {showLegacyBanner && (
        // Sprint 60.N Phase 4: was amber wash + amber border. Now Carbon
        // surface + amber left rail. No background blend.
        <div style={{
          padding: '10px 16px 10px 19px',
          background: C.surface,
          borderBottom: `1px solid ${C.border}`,
          borderLeft: `3px solid ${C.muted}`,
          display: 'flex', alignItems: 'center', gap: 12, flexWrap: 'wrap',
        }}>
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{ fontSize: T.caption, fontWeight: FW.bold, color: C.text }}>
              {unmigrated.length} legacy decision{unmigrated.length !== 1 ? 's' : ''} saved locally
            </div>
            <div style={{ fontSize: T.caption, color: C.muted, marginTop: 1, lineHeight: 1.4 }}>
              {commLive
                ? "Move them into shared approval history so they're durable across devices. Originals stay on the event until each write succeeds."
                : "Connect the backend to move them into shared approval history. Until then they live in this browser only."}
            </div>
          </div>
          {commLive && (
            <button
              onClick={runDecisionsMigration}
              disabled={migrating}
              style={{
                padding: '7px 14px', borderRadius: 7,
                border: `1px solid ${migrating ? C.border : C.accent + '66'}`,
                background: migrating ? C.bg : C.accent + '18',
                color: migrating ? C.muted : C.accent,
                fontSize: T.caption, fontWeight: FW.semibold,
                cursor: migrating ? 'default' : 'pointer',
                fontFamily: 'inherit', flexShrink: 0,
                display: 'flex', alignItems: 'center', gap: 6,
              }}
            >
              {migrating ? 'Moving…' : 'Move old decisions'}
            </button>
          )}
          <button
            onClick={() => setBannerDismissed(true)}
            title="Hide this banner for now. Old decisions stay on the event; the banner returns on next session."
            style={{
              padding: '7px 12px', borderRadius: 7,
              border: `1px solid ${C.border}`,
              background: 'transparent',
              color: C.muted,
              fontSize: T.caption, fontWeight: FW.semibold,
              cursor: 'pointer', fontFamily: 'inherit', flexShrink: 0,
            }}
          >
            Keep for now
          </button>
        </div>
      )}
      {/* Migration result toast (in-banner). Surfaces the actual count so
          the planner sees what happened — no silent success. */}
      {migrationResult && (
        <div style={{
          padding: '10px 16px 10px 19px',
          background: C.surface,
          borderBottom: `1px solid ${C.border}`,
          borderLeft: `3px solid ${migrationResult.ok ? C.success : C.muted}`,
          display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 12,
        }}>
          <div style={{ fontSize: T.caption, color: C.text, lineHeight: 1.5 }}>
            <strong style={{ fontWeight: FW.bold }}>
              {migrationResult.ok
                ? `Moved ${migrationResult.moved} decision${migrationResult.moved !== 1 ? 's' : ''} into shared approval history.`
                : `Moved ${migrationResult.moved}; ${migrationResult.failed} could not be moved.`}
            </strong>
            <span style={{ color: C.muted, marginLeft: 6 }}>
              Originals remain on the event.
            </span>
          </div>
          <button
            onClick={() => setMigrationResult(null)}
            style={{ background: 'none', border: 'none', cursor: 'pointer', color: C.muted, fontSize: T.body, lineHeight: 1, padding: '0 4px' }}
          >×</button>
        </div>
      )}
      {/* Sprint 66: Portal share banner */}
      <div style={{
        padding: '10px 16px',
        background: C.surface,
        borderBottom: `1px solid ${C.border}`,
        display: 'flex', alignItems: 'center', gap: 12, flexWrap: 'wrap',
      }}>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontSize: T.caption, fontWeight: FW.bold, color: C.text }}>
            Client portal
            {hasClientActivity && (
              <span style={{ marginLeft: 8, fontSize: T.eyebrow, fontWeight: FW.bold, color: C.success, background: C.success + '18', border: `1px solid 33`, padding: '2px 6px', borderRadius: 5, textTransform: 'uppercase', letterSpacing: '0.05em' }}>
                {clientRespondedN} response{clientRespondedN !== 1 ? 's' : ''}
              </span>
            )}
          </div>
          <div style={{ fontSize: T.caption, color: C.muted, marginTop: 1 }}>
            {pendingDecisions.length > 0
              ? `Share a private link — client sees ${pendingDecisions.length} item${pendingDecisions.length !== 1 ? 's' : ''} awaiting approval`
              : 'Share a private link so your client can view event status and approve decisions'}
          </div>
        </div>
        <button
          onClick={copyPortalLink}
          style={{
            padding: '7px 14px', borderRadius: 7,
            border: `1px solid ${copied ? C.success : C.border}`,
            background: copied ? C.success + '18' : C.bg,
            color: copied ? C.success : C.text,
            fontSize: T.caption, fontWeight: FW.semibold, cursor: 'pointer',
            fontFamily: 'inherit', flexShrink: 0, transition: 'all 0.15s',
            display: 'flex', alignItems: 'center', gap: 6,
          }}
        >
          {copied ? '✓ Link copied' : '🔗 Copy portal link'}
        </button>
      </div>

      {/* Client responses section — shown when client has responded */}
      {hasClientActivity && (
        <div style={{ padding: '10px 16px', background: C.surface, borderBottom: `1px solid ${C.border}` }}>
          <div style={{ fontSize: T.caption, fontWeight: FW.bold, color: C.muted, textTransform: 'uppercase', letterSpacing: '0.06em', marginBottom: 8 }}>
            Client responses (via portal)
          </div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
            {Object.entries(clientApprovals).map(([decId, verdict]) => {
              const d = (event?.decisions || []).find(x => x.id === decId);
              if (!d) return null;
              const isApproved = verdict === 'approved';
              return (
                <div key={decId} style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: T.caption }}>
                  <span style={{ width: 6, height: 6, borderRadius: '50%', background: isApproved ? C.success : C.muted, flexShrink: 0 }} />
                  <span style={{ color: C.text, fontWeight: FW.medium }}>{d.title}</span>
                  <span style={{ color: isApproved ? C.success : C.muted, fontWeight: FW.bold, fontSize: T.caption, textTransform: 'uppercase', letterSpacing: '0.04em' }}>
                    — {isApproved ? 'Approved' : 'Changes requested'}
                  </span>
                </div>
              );
            })}
          </div>
        </div>
      )}

      <div style={{ flex: 1, overflow: 'auto' }}>
        <DecisionApprovalCenter
          event={event}
          isMobile={isMobile}
          openId={openId}
          onBack={onBack}
          onResolveDecision={onResolveDecision}
          onExtendDecision={onExtendDecision}
          onReassignDecision={onReassignDecision}
          onMessage={() => onRouteToLinked && onRouteToLinked('Communication')}
          onSendMessage={(item, body) => setEvent(e => ({
            ...e,
            commClient: [...(e.commClient || []), {
              id: `m-${Date.now()}`,
              channel: 'client', direction: 'outbound', sender: 'planner',
              senderName: 'Planner',
              body, text: body,
              subject: `Re: ${item.title}`,
              relatedDecisionId: item.id,
              createdAt: new Date().toISOString(),
              message_type: 'standard', deliveryStatus: 'local-only',
            }],
          }))}
          onActApproval={onActApproval}
          onSaveNote={(itemId, note) => setEvent(e => ({ ...e, decisionNotes: { ...(e.decisionNotes || {}), [itemId]: note } }))}
        />
      </div>
    </div>
  );
}

// Sprint 57: workspace header for legacy L4 tabs (Budget / Guests / Seating /
// Planning Tasks / Calendar / Run of Show / Agenda) that didn't get the
// Sprint 49 `← Overview` back-strip. Matches the PLAN-overlay style
// (ChecklistGenerator.jsx:206) so the back path is consistent across all 13
// tabs — the v2 audit flagged this inconsistency as a Major-severity finding.
// ── ReadinessTrack — the ONE unified header progress bar ──────────────────────
// 4px-tall full-width track that lives directly under the host app-header on EVERY
// host tab (Your Event / Plan / Budget / Guests / The Day). Fill = the event's
// readinessScore(getEventReadiness(event)) as 0–100%. Studio Matte confidence palette
// ONLY: green (C.success) at/above 50%, steel (C.accent) below — never amber/gold.
// A node dot rides the fill end; faint ticks mark the 33% / 66% thirds. Honest: if the
// score is null (nothing to measure yet) it renders an empty track, not a guess.
function ReadinessTrack({ event }) {
  const C = useT();
  const score = (() => { try { return readinessScore(getEventReadiness(event)); } catch { return null; } })();
  const pct = score == null ? 0 : Math.max(0, Math.min(100, Math.round(score)));
  const fill = pct >= 50 ? (C.success || C.accent) : C.accent;
  const trackBg = C.border;
  return (
    <div aria-hidden style={{ position: 'relative', height: 4, background: trackBg, flexShrink: 0 }}>
      {/* faint thirds ticks — orientation, not measurement */}
      {[33, 66].map(t => (
        <div key={t} style={{ position: 'absolute', top: 0, bottom: 0, left: `${t}%`, width: 1, background: C.text, opacity: 0.08 }} />
      ))}
      {score != null && pct > 0 && (
        <>
          <div style={{ position: 'absolute', left: 0, top: 0, bottom: 0, width: `${pct}%`, background: `linear-gradient(90deg, ${fill}cc, ${fill})`, borderTopRightRadius: 4, borderBottomRightRadius: 4, transition: 'width 600ms ease' }} />
          {/* node dot at the fill end */}
          <div style={{ position: 'absolute', top: '50%', left: `${pct}%`, width: 7, height: 7, marginLeft: -4, marginTop: -3.5, borderRadius: '50%', background: fill, boxShadow: `0 0 6px ${fill}aa`, transition: 'left 600ms ease' }} />
        </>
      )}
    </div>
  );
}

