// Crew tab — assign studio members to this event, set role + call times +
// status, and contact them. Roster is studio-wide; crew is per-event.
function CrewTab({ event, setEvent, team = [], setTeam, isMobile, onBack }) {
  const C = useT();
  const T = useType(); const s = makeS(C);
  const crew = event.crew || [];
  const setCrew = (fn) => setEvent(e => ({ ...e, crew: typeof fn === 'function' ? fn(e.crew || []) : fn }));
  const assignedIds = new Set(crew.map(c => c.memberId).filter(Boolean));
  const available = team.filter(m => !assignedIds.has(m.id));
  const [adding, setAdding] = useState(false);
  const [nm, setNm] = useState(''); const [rl, setRl] = useState(''); const [em, setEm] = useState(''); const [ph, setPh] = useState('');

  const addTeammate = () => {
    if (!nm.trim()) return;
    const m = makeRosterMember({ name: nm, roleLabel: rl, email: em, phone: ph });
    setTeam?.(t => [...t, m]);
    setCrew(list => [...list, makeCrewAssignment(m, { roleLabel: rl })]);
    setNm(''); setRl(''); setEm(''); setPh(''); setAdding(false);
  };
  const assign = (m) => setCrew(list => [...list, makeCrewAssignment(m)]);
  const updateCrew = (id, key, val) => setCrew(list => list.map(c => c.id === id ? { ...c, [key]: val } : c));
  const removeCrew = (id) => setCrew(list => list.filter(c => c.id !== id));

  const field = { ...s.input, fontSize: T.secondary };
  const fieldRow = isMobile ? { display: 'flex', flexDirection: 'column', gap: 8 } : { display: 'flex', gap: 8, flexWrap: 'wrap', alignItems: 'flex-end' };

  return (
    <div data-testid="crew-tab">
      {/* Title rework (2026-06-11): conform to the app-wide crisp title — quiet
          ‹ Overview up-crumb, then "Crew" as a 22px sentence-case heading. */}
      <div style={{ marginBottom: 14 }}>
        {onBack && (
          <button onClick={onBack} style={{ background: 'none', border: 'none', cursor: 'pointer', fontSize: T.secondary, fontWeight: FW.semibold, letterSpacing: '0.01em', color: C.tier2, padding: 0, marginBottom: 6, fontFamily: 'inherit', display: 'inline-flex', alignItems: 'center', gap: 4 }}>‹ Overview</button>
        )}
        <div style={{ fontSize: T.title, fontWeight: FW.bold, letterSpacing: '-0.02em', lineHeight: 1.15, color: C.tier1 }}>Crew</div>
        <div style={{ marginTop: 3, fontSize: T.secondary, color: C.tier3, lineHeight: 1.4 }}>Assign studio teammates, set call times, and track who's confirmed. Solo events can leave this empty.</div>
      </div>

      {/* Assigned crew */}
      {crew.length === 0 ? (
        <div data-testid="crew-empty" style={{ background: C.surface2, border: `1px dashed ${C.border}`, borderRadius: 12, padding: '18px 16px', textAlign: 'center', color: C.muted, fontSize: T.secondary, marginBottom: 14 }}>
          No crew assigned yet. Add a teammate below — or run this event solo.
        </div>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 10, marginBottom: 16 }}>
          {crew.map(c => (
            <div key={c.id} data-testid="crew-row" style={{ background: C.surface2, border: `1px solid ${C.border}`, borderRadius: 12, padding: 14 }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline', gap: 10, flexWrap: 'wrap', marginBottom: 10 }}>
                <span style={{ fontSize: T.body, fontWeight: FW.bold, color: C.text }}>{c.name}{c.email ? <span style={{ fontSize: T.secondary, fontWeight: FW.regular, color: C.muted }}> · {c.email}</span> : null}</span>
                <button onClick={() => removeCrew(c.id)} style={{ background: 'none', border: 'none', color: C.muted, fontSize: T.secondary, cursor: 'pointer', fontFamily: 'inherit' }}>Remove</button>
              </div>
              <div style={fieldRow}>
                <label style={{ flex: 1, minWidth: 130 }}><span style={{ fontSize: T.caption, color: C.muted, display: 'block', marginBottom: 3, textTransform: 'uppercase', letterSpacing: '0.06em', fontWeight: FW.bold }}>Role</span>
                  <input data-testid="crew-role" style={field} value={c.roleLabel} placeholder="e.g. Second shooter" onChange={e => updateCrew(c.id, 'roleLabel', e.target.value)} /></label>
                <label style={{ width: isMobile ? '100%' : 120 }}><span style={{ fontSize: T.caption, color: C.muted, display: 'block', marginBottom: 3, textTransform: 'uppercase', letterSpacing: '0.06em', fontWeight: FW.bold }}>Call time</span>
                  <input type="time" style={field} value={c.callTime} onChange={e => updateCrew(c.id, 'callTime', e.target.value)} /></label>
                <label style={{ width: isMobile ? '100%' : 120 }}><span style={{ fontSize: T.caption, color: C.muted, display: 'block', marginBottom: 3, textTransform: 'uppercase', letterSpacing: '0.06em', fontWeight: FW.bold }}>Arrival</span>
                  <input type="time" style={field} value={c.arrivalTime} onChange={e => updateCrew(c.id, 'arrivalTime', e.target.value)} /></label>
                <label style={{ width: isMobile ? '100%' : 170 }}><span style={{ fontSize: T.caption, color: C.muted, display: 'block', marginBottom: 3, textTransform: 'uppercase', letterSpacing: '0.06em', fontWeight: FW.bold }}>Status</span>
                  <select data-testid="crew-status" style={field} value={c.status} onChange={e => updateCrew(c.id, 'status', e.target.value)}>
                    {CREW_STATUSES.map(st => <option key={st} value={st}>{CREW_STATUS_LABEL[st]}</option>)}
                  </select></label>
              </div>
              <label style={{ display: 'block', marginTop: 8 }}><span style={{ fontSize: T.caption, color: C.muted, display: 'block', marginBottom: 3, textTransform: 'uppercase', letterSpacing: '0.06em', fontWeight: FW.bold }}>Notes</span>
                <input style={field} value={c.notes} placeholder="Optional — e.g. handles drone, leaves at 9pm" onChange={e => updateCrew(c.id, 'notes', e.target.value)} /></label>
              <div style={{ marginTop: 10 }}><CrewContactActions c={c} event={event} /></div>
            </div>
          ))}
        </div>
      )}

      {/* Assign from roster */}
      {available.length > 0 && (
        <div style={{ marginBottom: 14 }}>
          <div style={{ fontSize: T.caption, color: C.muted, textTransform: 'uppercase', letterSpacing: '0.06em', fontWeight: FW.bold, marginBottom: 6 }}>Add from your studio</div>
          <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
            {available.map(m => (
              <button key={m.id} data-testid="crew-assign-chip" onClick={() => assign(m)} style={{ display: 'inline-flex', alignItems: 'center', gap: 6, padding: '8px 12px', borderRadius: 999, border: `1px solid ${C.border}`, background: 'transparent', color: C.text, fontSize: T.secondary, fontWeight: FW.semibold, cursor: 'pointer', fontFamily: 'inherit', minHeight: 40 }}>
                + {m.name}{m.roleLabel ? <span style={{ color: C.muted, fontWeight: FW.regular }}> · {m.roleLabel}</span> : null}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Add a new teammate */}
      {adding ? (
        <div style={{ background: C.surface2, border: `1px solid ${C.border}`, borderRadius: 12, padding: 14 }}>
          <div style={{ fontSize: T.secondary, fontWeight: FW.bold, color: C.text, marginBottom: 10 }}>Add a teammate</div>
          <div style={fieldRow}>
            <label style={{ flex: 1, minWidth: 130 }}><span style={{ fontSize: T.caption, color: C.muted, display: 'block', marginBottom: 3, textTransform: 'uppercase', letterSpacing: '0.06em', fontWeight: FW.bold }}>Name *</span>
              <input data-testid="crew-new-name" style={field} value={nm} placeholder="Full name" onChange={e => setNm(e.target.value)} /></label>
            <label style={{ flex: 1, minWidth: 130 }}><span style={{ fontSize: T.caption, color: C.muted, display: 'block', marginBottom: 3, textTransform: 'uppercase', letterSpacing: '0.06em', fontWeight: FW.bold }}>Role</span>
              <input style={field} value={rl} placeholder="e.g. Assistant" onChange={e => setRl(e.target.value)} /></label>
            <label style={{ flex: 1, minWidth: 130 }}><span style={{ fontSize: T.caption, color: C.muted, display: 'block', marginBottom: 3, textTransform: 'uppercase', letterSpacing: '0.06em', fontWeight: FW.bold }}>Email</span>
              <input style={field} value={em} placeholder="teammate@studio.com" onChange={e => setEm(e.target.value)} /></label>
            <label style={{ flex: 1, minWidth: 130 }}><span style={{ fontSize: T.caption, color: C.muted, display: 'block', marginBottom: 3, textTransform: 'uppercase', letterSpacing: '0.06em', fontWeight: FW.bold }}>Phone</span>
              <input style={field} value={ph} placeholder="(555) 555-0123" onChange={e => setPh(formatPhone(e.target.value))} /></label>
          </div>
          <div style={{ display: 'flex', gap: 8, marginTop: 12 }}>
            <button data-testid="crew-new-save" onClick={addTeammate} disabled={!nm.trim()} style={{ ...s.btn(nm.trim() ? 'primary' : 'secondary'), fontSize: T.secondary, opacity: nm.trim() ? 1 : 0.5 }}>Add to crew</button>
            <button onClick={() => { setAdding(false); setNm(''); setRl(''); setEm(''); setPh(''); }} style={{ ...s.btn('ghost'), fontSize: T.secondary }}>Cancel</button>
          </div>
        </div>
      ) : (
        <button data-testid="crew-add-teammate" onClick={() => setAdding(true)} style={{ ...s.btn('primary'), fontSize: T.secondary }}>+ Add a teammate</button>
      )}
    </div>
  );
}

// ── The Next-Step Spine (Sprint 61) ──────────────────────────────────────────
// Board headline innovation (audit 2026-06-11): the app named the next step on
// every screen but never CARRIED the planner from one to the next — seven
// bespoke red treatments, zero bridges. The Spine is ONE persistent ribbon,
// identical position + style on every event tab (L4), that:
//   • surfaces the single top action from the SAME engine the L3 Command hero
//     uses (selectEventNextAction) — Command IS the expanded detail view, so the
//     ribbon is hidden there and shown on every other tab;
//   • shows who it's waiting on (nextStepOwner) and a "1 of N" queue depth;
//   • ADVANCES on completion — when the top action changes (because the planner
//     resolved it elsewhere), a brief "Next up" tick fires (motion = change only);
//   • resolves into a quiet steel CAUGHT-UP reward when nothing needs the planner.
// It is a deterministic re-render of a queue already computed — no fake AI, no
// fake real-time. Navigation reuses the event's own primaryRoute dispatcher.
// Same component drives BOTH layers (board: one component, identical style):
//   • Event mode (L4 specialist tabs): pass `event` — the next action comes from
//     selectEventNextAction and the queue depth from getEventAttention.
//   • Studio mode (L1 Studio Home): pass a precomputed cross-event `command`
//     (selectStudioCommand), an `eventLabel` prefix, and `totalOpen`. The parent
//     owns navigation (it opens the right event), so onNavigate gets the route.
function NextStepSpine({ event, command, totalOpen: totalOpenProp, pad, isMobile, onNavigate, eventsHydrated = true, stickyTop = 0 }) {
  const C = useT();
  const T = useType();
  const s = makeS(C);
  const studio = command !== undefined;
  const na = studio ? command : selectEventNextAction(event);
  const totalOpen = studio
    ? (totalOpenProp || 0)
    : (() => { const a = getEventAttention(event); return (a.decisions || 0) + (a.approvals || 0) + (a.requests || 0) + (a.vendorIssues || 0); })();
  const caughtUp = !na || (na.category === 'neutral' && totalOpen === 0);
  const owner = nextStepOwner(na);
  const level = (na || {}).level;

  // Identity of the current top action — drives the handoff tick.
  const sig = caughtUp ? '__caught__' : `${(na || {}).category}:${(na || {}).title}`;
  const prevSig = useRef(sig);
  const [advanced, setAdvanced] = useState(false);
  useEffect(() => {
    if (prevSig.current !== sig) {
      prevSig.current = sig;
      setAdvanced(true);
      const t = setTimeout(() => setAdvanced(false), 1500);
      return () => clearTimeout(t);
    }
  }, [sig]);

  // Trust gate: never escalate to red (C.danger) before event data is hydrated.
  // On first paint `events` is the localStorage cache (pre-cloud-sync), which can
  // resolve to a false `critical` action and flash "you're late" before settling.
  // Until hydrated, a critical level renders steel (C.accent2); steel→red after
  // hydration is fine — red→steel on load is the trust defect we're killing.
  const accent = caughtUp ? C.muted
    : (level === 'critical' && eventsHydrated) ? C.danger
    : level === 'attention' ? C.muted
    : C.accent2;
  const ownerColor = owner.key === 'you' ? C.muted
    : (owner.key === 'vendor' || owner.key === 'client') ? C.text
    : C.muted;

  return (
    <div style={{
      padding: pad,
      borderBottom: `1px solid ${C.border}`,
      // Frozen on scroll — the next step stays in view as the host scrolls the surface.
      // Needs an OPAQUE base (was transparent) so scrolling content doesn't bleed through;
      // the brief "advanced" tint layers on top.
      background: C.bg,  // ALWAYS match the page carbon — no green band when caught up (the dim accent + "Caught up" text is the only signal; calm, not a status to flag)
      transition: 'background 0.45s ease',
      position: 'sticky',
      top: stickyTop,   // sits just below the (also-sticky) header
      zIndex: 25,       // sticky chrome stays BELOW the modal floor (overlays start at 40) so modals never get overlapped
    }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 14, flexWrap: 'wrap' }}>
        {/* accent rule — the ONE red/amber/steel moment, identical on every tab */}
        {/* The accent marks a LIVE next step by being brighter + a steady soft glow,
            dim when caught up. No perpetual pulse — motion is reserved for actual
            change (Attention System: motion = change only), so the bar is a calm
            state signal, not animated noise. */}
        <div style={{ width: 3, alignSelf: 'stretch', minHeight: 36, borderRadius: 2, background: accent, opacity: caughtUp ? 0.4 : 1, flexShrink: 0, boxShadow: caughtUp ? 'none' : `0 0 7px 1px ${accent}, 0 0 16px 3px ${accent}99` }} />

        {/* eyebrow + owner + action — breathes: a clear gap between the label row and
            the action line so the step reads as two distinct beats, not one cramped block. */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 7, minWidth: 0, flex: '1 1 auto' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
            <span style={{ fontSize: T.eyebrow, fontWeight: FW.heavy, letterSpacing: '0.16em', textTransform: 'uppercase', color: accent }}>
              {caughtUp ? 'Caught up' : 'Next step'}
            </span>
            {!caughtUp && (
              <span style={{ fontSize: T.eyebrow, fontWeight: FW.bold, letterSpacing: '0.08em', textTransform: 'uppercase', color: ownerColor, border: `1px solid ${ownerColor}55`, borderRadius: 5, padding: '1px 6px' }}>
                {owner.label}
              </span>
            )}
            {advanced && !caughtUp && (
              <span style={{ fontSize: T.eyebrow, fontWeight: FW.bold, color: C.success, display: 'inline-flex', alignItems: 'center', gap: 3 }}>
                <Icon name="check" size={11} /> Next up
              </span>
            )}
          </div>
          <div style={{
            // Board ruling 2026-06-24: this is the hero ACTION — the one sentence the whole
            // ribbon exists to say. It was 13/14 (secondary tier), quieter than its own
            // "NEXT STEP" eyebrow. Promote to the section tier, heavy, so the payload leads.
            fontSize: T.section, fontWeight: caughtUp ? FW.semibold : FW.heavy, color: caughtUp ? C.muted : C.text, lineHeight: 1.3, letterSpacing: '-0.01em',
            overflow: 'hidden', textOverflow: 'ellipsis',
            whiteSpace: isMobile ? 'normal' : 'nowrap',
            display: isMobile ? '-webkit-box' : 'block',
            WebkitLineClamp: isMobile ? 2 : undefined, WebkitBoxOrient: 'vertical',
          }}>
            {caughtUp
              ? (studio ? 'You’re caught up across your events.' : `Nothing needs you on ${(event && event.name) || 'this event'} right now.`)
              : na.title /* studio titles already name the event; event titles are action-first */}
          </div>
        </div>

        {/* right cluster — queue depth + the single CTA */}
        {caughtUp ? (
          <span style={{ display: 'inline-flex', alignItems: 'center', gap: 6, color: C.success, fontSize: T.secondary, fontWeight: FW.semibold, flexShrink: 0 }}>
            <Icon name="check" size={15} /> All clear
          </span>
        ) : (
          <div style={{ display: 'flex', alignItems: 'center', gap: 12, flexShrink: 0 }}>
            {totalOpen > 1 && (
              // Board 2026-06-12 ("1 of 33 — of what?"): bare "1 of N" reads as a
              // mystery count. Name it ("open items") + a tooltip so the planner
              // knows they're seeing the TOP of N things needing them, and that
              // clearing it advances to the next.
              <span title={`Your top next step — 1 of ${totalOpen} open items. Clear it and the next moves up.`}
                style={{ fontSize: T.caption, fontWeight: FW.semibold, color: C.muted, fontFeatureSettings: '"tnum" 1', whiteSpace: 'nowrap' }}>
                1 of {totalOpen} open
              </span>
            )}
            {/* Board ruling (two-reds): the Spine is persistent CHROME, so its CTA
                is an OUTLINE — accent border + text, never a filled block. This
                keeps the red SEMANTIC for a critical next-step without putting a
                second filled-red hero on a screen that already has its own content
                hero (e.g. Budget "STILL TO PAY"). One filled accent per screen;
                the Spine stays the quiet, consistent thread. */}
            <button
              onClick={() => onNavigate(na.primaryRoute)}
              style={{
                display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: 6,
                fontSize: T.secondary, fontWeight: FW.bold, whiteSpace: 'nowrap', cursor: 'pointer',
                padding: '6px 14px', borderRadius: 8, lineHeight: 1.1, fontFamily: 'inherit',
                border: `1px solid ${accent}`, color: accent, background: 'transparent',
                transition: 'background 0.12s',
              }}
              onMouseEnter={e => { e.currentTarget.style.background = accent + '14'; }}
              onMouseLeave={e => { e.currentTarget.style.background = 'transparent'; }}
            >
              {na.primaryCta} →
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

// Sprint 58C — Decision Memory capture modal. One short question, one optional
// answer. Never blocks: "Skip" records nothing and proceeds. The decision itself
// already happened; this only captures the WHY.
function RationaleModal({ prompt, onSave, onSkip }) {
  const C = useT();
  const T = useType();
  const [text, setText] = useState('');
  useEffect(() => { setText(''); }, [prompt]);
  if (!prompt) return null;
  return (
    <div onClick={onSkip} style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.55)', zIndex: 80, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 18 }}>
      <div onClick={e => e.stopPropagation()} style={{ width: 'min(440px, 94vw)', ...metalEdge(C), borderRadius: 14, padding: 20, boxShadow: '0 20px 60px rgba(0,0,0,0.5)' }}>
        <div style={{ fontSize: T.caption, fontWeight: FW.bold, letterSpacing: '0.12em', textTransform: 'uppercase', color: C.muted }}>Decision noted</div>
        <div style={{ fontSize: T.body, fontWeight: FW.bold, letterSpacing: '-0.01em', color: C.text, marginTop: 4 }}>{prompt.question || 'Why this decision?'}</div>
        {prompt.decision && <div style={{ fontSize: T.secondary, color: C.muted, marginTop: 4 }}>{prompt.decision}</div>}
        <textarea autoFocus value={text} onChange={e => setText(e.target.value)} placeholder="A sentence is plenty — your future self will thank you."
          rows={3} style={{ width: '100%', marginTop: 12, padding: '10px 12px', fontSize: T.secondary, lineHeight: 1.4, color: C.text, background: C.bg, border: `1px solid ${C.border}`, borderRadius: 9, resize: 'vertical', fontFamily: 'inherit', boxSizing: 'border-box' }}
          onKeyDown={e => { if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) onSave(text); }} />
        <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 8, marginTop: 12 }}>
          <button onClick={onSkip} style={{ ...makeS(C).btn('ghost'), fontSize: T.secondary }}>Skip</button>
          <button onClick={() => onSave(text)} disabled={!text.trim()} style={{ ...makeS(C).btn('primary'), fontSize: T.secondary, opacity: text.trim() ? 1 : 0.5, cursor: text.trim() ? 'pointer' : 'default' }}>Save reason</button>
        </div>
      </div>
    </div>
  );
}

// Sprint 58C — Decision Memory read surface. A plain, reverse-chronological log of
// captured decisions for THIS event. Renders nothing when memory is off / empty.
function DecisionHistory({ event }) {
  const C = useT();
  const T = useType();
  if (!decisionMemoryOn()) return null;
  const list = getDecisions(event);
  if (!list.length) return null;
  const fmtWhen = (iso) => { try { return new Date(iso).toLocaleDateString(undefined, { month: 'short', day: 'numeric' }); } catch { return ''; } };
  return (
    <div style={{ padding: '20px 0 8px', borderTop: `1px solid ${C.border}`, marginTop: 18 }}>
      <div style={{ fontSize: T.eyebrow, fontWeight: FW.bold, letterSpacing: '0.14em', textTransform: 'uppercase', color: C.muted, marginBottom: 4 }}>Decision History</div>
      <div style={{ fontSize: T.caption, color: C.muted, marginBottom: 12 }}>Why the calls were made — captured as you went.</div>
      <div style={{ ...metalEdge(C), borderRadius: 10 }}>
        {list.slice().reverse().map((d, i) => (
          <div key={d.id} style={{ padding: '12px 16px', borderTop: i === 0 ? 'none' : `1px solid ${C.border}` }}>
            <div style={{ display: 'flex', alignItems: 'baseline', gap: 8, justifyContent: 'space-between' }}>
              <div style={{ fontSize: T.secondary, fontWeight: FW.semibold, color: C.text }}>{d.decision || d.subjectLabel}</div>
              <div style={{ fontSize: T.caption, color: C.muted, flexShrink: 0 }}>{(DECISION_TYPE_LABEL[d.decisionType] || 'Decision')}{d.createdAt ? ' · ' + fmtWhen(d.createdAt) : ''}</div>
            </div>
            <div style={{ fontSize: T.secondary, color: C.muted, marginTop: 3, lineHeight: 1.45 }}>
              <span style={{ fontWeight: FW.bold, color: C.text, opacity: 0.8 }}>Because</span> {d.rationale}
              {d.createdBy ? <span style={{ opacity: 0.7 }}> — {d.createdBy}</span> : null}
            </div>
            {/* Sprint 58E — Outcome: completes the triple. Captured (vendor/overall)
                or derived (budget variance / timeline slip), shown when known. */}
            {(() => {
              const o = outcomeFor(event, d);
              if (!o) return null;
              const col = o.tone === 'good' ? C.success : o.tone === 'bad' ? C.danger : C.muted;
              return (
                <div style={{ fontSize: T.caption, color: col, marginTop: 3 }}>
                  <span style={{ fontWeight: FW.bold }}>→ Outcome:</span> {o.label}
                  <span style={{ color: C.muted, opacity: 0.7 }}> ({o.source})</span>
                </div>
              );
            })()}
          </div>
        ))}
      </div>
    </div>
  );
}

// Sprint 58E — Outcome Capture. The few signals that can't be derived: overall
// event + per-confirmed-vendor execution. One tap each, never a survey. Shown when
// pi.memory is on (best recorded after the event — hint says so). Writes to
// event.outcomes via the existing save path. Budget/timeline outcomes are NOT here
// (they derive automatically and show in Decision History).
function OutcomeChips({ options, value, onPick, C }) {
  return (
    <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6 }}>
      {options.map(opt => {
        const on = value === opt;
        const tone = outcomeTone(opt);
        const col = tone === 'good' ? C.success : tone === 'bad' ? C.danger : C.accent;
        return (
          <button key={opt} onClick={() => onPick(on ? null : opt)} style={{
            fontSize: T.caption, fontWeight: FW.semibold, padding: '5px 11px', borderRadius: 20, cursor: 'pointer',
            border: `1px solid ${on ? col : C.border}`, background: on ? col + '22' : 'transparent',
            color: on ? col : C.muted,
          }}>{OUTCOME_LABEL[opt] || opt}</button>
        );
      })}
    </div>
  );
}
