      <div style={{ marginTop: 14 }}>
        <div style={{ fontSize: T.secondary, fontWeight: FW.semibold, color: C.text, marginBottom: 6 }}>Biggest lesson <span style={{ color: C.muted, fontWeight: FW.regular }}>(optional, one line)</span></div>
        <input value={getLesson(event)} onChange={e => setEvent(ev => setLesson(ev, e.target.value))}
          placeholder="e.g. Parking filled early · catering ran over · timeline ran long"
          maxLength={200}
          style={{ width: '100%', padding: '8px 12px', fontSize: T.secondary, color: C.text, background: C.bg, border: `1px solid ${C.border}`, borderRadius: 8, fontFamily: 'inherit', boxSizing: 'border-box' }} />
      </div>
