const THEMES = { dark: DARK, light: LIGHT };

// AuthGate, LoginScreen, and ThemeFallbackSplash live in src/components/AuthGate.jsx

// ─── Cloud migration modal ────────────────────────────────────────────────────
// Offered once when a signed-in user has local data but no prior cloud sync.
// NEVER auto-migrates or auto-deletes local data — explicit user action only.
function MigrationModal({ events: localEvents, clients: localClients, onDone, onSuccess, themeC }) {
  const [phase,  setPhase]  = useState('prompt'); // prompt | migrating | done | error
  const [result, setResult] = useState(null);
  const C = themeC;

  const run = async () => {
    setPhase('migrating');
    try {
      const [evR, clR] = await Promise.all([
        migrateEventsToCloud(localEvents),
        migrateClientsToCloud(localClients),
      ]);
      setResult({ evR, clR });
      const failed = evR.failed + clR.failed;
      setPhase(failed > 0 ? 'error' : 'done');
      // Sprint 50: tell the parent it can merge the imported snapshot into
      // in-memory state so the workspace updates immediately.
      if (failed === 0 && typeof onSuccess === 'function') onSuccess();
    } catch {
      setPhase('error');
    }
  };

  // Did the failures come from a studio-ownership RLS block? An upsert becomes an
  // UPDATE for rows that already exist in the cloud, and the events/clients UPDATE
  // policy checks the EXISTING row's studio_id — so events belonging to a studio the
  // account is no longer a member of fail with "row-level security policy (USING
  // expression)". See docs/SUPABASE_SYNC_TROUBLESHOOTING_HANDOFF.md.
  const firstError = result?.evR?.firstError || result?.clR?.firstError || '';
  const isStudioMismatch = /row-level security|using expression|violates row-level/i.test(firstError);

  // Re-link: clear the studio cache + re-resolve (ensure_studio() self-heals a missing
  // membership), then retry the import under the correct/fresh studio.
  const relinkAndRetry = async () => {
    setPhase('migrating');
    try { await revalidateStudio(); } catch { /* fall through — retry surfaces the real state */ }
    await run();
  };

  const overlay = { position: 'fixed', inset: 0, zIndex: 10000, background: 'rgba(0,0,0,0.72)', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 24 };
  const box = { ...metalEdge(C), borderRadius: 14, padding: '28px 24px', maxWidth: 420, width: '100%' };

  return (
    <div style={overlay}>
      <div style={box}>
        <div style={{ fontSize: T.secondary, fontWeight: FW.heavy, letterSpacing: '0.1em', color: C.accent, textTransform: 'uppercase', marginBottom: 10 }}>Cloud sync</div>

        {phase === 'prompt' && (
          <>
            <div style={{ fontSize: T.title, fontWeight: FW.bold, marginBottom: 8, color: C.text }}>Save your data to the cloud?</div>
            <div style={{ fontSize: T.secondary, color: C.muted, lineHeight: 1.6, marginBottom: 20 }}>
              You have <strong style={{ color: C.text }}>{localEvents.length} event{localEvents.length !== 1 ? 's' : ''}</strong> and <strong style={{ color: C.text }}>{localClients.length} client{localClients.length !== 1 ? 's' : ''}</strong> saved locally. Import them to your account so they're available on any device.
              <br /><br />
              Your local data will <em>not</em> be deleted — it stays as a backup.
            </div>
            <div style={{ display: 'flex', gap: 10 }}>
              <button onClick={run} style={{ flex: 1, padding: '10px', borderRadius: 8, border: 'none', background: C.accent, color: '#fff', fontSize: T.secondary, fontWeight: FW.semibold, cursor: 'pointer', fontFamily: 'inherit' }}>
                Import to cloud
              </button>
              <button onClick={onDone} style={{ padding: '10px 16px', borderRadius: 8, border: `1px solid ${C.border}`, background: 'transparent', color: C.muted, fontSize: T.secondary, cursor: 'pointer', fontFamily: 'inherit' }}>
                Not now
              </button>
            </div>
          </>
        )}

        {phase === 'migrating' && (
          <div style={{ textAlign: 'center', padding: '20px 0', color: C.muted, fontSize: T.secondary }}>
            Uploading your data…
          </div>
        )}

        {phase === 'done' && (
          <>
            <div style={{ fontSize: T.title, fontWeight: FW.bold, marginBottom: 8, color: C.text }}>All done</div>
            <div style={{ fontSize: T.secondary, color: C.muted, marginBottom: 20, lineHeight: 1.6 }}>
              {result?.evR.migrated} event{result?.evR.migrated !== 1 ? 's' : ''} and {result?.clR.migrated} client{result?.clR.migrated !== 1 ? 's' : ''} saved to your account.
            </div>
            <button onClick={onDone} style={{ padding: '10px 20px', borderRadius: 8, border: 'none', background: C.accent, color: '#fff', fontSize: T.secondary, fontWeight: FW.semibold, cursor: 'pointer', fontFamily: 'inherit' }}>
              Continue
            </button>
          </>
        )}

        {phase === 'error' && (
          <>
            <div style={{ fontSize: T.title, fontWeight: FW.bold, marginBottom: 8, color: C.text }}>{isStudioMismatch ? 'These belong to a different studio' : 'Partial import'}</div>
            <div style={{ fontSize: T.secondary, color: C.muted, marginBottom: isStudioMismatch ? 14 : 20, lineHeight: 1.6 }}>
              {isStudioMismatch ? (
                <>
                  {(result?.evR.migrated || 0) + (result?.clR.migrated || 0)} uploaded, {(result?.evR.failed || 0) + (result?.clR.failed || 0)} blocked. These items are already in the cloud under a studio this account isn’t on anymore, so they can’t be overwritten. <strong style={{ color: C.text }}>Re-link your studio</strong> and try again — your local data is safe.
                </>
              ) : (
                <>
                  {(result?.evR.migrated || 0) + (result?.clR.migrated || 0)} items uploaded,
                  {' '}{(result?.evR.failed || 0) + (result?.clR.failed || 0)} failed. Your local data is intact — try again later.
                </>
              )}
            </div>
            {/* The real reason, verbatim — so the cause (RLS / auth / network) is visible without DevTools. */}
            {firstError && (
              <div style={{ fontSize: T.caption, color: C.muted, opacity: 0.7, marginBottom: 18, lineHeight: 1.5, wordBreak: 'break-word' }}>
                Details: {firstError}
              </div>
            )}
            <div style={{ display: 'flex', gap: 10 }}>
              {isStudioMismatch ? (
                <button onClick={relinkAndRetry} style={{ padding: '10px 16px', borderRadius: 8, border: 'none', background: C.accent, color: '#fff', fontSize: T.secondary, fontWeight: FW.semibold, cursor: 'pointer', fontFamily: 'inherit' }}>
                  Re-link &amp; retry
                </button>
              ) : (
                <button onClick={run} style={{ padding: '10px 16px', borderRadius: 8, border: 'none', background: C.accent, color: '#fff', fontSize: T.secondary, fontWeight: FW.semibold, cursor: 'pointer', fontFamily: 'inherit' }}>
                  Retry
                </button>
              )}
              <button onClick={onDone} style={{ padding: '10px 16px', borderRadius: 8, border: `1px solid ${C.border}`, background: 'transparent', color: C.muted, fontSize: T.secondary, cursor: 'pointer', fontFamily: 'inherit' }}>
                Dismiss
              </button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

// First-run welcome — the 20-second onboarding the audit called for. Account type is
